  ('253', '本教材在系统介绍无人机测绘系统组成、航空摄影测量基本知识和倾斜摄影测量技术的基础上，重点讲解无人机测绘航线规划、航拍作业、控制点布设等数据采集方法，并以Pix4Dmapper、ContextCapture等数据处理软件为例，详细说明无人机测绘数据的处理方法，最后梳理了无人机测绘技术在基础测绘、国土资源管理、国防安全、地质灾害、应急救援、农田监测等领域中的典型应用。
本教材可作为高等职业院校工程测量技术、测绘工程技术、测绘地理信息技术、摄影测量与遥感技术、地籍测绘与土地管理、国土空间规划与测绘、无人机测绘技术等专业的教材，也可供测绘地理信息相关领域的教师、科研和技术人员阅读参考。', 38.80, 31.04, 475, '本教材在系统介绍无人机测绘系统组成、航空摄影测量基本知识和倾斜摄影测量技术的基础上，重点讲解无人机测绘航线规划、航拍作业、控制点布设等数据采集方法，并以Pix4Dmapper、ContextCapture等数据处理软件为例，详细说明无人机测绘数据的处理方法，最后梳理了无人机测绘技术在基础测绘、国土资源管理、国防安全、地质灾害、应急救援、农田监测等领域中的典型应用。
本教材可作为高等职业院校工程测量技术、测绘工程技术、测绘地理信息技术、摄影测量与遥感技术、地籍测绘与土地管理、国土空间规划与测绘、无人机测绘技术等专业的教材，也可供测绘地理信息相关领域的教师、科研和技术人员阅读参考。', '前言
