  ('252', '传统音乐文化是我国悠久文明历史遗产的重要组成部分，它是民族文化的写照，具有丰富的文化内涵，不论是非音乐专业的大学生还是传统音乐文化爱好者，了解荆楚大地上的音乐及其文化背景，是有意义且有乐趣的事情。
本教材将音乐作品置于其特定的社会文化之中，以传统音乐中创作及使用最为广泛的民间音乐为主要内容，将至今广泛流传并活跃于田间地头、民俗活动、舞台上、网络上的民间歌曲、民间歌舞、民族器乐、曲艺音乐、戏曲音乐的代表性作品进行分析介绍，师生通过多元互动的实践方式，如讲、演、教、看、听、唱，去感受传统音乐作品的旋律、形式、表现力和深厚文化，发现传统音乐的美，了解传统音乐背后的文化，从而进一步认识、感受中国传统文化，增强文化自信，培养学生良好的音乐审美及人文艺术修养，以美养德，以美育人，提高学生的社会责任感，促进民族文化传承。
本教材可供非音乐专业的大学生艺术素养通识课使用，也可供传统音乐文化爱好者学习参考。', 38.80, 31.04, 73, '传统音乐文化是我国悠久文明历史遗产的重要组成部分，它是民族文化的写照，具有丰富的文化内涵，不论是非音乐专业的大学生还是传统音乐文化爱好者，了解荆楚大地上的音乐及其文化背景，是有意义且有乐趣的事情。
本教材将音乐作品置于其特定的社会文化之中，以传统音乐中创作及使用最为广泛的民间音乐为主要内容，将至今广泛流传并活跃于田间地头、民俗活动、舞台上、网络上的民间歌曲、民间歌舞、民族器乐、曲艺音乐、戏曲音乐的代表性作品进行分析介绍，师生通过多元互动的实践方式，如讲、演、教、看、听、唱，去感受传统音乐作品的旋律、形式、表现力和深厚文化，发现传统音乐的美，了解传统音乐背后的文化，从而进一步认识、感受中国传统文化，增强文化自信，培养学生良好的音乐审美及人文艺术修养，以美养德，以美育人，提高学生的社会责任感，促进民族文化传承。
本教材可供非音乐专业的大学生艺术素养通识课使用，也可供传统音乐文化爱好者学习参考。', '前 言
第一章 绪论
