  ('251', '本书分为上、下两册. 下册主要内容为向量代数与空间解析几何、多元函数微分学、重积分、曲线积分、曲面积分以及无穷级数. 本册按照“重基础、强练习、拓视野”的原则构建课程体系，保持了原有纸质教材的知识结构，每节增加了自测试题和答案解析，每章的总结部分增加了易错知识点的例题讲解，部分章节增加了实际应用案例，在提升课程教学效果的同时，为读者学习提供思维与探索的空间. 为发挥数字教材的多主体优势，本册中增加了12个重难点知识的名师教学视频，136个典型例题的讲解视频，以及40多幅数学知识的动图演示，新型资源的加入可以有效地提升读者的学习兴趣，便于读者自主学习.
