  ('249', '本书采用模块—单元—专题的逻辑结构，由4个模块、12个单元和41个专题组成。每个模块的内容相对完整，模块间相对独立。学习者可以系统地学习所有模块，也可以结合专业需要选学部分模块。本书可以帮助学习者比较深入地了解信息时代教育教学的新理念，系统地学习现代教育技术的基本理论，熟悉现代教育技术的主要实践领域及发展动态，掌握现代教学媒体技术、信息化教学设计技术、教学传播技术、常用数字化教学资源的开发和利用技术，并将这些技术与学科专业相融合。为了有效地促进教师教学和学生学习，本书用二维码关联了微课等数字资源。本书结构新颖，逻辑清晰，图文并茂，内容丰富，易教易学，知行合一。
本书可作为师范院校本科生公共课教材，也可作为教育硕士公共课教材，还可作为其他各类学校教师学习的教材。', 42.80, 34.24, 677, '本书采用模块—单元—专题的逻辑结构，由4个模块、12个单元和41个专题组成。每个模块的内容相对完整，模块间相对独立。学习者可以系统地学习所有模块，也可以结合专业需要选学部分模块。本书可以帮助学习者比较深入地了解信息时代教育教学的新理念，系统地学习现代教育技术的基本理论，熟悉现代教育技术的主要实践领域及发展动态，掌握现代教学媒体技术、信息化教学设计技术、教学传播技术、常用数字化教学资源的开发和利用技术，并将这些技术与学科专业相融合。为了有效地促进教师教学和学生学习，本书用二维码关联了微课等数字资源。本书结构新颖，逻辑清晰，图文并茂，内容丰富，易教易学，知行合一。
本书可作为师范院校本科生公共课教材，也可作为教育硕士公共课教材，还可作为其他各类学校教师学习的教材。', '前言
