  ('248', '本书是西北工业大学机械原理及机械零件教研室编《机械原理》（第九版）的配套辅助教材，对《机械原理》（第九版）各章内容的学习要求、重点难点、知识脉络、学习方法和注意事项作了简要说明，并对一些典型的例题和问题进行了较为详细的分析和求解，对课程中某些重要问题作了适当拓展延伸。在编写中注意了内容的启发性、科学性、实践性和趣味性。
本书有助于机械类专业学生对机械原理课程的学习与理解，也可供机械工程技术人员和自学机械原理课程的人员参考，对学生考研和青年教师备课也有帮助。', 50.00, 40.00, 2716, '本书是西北工业大学机械原理及机械零件教研室编《机械原理》（第九版）的配套辅助教材，对《机械原理》（第九版）各章内容的学习要求、重点难点、知识脉络、学习方法和注意事项作了简要说明，并对一些典型的例题和问题进行了较为详细的分析和求解，对课程中某些重要问题作了适当拓展延伸。在编写中注意了内容的启发性、科学性、实践性和趣味性。
