  ('247', '本数字教材内容体系以西北工业大学机械原理及机械零件教研室编《机械设计》（第十版)为蓝本，旨在提供机械设计课程学习辅导。
全书内容分为五大模块，包括机械设计课程的说明、机械设计学习指导、机械零件结构设计基本知识、机械设计习题的解题方法以及附录。学习指导按照主教材体系，共分5篇（18章）：第1篇总论；第2篇联接；第3篇机械传动；第4篇轴系零、部件；第5篇其他零、部件。另有附录：常用量的名称、单位、符号及换算关系表。通过图片、微视频、在线自测等多媒体素材辅助高校师生的教与学。
本书可作为普通高等学校机械类专业的教材，也可供其他类型院校相关专业使用。', 28.00, 22.40, 1086, '本数字教材内容体系以西北工业大学机械原理及机械零件教研室编《机械设计》（第十版)为蓝本，旨在提供机械设计课程学习辅导。
全书内容分为五大模块，包括机械设计课程的说明、机械设计学习指导、机械零件结构设计基本知识、机械设计习题的解题方法以及附录。学习指导按照主教材体系，共分5篇（18章）：第1篇总论；第2篇联接；第3篇机械传动；第4篇轴系零、部件；第5篇其他零、部件。另有附录：常用量的名称、单位、符号及换算关系表。通过图片、微视频、在线自测等多媒体素材辅助高校师生的教与学。
本书可作为普通高等学校机械类专业的教材，也可供其他类型院校相关专业使用。', 'A. 关于机械设计课程的说明
