  ('246', '本书以西方音乐的发展历史为主线，主体结构共分为十二章：古希腊和古罗马音乐、中世纪音乐、文艺复兴时期音乐、巴洛克音乐、前古典主义时期音乐、古典主义时期音乐、早期浪漫主义音乐、盛期浪漫主义音乐、中后期浪漫主义音乐、晚期浪漫主义音乐、民族主义音乐与20世纪音乐。每一章内容既包含对核心知识点的讲解和释疑，又加入了重难点专题与案例剖析、学科前沿与跨学科拓展等高阶学习模块，并配有多级理论习题与兼具趣味性、挑战度的实践活动。
本书不仅总结了经典的西方音乐史教学内容，还根据时代发展与新时代教学需要加入了深度学研内容，如西方音乐在中国的发展、西音史研究方法、西音史理论流派、音乐教育以及西方女性音乐家和为音乐发展做出贡献的特殊群体等。本书根据新文科课程建设要求，创新性地吸纳音乐学与哲学、美学、心理学、建筑学、医学、法学、数学、物理学等相关学科的交叉知识，并有机融入美育与思政元素。
本书可作为高等院校音乐学等相关专业的教学用书，也可作为西方音乐爱好者的参考资料。', 36.00, 28.80, 311, '本书以西方音乐的发展历史为主线，主体结构共分为十二章：古希腊和古罗马音乐、中世纪音乐、文艺复兴时期音乐、巴洛克音乐、前古典主义时期音乐、古典主义时期音乐、早期浪漫主义音乐、盛期浪漫主义音乐、中后期浪漫主义音乐、晚期浪漫主义音乐、民族主义音乐与20世纪音乐。每一章内容既包含对核心知识点的讲解和释疑，又加入了重难点专题与案例剖析、学科前沿与跨学科拓展等高阶学习模块，并配有多级理论习题与兼具趣味性、挑战度的实践活动。
本书不仅总结了经典的西方音乐史教学内容，还根据时代发展与新时代教学需要加入了深度学研内容，如西方音乐在中国的发展、西音史研究方法、西音史理论流派、音乐教育以及西方女性音乐家和为音乐发展做出贡献的特殊群体等。本书根据新文科课程建设要求，创新性地吸纳音乐学与哲学、美学、心理学、建筑学、医学、法学、数学、物理学等相关学科的交叉知识，并有机融入美育与思政元素。
本书可作为高等院校音乐学等相关专业的教学用书，也可作为西方音乐爱好者的参考资料。', '前言
