  ('245', '本教材坚持“以学生为主体，以情境活动任务为主导，以能力培养为宗旨”，以商务谈判能力为核心，以英语语言运用为主线，内容涵盖了国际贸易中交易磋商活动的全部内容。教材共计12个单元，包括公司和产品介绍、产品推销、询盘和报盘、价格磋商、佣金和折扣、质量和数量、支付方式、包装、运输、保险、交易达成和合同签订、索赔和理赔，内容具有很强的针对性和实用价值。教材将思政与商务谈判有机融合，以践行社会主义核心价值观；深化校企合作，在行业专家的参与下，为学生创造真实的语言学习环境；有效利用音视频等多媒体资源，帮助学生理解重难点和进行口语训练。教材可供商务英语、国际商务、国际贸易、跨境电商等专业学生学习，也可作为从事国际贸易、国际商务的企事业工作人员及广大商务英语爱好者的学习参考用书。', 46.00, 36.80, 2175, '本教材坚持“以学生为主体，以情境活动任务为主导，以能力培养为宗旨”，以商务谈判能力为核心，以英语语言运用为主线，内容涵盖了国际贸易中交易磋商活动的全部内容。教材共计12个单元，包括公司和产品介绍、产品推销、询盘和报盘、价格磋商、佣金和折扣、质量和数量、支付方式、包装、运输、保险、交易达成和合同签订、索赔和理赔，内容具有很强的针对性和实用价值。教材将思政与商务谈判有机融合，以践行社会主义核心价值观；深化校企合作，在行业专家的参与下，为学生创造真实的语言学习环境；有效利用音视频等多媒体资源，帮助学生理解重难点和进行口语训练。教材可供商务英语、国际商务、国际贸易、跨境电商等专业学生学习，也可作为从事国际贸易、国际商务的企事业工作人员及广大商务英语爱好者的学习参考用书。', '前言
