  ('244', '《英语短篇小说教程》于2010年由高等教育出版社出版，是普通高等教育“十一五”国家级规划教材，2011年被评为教育部“精品教材”。第二版教材出版于2019年，是依托爱课程 MOOC 的新形态教材。该书系统地介绍了英语短篇小说的相关知识，内容丰富，语言地道，对于全面提高学生的文学素养有很大的帮助。适合英语专业本科生、研究生和其他具有较好英语语言能力的学生使用。本教材使课堂学习和在线学习互为补充，使教师讲授和学生自主学习相结合，满足学生的个性化学习需要。', 56.00, 44.80, 1659, '《英语短篇小说教程》于2010年由高等教育出版社出版，是普通高等教育“十一五”国家级规划教材，2011年被评为教育部“精品教材”。第二版教材出版于2019年，是依托爱课程 MOOC 的新形态教材。该书系统地介绍了英语短篇小说的相关知识，内容丰富，语言地道，对于全面提高学生的文学素养有很大的帮助。适合英语专业本科生、研究生和其他具有较好英语语言能力的学生使用。本教材使课堂学习和在线学习互为补充，使教师讲授和学生自主学习相结合，满足学生的个性化学习需要。', '前言
