  ('243', '本教材作为融媒体、交互式、智能化数字教材，全书内容以就业为导向，以国家职业标准和数控车铣（中级）职业技能等级标准为基本依据，通过数控车床编程与加工技术、数控铣床/加工中心编程与加工技术、数控车铣（中级）考证综合训练3个情境，讲授数控车削和铣削加工基础，简单回转轴类零件、阶梯轴类零件、螺纹轴类零件、复杂轴类零件、简单零件铣削、孔类零件钻削和复杂零件铣削的编程与加工，以及数控车铣（中级）职业技能综合训练。
在内容上，本教材通过虚拟仿真软件，介绍目前广泛使用的发那科系统和西门子系统；在结构上，本教材体现岗课赛证的融合，遵循学习规律和技能形成规律，前后知识形成简单到复杂的任务序列，学习任务之间相互关联构成任务链，既有新知识点和技能点的补充，也包括已有知识点和技能点的拓展训练；在任务设计上，本教材将知识、技能及素质要求等要素进行整合，由简单到复杂，形成任务序列，最终培养读者数控加工编程的综合能力。
本教材嵌入了大量的微课、动画、虚拟仿真等视频资源，并对重点词加以提炼，方便读者学习。可作为职业本科院校成人高校及高等职业院校开设的数控专业和机械设计制造及自动化专业等相关专业的教学用书，也可作为相关行业人员的参考资料。', 45.80, 36.64, 486, '本教材作为融媒体、交互式、智能化数字教材，全书内容以就业为导向，以国家职业标准和数控车铣（中级）职业技能等级标准为基本依据，通过数控车床编程与加工技术、数控铣床/加工中心编程与加工技术、数控车铣（中级）考证综合训练3个情境，讲授数控车削和铣削加工基础，简单回转轴类零件、阶梯轴类零件、螺纹轴类零件、复杂轴类零件、简单零件铣削、孔类零件钻削和复杂零件铣削的编程与加工，以及数控车铣（中级）职业技能综合训练。
在内容上，本教材通过虚拟仿真软件，介绍目前广泛使用的发那科系统和西门子系统；在结构上，本教材体现岗课赛证的融合，遵循学习规律和技能形成规律，前后知识形成简单到复杂的任务序列，学习任务之间相互关联构成任务链，既有新知识点和技能点的补充，也包括已有知识点和技能点的拓展训练；在任务设计上，本教材将知识、技能及素质要求等要素进行整合，由简单到复杂，形成任务序列，最终培养读者数控加工编程的综合能力。
本教材嵌入了大量的微课、动画、虚拟仿真等视频资源，并对重点词加以提炼，方便读者学习。可作为职业本科院校成人高校及高等职业院校开设的数控专业和机械设计制造及自动化专业等相关专业的教学用书，也可作为相关行业人员的参考资料。', '前言
绪论
情境一 数控车床编程与加工技术
　项目一 数控车削加工基础
　　任务一 认识数控车床和车削加工
　　任务二 认识数控车床的坐标系
　　任务三 认识数控车削程序
　项目二 简单回转轴类零件编程与加工
　　任务一 短轴编程加工
　　任务二 圆弧类零件编程加工
　　任务三 轴套类零件编程加工
　　任务四 数控车床仿真模拟加工
　项目三 阶梯轴类零件编程与加工
　　任务一 简单阶梯轴编程加工
　　任务二 复杂阶梯轴编程加工
　　任务三 槽类零件编程加工
　项目四 螺纹轴类零件编程与加工
　　任务一 简单螺纹车削编程加工
　　任务二 复合螺纹切削循环车削编程加工
　　任务三 螺纹轴编程加工
　项目五 复杂轴类零件编程与加工
　　任务一 数控车削的子程序编程
　　任务二 数控车削的宏程序编程
情境二 数控铣床/加工中心编程与加工技术
　项目六 数控铣削加工基础
　　任务一 认识数控铣床/加工中心的类型与结构
　　任务二 认识数控铣床/加工中心的坐标系
　　任务三 认识数控铣削程序
　项目七 简单零件铣削编程与加工
　　任务一 平面和沟槽编程加工
　　任务二 数控铣床刀具半径补偿
　　任务三 简单零件轮廓编程加工
　　任务四 数控铣削仿真软件模拟加工
　项目八 孔类零件钻削的数控编程
　　任务一 简单孔类零件的数控编程
　　任务二 深孔类零件的数控编程
　　任务三 螺纹孔类零件的数控编程
　　任务四 镗孔类零件的数控编程
　　任务五 均匀分布孔系零件的数控编程
　项目九 复杂零件的编程与加工
　　任务一 使用子程序编程加工
　　任务二 使用图形变换指令编程加工
　　任务三 使用参数编程加工
情境三 “1+X”数控车铣（中级）职业技能综合训练
　项目十 “1+X”数控车床中级综合训练
　项目十一 “1+X”数控铣床中级综合训练
参考文献'),
  ('242', '本书针对近三年苏州大学创新创业课程“现代物理学在创新创业中的应用”课程案例，立足教学过程中学生的探究主体地位，以学生视角审视创新案例，按学生思维逻辑编写而成。
本书打破了创新实践教学中教师主导地位，变教师主讲为朋辈学习；扩大了物理教学案例的学科范畴，贴近生活，启迪思考。为了更好地体现我们教学过程中的朋辈学习的力量和教学传承的效果，本书配套的多媒体资源将不断更新，希望读者可以跟着我们的教学进程，体会到创新创业案例升级迭代的乐趣。', 20.00, 16.00, 112, '本书针对近三年苏州大学创新创业课程“现代物理学在创新创业中的应用”课程案例，立足教学过程中学生的探究主体地位，以学生视角审视创新案例，按学生思维逻辑编写而成。
本书打破了创新实践教学中教师主导地位，变教师主讲为朋辈学习；扩大了物理教学案例的学科范畴，贴近生活，启迪思考。为了更好地体现我们教学过程中的朋辈学习的力量和教学传承的效果，本书配套的多媒体资源将不断更新，希望读者可以跟着我们的教学进程，体会到创新创业案例升级迭代的乐趣。', '前言
