  ('241', 'Outline
Essential University Physics Experiment is one of the series of textbooks of the National Experimental Teaching Demonstration Center of the School of Physical Science and Technology of Soochow University. It is compiled by summarizing long-term experimental teaching experience. It is a newly compiled textbook for the English teaching course of college physics experiment.
Essential University Physics Experiment introduces the basic knowledge about measurement error and data processing, the introduction of common experimental instruments, and the basic methods and techniques of physical experiments. It is classified according to mechanics and thermodynamics, electromagnetism and optics, and includes 36 experiments. The new textbook emphasizes the comprehensive application of experimental theories, methods and skills, and pay attention to the cultivation of students'' independent experimental ability, analysis and research ability and innovation ability.
Essential University Physics Experiment can be used as a college physics experiment textbook for non-physics majored students of science and engineering in colleges and universities, and also as a reference book for experimental technicians or teachers of related courses.
江苏省高等学校重点教材编号：2021-2-175', 18.00, 14.40, 56, 'Outline
Essential University Physics Experiment is one of the series of textbooks of the National Experimental Teaching Demonstration Center of the School of Physical Science and Technology of Soochow University. It is compiled by summarizing long-term experimental teaching experience. It is a newly compiled textbook for the English teaching course of college physics experiment.
Essential University Physics Experiment introduces the basic knowledge about measurement error and data processing, the introduction of common experimental instruments, and the basic methods and techniques of physical experiments. It is classified according to mechanics and thermodynamics, electromagnetism and optics, and includes 36 experiments. The new textbook emphasizes the comprehensive application of experimental theories, methods and skills, and pay attention to the cultivation of students'' independent experimental ability, analysis and research ability and innovation ability.
Essential University Physics Experiment can be used as a college physics experiment textbook for non-physics majored students of science and engineering in colleges and universities, and also as a reference book for experimental technicians or teachers of related courses.
