  ('240', '我们已进入数字化与智能化时代，教育资源的数字化和“智慧+教育”将成为常态。本数字教材集聚了编者建设的优质课程、优质教材、优质资源，其以学习者为中心，以全新的方式呈现教材内容。
本数字教材以“信号表示、系统描述”为内涵，主要阐述信号和系统的时域分析、频域分析和复频域分析，揭示信号与系统在时域和变换域的内在作用机理。教材采用连续和离散并行、先时域后变换域的体系结构，以信号分析为基础，从信号表示的角度引入信号的变换，进而达成不同域下的系统描述。
本数字教材围绕“为什么、是什么、做什么”展开知识模块，通过简洁清晰的表述和生动丰富的案例诠释教学内容，强调基本理论、基本概念和基本方法，淡化计算技巧，引入MATLAB作为信号与系统分析的工具。
本数字教材提供了内容提要、教学目标、正文内容、重点难点分析、自测题、思考题、习题等教学素材，并配置了思维导图、重点词、H5交互、PPT、视频、音频、动画图形等多媒体资源。教学内容阐述清晰，表述严谨，数字资源丰富多维，有助于学习者在获取知识的同时，锻炼高阶思维能力。
本数字教材可作为电子信息工程、通信工程、信息工程、自动化、生物医学工程、计算机等专业的本科生教材，也可供有关科技工作者自学参考。', 28.00, 22.40, 1539, '我们已进入数字化与智能化时代，教育资源的数字化和“智慧+教育”将成为常态。本数字教材集聚了编者建设的优质课程、优质教材、优质资源，其以学习者为中心，以全新的方式呈现教材内容。
