  ('239', '本教材可供民航相关专业的学生了解民航发展历程和前沿知识、理解民航文化和民航精神、围绕民航话题进行英语语言技能训练，也可作为民航爱好者学习的科普读物。教材围绕民航话题，实践语言教学“产出导向”原则，培养学生语言知识与语言能力“迁移”的能力、批判性思维能力、用英语分析和解决实际问题的能力。篇章选材来自真实民航语境，帮助学生了解民航技术、体验民航文化、感受民航精神。基于民航情境设计教学活动，在完成任务的过程中发展语言能力和交际能力，为学生的“语言表现”提供有效输出途径。教材依托高教社数字教材云平台，构建立体化教学资源，保障线上线下混合式教学的实现，为移动学习与自主学习提供有效的内容支撑。', 56.00, 44.80, 263, '本教材可供民航相关专业的学生了解民航发展历程和前沿知识、理解民航文化和民航精神、围绕民航话题进行英语语言技能训练，也可作为民航爱好者学习的科普读物。教材围绕民航话题，实践语言教学“产出导向”原则，培养学生语言知识与语言能力“迁移”的能力、批判性思维能力、用英语分析和解决实际问题的能力。篇章选材来自真实民航语境，帮助学生了解民航技术、体验民航文化、感受民航精神。基于民航情境设计教学活动，在完成任务的过程中发展语言能力和交际能力，为学生的“语言表现”提供有效输出途径。教材依托高教社数字教材云平台，构建立体化教学资源，保障线上线下混合式教学的实现，为移动学习与自主学习提供有效的内容支撑。', '前言
