  ('238', '《高等数学数字教材》分上、下两册。上册主要内容包括函数、极限、连续，导数与微分，微分中值定理与导数的应用，不定积分，定积分，定积分的应用等6章。每章除了高等数学的经典内容外，还增加了典型例题与考研题选讲，以满足学有余力学生的个性化需求。本教材充分利用数字媒体表现形式丰富的特点，在本册中，绘制了250余幅精美彩色图形，制作了80多个形象动画，嵌入了50多个视频、12个H5自主学习模型和12个绘图工具。 本教材可用作高等学校高等数学课程的主教材，也可作为教学参考书供读者参考。', 68.00, 54.40, 857, '《高等数学数字教材》分上、下两册。上册主要内容包括函数、极限、连续，导数与微分，微分中值定理与导数的应用，不定积分，定积分，定积分的应用等6章。每章除了高等数学的经典内容外，还增加了典型例题与考研题选讲，以满足学有余力学生的个性化需求。本教材充分利用数字媒体表现形式丰富的特点，在本册中，绘制了250余幅精美彩色图形，制作了80多个形象动画，嵌入了50多个视频、12个H5自主学习模型和12个绘图工具。 本教材可用作高等学校高等数学课程的主教材，也可作为教学参考书供读者参考。', '前言
