  ('237', '本书以现代测量学观点全面介绍了心理测量学的理论与技术，侧重测量理论与技术在实践中的应用。学生可从中学到系统的心理测量学基础知识，为未来的理论研究、继续深造积蓄力量；也可学到实用的测量学操作技术，为未来的实践应用打好基础。同时，本书关联了丰富的数字资源，有助于学生的学习与教师的教学。
本书可供心理学、应用心理学、教育学和人力资源管理等专业教学使用，也可供需要心理测量学理论知识与实用技术的学习者、工作者和研究者参考。', 43.80, 35.04, 489, '本书以现代测量学观点全面介绍了心理测量学的理论与技术，侧重测量理论与技术在实践中的应用。学生可从中学到系统的心理测量学基础知识，为未来的理论研究、继续深造积蓄力量；也可学到实用的测量学操作技术，为未来的实践应用打好基础。同时，本书关联了丰富的数字资源，有助于学生的学习与教师的教学。
本书可供心理学、应用心理学、教育学和人力资源管理等专业教学使用，也可供需要心理测量学理论知识与实用技术的学习者、工作者和研究者参考。', '前言
