  ('236', '本书入选普通高等教育“十一五”本科国家级规划教材，第1版入选教育部“全国教师教育优秀课程资源”；第3版荣获“2017年精品阅读年度好书”。
第4版教材从内容的严谨性、学科发展的实效性出发，对各章节重点内容、作品资源链接、微课、作品导读等做了进一步打磨、更新。修订后的第4版教材依然分为上、中、下三编，共十四章。上编为基本理论，重在介绍儿童文学的基本原理、历史和今天、创作主体与接受对象、文本特征。中编为基本文体，主要介绍韵文类、幻想类、散文类、写实类、图画书类、综合艺术类等儿童文学类型；各章的章后附有与本章内容相吻合的优秀儿童文学作品及导读，以帮助学生加强对文体知识的理解。下编为教学应用，重在对儿童文学的应用进行方法论指导，包括儿童文学的编创、阅读指导以及儿童文学与小学习作教学等内容。教材整体保持了前三版适度的理论性、较强的知识性、鲜明的时代性、明显的实用性和实施的可操作性等特点。
本教材各章由章首语、正文、微课、资源链接、作品导读、探究·讨论·实践构成，网络学习资源包括教学大纲、教学设计、学习指南、学习方法、教学课件、教学资源等。
本书可作为高等院校小学教育专业教材，也可作为在职小学教师继续教育、自学进修参考书。', 42.00, 33.60, 287, '本书入选普通高等教育“十一五”本科国家级规划教材，第1版入选教育部“全国教师教育优秀课程资源”；第3版荣获“2017年精品阅读年度好书”。
第4版教材从内容的严谨性、学科发展的实效性出发，对各章节重点内容、作品资源链接、微课、作品导读等做了进一步打磨、更新。修订后的第4版教材依然分为上、中、下三编，共十四章。上编为基本理论，重在介绍儿童文学的基本原理、历史和今天、创作主体与接受对象、文本特征。中编为基本文体，主要介绍韵文类、幻想类、散文类、写实类、图画书类、综合艺术类等儿童文学类型；各章的章后附有与本章内容相吻合的优秀儿童文学作品及导读，以帮助学生加强对文体知识的理解。下编为教学应用，重在对儿童文学的应用进行方法论指导，包括儿童文学的编创、阅读指导以及儿童文学与小学习作教学等内容。教材整体保持了前三版适度的理论性、较强的知识性、鲜明的时代性、明显的实用性和实施的可操作性等特点。
本教材各章由章首语、正文、微课、资源链接、作品导读、探究·讨论·实践构成，网络学习资源包括教学大纲、教学设计、学习指南、学习方法、教学课件、教学资源等。
本书可作为高等院校小学教育专业教材，也可作为在职小学教师继续教育、自学进修参考书。', '上编 基本理论
