主要参考文献'),
  ('235', '太极拳是世界人类非物质文化遗产名录项目，它从历史长河中走来。作为中华民族优秀传统文化的一块瑰宝，太极拳协调舒缓的身体语言中，既有隽永的哲学文化思想，更蕴含着丰富的育人资源。
本数字教材是中国首部太极拳数字教材，由曾获得世界太极拳冠军、全运会太极拳全能冠军、国际级运动健将的国家级精品在线开放课程教学名师，湖北省“楚天名师”、武汉理工大学硕士生导师易鹏教授编著。他培养了多名高校太极拳比赛冠军，并通过多项教学研究成果，对太极拳教学如何适应现代化生活的新要求，进行了深入的探索，通过本数字教材的建设，进一步丰富完善了太极拳教材体系，从而使太极拳教学更加生活化、现代化、国际化。
太极拳数字教材是一种形式新颖、资源优化、实现"教与学"互动的智能教材，它展现了“课上课下、线上线下”立体教学新模式，使中国优秀传统文化与现代信息手段深度互融，形成了生动活泼、易教易学的教学特点。通过“‘互联网’+精品课程+教材+数字教材”，有效地将优质教学资源向国内外辐射，实现了太极拳教育从“一维面向技术学习”向“多维面向技术、知识和价值引领”的转变。本太极拳数字教材包括理论文化、科学习练、重点套路、技击实战、健康养生、特殊教育、问题打卡、鉴赏评价等内容。
生活无处不太极，一趟奇妙兴奋的健康旅行等着你。来吧，同学们！加入太极拳的学习队伍，让易鹏教授带着你我开启太极拳学习的新征程！', 56.00, 44.80, 1644, '太极拳是世界人类非物质文化遗产名录项目，它从历史长河中走来。作为中华民族优秀传统文化的一块瑰宝，太极拳协调舒缓的身体语言中，既有隽永的哲学文化思想，更蕴含着丰富的育人资源。
