  ('234', '本书针对物理学类专业学生对物理学基本规律的逻辑关系、发展历程以及实用性了解的需要，广泛参考专家意见后编写而成。
全书由绪论和第一至第六章组成。绪论部分描述了物理学大厦的轮廓，第一至第六章分别概述了机械运动、热运动、电磁现象、光现象、微观世界、时空结构等领域的知识体系的逻辑关系、发展历程和应用案例。全书用 105 个 AR 演示、25 个动画演示、206 个实物演示形象地展现了相关物理规律及其应用案例，以118 位科学巨匠的传记配音展现了科学家对物理相关领域的贡献。作者针对本书的编著体系配套了全程的授课视频、文字配音以及AR 演示、动画演示、实物演示等多种演示资源。授课教师通过 Email 联系作者（zhanghz@jlu.edu.cn），可获得配套的课件，这些课件可为教师的授课提供信息化教学保障。
本书旨在帮助和引领物理学类专业本科生加深对物理学的宏观认识，可作为普通高等学校物理学类专业“物理学导论”课程的教材，亦可作为其他专业相关课程的辅助参考书。', 30.00, 24.00, 1025, '本书针对物理学类专业学生对物理学基本规律的逻辑关系、发展历程以及实用性了解的需要，广泛参考专家意见后编写而成。
全书由绪论和第一至第六章组成。绪论部分描述了物理学大厦的轮廓，第一至第六章分别概述了机械运动、热运动、电磁现象、光现象、微观世界、时空结构等领域的知识体系的逻辑关系、发展历程和应用案例。全书用 105 个 AR 演示、25 个动画演示、206 个实物演示形象地展现了相关物理规律及其应用案例，以118 位科学巨匠的传记配音展现了科学家对物理相关领域的贡献。作者针对本书的编著体系配套了全程的授课视频、文字配音以及AR 演示、动画演示、实物演示等多种演示资源。授课教师通过 Email 联系作者（zhanghz@jlu.edu.cn），可获得配套的课件，这些课件可为教师的授课提供信息化教学保障。
本书旨在帮助和引领物理学类专业本科生加深对物理学的宏观认识，可作为普通高等学校物理学类专业“物理学导论”课程的教材，亦可作为其他专业相关课程的辅助参考书。', '绪论 物理学大厦概述
　1. 物理学研究内容分类
