  ('232', '本书是为适应数学学科本科生教学、面向21世纪进行改革的需要，结合吉林大学数学分析教学多年来教学实践的经验、体会编写而成的. 作者从内容的安排、思维方法的训练等方面进行改革，作了一些有益的尝试。
本书的主要内容包括极限论初步、微分学、积分学、无穷级数论、多元函数的微分学、多元函数的积分学、广义积分与含参变量的积分以及变分法等.
本书可作为综合性大学和高等师范大学数学专业教材，同时也可供其他对数学要求相对较高的专业的学生或研究人员选用。', 99.90, 79.92, 581, '本书是为适应数学学科本科生教学、面向21世纪进行改革的需要，结合吉林大学数学分析教学多年来教学实践的经验、体会编写而成的. 作者从内容的安排、思维方法的训练等方面进行改革，作了一些有益的尝试。
