  ('231', '本书是储能科学与工程新兴领域“十四五”高等教育教材体系建设规划项目成果，共分8章，第1章介绍了“双碳”目标背景下可再生能源利用及存储的重要意义、可再生能源利用技术概述及发展趋势，第2-6章系统地阐述了太阳能、风能、水能及海洋能、生物质能和地热能的资源分布、工作原理、主要利用技术及工艺技术进展，第7-8章全面论述了规模化储能技术分类、技术原理与储能技术规模布局和储能技术在可再生能源领域应用，对规模化储能技术的发展前景与趋势进行了深入分析和总结。
本书既有对可再生能源利用与存储技术的类别、原理的详细论述，又有对行业总体态势的分析和对未来发展前景的思考，尤其注重对各类可再生能源利用与存储技术和产业化发展现状的分析介绍，具有较强的实用性和前瞻性。本书可作为能源、化工、环境等领域的学生、研究人员和工程师等的教材与参考材料，也为今后从事可再生能源利用和存储领域的深入研究与开发奠定相关的理论与技术基础。', 30.00, 24.00, 235, '本书是储能科学与工程新兴领域“十四五”高等教育教材体系建设规划项目成果，共分8章，第1章介绍了“双碳”目标背景下可再生能源利用及存储的重要意义、可再生能源利用技术概述及发展趋势，第2-6章系统地阐述了太阳能、风能、水能及海洋能、生物质能和地热能的资源分布、工作原理、主要利用技术及工艺技术进展，第7-8章全面论述了规模化储能技术分类、技术原理与储能技术规模布局和储能技术在可再生能源领域应用，对规模化储能技术的发展前景与趋势进行了深入分析和总结。
本书既有对可再生能源利用与存储技术的类别、原理的详细论述，又有对行业总体态势的分析和对未来发展前景的思考，尤其注重对各类可再生能源利用与存储技术和产业化发展现状的分析介绍，具有较强的实用性和前瞻性。本书可作为能源、化工、环境等领域的学生、研究人员和工程师等的教材与参考材料，也为今后从事可再生能源利用和存储领域的深入研究与开发奠定相关的理论与技术基础。', '总序/前言
