  ('230', '本书共分为8个章节。第一章绪论介绍电化学发展简史、电化学技术应用和电化学学科研究对象。第二章介绍电化学热力学基础知识，包括电化学体系结构与组成、系列电极电位间逻辑关系。第三章电化学动力学基础知识，包括电化学控制步骤和极化的规律。第四章介绍电化学电源，包括各类一次电池和二次电池的结构特点和工作特性。第五章介绍电化学催化，包括电催化机理和典型的催化电极反应。第六章介绍光电化学，包括半导体能带结构特点、半导体光电化学特性和保护技术。第七章介绍电化学腐蚀，包括各类电池的腐蚀特点、核电材料的腐蚀行为以及油气装备材料的腐蚀特征。第八章介绍电化学测试技术，包括测试原理和测量方法。', 19.80, 15.84, 461, '本书共分为8个章节。第一章绪论介绍电化学发展简史、电化学技术应用和电化学学科研究对象。第二章介绍电化学热力学基础知识，包括电化学体系结构与组成、系列电极电位间逻辑关系。第三章电化学动力学基础知识，包括电化学控制步骤和极化的规律。第四章介绍电化学电源，包括各类一次电池和二次电池的结构特点和工作特性。第五章介绍电化学催化，包括电催化机理和典型的催化电极反应。第六章介绍光电化学，包括半导体能带结构特点、半导体光电化学特性和保护技术。第七章介绍电化学腐蚀，包括各类电池的腐蚀特点、核电材料的腐蚀行为以及油气装备材料的腐蚀特征。第八章介绍电化学测试技术，包括测试原理和测量方法。', '前言
