  ('229', '本书是先进轨道交通新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，全面介绍了“先进轨道交通”相关专业的国内外发展现状及课程教材建设情况。我国高速列车轻量化技术发展位居世界前列，安全服役性能也得到了国家、集团和路局等项目支持和研究，这些新研究及其所形成的系列成果未得到充分总结和宣传。同时，国铁集团相继布局了时速400公里列车轻量化技术重大项目，重大研发计划中连续多年关注到轻质高强材料在先进轨道交通中的典型场景应用。本数字教材立足既有轨道车辆结构强度可靠性基础，全面系统总结世界范围内轨道车辆轻量化技术途径和安全评价保障技术，展望和吸纳虚拟样机、大数据、大系统等新理念、新技术，并通过我国高速轨道车辆轻量化及安全设计的典型评估案例，共同思考未来五到十年现代轨道车辆的结构设计、制造及安全保障技术。', 48.00, 38.40, 37, '本书是先进轨道交通新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，全面介绍了“先进轨道交通”相关专业的国内外发展现状及课程教材建设情况。我国高速列车轻量化技术发展位居世界前列，安全服役性能也得到了国家、集团和路局等项目支持和研究，这些新研究及其所形成的系列成果未得到充分总结和宣传。同时，国铁集团相继布局了时速400公里列车轻量化技术重大项目，重大研发计划中连续多年关注到轻质高强材料在先进轨道交通中的典型场景应用。本数字教材立足既有轨道车辆结构强度可靠性基础，全面系统总结世界范围内轨道车辆轻量化技术途径和安全评价保障技术，展望和吸纳虚拟样机、大数据、大系统等新理念、新技术，并通过我国高速轨道车辆轻量化及安全设计的典型评估案例，共同思考未来五到十年现代轨道车辆的结构设计、制造及安全保障技术。', '前 言
