  ('228', '发展新能源汽车是我国由汽车大国迈向汽车强国的必由之路，也是推动新能源革命，实现“碳达峰、碳中和”目标的重要途径。随着新能源汽车产业的高速发展，车用动力系统不断迭代更新，前沿技术也随之涌现，然而，现有车辆动力方面的专业教材主要面向传统燃油汽车行业，建设明显滞后于技术的发展水平，难以满足目前产业对复合创新人才提出的新需求。面对新能源汽车技术和产业的快速发展，凝练新能源汽车动力知识体系、总结工程经验、展望技术趋势的工作越来越重要。因此，我们提出新编《车用新能源与动力》教材。
根据我国车用新能源与动力技术开发和产业化“三纵三横”布局，《车用新能源与动力》教材系统规划了车用新能源及动力系统的基础理论和系统集成技术。本书共五章，第一章为概述，介绍了全球能源转型之路、能源与动力发展史、国内外车用系能源与动力发展战略、车用动力分类、车用动力对比，分析了国内外车用新能源与动力系统的当期发展实践及技术发展趋势。第二章至第五章为主要技术分类，包括锂离子动力电池、氢燃料电池、高效发动机与低碳燃料技术、新能源驱动电机及动力耦合方式等关键技术等。第二章聚焦锂离子动力电池的发展现状及前沿技术，涵盖了电动汽车采用的相关动力电池体系，从锂离子电池的基础知识、电池组的系统集成与管理、动力电池成组与应用技术、动力电池的发展趋势等方面进行了全方位、全产业链的介绍。第三章聚焦氢燃料电池体系，分为燃料电池的分类、氢能产业链、氢燃料电池的结构、氢燃料电池发动机技术共五个小节，全面介绍了燃料电池从关键材料、零部件、发动机系统、储氢系统及动力系统的相关技术。第四章聚焦高效发动机与低碳燃料技术，介绍了混合动力专用发动机技术、低碳燃料发动机技术、零碳燃料发动机技术，总结了发展新型内燃机需要解决的关键技术。第五章聚焦驱动电机及动力耦合方式的发展，针对不同类型电动汽车对驱动电机的应用需求，系统地分析和梳理了驱动电机的类型、车用电机的布置形式、各类动力耦合方式的理论基础及工程化设计技术，突出驱动电机在电动汽车中的应用解决方案。
总之，新能源动力系统是车辆、机电、电化学、热能技术等多学科融合的工业制成品，设计与制造相关车辆离不开具备交叉融合的跨学科知识和创新意识的复合型人才。教材的编写将拓宽人才知识结构宽度和深度，完善材料化学、能源化学、电化学等基础知识，拓展车辆、机电、热能等专业知识广度全面解决应用创新人才培养与产业需求适配度低的问题。
本书依托北京理工大学机械与车辆学院车用新能源与动力团队，由王震坡主编，李磊、王志福、王欣、翟双等参与构思、编排并通稿，其中，王震坡、李磊参与了前言与第一章、第二章的编写，翟双参与了第三章的编写，王欣参与了第四章的编写，王志福参与了第五章的编写。特别鸣谢上海重塑能源科技有限公司的高雷先生对本书出版所提供的宝贵建议，及党永淳、韩长灏、邝达宏、余永超、刘现晨等同学在教材编撰中的辛苦付出。', 30.00, 24.00, 205, '发展新能源汽车是我国由汽车大国迈向汽车强国的必由之路，也是推动新能源革命，实现“碳达峰、碳中和”目标的重要途径。随着新能源汽车产业的高速发展，车用动力系统不断迭代更新，前沿技术也随之涌现，然而，现有车辆动力方面的专业教材主要面向传统燃油汽车行业，建设明显滞后于技术的发展水平，难以满足目前产业对复合创新人才提出的新需求。面对新能源汽车技术和产业的快速发展，凝练新能源汽车动力知识体系、总结工程经验、展望技术趋势的工作越来越重要。因此，我们提出新编《车用新能源与动力》教材。
根据我国车用新能源与动力技术开发和产业化“三纵三横”布局，《车用新能源与动力》教材系统规划了车用新能源及动力系统的基础理论和系统集成技术。本书共五章，第一章为概述，介绍了全球能源转型之路、能源与动力发展史、国内外车用系能源与动力发展战略、车用动力分类、车用动力对比，分析了国内外车用新能源与动力系统的当期发展实践及技术发展趋势。第二章至第五章为主要技术分类，包括锂离子动力电池、氢燃料电池、高效发动机与低碳燃料技术、新能源驱动电机及动力耦合方式等关键技术等。第二章聚焦锂离子动力电池的发展现状及前沿技术，涵盖了电动汽车采用的相关动力电池体系，从锂离子电池的基础知识、电池组的系统集成与管理、动力电池成组与应用技术、动力电池的发展趋势等方面进行了全方位、全产业链的介绍。第三章聚焦氢燃料电池体系，分为燃料电池的分类、氢能产业链、氢燃料电池的结构、氢燃料电池发动机技术共五个小节，全面介绍了燃料电池从关键材料、零部件、发动机系统、储氢系统及动力系统的相关技术。第四章聚焦高效发动机与低碳燃料技术，介绍了混合动力专用发动机技术、低碳燃料发动机技术、零碳燃料发动机技术，总结了发展新型内燃机需要解决的关键技术。第五章聚焦驱动电机及动力耦合方式的发展，针对不同类型电动汽车对驱动电机的应用需求，系统地分析和梳理了驱动电机的类型、车用电机的布置形式、各类动力耦合方式的理论基础及工程化设计技术，突出驱动电机在电动汽车中的应用解决方案。
总之，新能源动力系统是车辆、机电、电化学、热能技术等多学科融合的工业制成品，设计与制造相关车辆离不开具备交叉融合的跨学科知识和创新意识的复合型人才。教材的编写将拓宽人才知识结构宽度和深度，完善材料化学、能源化学、电化学等基础知识，拓展车辆、机电、热能等专业知识广度全面解决应用创新人才培养与产业需求适配度低的问题。
本书依托北京理工大学机械与车辆学院车用新能源与动力团队，由王震坡主编，李磊、王志福、王欣、翟双等参与构思、编排并通稿，其中，王震坡、李磊参与了前言与第一章、第二章的编写，翟双参与了第三章的编写，王欣参与了第四章的编写，王志福参与了第五章的编写。特别鸣谢上海重塑能源科技有限公司的高雷先生对本书出版所提供的宝贵建议，及党永淳、韩长灏、邝达宏、余永超、刘现晨等同学在教材编撰中的辛苦付出。', '前言
