  ('227', '本教材运用丰富、详实的案例，较为系统地阐释了幼儿园教育活动设计的理论和实践。涵盖了“幼儿园教育活动概述”“幼儿园五大领域教育活动”“幼儿园区域活动”“幼儿园思政教育活动”“幼儿园一日生活活动”“家园共育和社区活动”等内容。在结构与选材上，以《幼儿园教育指导纲要（试行）》《3~6 岁儿童学习与发展指南》为理论依据，回应了幼儿核心经验发展、课程思政等重要问题，凸显了区域学前教育课程发展的基本情况及对国家政策导向的贯彻和落实。本教材既有利于学习教育活动设计的基本理论，又有助于学习者学习学前教育优秀案例。
在体例上，每章设置了“学习目标”“知识导图”“师生互动”“思考与实训”栏目，同时，一些具有代表性的案例视频以二维码形式提供在章节相应位置，方便学习者扫码学习。', 51.00, 40.80, 246, '本教材运用丰富、详实的案例，较为系统地阐释了幼儿园教育活动设计的理论和实践。涵盖了“幼儿园教育活动概述”“幼儿园五大领域教育活动”“幼儿园区域活动”“幼儿园思政教育活动”“幼儿园一日生活活动”“家园共育和社区活动”等内容。在结构与选材上，以《幼儿园教育指导纲要（试行）》《3~6 岁儿童学习与发展指南》为理论依据，回应了幼儿核心经验发展、课程思政等重要问题，凸显了区域学前教育课程发展的基本情况及对国家政策导向的贯彻和落实。本教材既有利于学习教育活动设计的基本理论，又有助于学习者学习学前教育优秀案例。
