  ('226', '本书是教育部战略性新兴领域“十四五”高等教育教材体系建设项目的研究成果，全面介绍了“智能网联和新能源汽车”相关专业的国内外发展现状及课程教材建设情况。新一轮科技革命与产业变革加速演进，智能网联汽车成为跨行业、多领域先进技术集成应用的载体，也将成为万物互联时代驱动智能交通、智慧能源、智慧城市深度融合发展的超级终端。智能座舱是智能汽车各类新技术的综合应用空间，能够为驾乘人员提供高安全性、舒适性与宜人性驾乘体验，是传统汽车制造业向智能汽车产业生态升级的入口，是汽车智能化、网联化、电动化与共享化的最佳交汇点。汽车由单一的出行工具向“第三生活空间”演进，座舱的形态、功能以及交互方式逐步发生变化，已从传统“人适应车”，逐步转变为“车适应人”，并向着未来“人车相互适应”的自然交互服务发展演进。
本书详尽探讨了汽车智能座舱的架构、技术、创新与服务，共分8章，涵盖了智能座舱的硬件支撑技术、系统软件技术、乘坐舒适技术、多模态交互技术、舱内感知技术、信息应用技术以及前瞻技术与发展趋势，兼顾内容的完整性、广度与深度。
本书可作为高等学校车辆工程专业的参考书，也可供汽车智能座舱技术研究与应用等行业的有关人员学习参考。
图书在版编目（CIP）数据', 49.00, 39.20, 109, '本书是教育部战略性新兴领域“十四五”高等教育教材体系建设项目的研究成果，全面介绍了“智能网联和新能源汽车”相关专业的国内外发展现状及课程教材建设情况。新一轮科技革命与产业变革加速演进，智能网联汽车成为跨行业、多领域先进技术集成应用的载体，也将成为万物互联时代驱动智能交通、智慧能源、智慧城市深度融合发展的超级终端。智能座舱是智能汽车各类新技术的综合应用空间，能够为驾乘人员提供高安全性、舒适性与宜人性驾乘体验，是传统汽车制造业向智能汽车产业生态升级的入口，是汽车智能化、网联化、电动化与共享化的最佳交汇点。汽车由单一的出行工具向“第三生活空间”演进，座舱的形态、功能以及交互方式逐步发生变化，已从传统“人适应车”，逐步转变为“车适应人”，并向着未来“人车相互适应”的自然交互服务发展演进。
本书详尽探讨了汽车智能座舱的架构、技术、创新与服务，共分8章，涵盖了智能座舱的硬件支撑技术、系统软件技术、乘坐舒适技术、多模态交互技术、舱内感知技术、信息应用技术以及前瞻技术与发展趋势，兼顾内容的完整性、广度与深度。
本书可作为高等学校车辆工程专业的参考书，也可供汽车智能座舱技术研究与应用等行业的有关人员学习参考。
