  ('225', '本书是先进轨道交通战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果。本书以人因工程学理论与研究方法为基础、在“人-机-环-管”协同发展和系统工程理念支持下，构建我国轨道交通人因工程理论体系。本书分为基础理论、方法与应用两部分。基础理论部分，全面梳理近年来国际国内学科进展，系统搭建轨道交通人因安全工程理论体系，阐述交通运输信息化、智能化背景下，人的感觉、知觉特性，注意、记忆的特征与机制、思维与决策过程等；介绍人的行为失误机理，以及影响作业绩效与作业安全的诸多因素，如情绪、人格、疲劳、脑力负荷等；最后介绍了为应对新质生产力发展要求，对轨道交通人员安全管理提出的新标准与新趋势，包括运用马斯洛需求模型、需求激励理论、班组内的职权梯度设计、技能的动力定型等理论进行分析与研究。在方法与技术部分，结合轨道交通产业发展实际，将理论研究与产业实践相结合，提供典型解决方案和自主研发技术应用案例，包括职业胜任力测评、不安全作业状态评估与干预、智能仿真实训系统建设等。
本教材聚焦轨道交通领域，提供丰富真实的轨道交通研究案例，将理论与实际、知识和技能、基础知识与科学前沿相统一。本书可以作为交通运输工程、人机工程、安全工程、应用心理学等相关专业的本科生或研究生教材，也可以供轨道交通相关的研究人员和工程技术人员阅读参考。', 38.00, 30.40, 22, '本书是先进轨道交通战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果。本书以人因工程学理论与研究方法为基础、在“人-机-环-管”协同发展和系统工程理念支持下，构建我国轨道交通人因工程理论体系。本书分为基础理论、方法与应用两部分。基础理论部分，全面梳理近年来国际国内学科进展，系统搭建轨道交通人因安全工程理论体系，阐述交通运输信息化、智能化背景下，人的感觉、知觉特性，注意、记忆的特征与机制、思维与决策过程等；介绍人的行为失误机理，以及影响作业绩效与作业安全的诸多因素，如情绪、人格、疲劳、脑力负荷等；最后介绍了为应对新质生产力发展要求，对轨道交通人员安全管理提出的新标准与新趋势，包括运用马斯洛需求模型、需求激励理论、班组内的职权梯度设计、技能的动力定型等理论进行分析与研究。在方法与技术部分，结合轨道交通产业发展实际，将理论研究与产业实践相结合，提供典型解决方案和自主研发技术应用案例，包括职业胜任力测评、不安全作业状态评估与干预、智能仿真实训系统建设等。
本教材聚焦轨道交通领域，提供丰富真实的轨道交通研究案例，将理论与实际、知识和技能、基础知识与科学前沿相统一。本书可以作为交通运输工程、人机工程、安全工程、应用心理学等相关专业的本科生或研究生教材，也可以供轨道交通相关的研究人员和工程技术人员阅读参考。', '前言
