  ('224', '《轨道交通网络空间安全》是一本全面深入探讨轨道交通系统在数字化时代所面临的网络空间安全挑战的专业书籍。本书由闫连山、沈超、陈建译、李赛飞专家学者编著，汇集了他们在该领域的研究成果和实践经验。作为国家关键信息基础设施的重要组成部分，轨道交通系统的安全运行不仅关系到广大乘客的生命财产安全，也是国家稳定发展的关键。
本书是高等学校交通运输类、安全科学类、轨道交通、铁道工程、网络空间信息安全等相关专业的专业课教材。全书从系统性、前瞻性和实用性三个维度，构建了涵盖网络空间安全基础理论、技术应用、案例分析和安全策略建议的知识框架。本书是高等学校交通运输类、安全科学类、轨道交通、铁道工程、网络空间信息安全等相关专业的专业课教材。全书从系统性、前瞻性和实用性三个维度，构建了涵盖网络空间安全基础理论、技术应用、案例分析和安全策略建议的知识框架。全书共五章，主要包括轨道交通网络空间安全发展与挑战、基础理论、攻防技术与实践、关键设施专网安全、信号控制系统安全等内容。除作为教材，本书还适合轨道交通行业的管理者、技术人员及相关领域的研究等从业人员阅读参考。', 39.00, 31.20, 68, '《轨道交通网络空间安全》是一本全面深入探讨轨道交通系统在数字化时代所面临的网络空间安全挑战的专业书籍。本书由闫连山、沈超、陈建译、李赛飞专家学者编著，汇集了他们在该领域的研究成果和实践经验。作为国家关键信息基础设施的重要组成部分，轨道交通系统的安全运行不仅关系到广大乘客的生命财产安全，也是国家稳定发展的关键。
本书是高等学校交通运输类、安全科学类、轨道交通、铁道工程、网络空间信息安全等相关专业的专业课教材。全书从系统性、前瞻性和实用性三个维度，构建了涵盖网络空间安全基础理论、技术应用、案例分析和安全策略建议的知识框架。本书是高等学校交通运输类、安全科学类、轨道交通、铁道工程、网络空间信息安全等相关专业的专业课教材。全书从系统性、前瞻性和实用性三个维度，构建了涵盖网络空间安全基础理论、技术应用、案例分析和安全策略建议的知识框架。全书共五章，主要包括轨道交通网络空间安全发展与挑战、基础理论、攻防技术与实践、关键设施专网安全、信号控制系统安全等内容。除作为教材，本书还适合轨道交通行业的管理者、技术人员及相关领域的研究等从业人员阅读参考。', '前言
