  ('223', '《新大学英语:综合教程2》的每一个单元都是围绕一个具有实际意义的项目来设计的。项目的完成涉及一系列的语言活动。单元学习的结果即是意味着项目的完成。学习者不但需要从外界吸收语言形式，还要创造性地使用已有的语言材料，完成实际的交际任务，最终实现构建自己新的语言体系的目的。增强其自主学习能力，提高综合文化素养。
《新大学英语:综合教程2》为《综合教程》系列第二册，共8个单元，每个单元包含5个部分。第一部分（Part One：Warming up）是热身练习。该部分以阅读和视听材料的学习为主。第二部分（Part Two：Initializing the Project）通过一系列学习活动，让学生从语言、格式、文化、技巧等方面对本单元将要完成的项目进行学习。学习活动的设计既照顾到交际性，也包含对语言形式和文化知识的学习。第三部分（Part Three：Exploring the Field）是单元学习的重点。这一部分提供一到两个项目结果样本或参考文本等。第四部分（Part Four：Constructing the Project）是项目完成阶段，也是每个单元的核心部分。第五部分（Part Five：Assessing Learning）为学生提供一个反思的机会，回顾自己在本单元的学习过程中都做了些什么，学了些什么，效果如何，还有哪些欠缺之处，下一步有什么打算等。', 66.00, 52.80, 1097, '《新大学英语:综合教程2》的每一个单元都是围绕一个具有实际意义的项目来设计的。项目的完成涉及一系列的语言活动。单元学习的结果即是意味着项目的完成。学习者不但需要从外界吸收语言形式，还要创造性地使用已有的语言材料，完成实际的交际任务，最终实现构建自己新的语言体系的目的。增强其自主学习能力，提高综合文化素养。
