  ('222', '本书是作者在南京航空航天大学讲授近二十年“高等量子力学”课程讲义的基础上编写而成的，内容包括量子力学的数学基础、量子力学公理化体系简介、二次量子化、相干态简介以及量子力学中的格林函数。本书内容丰富、深入浅出、难度适中，内容的深度和广度符合多层次的教学要求，并且附有大量的例题与习题。
本书可作为凝聚态、材料、光学等专业研究生的教材，也可供高年级本科生学习高等量子力学课程使用。全书内容对应约80学时教学需求，使用本书的教师也可以按照自己的教学需要调整课时。', 18.00, 14.40, 1054, '本书是作者在南京航空航天大学讲授近二十年“高等量子力学”课程讲义的基础上编写而成的，内容包括量子力学的数学基础、量子力学公理化体系简介、二次量子化、相干态简介以及量子力学中的格林函数。本书内容丰富、深入浅出、难度适中，内容的深度和广度符合多层次的教学要求，并且附有大量的例题与习题。
本书可作为凝聚态、材料、光学等专业研究生的教材，也可供高年级本科生学习高等量子力学课程使用。全书内容对应约80学时教学需求，使用本书的教师也可以按照自己的教学需要调整课时。', 'Preface
