  ('221', '本教材是融媒体、交互式、智能化数字教材，主要介绍建筑电气、建筑给排水、采暖、通风空调工程计量与计价方法。教材内容围绕工程造价行业典型工作任务展开，按照工作难度由简单到复杂分成7个类别，每个类别对应2套案例工程任务。教材在专业内容中穿插了与安装工程造价工作相关的课程思政栏目，在学习者完成知识目标、技能目标的过程中，帮助其达成素养目标的培养。
本教材重要的知识点、技能点均配有微课、习题库等数字资源供在线浏览或测评，学习者在学习本教材的同时还可登录智慧职教（www.icve.com.cn）或智慧职教MOOC学院（mooc.icve.com.cn）搜索课程“安装工程计量与计价”进行在线学习。教材配套CAD图纸、相关定额表，可发邮件至gztj@pub.hep.cn获取。
本教材适合高等职业院校工程造价专业学生学习使用，也可供从事工程造价工作的专业技术人员使用。', 49.80, 39.84, 172, '本教材是融媒体、交互式、智能化数字教材，主要介绍建筑电气、建筑给排水、采暖、通风空调工程计量与计价方法。教材内容围绕工程造价行业典型工作任务展开，按照工作难度由简单到复杂分成7个类别，每个类别对应2套案例工程任务。教材在专业内容中穿插了与安装工程造价工作相关的课程思政栏目，在学习者完成知识目标、技能目标的过程中，帮助其达成素养目标的培养。
