后记'),
  ('220', '本书通过讲解各类茶来识茶之文化、比制茶之工艺、品泡茶之技法，采用教师操作示范、文字与视频资源有效整合的方式编写。
本书包含6个项目：项目一“茶之源”，介绍了茶的发展历史；项目二“茶之路”，介绍了茶叶生产与鉴赏的知识；项目三“茶之类”，介绍了绿茶、白茶、黄茶、红茶、青茶、黑茶、普洱茶七大茶类；项目四“茶之美态”，介绍了茶器之美、茶席之美、茶人之美；项目五“民俗茶艺”，介绍了白族三道茶、客家擂茶、油茶、奶茶、藏族酥油茶、傣族竹筒茶等中国传统非遗技艺的知识；项目六“茶与健康”，介绍了茶的科学饮法等知识。
本书可作为高等职业院校、中等职业学校酒店管理与数字化运营及相关专业的教学用书，也可供社会从业者的培训教材、还可供茶艺爱好者参考阅读。', 42.00, 33.60, 437, '本书通过讲解各类茶来识茶之文化、比制茶之工艺、品泡茶之技法，采用教师操作示范、文字与视频资源有效整合的方式编写。
本书包含6个项目：项目一“茶之源”，介绍了茶的发展历史；项目二“茶之路”，介绍了茶叶生产与鉴赏的知识；项目三“茶之类”，介绍了绿茶、白茶、黄茶、红茶、青茶、黑茶、普洱茶七大茶类；项目四“茶之美态”，介绍了茶器之美、茶席之美、茶人之美；项目五“民俗茶艺”，介绍了白族三道茶、客家擂茶、油茶、奶茶、藏族酥油茶、傣族竹筒茶等中国传统非遗技艺的知识；项目六“茶与健康”，介绍了茶的科学饮法等知识。
本书可作为高等职业院校、中等职业学校酒店管理与数字化运营及相关专业的教学用书，也可供社会从业者的培训教材、还可供茶艺爱好者参考阅读。', '前言
