  ('219', '本教材为产品艺术设计专业的专业基础课程教材，包含初识图像表达、选区图像表达、形状图像表达、常见材质表达、平面设计表达、走进KeyShot渲染、收音机时钟渲染、单戒圈渲染、白色充电器渲染、走进C4D三维世界10个项目，通过项目、任务化的体例设置将Photoshop、KeySot、Cinema 4D三款软件使用的知识点和技能点分解到每个项目中，强化学生职业素养的养成和图像表达专业知识的积累，有效将课程思政内容、职业素养和工匠精神通过项目融入教材，全面落实立德树人根本任务。
本教材配有丰富的数字资源，读者在教材中即可进行视频观摩、学习，图片可放大查看，知识点交互学习，更加丰富读者的阅读体验。
