  ('218', '随着城市轨道交通的快速发展，相关的企业急需具备城市轨道交通运营专业知识的技能型人才，这为职业教育城市轨道交通专业的发展带来良好的机遇。
本书采用项目-任务的形式编写，以国家职业标准为依据，以综合职业能力培养为目标，以典型工作任务为载体，以学生为中心，将理论知识和实践技能相结合，并基于企业真实场景，展现行业新业态、新水平、新技术。配合教学开发微课视频、动画等数字资源，帮助学生理解教材中的重点和难点。
本书主要包括：城市轨道交通车站设备概述；城市轨道交通车站自动售检票系统；城市轨道交通车站楼梯、电梯及自动扶梯；城市轨道交通车站站台安全门运行与维护；城市轨道交通低压配电与照明系统；城市轨道交通车站消防系统；城市轨道交通车站暖通空调系统；城市轨道交通环境与设备监控系统8个项目，共33个任务。
本书可作为高等职业教育城市轨道交通运营管理专业的核心课程教材，也可作为城市轨道交通机电技术等其他相关专业的拓展课程教材，还可作为相关企业岗前培训用书。', 39.80, 31.84, 53, '随着城市轨道交通的快速发展，相关的企业急需具备城市轨道交通运营专业知识的技能型人才，这为职业教育城市轨道交通专业的发展带来良好的机遇。
本书采用项目-任务的形式编写，以国家职业标准为依据，以综合职业能力培养为目标，以典型工作任务为载体，以学生为中心，将理论知识和实践技能相结合，并基于企业真实场景，展现行业新业态、新水平、新技术。配合教学开发微课视频、动画等数字资源，帮助学生理解教材中的重点和难点。
