  ('217', '本教材为高等职业教育城市轨道交通类数字教材。根据城市轨道交通站务人员典型工作任务，设计了城市轨道交通车站及设备认知、站台门的操作、电梯的操作、消防设备设施的操作、通风空调系统的操作、低压配电及照明系统的管理、给排水系统的管理、自动售检票系统的操作和车站综合监控系统的管理，共9个项目。针对每个项目下的相关任务，设计了工作手册，并配套了微课、实操视频等数字化资源。
