  ('216', '本教材为全国城市轨道交通专业教学资源库课程“城市轨道交通低压配电与照明系统”的配套教材。本教材完整阐述了城市轨道交通低压配电及照明系统的基础知识和设备维护实训知识，将理论和实际操作相结合，重点培养地铁运营维护人员的操作应用能力。全书共3个单元：单元一为低压配电基础，介绍城市轨道交通低压配电的基础知识；单元二为城市轨道交通低压配电系统，介绍环控电控柜，冷水机组启动柜，地铁事故照明装置，配电箱、电源切换箱、车辆段配电柜，低压风机就地控制箱，水泵控制箱，集束母线及电线、电缆等设备认知、操作、维护和检修；单元三为城市轨道交通照明系统，介绍照明基础知识，车站低压照明系统，照明电气设计，常见照明故障及现场处理，低压照明系统的维护，电气火灾监控系统等。
本教材重/难点知识点配有微课、视频等丰富的数字化资源，直接在线学习、浏览。
本教材可供高等职业院校、应用型本科院校城市轨道交通机电类相关专业教学选用，也可供从事城市轨道交通站务、机电维修等工作的技术及管理人员学习参考。', 33.80, 27.04, 58, '本教材为全国城市轨道交通专业教学资源库课程“城市轨道交通低压配电与照明系统”的配套教材。本教材完整阐述了城市轨道交通低压配电及照明系统的基础知识和设备维护实训知识，将理论和实际操作相结合，重点培养地铁运营维护人员的操作应用能力。全书共3个单元：单元一为低压配电基础，介绍城市轨道交通低压配电的基础知识；单元二为城市轨道交通低压配电系统，介绍环控电控柜，冷水机组启动柜，地铁事故照明装置，配电箱、电源切换箱、车辆段配电柜，低压风机就地控制箱，水泵控制箱，集束母线及电线、电缆等设备认知、操作、维护和检修；单元三为城市轨道交通照明系统，介绍照明基础知识，车站低压照明系统，照明电气设计，常见照明故障及现场处理，低压照明系统的维护，电气火灾监控系统等。
本教材重/难点知识点配有微课、视频等丰富的数字化资源，直接在线学习、浏览。
本教材可供高等职业院校、应用型本科院校城市轨道交通机电类相关专业教学选用，也可供从事城市轨道交通站务、机电维修等工作的技术及管理人员学习参考。', '前言
