  ('215', '本书为全国城市轨道交通专业教学资源库课程“城市轨道交通职业素养与礼仪”的配套教材。全书以城市轨道交通服务工作过程为导向，分为三大模块：认知城市轨道交通职业素养（模块一）、规划职业生涯（模块二）、城市轨道交通职业礼仪（模块三），以轨道交通实际岗位服务内容为引领，每个模块下设对应的项目及任务，详细介绍了城市轨道交通职业素养与礼仪的相关内容。
本书可作为高职、中职院校城市轨道交通专业及相关专业的基础教材，同时也可供从事城市轨道交通服务工作的专业技术人员培训使用。', 39.80, 31.84, 76, '本书为全国城市轨道交通专业教学资源库课程“城市轨道交通职业素养与礼仪”的配套教材。全书以城市轨道交通服务工作过程为导向，分为三大模块：认知城市轨道交通职业素养（模块一）、规划职业生涯（模块二）、城市轨道交通职业礼仪（模块三），以轨道交通实际岗位服务内容为引领，每个模块下设对应的项目及任务，详细介绍了城市轨道交通职业素养与礼仪的相关内容。
本书可作为高职、中职院校城市轨道交通专业及相关专业的基础教材，同时也可供从事城市轨道交通服务工作的专业技术人员培训使用。', '前言
