  ('214', '内容简介
本书是国家职业教育城市轨道交通专业教学资源库课程“城市轨道交通专用通信设备维护”的配套教材，介绍城市轨道交通专用通信系统的原理和维护，阐述城市轨道交通通信设备维护的基本知识和通信工岗位检修作业示范。全书共分为8个单元，包括城市轨道交通专用通信系统概述、城市轨道交通电话系统、城市轨道交通无线集群系统、城市轨道交通广播系统、城市轨道交通时钟系统、城市轨道交通视频监视系统、城市轨道交通乘客信息系统、城市轨道交通通信电源及接地系统，以及各单元的任务实施、任务拓展和思考与练习。
本书可作为高等职业院校、职教本科的城市轨道交通通信信号专业的专用通信系统及设备维护的课程教材，也可作为通信相关从业人员的参考及企业培训教材。', 39.90, 31.92, 38, '内容简介
本书是国家职业教育城市轨道交通专业教学资源库课程“城市轨道交通专用通信设备维护”的配套教材，介绍城市轨道交通专用通信系统的原理和维护，阐述城市轨道交通通信设备维护的基本知识和通信工岗位检修作业示范。全书共分为8个单元，包括城市轨道交通专用通信系统概述、城市轨道交通电话系统、城市轨道交通无线集群系统、城市轨道交通广播系统、城市轨道交通时钟系统、城市轨道交通视频监视系统、城市轨道交通乘客信息系统、城市轨道交通通信电源及接地系统，以及各单元的任务实施、任务拓展和思考与练习。
本书可作为高等职业院校、职教本科的城市轨道交通通信信号专业的专用通信系统及设备维护的课程教材，也可作为通信相关从业人员的参考及企业培训教材。', '前言
