  ('213', '本教材是高等职业教育装备制造大类专业课程新形态数字教材。本教材介绍了生产、生活和科学研究等领域常用传感器的工作原理、结构组成、特性参数、测量电路和使用方法等知识。在实际的工作任务中介绍各类传感器的选用原则、检测系统的设计方法和检测技术的工程应用等知识；通过企业的实际工程案例介绍行业领先的新技术、新工艺、新方法和新规程；融入传感网应用开发和智能制造生产线集成应用职业技能等级证书要求；关注智能传感器和多传感器融合技术等前沿科学技术。本教材具有较强的实用性和可操作性，满足育训结合教学改革的需求。同时将思政教育、安全教育和劳动教育融入课程教学内容，潜移默化地培养学习者的爱国情怀，以及精益求精、吃苦耐劳的工匠精神。本教材分为8个项目：项目1介绍传感器与自动检测技术的基础知识；项目2至项目7分别介绍压力检测技术、位移检测技术、速度检测技术、物位检测技术、温度检测技术和环境量检测技术以及各类传感器的典型应用；项目8介绍智能传感器和多传感器融合技术。本教材包含丰富的动画和微视频等信息化教学资源，读者可在教材中直接点击浏览、学习。本教材可以作为高等职业院校自动化类、机电类、电子信息类、仪器仪表类、机械制造类相关专业的教学用书，也可供其他工程技术人员和社会从业人员参考。', 45.00, 36.00, 267, '本教材是高等职业教育装备制造大类专业课程新形态数字教材。本教材介绍了生产、生活和科学研究等领域常用传感器的工作原理、结构组成、特性参数、测量电路和使用方法等知识。在实际的工作任务中介绍各类传感器的选用原则、检测系统的设计方法和检测技术的工程应用等知识；通过企业的实际工程案例介绍行业领先的新技术、新工艺、新方法和新规程；融入传感网应用开发和智能制造生产线集成应用职业技能等级证书要求；关注智能传感器和多传感器融合技术等前沿科学技术。本教材具有较强的实用性和可操作性，满足育训结合教学改革的需求。同时将思政教育、安全教育和劳动教育融入课程教学内容，潜移默化地培养学习者的爱国情怀，以及精益求精、吃苦耐劳的工匠精神。本教材分为8个项目：项目1介绍传感器与自动检测技术的基础知识；项目2至项目7分别介绍压力检测技术、位移检测技术、速度检测技术、物位检测技术、温度检测技术和环境量检测技术以及各类传感器的典型应用；项目8介绍智能传感器和多传感器融合技术。本教材包含丰富的动画和微视频等信息化教学资源，读者可在教材中直接点击浏览、学习。本教材可以作为高等职业院校自动化类、机电类、电子信息类、仪器仪表类、机械制造类相关专业的教学用书，也可供其他工程技术人员和社会从业人员参考。', '前言
