  ('212', '本教材贯彻落实党的二十大关于“重视心理健康和精神卫生”的相关要求，依据《高等学校学生心理健康教育指导纲要》等文件精神，针对高职大学生的身心特点和心理发展规律编写而成。
本教材涵盖大学生普遍关注的心理健康、自我意识、人际交往、情绪管理、学习心理、压力管理、恋爱与性、生命教育、生涯规划九个模块，各模块从学生身边的案例导入，从认知、体验和调适的角度层层递进、贯穿主题，既保证心理健康教育的知识传授，又强化心理健康方法与技能的训练。在理论讲解的过程中穿插视频连线、小贴士、活动体验、心理测试、思考题和阅读导航等内容，丰富学习情境，力图构建兼具实用性和交互性的立体化教学空间，同时将探索、创新的精神，自信、友善的品格与合作、互助的理念融入其中，注重知识传授、能力培养、素质教育的融合。
本教材既可以作为高职院校大学生心理健康教育课程的教学用书，也可供关注心理健康养成、有意从事社会心理服务工作的相关人员学习，亦可作为企业员工心理培训的指导用书。', 38.80, 31.04, 649, '本教材贯彻落实党的二十大关于“重视心理健康和精神卫生”的相关要求，依据《高等学校学生心理健康教育指导纲要》等文件精神，针对高职大学生的身心特点和心理发展规律编写而成。
本教材涵盖大学生普遍关注的心理健康、自我意识、人际交往、情绪管理、学习心理、压力管理、恋爱与性、生命教育、生涯规划九个模块，各模块从学生身边的案例导入，从认知、体验和调适的角度层层递进、贯穿主题，既保证心理健康教育的知识传授，又强化心理健康方法与技能的训练。在理论讲解的过程中穿插视频连线、小贴士、活动体验、心理测试、思考题和阅读导航等内容，丰富学习情境，力图构建兼具实用性和交互性的立体化教学空间，同时将探索、创新的精神，自信、友善的品格与合作、互助的理念融入其中，注重知识传授、能力培养、素质教育的融合。
本教材既可以作为高职院校大学生心理健康教育课程的教学用书，也可供关注心理健康养成、有意从事社会心理服务工作的相关人员学习，亦可作为企业员工心理培训的指导用书。', '前言
