  ('211', '本教材分为两篇，共9个模块，第一篇路基施工技术，内容包括路基施工准备、一般路基施工、特殊路基施工、路基防护与支挡工程施工和路基排水工程施工；第二篇路面施工技术，内容包括路面施工准备、路面基层（底基层）施工技术、沥青路面施工技术和水泥混凝土路面施工技术。
本教材既可作为高等职业技术院校道路与桥梁工程技术、建设工程监理、工程造价等专业教材，又可作为成人教育相关专业培训教材，还可供工程技术人员学习参考。', 39.80, 31.84, 132, '本教材分为两篇，共9个模块，第一篇路基施工技术，内容包括路基施工准备、一般路基施工、特殊路基施工、路基防护与支挡工程施工和路基排水工程施工；第二篇路面施工技术，内容包括路面施工准备、路面基层（底基层）施工技术、沥青路面施工技术和水泥混凝土路面施工技术。
