  ('210', '本书包括土工试验与工程地质勘察报告阅读应用、土石方工程施工、深基坑工程施工、特殊（软弱）地基处理工程施工、基础工程施工5个教学单元，按照项目任务式结构进行编写，结合具体的工程实践项目，注重对学生专业技能的训练和职业素养的培养。
本书可作为高等职业院校建筑工程技术、装配式建筑工程技术、智能建造技术、工程监理、工程造价等专业的课程教材，也可作为在职建筑工程技术人员的岗位培训教材，还可作为建筑工程管理人员的自学参考用书。', 36.80, 29.44, 85, '本书包括土工试验与工程地质勘察报告阅读应用、土石方工程施工、深基坑工程施工、特殊（软弱）地基处理工程施工、基础工程施工5个教学单元，按照项目任务式结构进行编写，结合具体的工程实践项目，注重对学生专业技能的训练和职业素养的培养。
本书可作为高等职业院校建筑工程技术、装配式建筑工程技术、智能建造技术、工程监理、工程造价等专业的课程教材，也可作为在职建筑工程技术人员的岗位培训教材，还可作为建筑工程管理人员的自学参考用书。', '前言
