  ('209', '本书为城市轨道交通专业课程国家教学资源库配套教材。全书分为四个单元，分别是企业文化认知、企业文化建设、地铁行业企业文化和我国典型城市地铁企业文化。从企业文化的通用理论知识入手，介绍企业文化的内涵作用和企业文化建设，阐述地铁行业企业文化的共性特点，并重点分析我国北京、上海和广州三大城市地铁企业文化。
本书的主要特色有：
（1）内容充实，将企业文化理论与企业文化建设实践充分结合。既有特大城市地铁企业成熟的企业文化分析，又有快速发展中的城市地铁企业文化介绍。高职院校可根据所在城市需要灵活选择教学单元。本书每一单元配套学习目标和单元练习题，可以有效巩固学习成果。
（2）教材坚持立德树人，全书贯彻爱国、爱城、爱企、爱岗的核心价值理念，弘扬轨道交通企业发展历程中积淀的优秀企业文化，有利于引导学生形成文化认同感。
（3）基于高教出版社“高教云书”平台，打造融媒体交互式智能化数字教材。采用适宜的多媒体教学资源表现教材内容，编写风格深入浅出，图文并茂， 穿插大量企业文化最新案例，贴合高职学生擅于立体化获取信息的学习特点，可读性强。平台界面友好、易于应用和传播。
本书反映轨道交通行业企业文化最新建设成果，既可以作为高等职业院校教学用书，也可以作为地铁从业人员自学读物。', 38.80, 31.04, 33, '本书为城市轨道交通专业课程国家教学资源库配套教材。全书分为四个单元，分别是企业文化认知、企业文化建设、地铁行业企业文化和我国典型城市地铁企业文化。从企业文化的通用理论知识入手，介绍企业文化的内涵作用和企业文化建设，阐述地铁行业企业文化的共性特点，并重点分析我国北京、上海和广州三大城市地铁企业文化。
本书的主要特色有：
（1）内容充实，将企业文化理论与企业文化建设实践充分结合。既有特大城市地铁企业成熟的企业文化分析，又有快速发展中的城市地铁企业文化介绍。高职院校可根据所在城市需要灵活选择教学单元。本书每一单元配套学习目标和单元练习题，可以有效巩固学习成果。
（2）教材坚持立德树人，全书贯彻爱国、爱城、爱企、爱岗的核心价值理念，弘扬轨道交通企业发展历程中积淀的优秀企业文化，有利于引导学生形成文化认同感。
（3）基于高教出版社“高教云书”平台，打造融媒体交互式智能化数字教材。采用适宜的多媒体教学资源表现教材内容，编写风格深入浅出，图文并茂， 穿插大量企业文化最新案例，贴合高职学生擅于立体化获取信息的学习特点，可读性强。平台界面友好、易于应用和传播。
本书反映轨道交通行业企业文化最新建设成果，既可以作为高等职业院校教学用书，也可以作为地铁从业人员自学读物。', '前言
