  ('208', '本教材为根据高等职业院校学生的特点，结合教学改革与课程建设的工作思路而编写的创新型数字教材。本教材包括7个任务、18个子任务，主要内容包括安全用电与直流电路的分析、交流电路的连接与测量、变压器与三相异步电动机的认知与控制、直流稳压电源的分析与测试、小信号电压放大器的分析与测试、数码显示器的组装与调试、抢答器的组装与调试。每个任务后都附有相应的技能训练，同时配有习题及答案。
本教材内容丰富、重点突出、形式新颖，可作为高等职业院校装备制造大类、电子与信息大类相关专业的教材，也可供相关专业技术人员参考。', 40.00, 32.00, 1181, '本教材为根据高等职业院校学生的特点，结合教学改革与课程建设的工作思路而编写的创新型数字教材。本教材包括7个任务、18个子任务，主要内容包括安全用电与直流电路的分析、交流电路的连接与测量、变压器与三相异步电动机的认知与控制、直流稳压电源的分析与测试、小信号电压放大器的分析与测试、数码显示器的组装与调试、抢答器的组装与调试。每个任务后都附有相应的技能训练，同时配有习题及答案。
