参考文献'),
  ('207', '本书详细介绍常用的不可控型、半控型和全控型电力电子器件以及它们的应用基础，重点介绍整流（AC−DC）、逆变（DC−AC）、交流调压和交−交变频（AC−AC）、直流变换（DC−DC）四种电力变换方式所涉及的典型电力变换电路。
全书内容涵盖电力电子技术课程的大部分教学环节，便于教学使用。书中的电路图全部由PLECS、PSIM或MATLAB等仿真软件绘制并完成仿真。全书内容深入浅出，实用性强。
为强化实践技能的培养，本书基于PLECS、PSIM与MATLAB三种仿真软件，系统地针对上述典型电力变换电路进行仿真实验。该方法具有方便易学、实践性强的特点，可弥补学生平时实验训练不足的缺陷。
通过观察电力电子变换电路电压和电流的仿真波形，可以对所学习的电路有更加直观和深入的理解；可以通过仿真对即将进行的实验有一个全面的理解、预习和准备；可以通过仿真找到电路设计中可能存在的问题，并确定最优控制参数；通过仿真可以对实验室中不存在的实验电路或不方便学生使用的实验电路进行分析和学习。
本书可作为自动化类、机电设备类等专业电力电子技术课程的教材，也可作为相关工程技术人员的参考书。', 49.80, 39.84, 300, '本书详细介绍常用的不可控型、半控型和全控型电力电子器件以及它们的应用基础，重点介绍整流（AC−DC）、逆变（DC−AC）、交流调压和交−交变频（AC−AC）、直流变换（DC−DC）四种电力变换方式所涉及的典型电力变换电路。
