  ('206', '服装款式设计与表达是一门实践性强，且在服装设计与工艺专业有着广泛应用的核心课程。
本书包含服装设计师岗位能力，重塑款式设计，构成要素设计，设计基本方法应用，面料、色彩搭配设计，设计方法的综合运用六个模块，以实际款式案例，从设计、开发、制作等方面详细介绍了连衣裙、西装、衬衫、裤子、旗袍、运动服等款式服装的设计方法、面料选择及色彩搭配。
本书配有丰富的动画、视频、在线试题等数字资源，形成可听、可视、可练的多元化教材。本书可作为高等职业教育专科、本科，五年制高职及应用型本科院校服装设计与工艺专业、服装艺术设计专业的教学用书，也可供相关从业者参考学习。', 45.80, 36.64, 811, '服装款式设计与表达是一门实践性强，且在服装设计与工艺专业有着广泛应用的核心课程。
本书包含服装设计师岗位能力，重塑款式设计，构成要素设计，设计基本方法应用，面料、色彩搭配设计，设计方法的综合运用六个模块，以实际款式案例，从设计、开发、制作等方面详细介绍了连衣裙、西装、衬衫、裤子、旗袍、运动服等款式服装的设计方法、面料选择及色彩搭配。
本书配有丰富的动画、视频、在线试题等数字资源，形成可听、可视、可练的多元化教材。本书可作为高等职业教育专科、本科，五年制高职及应用型本科院校服装设计与工艺专业、服装艺术设计专业的教学用书，也可供相关从业者参考学习。', '前言
模块一 诠释概念——服装设计师岗位能力
　任务一 岗位认知——服装设计师岗位认知
　任务二 总结提炼——学会款式图表达方法
　任务三 寻找灵感——学会设计构思方法
模块二 外廓内型——重塑款式设计
　任务一 轮廓赋能——连衣裙款式设计
　任务二 结构重塑——西装款式设计
模块三 细节之美——构成要素设计
　任务一 局部之美——领子、袖子款式设计
　任务二 部件之美——口袋、门襟款式设计
　任务三 精工技艺——半裙款式设计
模块四 美学法则——设计基本方法应用
　任务一 点的应用——裤子款式设计
　任务二 线的应用——衬衫款式设计
　任务三 面的应用——夹克衫款式设计
　任务四 美学法则——连衣裙韵律设计
模块五 锦上添花——面料、色彩搭配设计
　任务一 匠心织造——连衣裙面料设计
　任务二 云舒霞卷——大衣配色设计
模块六 能力提升——设计方法的综合运用
