  ('205', '本教材为服装设计与工艺专业的核心课程教材，内容涵盖服装市场营销活动的整个过程，从基础认知，到营销机会分析，再到营销实务，根据营销任务层层递进构建内容体系，包含服装市场营销基础、服装市场机会分析、服装STP营销战略选择、服装4P营销策略组合、服装新媒体营销策略5个项目。
同时，本教材引入大量中国本土品牌营销成功案例，通过传统文化元素、思政案例、营销法律法规等引导学生树立文化自信、国货品牌自信，教导学生要诚实守信，做知法懂法的营销人，并配有视频、动画等数字化资源。
本教材可以作为高等职业教育专科、本科，应用型本科及中等职业教育服装设计与工艺等相关专业的教材，以及相关从业者的参考用书。', 46.80, 37.44, 150, '本教材为服装设计与工艺专业的核心课程教材，内容涵盖服装市场营销活动的整个过程，从基础认知，到营销机会分析，再到营销实务，根据营销任务层层递进构建内容体系，包含服装市场营销基础、服装市场机会分析、服装STP营销战略选择、服装4P营销策略组合、服装新媒体营销策略5个项目。
同时，本教材引入大量中国本土品牌营销成功案例，通过传统文化元素、思政案例、营销法律法规等引导学生树立文化自信、国货品牌自信，教导学生要诚实守信，做知法懂法的营销人，并配有视频、动画等数字化资源。
本教材可以作为高等职业教育专科、本科，应用型本科及中等职业教育服装设计与工艺等相关专业的教材，以及相关从业者的参考用书。', '前言
