  ('204', '本教程包括钢结构BIM建模基础知识、钢结构BIM建模软件操作、单层工业厂房钢结构BIM建模、钢结构BIM建模深化出图4部分内容，以Tekla软件为建模工具，以某单层工业厂房企业案例为任务载体，根据实际工程施工图纸，并依据《钢结构设计及施工规范》《BIM建模行业技术规范》等规范，由浅入深阐述钢结构BIM技术的应用。
本教材采用全新数字化编写模式，数字化资源形式多样，包括演示视频、微课、三维动画、虚拟仿真、教学课件、企业案例等。除此之外，教材还设计了知识链接、特别提示及推荐阅读资料等内容板块。此外，每个项目还附有单选题、多选题、判断题等多种题型供读者测试练习。通过对本教材的学习，读者可以掌握建筑钢结构BIM技术建模技能，培养建立钢结构BIM模型的能力。
本教材既可作为高职院校土建类相关专业的教材，也可作为“1+X”BIM证书考试的参考教材，还可作为钢结构施工单位详图深化设计人员入职学习培训资料。', 46.80, 37.44, 101, '本教程包括钢结构BIM建模基础知识、钢结构BIM建模软件操作、单层工业厂房钢结构BIM建模、钢结构BIM建模深化出图4部分内容，以Tekla软件为建模工具，以某单层工业厂房企业案例为任务载体，根据实际工程施工图纸，并依据《钢结构设计及施工规范》《BIM建模行业技术规范》等规范，由浅入深阐述钢结构BIM技术的应用。
本教材采用全新数字化编写模式，数字化资源形式多样，包括演示视频、微课、三维动画、虚拟仿真、教学课件、企业案例等。除此之外，教材还设计了知识链接、特别提示及推荐阅读资料等内容板块。此外，每个项目还附有单选题、多选题、判断题等多种题型供读者测试练习。通过对本教材的学习，读者可以掌握建筑钢结构BIM技术建模技能，培养建立钢结构BIM模型的能力。
本教材既可作为高职院校土建类相关专业的教材，也可作为“1+X”BIM证书考试的参考教材，还可作为钢结构施工单位详图深化设计人员入职学习培训资料。', '前言
项目一 钢结构BIM建模基础知识
　任务一 钢结构BIM建模概况
　任务二 建筑钢结构常用钢材的认知
　任务三 建筑钢结构连接的认知
　任务四 建筑钢结构杆件断面的认知
　任务五 建筑钢结构杆件连接的认知
　任务六 建筑钢结构中钢-混凝土剪力墙的认知
项目二 钢结构BIM建模软件操作
　任务一 钢结构BIM软件安装
　任务二 常用模型文件的设置
　任务三 钢结构BIM软件建模命令的操作
　任务四 钢结构BIM编辑命令操作
　任务五 常用辅助命令的操作
　任务六 模型文件中切割命令的操作
　任务七 CAD轮廓线导入模型视图操作
　任务八 钢结构BIM常用快捷键操作
项目三 单层工业厂房钢结构BIM建模
　任务一 创建厂房主结构模型
　任务二 创建厂房吊车梁系统模型
　任务三 创建厂房次结构模型
项目四 钢结构BIM建模深化出图
　任务一 审核深化设计模型
　任务二 创建设计模型中的布置图
　任务三 创建深化设计详图图纸
　任务四 导出CAD图纸及工程报表'),
  ('203', '工程地质与土力学是高等职业院校道路与桥梁工程技术专业的专业基础课程之一。本课程以工程地质学和土力学的基本理论为基础，培养学生今后能成为从事工程地质勘察与设计、地质灾害防治及岩土工程试验的建设单位技术人员、地质勘察设计院技术人员和施工企业技术人员。本书以交通土建类专业学生的就业为导向，根据行业专家对本专业所涵盖的岗位群进行的任务和职业能力分析，同时遵循高等职业院校学生的认知规律，紧密结合职业资格证书中相关的考核要求，确定本课程的学习内容。为了充分体现“任务引领、实践导向”的课程思想，本书共分8个学习情境，主要包括地质构造的认识及岩石性质、特殊土和不良地质作用、土的物理性质及工程分类、地下水、土中应力与地基变形计算、土的抗剪强度与地基承载力、土压力与土坡稳定分析、工程地质勘察等内容。同时，本书选择具有代表性的野外地质实习和岩土试验案例进行教学，以加深学生对课程内容的理解。此外，本书还根据技能培养与训练要求及可持续发展的需要，安排了必要的专业理论知识与能力训练项目。
本书可作为高等职业院校市政工程技术、建筑工程技术、水利工程、道路桥梁工程技术、智能建造技术等专业的课程教材，也可作为相关工程技术人员的参考用书。', 42.00, 33.60, 156, '工程地质与土力学是高等职业院校道路与桥梁工程技术专业的专业基础课程之一。本课程以工程地质学和土力学的基本理论为基础，培养学生今后能成为从事工程地质勘察与设计、地质灾害防治及岩土工程试验的建设单位技术人员、地质勘察设计院技术人员和施工企业技术人员。本书以交通土建类专业学生的就业为导向，根据行业专家对本专业所涵盖的岗位群进行的任务和职业能力分析，同时遵循高等职业院校学生的认知规律，紧密结合职业资格证书中相关的考核要求，确定本课程的学习内容。为了充分体现“任务引领、实践导向”的课程思想，本书共分8个学习情境，主要包括地质构造的认识及岩石性质、特殊土和不良地质作用、土的物理性质及工程分类、地下水、土中应力与地基变形计算、土的抗剪强度与地基承载力、土压力与土坡稳定分析、工程地质勘察等内容。同时，本书选择具有代表性的野外地质实习和岩土试验案例进行教学，以加深学生对课程内容的理解。此外，本书还根据技能培养与训练要求及可持续发展的需要，安排了必要的专业理论知识与能力训练项目。
本书可作为高等职业院校市政工程技术、建筑工程技术、水利工程、道路桥梁工程技术、智能建造技术等专业的课程教材，也可作为相关工程技术人员的参考用书。', '前言
