  ('202', '本教材以7个学习项目系统地介绍工业机器人各组成部分及其应用。项目1介绍工业机器人的基本概念、分类及发展，工业机器人的基本结构及典型应用。项目2首先介绍工业机器人的结构基础知识，然后在此基础上介绍六关节机器人的机械结构及关键零部件。项目3主要介绍工业机器人的控制与驱动系统。项目4介绍华数工业机器人的示教器的使用方法及手动操作方法。项目5在工业机器人示教编程概念的基础上，介绍工业机器人程序和文件管理办法以及指令系统。项目6通过几个实例，介绍华数工业机器人的典型应用。项目7介绍工业机器人的日常管理与维护技能。本教材配有在线开放课程和教学课件。
本教材适合作为职业院校工业机器人技术、智能机器人技术、机电一体化技术等专业及装备制造大类其他相关专业的教材，也可供相关技术人员参考。', 40.00, 32.00, 293, '本教材以7个学习项目系统地介绍工业机器人各组成部分及其应用。项目1介绍工业机器人的基本概念、分类及发展，工业机器人的基本结构及典型应用。项目2首先介绍工业机器人的结构基础知识，然后在此基础上介绍六关节机器人的机械结构及关键零部件。项目3主要介绍工业机器人的控制与驱动系统。项目4介绍华数工业机器人的示教器的使用方法及手动操作方法。项目5在工业机器人示教编程概念的基础上，介绍工业机器人程序和文件管理办法以及指令系统。项目6通过几个实例，介绍华数工业机器人的典型应用。项目7介绍工业机器人的日常管理与维护技能。本教材配有在线开放课程和教学课件。
本教材适合作为职业院校工业机器人技术、智能机器人技术、机电一体化技术等专业及装备制造大类其他相关专业的教材，也可供相关技术人员参考。', '前 言
