  ('201', '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材共十五章，介绍一般机械中常用机构和通用零部件的结构、运动特性、工作原理、工程应用，给出了带传动和齿轮传动的设计计算方法和步骤，力求能给学生一个完整的机械设计基础知识和基本思路，同时引入较新内容，如机构创新设计、非圆齿轮传动、弹性连接、盘形制动等。
本教材编写团队具有多年机械设计基础课程教学经验和资源开发经验，在教材中运用了大量的立体图例和实物图例，其目的在于化抽象平面图例为简捷形象的立体图例，帮助学生识读零部件图，学习掌握零部件结构及相互连接关系，有利于培养学生工程意识和分析问题、解决问题的能力。同时，对于复杂的过程给出了中间环节的动画，以利于学习者的理解。
本教材可供高等职业院校机械类、近机类专业学生使用，也可作为相关行业领域的职工培训教材，参考学时为60～80学时。', 46.80, 37.44, 285, '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材共十五章，介绍一般机械中常用机构和通用零部件的结构、运动特性、工作原理、工程应用，给出了带传动和齿轮传动的设计计算方法和步骤，力求能给学生一个完整的机械设计基础知识和基本思路，同时引入较新内容，如机构创新设计、非圆齿轮传动、弹性连接、盘形制动等。
本教材编写团队具有多年机械设计基础课程教学经验和资源开发经验，在教材中运用了大量的立体图例和实物图例，其目的在于化抽象平面图例为简捷形象的立体图例，帮助学生识读零部件图，学习掌握零部件结构及相互连接关系，有利于培养学生工程意识和分析问题、解决问题的能力。同时，对于复杂的过程给出了中间环节的动画，以利于学习者的理解。
本教材可供高等职业院校机械类、近机类专业学生使用，也可作为相关行业领域的职工培训教材，参考学时为60～80学时。', '前言
