  ('200', '本书依据最新的高等职业院校专业教学标准，对接“1+X”建筑工程识图职业技能等级标准（初级、中级），将建筑工程识图与AutoCAD绘图深度融合，与最新的国家标准规范紧密衔接，遵循“做中学、学中做”原则，循序渐进地介绍了点线面体基本原理、建筑施工图、结构施工图及其AutoCAD软件绘图步骤，图文并茂，内容丰富，实用性强。本书共十个模块，分别介绍了建筑制图概述、建筑制图标准的规定及运用、正投影的基本原理与绘制、施工图概述、建筑平面图的识读与绘制、建筑立面图的识读与绘制、建筑剖面图的识读与绘制、基础施工图的识读与绘制、结构平面图的识读与绘制、结构构件详图的识读与绘制。同时，本书还附有电子课件、画图练习、案例图样、上机实训及微课视频，供读者学习参考。
本书可以作为高职土建类专业的课程教材，也可作为AutoCAD软件培训的辅导教材，还可作为读者自学建筑识图与AutoCAD制图的教材或参考书。', 43.80, 35.04, 810, '本书依据最新的高等职业院校专业教学标准，对接“1+X”建筑工程识图职业技能等级标准（初级、中级），将建筑工程识图与AutoCAD绘图深度融合，与最新的国家标准规范紧密衔接，遵循“做中学、学中做”原则，循序渐进地介绍了点线面体基本原理、建筑施工图、结构施工图及其AutoCAD软件绘图步骤，图文并茂，内容丰富，实用性强。本书共十个模块，分别介绍了建筑制图概述、建筑制图标准的规定及运用、正投影的基本原理与绘制、施工图概述、建筑平面图的识读与绘制、建筑立面图的识读与绘制、建筑剖面图的识读与绘制、基础施工图的识读与绘制、结构平面图的识读与绘制、结构构件详图的识读与绘制。同时，本书还附有电子课件、画图练习、案例图样、上机实训及微课视频，供读者学习参考。
本书可以作为高职土建类专业的课程教材，也可作为AutoCAD软件培训的辅导教材，还可作为读者自学建筑识图与AutoCAD制图的教材或参考书。', '前言
