  ('199', '本教材旨在提供系统、全面的矿山地质学知识，培养学生在矿产资源勘查、开发、利用等方面的能力。教材以模块的形式进行编写，共10个项目，分别为地质基础认知项目，矿床、矿体与矿石认知项目，矿山地质工作简介项目，矿山地质图读图项目，矿山基本图件制图项目，矿山地质编录项目，矿山地质采样项目，生产勘探项目，矿山数字化项目，矿山矿产资源管理与生产指导项目。
