  ('198', '本教材为服装设计与工艺专业核心课程教材，包含课程导入、礼服基础型的立体裁剪、礼服立体裁剪的艺术表现手法、礼服立体裁剪企业真实项目和礼服的拓展知识五部分内容，旨在培养学生运用立体裁剪技术进行礼服的创意设计和立体造型，并将布样板修整转化成纸样板的职业能力，使学生会礼服款式设计、精礼服立体裁剪、懂礼服工艺制作，能适应礼服制版师或礼服设计师的工作要求。
本教材配有丰富的数字资源，教学视频与文字同步，读者在教材中即可进行视频观摩、学习；具体操作过程采用折叠展开设计，使操作步骤更为明晰；精致彩图可点击放大观察细部；内嵌自测练习等交互，更加丰富读者的阅读体验。
本教材可以作为高等职业教育专科、本科，应用型本科及中等职业教育服装设计与工艺等相关专业的教材，以及相关从业者的参考用书。', 49.80, 39.84, 190, '本教材为服装设计与工艺专业核心课程教材，包含课程导入、礼服基础型的立体裁剪、礼服立体裁剪的艺术表现手法、礼服立体裁剪企业真实项目和礼服的拓展知识五部分内容，旨在培养学生运用立体裁剪技术进行礼服的创意设计和立体造型，并将布样板修整转化成纸样板的职业能力，使学生会礼服款式设计、精礼服立体裁剪、懂礼服工艺制作，能适应礼服制版师或礼服设计师的工作要求。
本教材配有丰富的数字资源，教学视频与文字同步，读者在教材中即可进行视频观摩、学习；具体操作过程采用折叠展开设计，使操作步骤更为明晰；精致彩图可点击放大观察细部；内嵌自测练习等交互，更加丰富读者的阅读体验。
