  ('197', '随着全球环境问题的日益严重，绿色建筑作为可持续发展的重要组成部分，正逐渐受到广泛关注。本书紧密围绕党的二十大精神，以推进职业教育和数字化转型为目的，以项目为载体，全面而系统地介绍绿色建筑的理论与实践，涵盖设计原则、物理环境优化、模拟软件应用和技术实践等多个方面，并辅以丰富的案例解析。本书内容基于建筑学科，融合环境科学、能源工程、材料科学等多个学科的知识，展现跨学科的综合性和前沿性，参考国际先进的绿色建筑理念和技术，引用国际知名的绿色建筑案例，使读者能够接触国际前沿的绿色建筑理论与实践。本书实现了动态的、交互性的数字化形态转变，通过彩图、音频、视频、动画等多种形式呈现知识，并附有实训拓展任务、实际工程图纸和教学资料等。
本书不仅注重理论知识的传授，还强调实践应用能力的培养。通过大量的实践案例和实训锻炼，帮助学生将理论知识与实际操作相结合，提升解决实际问题的能力。本书可作为应用型本科院校、职业本科院校和高等职业院校土建类相关专业的教学用书。希望本书能为建筑学、城乡规划、环境科学等相关专业的学生和从业人员提供有益的指导，为职业教育发展奠定坚实的基础。', 36.80, 29.44, 99, '随着全球环境问题的日益严重，绿色建筑作为可持续发展的重要组成部分，正逐渐受到广泛关注。本书紧密围绕党的二十大精神，以推进职业教育和数字化转型为目的，以项目为载体，全面而系统地介绍绿色建筑的理论与实践，涵盖设计原则、物理环境优化、模拟软件应用和技术实践等多个方面，并辅以丰富的案例解析。本书内容基于建筑学科，融合环境科学、能源工程、材料科学等多个学科的知识，展现跨学科的综合性和前沿性，参考国际先进的绿色建筑理念和技术，引用国际知名的绿色建筑案例，使读者能够接触国际前沿的绿色建筑理论与实践。本书实现了动态的、交互性的数字化形态转变，通过彩图、音频、视频、动画等多种形式呈现知识，并附有实训拓展任务、实际工程图纸和教学资料等。
本书不仅注重理论知识的传授，还强调实践应用能力的培养。通过大量的实践案例和实训锻炼，帮助学生将理论知识与实际操作相结合，提升解决实际问题的能力。本书可作为应用型本科院校、职业本科院校和高等职业院校土建类相关专业的教学用书。希望本书能为建筑学、城乡规划、环境科学等相关专业的学生和从业人员提供有益的指导，为职业教育发展奠定坚实的基础。', '前言
