  ('196', '本教材从乒乓球技战术学习与健身娱乐相结合的理念出发，运用最新的教学方法和信息化手段，全方位、立体化、图文并茂地介绍了中国乒乓球运动发展史、乒乓球运动基本理论知识、乒乓球技术、乒乓球战术、乒乓球身体素质训练方法、中国优秀乒乓球运动员技术打法六章内容，完整地展现了乒乓球运动的魅力。
本教材既可作为职业院校乒乓球课程的专项教材，也可作为乒乓球运动员、教练员和不同水平乒乓球爱好者的参考用书。', 40.00, 32.00, 140, '本教材从乒乓球技战术学习与健身娱乐相结合的理念出发，运用最新的教学方法和信息化手段，全方位、立体化、图文并茂地介绍了中国乒乓球运动发展史、乒乓球运动基本理论知识、乒乓球技术、乒乓球战术、乒乓球身体素质训练方法、中国优秀乒乓球运动员技术打法六章内容，完整地展现了乒乓球运动的魅力。
本教材既可作为职业院校乒乓球课程的专项教材，也可作为乒乓球运动员、教练员和不同水平乒乓球爱好者的参考用书。', '前言
