  ('195', '本教材针对国内主流发电企业使用的300 MW和600 MW火电机组的检修工作进行讲解，从职业岗位能力出发，对接企业检修生产规程，注重吸收电力检修行业发展的新知识、新技术、新工艺。根据职业院校的教学特点，融入电力生产企业检修现场视频、图片，同时结合校内VR虚拟现实仿真学习资源，对热力设备的检修基础、方法、原理进行讲解，是一部深入浅出的数字教材。本教材分为检修工量具、零部件检修、单体设备检修、大型设备检修，共四篇。按照检修对象由小及大、由易到难的顺序编排。内容包括：管道检修、阀门检修、轴承检修、泵与风机检修、传动设备检修、锅炉检修、汽轮机本体检修。
本教材适用于高等职业院校热能动力工程技术、发电供热等专业教育教学使用，也可作为火力发电厂热能动力专业检修人员的培训教材和自学用书。', 59.00, 47.20, 112, '本教材针对国内主流发电企业使用的300 MW和600 MW火电机组的检修工作进行讲解，从职业岗位能力出发，对接企业检修生产规程，注重吸收电力检修行业发展的新知识、新技术、新工艺。根据职业院校的教学特点，融入电力生产企业检修现场视频、图片，同时结合校内VR虚拟现实仿真学习资源，对热力设备的检修基础、方法、原理进行讲解，是一部深入浅出的数字教材。本教材分为检修工量具、零部件检修、单体设备检修、大型设备检修，共四篇。按照检修对象由小及大、由易到难的顺序编排。内容包括：管道检修、阀门检修、轴承检修、泵与风机检修、传动设备检修、锅炉检修、汽轮机本体检修。
