  ('194', '色彩构成与设计是高等职业院校艺术设计类专业一年级学生必修的专业基础课程。
本教材共六章，分为色彩基础知识、色彩视觉感知、色彩构成、色彩设计、图像软件色彩应用、中国传统色彩体系，通过对不同色彩的选择和搭配进行合理的规划与运用，创造出各种视觉艺术效果，培养学生认识色彩，提升色彩感知力，掌握色彩设计的方法，能够在视觉艺术创作实践中合理地运用色彩创作出优秀的艺术作品，同时提升作品的美感和艺术性，传递信息和情感。
本教材可作为视觉传达设计、环境艺术设计、服装服饰设计、产品艺术设计、影视动画设计等艺术设计类专业的教学用书，也可供艺术设计爱好者参考使用。', 49.80, 39.84, 361, '色彩构成与设计是高等职业院校艺术设计类专业一年级学生必修的专业基础课程。
