  ('193', '设计色彩是高等教育院校艺术设计类的专业基础课，旨在提高学生色彩搭配能力、色彩形式转换能力、色彩创意表达能力、数字化应用能力和拓展实践能力。
本教材分为课程概述、项目实训、应用研发、拓展实践四个部分，包含色彩的分析与提取、色彩的再现与转调、色彩的材料与肌理、色彩的对比与形式、色彩的情感与空间、空间形态置换、主题创作、数字化技术应用、文创产品研发、展览组织与推广、艺术品定制与陈列等内容。
本书可作为高等职业教育专科、本科，五年制高职院校艺术设计类专业的教学用书，也可供艺术设计爱好者参考使用。', 49.80, 39.84, 394, '设计色彩是高等教育院校艺术设计类的专业基础课，旨在提高学生色彩搭配能力、色彩形式转换能力、色彩创意表达能力、数字化应用能力和拓展实践能力。
