  ('192', '内容提要
侍酒师职业是国家设立的新兴职业，现已成为许多职业院校设立相关专业的重点方向之一。本教材的编写以党的二十大精神为指引，落实立德树人的根本任务。教材在整合侍酒师综合知识和应用素质要求的基础上，基于多角度、多维度系统地阐述了侍酒师所需文化类知识、酒水类知识、管理类知识、营销类知识等内容，并介绍了近年来市场认可的餐酒搭配知识。配合侍酒实操应用方法、酒水类市场化感官品鉴应用、侍酒师岗位应用等实操内容。内容设置不局限于传统舶来葡萄酒品类，结合中国国情及行业发展状况，为中国侍酒师设计包含全酒类的知识体系及实操体系。课程内容设计基于新媒体平台功能，灵活运用新媒体平台的资源创新教材形式，以基础知识及理论内容配合新媒体化图片及视频演示为主要特色。并在实操应用教学板块中，利用多角度多媒体视频展示方法，为课程实操练习提供标准参考依据及审核标准。
本书可作为高等职业专科院校、职业本科院校及应用型本科院校旅游管理、酒店管理、葡萄酒文化与营销、空中乘务等专业的课程教材，同时还可供社会从业人士参考使用。', 50.00, 40.00, 171, '内容提要
侍酒师职业是国家设立的新兴职业，现已成为许多职业院校设立相关专业的重点方向之一。本教材的编写以党的二十大精神为指引，落实立德树人的根本任务。教材在整合侍酒师综合知识和应用素质要求的基础上，基于多角度、多维度系统地阐述了侍酒师所需文化类知识、酒水类知识、管理类知识、营销类知识等内容，并介绍了近年来市场认可的餐酒搭配知识。配合侍酒实操应用方法、酒水类市场化感官品鉴应用、侍酒师岗位应用等实操内容。内容设置不局限于传统舶来葡萄酒品类，结合中国国情及行业发展状况，为中国侍酒师设计包含全酒类的知识体系及实操体系。课程内容设计基于新媒体平台功能，灵活运用新媒体平台的资源创新教材形式，以基础知识及理论内容配合新媒体化图片及视频演示为主要特色。并在实操应用教学板块中，利用多角度多媒体视频展示方法，为课程实操练习提供标准参考依据及审核标准。
