  ('191', '本教材为艺术设计类基础课程教材，包含视觉形态平面构成基础、视觉形态的色彩与肌理、视觉形态空间构成基础与材料表现、二维形态到三维视觉设计基础的综合实训等内容，旨在基本原理和实训的引导下，建立设计基础与设计专业之间的连接点，让学生自主探索视觉形态设计语汇语境，培养创造思维。
