  ('190', '本教材是“十二五”职业教育国家规划教材的修订版，是在认真吸纳近年来课程改革成果的基础上修订而成的。
本教材共13章，包括力和受力图、平面力系的平衡、轴向拉伸和压缩、剪切与扭转、弯曲、组合变形、压杆的稳定性、结构的几何组成分析、静定结构的内力、静定结构的位移、超静定结构分析、用PKPM软件计算平面杆件结构、影响线等。
