  ('189', '《物理创新实验》
内容提要
本教材以项目化、模块化的形式组织内容，由7个项目组成，分别为“物理实验规范”“流体压强”“光学成像”“波动光学”“电子电路”“恒定磁场”和“综合创新作品设计”，构建从“形成实验规范”到“训练基础实验”再到“实现创新应用”的进阶模式。
教材以“讲好中国科技故事”为出发点，以中国现代科技发展为亮点，展现国家科技工程新动态。以世界为背景，在中外今昔对比中，呈现中国重大科技工程的先进性，增强民族自豪感。教材以学生学习成效为导向，以团队合作为基本工作方式，以学习者行动参与为主要模式，以综合创新作品设计为亮点，以大赛历练为升华，设置学习成效达成度自检表、团队展示窗、作品展示窗、综合创新作品设计展示窗和大赛历练窗，供读者记录学习点滴和成效。
本教材面向职业院校理工科学生，进行基础物理实验的训练，使其掌握基本物理实验规范，并在此基础之上，进行物理创新实践活动，以产品为导向，运用物理知识和实验技能，制作开发具有实用功能的科技创新作品，突出“理-行-研-创”的教育范式。', 49.80, 39.84, 256, '《物理创新实验》
内容提要
本教材以项目化、模块化的形式组织内容，由7个项目组成，分别为“物理实验规范”“流体压强”“光学成像”“波动光学”“电子电路”“恒定磁场”和“综合创新作品设计”，构建从“形成实验规范”到“训练基础实验”再到“实现创新应用”的进阶模式。
教材以“讲好中国科技故事”为出发点，以中国现代科技发展为亮点，展现国家科技工程新动态。以世界为背景，在中外今昔对比中，呈现中国重大科技工程的先进性，增强民族自豪感。教材以学生学习成效为导向，以团队合作为基本工作方式，以学习者行动参与为主要模式，以综合创新作品设计为亮点，以大赛历练为升华，设置学习成效达成度自检表、团队展示窗、作品展示窗、综合创新作品设计展示窗和大赛历练窗，供读者记录学习点滴和成效。
本教材面向职业院校理工科学生，进行基础物理实验的训练，使其掌握基本物理实验规范，并在此基础之上，进行物理创新实践活动，以产品为导向，运用物理知识和实验技能，制作开发具有实用功能的科技创新作品，突出“理-行-研-创”的教育范式。', '前 言
项目1 物理实验规范
　1.1 虚实结合数据在线的物理实验
　1.2 测量和不确定度
　1.3 数据处理方法
　1.4 实验设计
　1.5 赛教融合教学互长
　1.6 实验室规范
项目2 流体压强
　2.1 科技导航：奋斗者号
　2.2 空气的质量和气压的威力
　2.3 超乎想象的液体压强
项目3 光学成像
　3.1 科技导航：中国天眼
　3.2 追寻光的路径——透镜成像
　3.3 复杂镜面成像系统
　3.4 经典成像系统
项目4 波动光学
　4.1 科技导航：中国神光
　4.2 激光干涉全息照相
　4.3 初测光波的波长——牛顿环等厚干涉法
　4.4 再问光波的波长——光栅衍射法
项目5 电子电路
　5.1 科技导航：中国芯片
　5.2 元器件的伏安特性测试
　5.3 简易电子琴的制作
　5.4 心形流水灯的制作
项目6 恒定磁场
　6.1 科技导航：中国磁悬浮列车
　6.2 霍尔效应探测磁场
　6.3 霍尔效应探究半导体特性
项目7 综合创新作品设计
　7.1 创意激光琴
　7.2 创意磁悬浮装置
