  ('188', '液压与气压传动是自动控制领域中的一个重要技术门类，是机械行业工程技术人员需要掌握的专业课程。
本教材根据高等职业教育特点，以培养技术应用能力为目标，在内容上以液压传动为主、以气压传动为辅，将液压传动与气压传动融为一体，并选编了典型的应用案例。
教材共5个项目，主要介绍了磨床工作台方向控制回路设计、牛头刨床压力控制回路设计、组合机床动力滑台速度控制回路设计、钻床多缸控制回路设计、气压传动基本回路。
本教材可作为高等职业院校机械类、机电类各专业教材，也可供相关专业的工程技术人员参考。', 28.80, 23.04, 178, '液压与气压传动是自动控制领域中的一个重要技术门类，是机械行业工程技术人员需要掌握的专业课程。
本教材根据高等职业教育特点，以培养技术应用能力为目标，在内容上以液压传动为主、以气压传动为辅，将液压传动与气压传动融为一体，并选编了典型的应用案例。
教材共5个项目，主要介绍了磨床工作台方向控制回路设计、牛头刨床压力控制回路设计、组合机床动力滑台速度控制回路设计、钻床多缸控制回路设计、气压传动基本回路。
本教材可作为高等职业院校机械类、机电类各专业教材，也可供相关专业的工程技术人员参考。', '前言
