  ('187', '本书是融媒体、交互式、智能化数字教材。
本教材以3个典型模块作为学习载体，面向生产、维护、设计等3D打印实践方向，通过学习本教材可以帮助读者掌握三维扫描仪的操作使用和逆向数据处理方法，具备 FDM （熔融沉积制造）3D 打印机维护与故障排除技能，掌握工业产品的逆向建模与增材制造方法及基于3D打印技术的医疗支具设计与开发方法，从而达到增材制造技术技能型人才培养目标以及增材制造设备操作与维护工程师、增材制造模型设计工程师、医院数字化医学创新中心 3D 打印技术岗位的任职要求。
本书可作为高等职业院校机械设计与制造等专业教材，也可供相关技术人员参考。', 29.80, 23.84, 97, '本书是融媒体、交互式、智能化数字教材。
本教材以3个典型模块作为学习载体，面向生产、维护、设计等3D打印实践方向，通过学习本教材可以帮助读者掌握三维扫描仪的操作使用和逆向数据处理方法，具备 FDM （熔融沉积制造）3D 打印机维护与故障排除技能，掌握工业产品的逆向建模与增材制造方法及基于3D打印技术的医疗支具设计与开发方法，从而达到增材制造技术技能型人才培养目标以及增材制造设备操作与维护工程师、增材制造模型设计工程师、医院数字化医学创新中心 3D 打印技术岗位的任职要求。
本书可作为高等职业院校机械设计与制造等专业教材，也可供相关技术人员参考。', '前言
模块一 FDM 3D打印机装调与创新设计
　任务一 航空飞机手办模型的FDM 3D打印制作
　任务二 FDM 3D打印机Y轴组件的装配与测试
