  ('186', '本书贯彻落实党的二十大关于“加快建设高质量教育体系，发展素质教育”的相关要求，落实立德树人根本任务，以《关于加强高等学校服务国家通用语言文字高质量推广普及的若干意见》为纲领，以职场新人需具备的专业素质为导向，以普通话口语为呈现方式，结合教育学、心理学等知识，融入中华优秀传统文化和现代礼仪等内容，旨在提升学生的沟通能力、思维品质和综合素养。全书按照沟通与表达的难易程度由浅入深地进行设计，分为初级尝试、中级把握、高级探究3个项目，共18个沟通任务，每个任务下巧设案例导入、知识解析、方法突破、综合训练、自我评估等栏目，有机融入思政元素，突出职场模拟训练，注重沟通中的双向交流，强调语言表达的精确性、生动性、有效性，体现了能力目标与过程训练的结合，使学习者有抓手、见效快。
本书配套知识拓展、沟通测试等资源，力图构建多样性、实用性和交互性的立体化教学空间。
本书既可作为高职院校（专科层次、本科层次）沟通与口才、职业素养等课程的配套教材，也可供有意提升沟通能力的社会人士学习参考，亦可作为企业培训的指导用书。', 38.80, 31.04, 649, '本书贯彻落实党的二十大关于“加快建设高质量教育体系，发展素质教育”的相关要求，落实立德树人根本任务，以《关于加强高等学校服务国家通用语言文字高质量推广普及的若干意见》为纲领，以职场新人需具备的专业素质为导向，以普通话口语为呈现方式，结合教育学、心理学等知识，融入中华优秀传统文化和现代礼仪等内容，旨在提升学生的沟通能力、思维品质和综合素养。全书按照沟通与表达的难易程度由浅入深地进行设计，分为初级尝试、中级把握、高级探究3个项目，共18个沟通任务，每个任务下巧设案例导入、知识解析、方法突破、综合训练、自我评估等栏目，有机融入思政元素，突出职场模拟训练，注重沟通中的双向交流，强调语言表达的精确性、生动性、有效性，体现了能力目标与过程训练的结合，使学习者有抓手、见效快。
本书配套知识拓展、沟通测试等资源，力图构建多样性、实用性和交互性的立体化教学空间。
