  ('185', '本教材紧密结合全国职业院校技能大赛高职组“工业机器人技术应用”竞赛设备平台，贯彻落实“岗课赛证”综合育人理念，通过5个项目化教学模块，以“知识+任务”的形式深入浅出地介绍工业机器人基础知识、KEBAT70R工业机器人示教器的结构与功能、工业机器人基本操作方法、坐标系的建立与应用、编程指令功能与应用、工业机器人程序编写流程与规范、工业机器人程序调试及轨迹优化等内容。
本教材为数字教材，具有丰富的数字化教学资源。教材中的知识要点与操作案例，均配套有相关的教学视频和示例程序。同时，配置了动画、图片、微课、习题库等不同类型的教学资源，充分保证了学生自主学习需求，提高了学习效率。
本教材适合作为高等职业院校工业机器人技术专业及装备制造大类其他相关专业教材，也可作为相关工程技术人员参考用书和培训教材。', 45.00, 36.00, 145, '本教材紧密结合全国职业院校技能大赛高职组“工业机器人技术应用”竞赛设备平台，贯彻落实“岗课赛证”综合育人理念，通过5个项目化教学模块，以“知识+任务”的形式深入浅出地介绍工业机器人基础知识、KEBAT70R工业机器人示教器的结构与功能、工业机器人基本操作方法、坐标系的建立与应用、编程指令功能与应用、工业机器人程序编写流程与规范、工业机器人程序调试及轨迹优化等内容。
本教材为数字教材，具有丰富的数字化教学资源。教材中的知识要点与操作案例，均配套有相关的教学视频和示例程序。同时，配置了动画、图片、微课、习题库等不同类型的教学资源，充分保证了学生自主学习需求，提高了学习效率。
本教材适合作为高等职业院校工业机器人技术专业及装备制造大类其他相关专业教材，也可作为相关工程技术人员参考用书和培训教材。', '前言
