  ('184', '本教材是职业院校与企业“双元”合作编写的数字教材。在合作企业的配合下，根据职业岗位能力，以相应岗位的基本工作领域以及典型工作任务设计本教材基本框架，并以此完善具体的教材内容。本教材在编写过程中导入问题和任务，结合维修涂装企业典型案例进行表面处理、遮蔽、调漆、喷漆、喷漆后的处理等相关作业，并自觉遵循安全作业规范及7S的工作要求。
本教材按照任务设计了学习目标、任务引入、任务分析、实训指导以及知识学习等环节，同时提供了丰富的教学、学习资源，这些资源可以直接通过数字教材在线观看与学习。本教材可采用讲解、实训、理论学习、测试、讨论以及线上、线下结合等方式进行，打造立体化的学习模式。
本教材既可作为职业院校汽车类相关专业的教材，也可供汽车维修企业以及相关专业人员参考阅读。', 42.80, 34.24, 131, '本教材是职业院校与企业“双元”合作编写的数字教材。在合作企业的配合下，根据职业岗位能力，以相应岗位的基本工作领域以及典型工作任务设计本教材基本框架，并以此完善具体的教材内容。本教材在编写过程中导入问题和任务，结合维修涂装企业典型案例进行表面处理、遮蔽、调漆、喷漆、喷漆后的处理等相关作业，并自觉遵循安全作业规范及7S的工作要求。
本教材按照任务设计了学习目标、任务引入、任务分析、实训指导以及知识学习等环节，同时提供了丰富的教学、学习资源，这些资源可以直接通过数字教材在线观看与学习。本教材可采用讲解、实训、理论学习、测试、讨论以及线上、线下结合等方式进行，打造立体化的学习模式。
本教材既可作为职业院校汽车类相关专业的教材，也可供汽车维修企业以及相关专业人员参考阅读。', '前 言
项目一 汽车涂装安全环保措施与职业健康
　任务1 安全环保措施
　　学习目标
　　任务引入
　　任务分析
　　任务实施
　　实训指导
