  ('181', '《装配式混凝土结构工程施工》一书依据国家相关最新规范、规程和标准编写而成，主要介绍了装配式混凝土（PC）构件施工图表示方法、PC构件工厂配模与制作、PC构件现场施工等内容，使学生能够熟练识读装配式混凝土结构施工图，掌握PC构件生产前准备工作、生产工艺流程和质量控制要点，具备组织装配式框架结构、剪力墙结构、框架-剪力墙结构安装施工和编制施工组织设计文件的能力。
本书在内容编排上以施工流程为主线，共设计六个学习项目：“概述”“装配式混凝土结构施工图识读”“装配式混凝土构件生产”“装配式混凝土构件运输”“装配式混凝土工程施工”“装配式混凝土工程信息化管理”，每个项目内含若干学习任务，详细介绍了装配式混凝土建筑施工图表示方法，剪力墙、板等构件的识读、生产、运输、施工等内容。
本书可作为高等职业院校、职业本科院校以及中等职业技术学校建筑工程技术、建筑工程管理、工程造价等相关专业的教学用书，也可作为建筑工程技术人员的参考资料。', 43.80, 35.04, 90, '《装配式混凝土结构工程施工》一书依据国家相关最新规范、规程和标准编写而成，主要介绍了装配式混凝土（PC）构件施工图表示方法、PC构件工厂配模与制作、PC构件现场施工等内容，使学生能够熟练识读装配式混凝土结构施工图，掌握PC构件生产前准备工作、生产工艺流程和质量控制要点，具备组织装配式框架结构、剪力墙结构、框架-剪力墙结构安装施工和编制施工组织设计文件的能力。
本书在内容编排上以施工流程为主线，共设计六个学习项目：“概述”“装配式混凝土结构施工图识读”“装配式混凝土构件生产”“装配式混凝土构件运输”“装配式混凝土工程施工”“装配式混凝土工程信息化管理”，每个项目内含若干学习任务，详细介绍了装配式混凝土建筑施工图表示方法，剪力墙、板等构件的识读、生产、运输、施工等内容。
本书可作为高等职业院校、职业本科院校以及中等职业技术学校建筑工程技术、建筑工程管理、工程造价等相关专业的教学用书，也可作为建筑工程技术人员的参考资料。', '前言
