  ('180', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，是模式识别领域的基础教材，包含理论、实验和应用三方面内容。理论知识以统计模式识别为主，包括线性分类器、非线性分类器、特征提取、非监督聚类、神经网络等，立足经典理论和现代方法；实验部分围绕卫星目标识别综合项目，设计了一整套层次递进的实验内容，理论支撑实践，实践深化理论。应用部分结合航空航天实际工程案例对理论进行应用分析，实现了模式识别理论与实际工程应用的深度融合。
本书以模式识别理论为主线，结合应用案例进行分析，并且通过实验来深化理论、提高动手实践能力。本书可以作为空天智能交叉融合类专业以及人工智能、电子信息、自动化、计算机等相关专业的本科生或研究生教材，也可以供人工智能相关的研究人员和工程技术人员阅读参考。', 39.90, 31.92, 57, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，是模式识别领域的基础教材，包含理论、实验和应用三方面内容。理论知识以统计模式识别为主，包括线性分类器、非线性分类器、特征提取、非监督聚类、神经网络等，立足经典理论和现代方法；实验部分围绕卫星目标识别综合项目，设计了一整套层次递进的实验内容，理论支撑实践，实践深化理论。应用部分结合航空航天实际工程案例对理论进行应用分析，实现了模式识别理论与实际工程应用的深度融合。
本书以模式识别理论为主线，结合应用案例进行分析，并且通过实验来深化理论、提高动手实践能力。本书可以作为空天智能交叉融合类专业以及人工智能、电子信息、自动化、计算机等相关专业的本科生或研究生教材，也可以供人工智能相关的研究人员和工程技术人员阅读参考。', '前言
第一章 绪论
　学习目标
　1.1 模式与模式识别
　1.2 模式识别的方法和发展历史
　1.3 模式识别系统基本框架和构成
