  ('179', '本书是智能网联和新能源汽车战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，全面介绍了“智能网联和新能源汽车”相关专业的国内外发展现状及课程教材建设情况。本书以汽车软件研发平台项目为牵引，理论和实践双轨交叉并行，以电控系统、智能驾驶、信息安全等软件应用为案例，实现车辆工程与软件工程的深度融合。理论体系设置6个知识模块，实践围绕“汽车软件研发平台”项目，设计不同阶段的实践与应用， 7个实践案例对应软件开发过程，结合开发环境和工具。主要内容有：第1章 汽车软件工程简介； 第2章汽车软件工程基础理论；第3章 汽车软件需求分析；第4章 汽车软件设计与实现； 第5章 汽车软件集成与测试；第6章 汽车软件管理与维护。
本书适合车辆工程、新能源汽车、智能驾驶、交通工程、以及电子信息、计算机技术和软件工程等相关专业的高年级本科生和研究生，以及从事汽车软件工程、电控技术、信息安全、机电系统开发等相关领域的高新技术研发和工程技术人员。', 49.00, 39.20, 236, '本书是智能网联和新能源汽车战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，全面介绍了“智能网联和新能源汽车”相关专业的国内外发展现状及课程教材建设情况。本书以汽车软件研发平台项目为牵引，理论和实践双轨交叉并行，以电控系统、智能驾驶、信息安全等软件应用为案例，实现车辆工程与软件工程的深度融合。理论体系设置6个知识模块，实践围绕“汽车软件研发平台”项目，设计不同阶段的实践与应用， 7个实践案例对应软件开发过程，结合开发环境和工具。主要内容有：第1章 汽车软件工程简介； 第2章汽车软件工程基础理论；第3章 汽车软件需求分析；第4章 汽车软件设计与实现； 第5章 汽车软件集成与测试；第6章 汽车软件管理与维护。
本书适合车辆工程、新能源汽车、智能驾驶、交通工程、以及电子信息、计算机技术和软件工程等相关专业的高年级本科生和研究生，以及从事汽车软件工程、电控技术、信息安全、机电系统开发等相关领域的高新技术研发和工程技术人员。', '序
第一章 汽车软件工程概述
第二章 汽车软件工程基础理论
第三章 汽车软件系统开发基础
第四章 汽车软件需求分析
第五章 汽车架构分析
第六章 汽车软件系统设计
第七章 汽车软件组件设计与实现
第八章 汽车软件的集成和测试
第九章 汽车软件系统的标定和验收
第十章 汽车软件系统开发的支持过程
附录 工程案
