  ('178', '本教材围绕当前车联网技术发展及其应用场景，以任务情境、学习目标、知识储备、任务实施、评价与考核为主线进行内容编排，以车联网技术及其应用认知、车联网通信关键技术简介、车内无线网络搭建与测试、车路协同网络搭建与测试、车联网典型应用场景仿真和车联网安全与隐私保护六个项目为载体，设置了一系列配套的实训任务，较为完整地构建了车联网技术及其应用的学习内容，充分体现了“学中做、做中学”的职业教育特色。
本教材可以供高职高专院校智能网联汽车技术、智能交通技术、新能源汽车技术等相关专业课程的教学使用，也可以供车联网从业人员的参考和培训用书。', 39.80, 31.84, 89, '本教材围绕当前车联网技术发展及其应用场景，以任务情境、学习目标、知识储备、任务实施、评价与考核为主线进行内容编排，以车联网技术及其应用认知、车联网通信关键技术简介、车内无线网络搭建与测试、车路协同网络搭建与测试、车联网典型应用场景仿真和车联网安全与隐私保护六个项目为载体，设置了一系列配套的实训任务，较为完整地构建了车联网技术及其应用的学习内容，充分体现了“学中做、做中学”的职业教育特色。
本教材可以供高职高专院校智能网联汽车技术、智能交通技术、新能源汽车技术等相关专业课程的教学使用，也可以供车联网从业人员的参考和培训用书。', '前言
