  ('177', '本书由等离子体物理学的三个部分组成：理论部分、实验部分和计算部分。等离子体物理学理论部分主要介绍单粒子轨道运动、磁流体力学理论和动理学理论；实验部分则介绍了当今等离子体物理学的主要实践知识及其应用，包括等离子体的产生、常用等离子体的诊断方法、低温等离子体及其应用、等离子体在约束聚变中的作用；在计算模拟部分，首先概述了MATLAB算法，然后详细说明了磁镜中磁力线轨迹、磁流体模式和朗道阻尼的MATLAB模拟计算的细致结果及其物理意义。
该书适用于理工科高等院校高年级本科生们学习等离子体物理学课程，对相关学科的研究生以及科研工作者则具有参考作用。', 26.00, 20.80, 217, '本书由等离子体物理学的三个部分组成：理论部分、实验部分和计算部分。等离子体物理学理论部分主要介绍单粒子轨道运动、磁流体力学理论和动理学理论；实验部分则介绍了当今等离子体物理学的主要实践知识及其应用，包括等离子体的产生、常用等离子体的诊断方法、低温等离子体及其应用、等离子体在约束聚变中的作用；在计算模拟部分，首先概述了MATLAB算法，然后详细说明了磁镜中磁力线轨迹、磁流体模式和朗道阻尼的MATLAB模拟计算的细致结果及其物理意义。
该书适用于理工科高等院校高年级本科生们学习等离子体物理学课程，对相关学科的研究生以及科研工作者则具有参考作用。', '前言
