  ('176', '本书是航空航天战略性新兴领域“十四五”高等教育教材， 可作为航空航天类无人驾驶航空器系统工程专业教材。本书从导航技术概念开始，讲解导航技术的发展和趋势，引出智能导航的概念内涵、系统架构和软硬件组成；进一步围绕智能导航相关技术展开介绍。在深入讲解智能导航基本原理、核心技术、重要工具的基础上，每章节内容均安排有相关技术的实践探索环节，帮助学生在动手实践过程中学以致用。同时，教材结合当前大模型、通用人工智能等前沿技术，讲解智能导航方法的新方向，了解智能导航在认知技术、仿生技术、协同技术等方向的新进展，为学生从事相关研究工作奠定基础，更强调系统思维对学生未来创新思维的促进作用。', 40.00, 32.00, 103, '本书是航空航天战略性新兴领域“十四五”高等教育教材， 可作为航空航天类无人驾驶航空器系统工程专业教材。本书从导航技术概念开始，讲解导航技术的发展和趋势，引出智能导航的概念内涵、系统架构和软硬件组成；进一步围绕智能导航相关技术展开介绍。在深入讲解智能导航基本原理、核心技术、重要工具的基础上，每章节内容均安排有相关技术的实践探索环节，帮助学生在动手实践过程中学以致用。同时，教材结合当前大模型、通用人工智能等前沿技术，讲解智能导航方法的新方向，了解智能导航在认知技术、仿生技术、协同技术等方向的新进展，为学生从事相关研究工作奠定基础，更强调系统思维对学生未来创新思维的促进作用。', '前言
