  ('175', '当前，中国航天已取得了一系列具有国际影响力的标志性成果，在关键领域走在了世界前列。星球车及深空探测是航天领域的重要发展方向，是人类探索宇宙必不可少的重要工具。
全书从典型航天工程（探月工程、火星探测）出发，聚焦以星球车为典型代表的航天前沿科技，紧密结合国家战略新兴领域发展成果和国际科研动态，覆盖了星球车的控制、感知、路径规划、嵌入式系统、虚拟仿真等专业技术知识，构建了“基础理论-虚仿实验-航天应用场景”相贯通的教材内容体系。内容设置不仅能够激发学生们对航天科技的兴趣，更能有效培养学生的创新思维和实践能力，为将来投身于航空航天等领域打下坚实的基础。
本数字教材在内容呈现上，不仅引入了音视频、动画、思维导图等多种资源，还与虚拟仿真技术深度结合。这种虚实融合的多形态学习方式能够帮助学生有效地直观感受原本难以触及的星球车真实样态，加深对相关知识点的理解，引导读者举一反三。
本数字教材适合作为高等院校自动化类、航空航天类、仪器类、电子信息类等相关专业教材，同时也可作为工程技术人员的参考书。', 40.00, 32.00, 111, '当前，中国航天已取得了一系列具有国际影响力的标志性成果，在关键领域走在了世界前列。星球车及深空探测是航天领域的重要发展方向，是人类探索宇宙必不可少的重要工具。
