  ('174', '内容简介
本书是航空航天新兴领域“十四五”高等教育教材。人工智能时代已然来临，航空航天作为全世界最早的信息科技产业应用技术领域之一，迫切需要开设人工智能技术及其于航空航天的应用课程，为人工智能在航空航天的普及、人才的培养、学科的发展提供条件。本书重点介绍了人工智能是什么、人工智能在航空航天领域能做什么，选取线性回归、逻辑回归、神经网络、聚类、降维、异常检测、深度学习与强化学习，结合人工智能于航空航天应用的案例解释人工智能的应用，以点带面，传授人工智能的基本知识、人工智能的算法理论及其的应用方式。
