  ('173', '内容简介
本书是“智能+航空航天”战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，全面介绍了“智能+航空航天”相关专业的国内外发展现状及课程教材建设情况，内容包括“智能+航空航天”教材建设的研究报告、建设方案、支撑专业、配套课程四个部分。第一部分为航空航天类新兴领域教材研究与实践项目研究报告，调研并分析了国内外航空航天专业人才培养需求、专业设置情况、课程与教材建设情况等；第二部分为航空航天类战略性新兴领域教材建设方案，阐述了“智能+航空航天”战略性新兴领域教材体系的建设目标、建设基础、建设计划与教材规划；第三部分为航空航天类战略性新兴领域教材支撑专业，梳理了北京航空航天大学、南京航空航天大学、沈阳航空航天大学相关专业的培养方案；第四部分为航空航天类战略性新兴领域核心课程教学大纲，介绍了“智能+航空航天”战略性新兴领域教材体系重点支撑的20门核心课程的知识体系。
本书可供高等学校从事航空航天类课程教学的教师参考，也可供相关学科教学管理部门进行 课程体系建设与管理时参考使用。', 49.00, 39.20, 207, '内容简介
