  ('172', '本教材是航空航天战略性新兴领域“十四五”高等教育教材。全教材共8章，第1～2章介绍飞行器智能制造技术体系，第3～7章介绍数字孪生、智能增材、智能装配、结构电路一体化等前沿智能制造技术，第8章介绍飞行器智能制造感知与监测技术。本书特点是：① 前沿性，本书面向飞行器制造领域的多学科交叉与发展前沿，阐述人工智能技术、增材制造技术，机器人技术、复合材料技术等基础理论、关键技术及典型应用案例，提升学生创新能力，拓宽学生视野。② 系统性，本书从飞行器智能制造体系出发，系统地总结了近年来人工智能技术在飞行器制造领域的发展与应用，提升了学生对先进制造技术的认知能力。③ 工程性，本书聚集瞄准国家重大战略需求，与航空、航天等领域的典型应用场景紧密结合，以工程应用为牵引，深化学生对工程实践的理解，加深学生的国防情怀。
本教材除可作为高等学校航空宇航科学与技术、机械工程相关专业教材外，还适合智能制造相关行业的管理者和专业技术人员阅读参考。', 35.00, 28.00, 29, '本教材是航空航天战略性新兴领域“十四五”高等教育教材。全教材共8章，第1～2章介绍飞行器智能制造技术体系，第3～7章介绍数字孪生、智能增材、智能装配、结构电路一体化等前沿智能制造技术，第8章介绍飞行器智能制造感知与监测技术。本书特点是：① 前沿性，本书面向飞行器制造领域的多学科交叉与发展前沿，阐述人工智能技术、增材制造技术，机器人技术、复合材料技术等基础理论、关键技术及典型应用案例，提升学生创新能力，拓宽学生视野。② 系统性，本书从飞行器智能制造体系出发，系统地总结了近年来人工智能技术在飞行器制造领域的发展与应用，提升了学生对先进制造技术的认知能力。③ 工程性，本书聚集瞄准国家重大战略需求，与航空、航天等领域的典型应用场景紧密结合，以工程应用为牵引，深化学生对工程实践的理解，加深学生的国防情怀。
