  ('171', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，本书从天基空间系统总体出发，详细介绍其中信息处理的技术需求、特点难点、主要流程和典型方法，针对实际问题设置理论内容和研究型开放课题，覆盖天基空间目标信息处理全过程。
本书可作为航天+智能交叉方向本科生教材，同时也可以作为相关专业研究生和相关领域工程技术人员的参考书。', 40.00, 32.00, 18, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，本书从天基空间系统总体出发，详细介绍其中信息处理的技术需求、特点难点、主要流程和典型方法，针对实际问题设置理论内容和研究型开放课题，覆盖天基空间目标信息处理全过程。
