  ('170', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设项目成果。
本书旨在以综合性、前沿性、实用性为特色，多角度介绍飞行器智能集群的基础概念与技术方法。智能化、集群化是先进飞行器发展的主要方向，而集群智能是智能飞行器发展的重要研究领域，以飞行器集群为代表的集群系统具有大规模性、开放性、高动态性及强容错性等典型应用特征。本教材以仿生集群概念展开集群概念介绍，回顾了飞行器状态估计与姿态、航迹控制等基础知识，以飞行器集群决策、控制、感知三个维度阐释了集群体系架构与任务分配、集群控制与航迹规划、集群定位于协同感知方面的概念、理论、方法。
本书可作为高等学校航空航天类相关课程教材，也可供相关行业工程技术人员或研究人员参考。', 48.00, 38.40, 25, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设项目成果。
本书旨在以综合性、前沿性、实用性为特色，多角度介绍飞行器智能集群的基础概念与技术方法。智能化、集群化是先进飞行器发展的主要方向，而集群智能是智能飞行器发展的重要研究领域，以飞行器集群为代表的集群系统具有大规模性、开放性、高动态性及强容错性等典型应用特征。本教材以仿生集群概念展开集群概念介绍，回顾了飞行器状态估计与姿态、航迹控制等基础知识，以飞行器集群决策、控制、感知三个维度阐释了集群体系架构与任务分配、集群控制与航迹规划、集群定位于协同感知方面的概念、理论、方法。
