  ('169', '为适应国家对汽车行业技能型紧缺人才的培养要求，本书结合高等职业教育汽车类专业人才培养目标，本着“适用、实用”的原则，突出“学中练”“练中学”“学练结合”，着重培养学生的专业能力、职业素养和综合实践能力。同时，本书融入国家职业技能等级标准的相关内容，实现课证衔接。本书主要内容包括：汽油机电控燃油喷射系统检修，汽油机电控点火系统检修，汽油机怠速控制系统检修，汽油机进气系统检修，汽油机排放控制系统检修，汽油机巡航和电控节气门控制系统检修，汽油机自诊断、失效保护和应急备用系统检修，柴油机高压共轨控制系统检修等。本书可作为高等职业院校汽车类专业课程教材，也可作为汽车企业高级技术人员的培训教材。', 46.80, 37.44, 18, '为适应国家对汽车行业技能型紧缺人才的培养要求，本书结合高等职业教育汽车类专业人才培养目标，本着“适用、实用”的原则，突出“学中练”“练中学”“学练结合”，着重培养学生的专业能力、职业素养和综合实践能力。同时，本书融入国家职业技能等级标准的相关内容，实现课证衔接。本书主要内容包括：汽油机电控燃油喷射系统检修，汽油机电控点火系统检修，汽油机怠速控制系统检修，汽油机进气系统检修，汽油机排放控制系统检修，汽油机巡航和电控节气门控制系统检修，汽油机自诊断、失效保护和应急备用系统检修，柴油机高压共轨控制系统检修等。本书可作为高等职业院校汽车类专业课程教材，也可作为汽车企业高级技术人员的培训教材。', '前言
