  ('168', '本书是中山大学光学课程教学团队中的多位成员结合在本校多年的教 学经验编写的光学教材 。本书力求为读者建立清晰的传统光学基础知识框 架，同时可开拓读者视野，使其总览学科概貌 。本书共分 7 章，涉及几何光 学 、波动光学和 量 子 光 学 三 部 分 。 第 1 章 是 几 何 光 学，包 含 光 度 学 内 容； 第 2、第 3、第 4 章是波动光学，其中对于薄膜光学 、傅里叶光学 、全息术和近 场光学等内容分别结合相关章节作了适量的介绍；第 5 章是光的色散 、吸收 和散射；第 6 章是光的量子现象；第 7 章是激光 。
本书可作为高等学校物理学类专业光学课程的本科生教材，也可供光 学相关工程技术人员参考 。', 53.80, 43.04, 57, '本书是中山大学光学课程教学团队中的多位成员结合在本校多年的教 学经验编写的光学教材 。本书力求为读者建立清晰的传统光学基础知识框 架，同时可开拓读者视野，使其总览学科概貌 。本书共分 7 章，涉及几何光 学 、波动光学和 量 子 光 学 三 部 分 。 第 1 章 是 几 何 光 学，包 含 光 度 学 内 容； 第 2、第 3、第 4 章是波动光学，其中对于薄膜光学 、傅里叶光学 、全息术和近 场光学等内容分别结合相关章节作了适量的介绍；第 5 章是光的色散 、吸收 和散射；第 6 章是光的量子现象；第 7 章是激光 。
