  ('167', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，以航空航天相关应用场景为牵引，讲解数值计算和机器学习的基本算法和核心思想，并给出其在实际工程和科研中的应用例子。全书分为四个部分。第一部分为第一至三章，建立基本概念，提供Python基础知识，为后续编程实践打好基础。第二部分为第四至十章，介绍数值分析方法，包括方程求解，求微分、解微分方程、插值、拟合、寻优等，这些内容也是航空航天领域算法工程师必须掌握的。第三部分为第十一至十六章，介绍基本机器学习方法，包括K近邻、K均值、支持向量机和神经网络等算法。第四部分为第十七章至二十三章，我们进入一个更“实战”的层次，通过数字孪生模型、寿命预测、空间目标分类等例子，将读者代入一个个航空航天工程场景中，体会所学算法的威力，培养同学将复杂工程问题抽象为机器学习算法模型的能力。在编写过程中，贯彻“空谈无益，动手实践”这一教学理念。除了剖析各算法数学结构，还给出核心实现的示例代码。在课后作业中，同学将亲自动手，对示例代码进行一定的拓展，切实培养实践能力，获得更多探索的乐趣。本书可作为高等学校高等院校飞行器动力工程、空天智能电推进技术等专业本科生的教材或参考书，也可供航空航天工业部门设计、研究人员参考。', 40.00, 32.00, 256, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，以航空航天相关应用场景为牵引，讲解数值计算和机器学习的基本算法和核心思想，并给出其在实际工程和科研中的应用例子。全书分为四个部分。第一部分为第一至三章，建立基本概念，提供Python基础知识，为后续编程实践打好基础。第二部分为第四至十章，介绍数值分析方法，包括方程求解，求微分、解微分方程、插值、拟合、寻优等，这些内容也是航空航天领域算法工程师必须掌握的。第三部分为第十一至十六章，介绍基本机器学习方法，包括K近邻、K均值、支持向量机和神经网络等算法。第四部分为第十七章至二十三章，我们进入一个更“实战”的层次，通过数字孪生模型、寿命预测、空间目标分类等例子，将读者代入一个个航空航天工程场景中，体会所学算法的威力，培养同学将复杂工程问题抽象为机器学习算法模型的能力。在编写过程中，贯彻“空谈无益，动手实践”这一教学理念。除了剖析各算法数学结构，还给出核心实现的示例代码。在课后作业中，同学将亲自动手，对示例代码进行一定的拓展，切实培养实践能力，获得更多探索的乐趣。本书可作为高等学校高等院校飞行器动力工程、空天智能电推进技术等专业本科生的教材或参考书，也可供航空航天工业部门设计、研究人员参考。', '前言
