  ('166', '“公差配合与技术测量”课程是高等院校机械制造类专业的一门重要的专业技术基础课程，具有较强的实践应用性，课程从互换性角度出发，围绕误差与公差的关系解决使用要求与制造要求之间的矛盾问题，培养学生依据国家标准正确选用公差与配合，正确理解图样设计要求，合理选用计量器具并能进行相应的测量数据处理工作，达到胜任机械零部件及机械产品设计、制造、维修、质量控制、生产管理等岗位的工作能力。
为适应现代生产和科学技术发展需要，深入课程内容改革，结合高职高专教育特点，以"必需、够用”为原则组织内容编写，加强应用、注重更新，突出实践应用性。
教材编写中力求突出以下特点：
依据高职高专办学理念和人才培养目标，结合双师型教师教学方式，对课程内容进行深入浅出、循序渐进式渗透融入。
通过项目牵引、任务驱动的教学设计，贯彻落实极公差合与测量技术等各项国家标准。
融入大量多媒体信息化教学形式，娓娓道来的微课讲述、生动形象的动画演示，使学习更具自主性和趣味性。', 46.80, 37.44, 150, '“公差配合与技术测量”课程是高等院校机械制造类专业的一门重要的专业技术基础课程，具有较强的实践应用性，课程从互换性角度出发，围绕误差与公差的关系解决使用要求与制造要求之间的矛盾问题，培养学生依据国家标准正确选用公差与配合，正确理解图样设计要求，合理选用计量器具并能进行相应的测量数据处理工作，达到胜任机械零部件及机械产品设计、制造、维修、质量控制、生产管理等岗位的工作能力。
