  ('163', '本书为职业本科院校信息技术公共基础课程配套数字教材，由深圳职业技术大学大学计算机公共课程教学团队编写。
本书以信息社会责任为切入点，以计算思维培养为导向，以项目导向、任务驱动的模式组织教学内容，案例有机融入“云大物智”等领域最新的知识及自主可控的研发成果，提升学生运用信息技术高效解决问题的能力，培养学生的信息意识、计算思维能力、数字化创新与发展能力。
全书共9章，主要内容包括新一代信息技术、办公软件实用技术、问题求解与计算思维、程序设计基础、机器人流程自动化等。
