  ('162', '本教材作为人工智能通识类教材，既有博而通的理论，又有专而精的实践，将理论与实践高度结合。教材以普及人工智能基础知识、介绍人工智能行业应用、实践人工智能大模型、提升学生的人工智能基本素养为目标。全书共六大项目，分别为：揭开人工智能的神秘面纱、无处不在的人工智能、神来之笔的人工智能、人工智能软硬件技术、人工智能的技术生态、人工智能的伦理道德。本教材选取生活化、典型化、具体化、热点化的情景案例作为任务导入，理实一体，促进知识、技能的活学活用；通过任务实施，学生能够从单一的技能点出发，拓展多个领域的应用能力，扩大学习视野。本教材设置有“交流与思考”“科教兴国”等多种学习模块，旨在培养具有社会责任感和创新精神的人工智能人才，增大不同专业学生接触前沿技术的机会，促进人工智能技术与各专业间的融合，为加快发展新质生产力不断培育高层次技术技能人才。
本教材是具有交互性、智能化的数字教材，配有虚拟仿真、操作视频、微课、在线测试等丰富的数字化教学资源，读者可在教材中直接点击浏览、操作、学习。
