  ('161', '本书为先进轨道交通战略性新兴领域“十四五”高等教育教材之一。随着物联网、移动互联网和大数据等信息技术的广泛使用，国家战略中“双碳”目标的要求，以智能建造、智能运维为代表的智能化，以减振降噪为代表的绿色环保已成为轨道交通可持续发展的重要内涵。在此背景下，轨道工程从业者借助新材料，新技术和新工艺，在设计理论、建造技术、监测与检测、维护和管理等方面都有新的突破，并取得了丰富的成果。
西南交通大学轨道工程教研组在总结近年来轨道工程智能化及绿色铁路相关研究成果的基础上，编写了《可持续轨道工程》。全书共11章，内容包括：绪论、轨道结构、轨道几何形位与车辆基本结构、轮轨接触几何关系与相互作用、道岔、无缝线路、轨道力学与轨道结构设计、轨道建造、轨道智能运维、环境友好型轨道、新型可持续轨道结构。
教材中除介绍传统轨道工程的各理论和方法外，还以可持续轨道工程为指导思想，在各章节补充了节能、减碳、智能建造、智能运维、韧性提升、环境友好等内容。此外，本书各章节中的可持续发展相关知识点涵盖干线铁路网、城际铁路网、市域（郊）铁路网、城市轨道交通网这四个轨道交通领域的设计、生产、施工、运营与维护各阶段相关知识、成果及技术。
本书以高等院校土木工程、铁道工程等专业的本科教学为主，兼顾上述专业的研究生教学。', 68.00, 54.40, 182, '本书为先进轨道交通战略性新兴领域“十四五”高等教育教材之一。随着物联网、移动互联网和大数据等信息技术的广泛使用，国家战略中“双碳”目标的要求，以智能建造、智能运维为代表的智能化，以减振降噪为代表的绿色环保已成为轨道交通可持续发展的重要内涵。在此背景下，轨道工程从业者借助新材料，新技术和新工艺，在设计理论、建造技术、监测与检测、维护和管理等方面都有新的突破，并取得了丰富的成果。
西南交通大学轨道工程教研组在总结近年来轨道工程智能化及绿色铁路相关研究成果的基础上，编写了《可持续轨道工程》。全书共11章，内容包括：绪论、轨道结构、轨道几何形位与车辆基本结构、轮轨接触几何关系与相互作用、道岔、无缝线路、轨道力学与轨道结构设计、轨道建造、轨道智能运维、环境友好型轨道、新型可持续轨道结构。
教材中除介绍传统轨道工程的各理论和方法外，还以可持续轨道工程为指导思想，在各章节补充了节能、减碳、智能建造、智能运维、韧性提升、环境友好等内容。此外，本书各章节中的可持续发展相关知识点涵盖干线铁路网、城际铁路网、市域（郊）铁路网、城市轨道交通网这四个轨道交通领域的设计、生产、施工、运营与维护各阶段相关知识、成果及技术。
本书以高等院校土木工程、铁道工程等专业的本科教学为主，兼顾上述专业的研究生教学。', '前言
