  ('160', '《电推进智能控制》是航空航天新兴领域“十四五”高等教育教材，专为空天智能电推进技术专业的高年级学生编写。
本书覆盖了经典控制、现代控制和智能控制的理论基础与实践应用，共分为八章，内容包括绪论、经典控制实例、状态空间分析法、智能控制、多旋翼飞行器控制、氢燃料电池混合动力系统控制、离子风飞行器动力装置控制以及电推进智能控制前沿。通过磁盘驱动器、倒立摆、登月小车、多旋翼飞行器、氢能飞行器、离子风飞行器等空天领域的多个典型案例，本书从简单到复杂、从理论到工程，循序渐进地将控制学与电推进技术相融合，增强学生对控制学的理解和掌握，同时培养其在电推进领域的工程实践能力。
本书可供飞行器动力工程、空天智能电推进技术专业的本科生，以及“两机”领域卓越工程师方向研究生课程教学使用。', 35.00, 28.00, 50, '《电推进智能控制》是航空航天新兴领域“十四五”高等教育教材，专为空天智能电推进技术专业的高年级学生编写。
