  ('159', '本教材《航空推进器原理与设计》旨在为学生提供全面而系统的航空推进器知识，涵盖其基本概念、工作原理及设计方法。教材分为六个主要部分：航空推进器概况，空气动力学基础，航空推进器总体气动布局原理，涵道风扇的工作原理，涵道风扇气动设计，非定常气动特性。本教材适合航空航天工程及相关专业的本科生和研究生使用。
航空推进器概况：本部分介绍航空推进器的基本组成、分类以及在现代航空中的重要性，帮助学生建立对推进器整体框架的认识。
空气动力学基础：本部分深入探讨空气动力学的基本原理，包括流体力学的基本概念、气动性能参数及其与推进器性能之间的关系，为后续课程奠定坚实的理论基础。
航空推进器总体气动布局原理：分析推进器的气动布局设计，探讨如何通过优化设计提高推进器的效率和性能，并讨论不同布局对气动特性的影响。
涵道风扇的工作原理：详细讲解涵道风扇的工作机制，包括进气、压缩和排气过程，阐明其在现代航空推进器中的关键作用。
涵道风扇气动设计：介绍涵道风扇的气动设计关键因素，包括叶片形状、气流通道设计及其对推进效率的影响，探讨流动优化技术在设计中的应用。
非定常气动特性：主要研究航空推进器中的非定常流动现象，主要包括气动不稳定性、气动弹性、气动声学三个部分。该部分内容重点关注航空推进器领域最前沿的研究进展与问题。
本教材通过理论与实践相结合的方式，配合丰富的案例分析和实例研究，旨在激发学生对航空推进技术的兴趣，培养其独立思考和解决实际问题的能力。通过本课程的学习，学生将掌握航空推进器的基本原理及设计方法，为未来的研究和工程实践打下坚实的基础。', 48.00, 38.40, 104, '本教材《航空推进器原理与设计》旨在为学生提供全面而系统的航空推进器知识，涵盖其基本概念、工作原理及设计方法。教材分为六个主要部分：航空推进器概况，空气动力学基础，航空推进器总体气动布局原理，涵道风扇的工作原理，涵道风扇气动设计，非定常气动特性。本教材适合航空航天工程及相关专业的本科生和研究生使用。
