  ('158', '智能电动汽车是未来汽车科技的战略制高点，而科学完善的试验体系是智能电动汽车研发与规模化应用的基础。本书汇聚国内《汽车试验学》课程的众多优秀教学团队，结合行业最新前沿技术，系统介绍了智能电动汽车试验的基本原理、基本方法和典型技术。
全书共七章，第一章为概述；第二至四章阐明了汽车试验基础理论与方法、试验数据处理与分析方法，介绍了典型汽车试验设备与设施；第五章简要讲述了整车基本性能试验方法；第六章详细讲解了电动汽车及关键零部件性能试验方法；第七章系统讲述了智能汽车及关键系统性能试验方法。
本书可作为高等学校车辆工程专业或其他相关专业智能电动汽车试验理论与技术教学的专业教材，也可作为汽车设计、制造、检测和修理等相关行业从业人员开展智能电动汽车试验检测方面工作的技术参考。', 30.00, 24.00, 56, '智能电动汽车是未来汽车科技的战略制高点，而科学完善的试验体系是智能电动汽车研发与规模化应用的基础。本书汇聚国内《汽车试验学》课程的众多优秀教学团队，结合行业最新前沿技术，系统介绍了智能电动汽车试验的基本原理、基本方法和典型技术。
全书共七章，第一章为概述；第二至四章阐明了汽车试验基础理论与方法、试验数据处理与分析方法，介绍了典型汽车试验设备与设施；第五章简要讲述了整车基本性能试验方法；第六章详细讲解了电动汽车及关键零部件性能试验方法；第七章系统讲述了智能汽车及关键系统性能试验方法。
本书可作为高等学校车辆工程专业或其他相关专业智能电动汽车试验理论与技术教学的专业教材，也可作为汽车设计、制造、检测和修理等相关行业从业人员开展智能电动汽车试验检测方面工作的技术参考。', '简介
