  ('157', '本书是航空航天领域“十四五”高等教育教材。全书共五章，围绕航空电推进系统中能源存储与转换技术，对航空电源技术进行系统性阐述，具体包括航空能源概述、能源物理化学、物理电源技术、化学电源技术以及混合电池系统设计五部分。
本书主要介绍能源存储与转换技术的基础知识，并强调突出航空航天特色，用数字赋能新时代教材，加入丰富的视频、动画、图片、典型案例等资源，融入航空电推进领域能源系统最新进展与前沿技术，激发学生学习兴趣，加强对教材知识的理解与融会贯通能力。
本书可供航空航天、能源动力、电推进、材料、物理、化学等相关专业的高等教育本科生或研究生使用，也可作为从事新能源、太阳能电池、储能电池、燃料电池、电动汽车、电动飞机、规模储能等领域研究与应用人员的基础参考书。', 30.00, 24.00, 57, '本书是航空航天领域“十四五”高等教育教材。全书共五章，围绕航空电推进系统中能源存储与转换技术，对航空电源技术进行系统性阐述，具体包括航空能源概述、能源物理化学、物理电源技术、化学电源技术以及混合电池系统设计五部分。
本书主要介绍能源存储与转换技术的基础知识，并强调突出航空航天特色，用数字赋能新时代教材，加入丰富的视频、动画、图片、典型案例等资源，融入航空电推进领域能源系统最新进展与前沿技术，激发学生学习兴趣，加强对教材知识的理解与融会贯通能力。
本书可供航空航天、能源动力、电推进、材料、物理、化学等相关专业的高等教育本科生或研究生使用，也可作为从事新能源、太阳能电池、储能电池、燃料电池、电动汽车、电动飞机、规模储能等领域研究与应用人员的基础参考书。', '前言
