  ('156', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，书中紧密结合无人机集群技术最新发展趋势，按照“网联化”与“智能化”两条主线组织内容，注重理论与实践相结合。全书共分为8章，包括绪论、无人机集群网络体系结构与协同控制结构、无人机集群通信物理层技术、无人机集群信道接入技术、无人机集群路由技术、无人机集群航迹规划和无人机集群虚拟仿真实验。
本数字教材配有视频讲解和虚拟仿真实验，内容覆盖面广、难度适中，可作为高等院校相关课程的教材，也可作为无人机集群领域工程技术人员的参考书。', 35.00, 28.00, 120, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果，书中紧密结合无人机集群技术最新发展趋势，按照“网联化”与“智能化”两条主线组织内容，注重理论与实践相结合。全书共分为8章，包括绪论、无人机集群网络体系结构与协同控制结构、无人机集群通信物理层技术、无人机集群信道接入技术、无人机集群路由技术、无人机集群航迹规划和无人机集群虚拟仿真实验。
