  ('155', '本书为数字教材，已列入教育部战略性新兴领域“十四五”高等教育教材体系系列。本书从轨道交通与轨道交通产业基础特性入手，涉及新经济理论导论与轨道交通线网规划理论两大领域，主要内容包括轨道交通及轨道交通产业、新经济与产业发展升级的融合方式、轨道交通产业新经济分析、轨道交通线网规划概述、轨道交通运输需求预测理论与方法、轨道交通线网规模匡算理论与方法、轨道交通线网规划理论与方法、四网融合的区域轨道服务网络优化方法等8章。本书可作为高等学校交通运输及相关专业教材，供本科与研究生教学使用，也可供交通运输从业人员参考。', 49.00, 39.20, 43, '本书为数字教材，已列入教育部战略性新兴领域“十四五”高等教育教材体系系列。本书从轨道交通与轨道交通产业基础特性入手，涉及新经济理论导论与轨道交通线网规划理论两大领域，主要内容包括轨道交通及轨道交通产业、新经济与产业发展升级的融合方式、轨道交通产业新经济分析、轨道交通线网规划概述、轨道交通运输需求预测理论与方法、轨道交通线网规模匡算理论与方法、轨道交通线网规划理论与方法、四网融合的区域轨道服务网络优化方法等8章。本书可作为高等学校交通运输及相关专业教材，供本科与研究生教学使用，也可供交通运输从业人员参考。', '前言
