  ('154', '本书为数字教材，已列入教育部战略性新兴领域“十四五”高等教育教材体系系列，是为适应我国轨道交通发展与实践而编写的轨道交通运输组织教材。主要内容包括轨道交通运输计划基本理论、普速铁路运输计划编制方法、重载铁路运输计划编制方法、高速铁路运输计划编制方法、市域铁路运输计划编制方法、城市轨道交通运输计划编制方法、多制式轨道交通运输计划协同编制方法、基于区域协同的高速铁路列车运行图编制理论与方法、基于市场导向动态规划型运输组织模式的铁路运输计划编制理论与方法、基于深度强化学习的轨道交通运输计划编制优化技术和轨道交通运输计划编制系统等11章。本书可作为高等学校交通运输、交通工程、铁道工程等相关课程教材，供本科与研究生教学使用，也可供交通运输部门从事实际生产工作的轨道交通专业技术人员、管理人员和交通勘察设计相关人员参考。', 55.00, 44.00, 60, '本书为数字教材，已列入教育部战略性新兴领域“十四五”高等教育教材体系系列，是为适应我国轨道交通发展与实践而编写的轨道交通运输组织教材。主要内容包括轨道交通运输计划基本理论、普速铁路运输计划编制方法、重载铁路运输计划编制方法、高速铁路运输计划编制方法、市域铁路运输计划编制方法、城市轨道交通运输计划编制方法、多制式轨道交通运输计划协同编制方法、基于区域协同的高速铁路列车运行图编制理论与方法、基于市场导向动态规划型运输组织模式的铁路运输计划编制理论与方法、基于深度强化学习的轨道交通运输计划编制优化技术和轨道交通运输计划编制系统等11章。本书可作为高等学校交通运输、交通工程、铁道工程等相关课程教材，供本科与研究生教学使用，也可供交通运输部门从事实际生产工作的轨道交通专业技术人员、管理人员和交通勘察设计相关人员参考。', '前言
