  ('153', '内容简介
本书是战略性新兴领域“十四五”高等教育国家级规划教材、机器人技术与系统系列教材。本书首先讲述了传感与测量系统，以及测量系统误差等基础概念，之后主要介绍在精密传感领域中所使用的典型传感器，如电阻应变式、电容式传感器、电感式传感器、热电势传感器、压电式传感器、磁电式传感器、光电式传感器等，以及目前领域前沿MEMS传感器，最后讲述了传感器融合及智能化趋势。其中主要介绍了各类传感器的精密传感原理、设计方法与工程应用等。
本书能较好的满足高校测控技术与仪器、自动化等专业宽口径素质教学需要，并为专业技术人员提供参考。', 35.00, 28.00, 50, '内容简介
本书是战略性新兴领域“十四五”高等教育国家级规划教材、机器人技术与系统系列教材。本书首先讲述了传感与测量系统，以及测量系统误差等基础概念，之后主要介绍在精密传感领域中所使用的典型传感器，如电阻应变式、电容式传感器、电感式传感器、热电势传感器、压电式传感器、磁电式传感器、光电式传感器等，以及目前领域前沿MEMS传感器，最后讲述了传感器融合及智能化趋势。其中主要介绍了各类传感器的精密传感原理、设计方法与工程应用等。
本书能较好的满足高校测控技术与仪器、自动化等专业宽口径素质教学需要，并为专业技术人员提供参考。', '前言
