  ('152', '内容提要 本书是大数据新兴领域“十四五”高等教育教材。在当今社会，数据已经晋升为与传统土地、劳动力、资本和技术并列的“第五生产要素”。凭借其可共享、可复制的独特属性，数据对经济增长产生了倍增效应。然而，这些特征也进一步凸显了平衡数据价值与安全的重要性，以确保其能够持续发挥关键作用。因此，围绕数据隐私和隐私计算技术的研究已成为数据科学领域的热点议题。隐私计算技术正是为了在确保数据隐私的前提下，实现数据的协同处理、分析和应用，即实现“数据可用不可见”。作为一门交叉学科，隐私计算横跨了人工智能、密码学、数据科学等多个领域。本教材力求全面而系统地介绍数据隐私和隐私计算的基本概念，并深入阐述主流技术手段，包括安全多方计算、可信执行环境、联邦学习、差分隐私以及数据匿名化等。同时，本教材还结合了丰富的应用场景实例，将理论知识与实践应用紧密结合，旨在满足从本科生到研究生不同层次学习者的需求。', 39.00, 31.20, 209, '内容提要 本书是大数据新兴领域“十四五”高等教育教材。在当今社会，数据已经晋升为与传统土地、劳动力、资本和技术并列的“第五生产要素”。凭借其可共享、可复制的独特属性，数据对经济增长产生了倍增效应。然而，这些特征也进一步凸显了平衡数据价值与安全的重要性，以确保其能够持续发挥关键作用。因此，围绕数据隐私和隐私计算技术的研究已成为数据科学领域的热点议题。隐私计算技术正是为了在确保数据隐私的前提下，实现数据的协同处理、分析和应用，即实现“数据可用不可见”。作为一门交叉学科，隐私计算横跨了人工智能、密码学、数据科学等多个领域。本教材力求全面而系统地介绍数据隐私和隐私计算的基本概念，并深入阐述主流技术手段，包括安全多方计算、可信执行环境、联邦学习、差分隐私以及数据匿名化等。同时，本教材还结合了丰富的应用场景实例，将理论知识与实践应用紧密结合，旨在满足从本科生到研究生不同层次学习者的需求。', '前言
