  ('151', '本书全面介绍了通信集成电路设计的基础理论和实际应用，内容涵盖了通信系统的基本概念、数字基带信号处理基础理论及VLSI设计基础、数字通信调制与解调、信道编码与解码、射频通信系统、通信系统仿真设计等。本书不仅介绍了通信系统中的典型算法，并且将信号处理电路设计及优化技术与其相融合，具有较好的交叉视角。本书还提供了大量的习题、视频、仿真实例以及项目设计，以供读者将理论与实践结合。
本书可作为集成电路、通信工程相关专业的高年级本科生及研究生教材。对于从事通信集成电路设计的工程技术人员，本书也是一本具有理论和实践价值的参考书。', 30.00, 24.00, 100, '本书全面介绍了通信集成电路设计的基础理论和实际应用，内容涵盖了通信系统的基本概念、数字基带信号处理基础理论及VLSI设计基础、数字通信调制与解调、信道编码与解码、射频通信系统、通信系统仿真设计等。本书不仅介绍了通信系统中的典型算法，并且将信号处理电路设计及优化技术与其相融合，具有较好的交叉视角。本书还提供了大量的习题、视频、仿真实例以及项目设计，以供读者将理论与实践结合。
本书可作为集成电路、通信工程相关专业的高年级本科生及研究生教材。对于从事通信集成电路设计的工程技术人员，本书也是一本具有理论和实践价值的参考书。', '序言
