  ('149', '本书依据教育部高等学校土木工程专业教学指导分委员会的课程大纲和土木工程本科专业课程的教学大纲要求编写。全书共9章，内容包括地震和地震动的基本知识，建筑抗震的概念设计，场地、地基与基础的基本概念，结构地震反应分析与抗震验算方法，钢筋混凝土房屋、砌体房屋、钢结构房屋与非结构构件的抗震设计，以及隔震与消能减震房屋的设计等。
本书充分利用数字教材的特点，设置思维导图，梳理各章节知识点，并与知识点所在正文相关联。每章都附有本章提要、知识点视频解读、本章小结、思考题与习题等内容，帮助读者理解地震学与地震工程学的内在联系，熟悉建筑抗震设计的基本原理与方法，了解该领域的前沿技术。
