  ('148', '本教材依据教育部最新发布的《高等职业教育专科信息技术课程标准》及《全国高等学校计算机水平考试大纲》编写。本教材以行业企业用人需求为导向，落实立德树人根本任务，培养学生通过信息技术解决实际问题的能力。本教材分为信息素养与社会责任、信息检索技术、文档处理技术、电子表格处理、演示文稿制作、数字媒体技术、信息安全技术、新一代信息技术等8个模块，每个模块都以信息技术在生活、工作中的实际应用来设计导入任务。本教材内容丰富、案例新颖、结构清晰，配套建设了微课程视频、动画、辅学课件、习题等数字化资源，具有融媒体、交互式、智能化等特点。本教材可作为高等职业院校“信息技术”和“计算机应用基础”课程教材及全国计算机等级考试的备考用书，还可供计算机从业人员、信息技术爱好者自学参考。', 46.50, 37.20, 257, '本教材依据教育部最新发布的《高等职业教育专科信息技术课程标准》及《全国高等学校计算机水平考试大纲》编写。本教材以行业企业用人需求为导向，落实立德树人根本任务，培养学生通过信息技术解决实际问题的能力。本教材分为信息素养与社会责任、信息检索技术、文档处理技术、电子表格处理、演示文稿制作、数字媒体技术、信息安全技术、新一代信息技术等8个模块，每个模块都以信息技术在生活、工作中的实际应用来设计导入任务。本教材内容丰富、案例新颖、结构清晰，配套建设了微课程视频、动画、辅学课件、习题等数字化资源，具有融媒体、交互式、智能化等特点。本教材可作为高等职业院校“信息技术”和“计算机应用基础”课程教材及全国计算机等级考试的备考用书，还可供计算机从业人员、信息技术爱好者自学参考。', '前言
