  ('147', '内容提要
本教材由“常用机构的工作原理与运动分析”“挠性传动设计”“齿轮传动设计”“轴的设计”4个项目组成，各项目包含教学目标、工作任务、知识总结和练习题，每个项目由2～3个工作任务组成，每个工作任务涵盖任务描述、知识链接和任务实施。教材在内容体系的安排上注重工作任务的完整性、实践性，内容编写由浅入深、循序渐进，详略得当。
本教材是高等职业教育融媒体、交互式、智能化数字教材，教材中配置了大量的信息化资源，如二维动画、三维动画、教学视频、微课等，方便读者学习使用。
本教材突出工程实用性，贴合生产实际，内容详实，适合高等职业院校机械类和近机械类学生使用，也可作为相关岗位技术人员培训用书。', 48.00, 38.40, 862, '内容提要
本教材由“常用机构的工作原理与运动分析”“挠性传动设计”“齿轮传动设计”“轴的设计”4个项目组成，各项目包含教学目标、工作任务、知识总结和练习题，每个项目由2～3个工作任务组成，每个工作任务涵盖任务描述、知识链接和任务实施。教材在内容体系的安排上注重工作任务的完整性、实践性，内容编写由浅入深、循序渐进，详略得当。
本教材是高等职业教育融媒体、交互式、智能化数字教材，教材中配置了大量的信息化资源，如二维动画、三维动画、教学视频、微课等，方便读者学习使用。
本教材突出工程实用性，贴合生产实际，内容详实，适合高等职业院校机械类和近机械类学生使用，也可作为相关岗位技术人员培训用书。', '前言
绪论
　一、本课程的研究对象与基本概念
　二、本课程的性质、内容和任务
　三、本课程的学习方法
　四、机械设计的常用方法
