  ('146', '本教材以高职高专教育“理论够用、应用为主”的指导思想为原则，以机械制造业从业人员必需的基本理论、基本技能为主线，采用任务驱动的方式进行编写。全书共5个任务（包含16个子任务）：公差与检测、极限与配合、几何公差与检测、表面粗糙度及检测和典型零件的公差检测与应用。
