  ('145', '本书以教育部数控技术应用型紧缺人才的培训方案为指导思想，参照最新的数控、模具专业教学计划，根据“基本理论的教学以应用为目的，以必需和够用为尺度”这一指导原则编写。全书介绍了主流数控系统 FANUC0i-MB及SINUMERIK802S/C的基本功能，以先进而具体的工装设备、工艺路线和加工方法为例，讲述各种编程指令的综合应用及数控机床的操作；重点讲述了数控铣床的编程与操作步骤，并用数控仿真软件——上海宇龙数控仿真软件进行仿真运行，讲授知识由浅入深、循序渐进、讲解详细，使本教材具有针对性、可操作性和实用性，力争对数控加工制造领域人才的培养起到促进作用。', 45.60, 36.48, 124, '本书以教育部数控技术应用型紧缺人才的培训方案为指导思想，参照最新的数控、模具专业教学计划，根据“基本理论的教学以应用为目的，以必需和够用为尺度”这一指导原则编写。全书介绍了主流数控系统 FANUC0i-MB及SINUMERIK802S/C的基本功能，以先进而具体的工装设备、工艺路线和加工方法为例，讲述各种编程指令的综合应用及数控机床的操作；重点讲述了数控铣床的编程与操作步骤，并用数控仿真软件——上海宇龙数控仿真软件进行仿真运行，讲授知识由浅入深、循序渐进、讲解详细，使本教材具有针对性、可操作性和实用性，力争对数控加工制造领域人才的培养起到促进作用。', '前言
项目一 数控铣床基本操作
