  ('144', '本书主要内容包括业务受理与产品检测、软件安装与产品调试、产品拆装与屏幕维修、电路识图与故障维修。各项目以智能通信终端产品维修工程师的实际岗位工作过程为依据进行编写。
本书是高等职业教育融媒体、交互式、智能化数字教材。配有相关的微课视频、图片、在线测试等丰富的数字化教学资源，读者可在教材中直接点击浏览、操作、学习。
本书以简单易懂的项目为主线进行讲解，全面介绍了实现项目所需的知识点，既可作为高等职业院校智能产品开发与应用专业的教材，也可作为电子信息工程技术、应用电子技术等相关专业的教材，同时也是职业技能等级评价、职业技能大赛培训及社会培训的理想用书。', 46.80, 37.44, 74, '本书主要内容包括业务受理与产品检测、软件安装与产品调试、产品拆装与屏幕维修、电路识图与故障维修。各项目以智能通信终端产品维修工程师的实际岗位工作过程为依据进行编写。
本书是高等职业教育融媒体、交互式、智能化数字教材。配有相关的微课视频、图片、在线测试等丰富的数字化教学资源，读者可在教材中直接点击浏览、操作、学习。
