  ('143', '图书简介
本书以项目引领、教学一体化为特色，根据高职高专教学的基本要求，结合岗位技能职业标准，在保证知识体系完整的基础上，以智能终端产品项目案例为主线，以案例实际工作流程为任务，以技能培养为编写宗旨，是全国高等职业院校智能产品开发与应用专业国家级教学资源库配套教材。
本书的内容通过案例载体来展开，每个项目又依据实际工作流程分成多个子任务，这更有利于在了解岗位职责的同时进行系统学习，最后配有专项实训和课后习题，方便巩固知识点。
全书共有五个项目，分别介绍了客户服务基本技能、智能通信终端产品技术服务、智能家居技术服务、立式测温人证一体机技术服务和智能安防工程系统维护，此外，每个项目选材力求通俗、简明、实用、操作性强。
本书适合作为智能产品开发与应用专业教材，也可作为电子信息工程技术、应用电子技术等相关专业的教材使用，还可供智能终端产品维修技术人员和相关人员参考。', 49.80, 39.84, 17, '图书简介
本书以项目引领、教学一体化为特色，根据高职高专教学的基本要求，结合岗位技能职业标准，在保证知识体系完整的基础上，以智能终端产品项目案例为主线，以案例实际工作流程为任务，以技能培养为编写宗旨，是全国高等职业院校智能产品开发与应用专业国家级教学资源库配套教材。
本书的内容通过案例载体来展开，每个项目又依据实际工作流程分成多个子任务，这更有利于在了解岗位职责的同时进行系统学习，最后配有专项实训和课后习题，方便巩固知识点。
全书共有五个项目，分别介绍了客户服务基本技能、智能通信终端产品技术服务、智能家居技术服务、立式测温人证一体机技术服务和智能安防工程系统维护，此外，每个项目选材力求通俗、简明、实用、操作性强。
本书适合作为智能产品开发与应用专业教材，也可作为电子信息工程技术、应用电子技术等相关专业的教材使用，还可供智能终端产品维修技术人员和相关人员参考。', '前言
