  ('142', '本书包括6个项目，13个工作任务，编写中主要涉及车型为全国技能大赛典型车型比亚迪秦EV。本书以教育部《高等职业学校专业教学标准》及全国职业院校技能大赛标准、“1+X”新能源汽车装调与测试职业技能等级证书考核标准为准绳，有效融入企业检修实际案例、全国职业院校技能大赛汽车故障检修赛项典型案例，打破传统知识体系，以“必须、够用”为原则，成功将理论与实践融合，精准地体现了“学中做”和“做中学”。
本书是具有融媒体、智能化的数字教材，配有操作视频、微课、图片等资源，读者可在教材中直接点击浏览、操作、学习。
本书可作为高职高专学校、职教本科院校新能源汽车技术、汽车检测与维修、汽车电子技术、汽车试验技术等专业教材，也可供从事本专业工作的工程技术人员和维修技术人员学习参考。', 39.80, 31.84, 187, '本书包括6个项目，13个工作任务，编写中主要涉及车型为全国技能大赛典型车型比亚迪秦EV。本书以教育部《高等职业学校专业教学标准》及全国职业院校技能大赛标准、“1+X”新能源汽车装调与测试职业技能等级证书考核标准为准绳，有效融入企业检修实际案例、全国职业院校技能大赛汽车故障检修赛项典型案例，打破传统知识体系，以“必须、够用”为原则，成功将理论与实践融合，精准地体现了“学中做”和“做中学”。
本书是具有融媒体、智能化的数字教材，配有操作视频、微课、图片等资源，读者可在教材中直接点击浏览、操作、学习。
本书可作为高职高专学校、职教本科院校新能源汽车技术、汽车检测与维修、汽车电子技术、汽车试验技术等专业教材，也可供从事本专业工作的工程技术人员和维修技术人员学习参考。', '前言
