  ('141', '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材引入广告设计公司4A作业规范，融入1+X技能等级证书“数字影像处理（中级）”技能点，联合浙江时光坐标科技股份有限公司、山东新视觉新媒体传媒有限公司组建教材编写及资源开发团队，对标新媒体、平面设计，尤其是虚拟现实产品设计等行业对平面图像的新要求及设计规范编写教材内容。以提升职业岗位技能和素质培养为主线，采用企业案例，遵循岗位工作流程，项目式体例编写，以任务为导向，引导学生整合与应用所学知识。遵循学生的认知规律，详细讲解了Photoshop的强大的图形图像处理功能及在实际工作中应用，适当补充实用的平面设计相关知识，弥补计算机专业学生平面设计理论知识的不足，循序渐进地培养学生对平面图形图像的绘制、处理、创作的专业知识和技能，关注学生掌握理论知识后的实践活动，注重培养学生的创新思维、学习方法、学习能力。
本教材借助现代信息技术，配套相关的微课视频、重难点动画等多种信息化资源助力教学，内容详实，结构清晰，语言流畅，实例分析透彻，介绍的操作步骤简洁实用。
本教材既适合作为各类高职高专院校学生相关课程的教材，也可作为计算机培训学校的教材作为平面设计人员以及从事图形图像设计相关工作人员的参考书。', 49.80, 39.84, 890, '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材引入广告设计公司4A作业规范，融入1+X技能等级证书“数字影像处理（中级）”技能点，联合浙江时光坐标科技股份有限公司、山东新视觉新媒体传媒有限公司组建教材编写及资源开发团队，对标新媒体、平面设计，尤其是虚拟现实产品设计等行业对平面图像的新要求及设计规范编写教材内容。以提升职业岗位技能和素质培养为主线，采用企业案例，遵循岗位工作流程，项目式体例编写，以任务为导向，引导学生整合与应用所学知识。遵循学生的认知规律，详细讲解了Photoshop的强大的图形图像处理功能及在实际工作中应用，适当补充实用的平面设计相关知识，弥补计算机专业学生平面设计理论知识的不足，循序渐进地培养学生对平面图形图像的绘制、处理、创作的专业知识和技能，关注学生掌握理论知识后的实践活动，注重培养学生的创新思维、学习方法、学习能力。
本教材借助现代信息技术，配套相关的微课视频、重难点动画等多种信息化资源助力教学，内容详实，结构清晰，语言流畅，实例分析透彻，介绍的操作步骤简洁实用。
本教材既适合作为各类高职高专院校学生相关课程的教材，也可作为计算机培训学校的教材作为平面设计人员以及从事图形图像设计相关工作人员的参考书。', '前言
