  ('140', '本教材面向高等职业教育，教材编写充分考虑了高等职业院校学生的学习基础，按照职业岗位需求，结合高等职业院校学生的学习特点，以学生为主体、教师为主导，依据岗位能力设计教学模块，采用“教、学、做”一体化教学方法，教材内容秉承“理论够用、重在实践”的原则进行设计，秉持“项目引领、任务驱动”理念，将C 语言程序设计的基础知识、选择结构、循环结构、数组、函数、指针、结构体及文件等内容进行重构，设计了“简易个人信息系统”“简易体重管理系统”“简易密码验证系统”“学生成绩管理系统”“学生信息管理系统”五个典型教学项目。
本教材是高等职业教育融媒体、交互式、智能化数字教材。配有相关的微课视频、重难点动画、在线测试等丰富的数字化教学资源，读者可在教材中直接点击浏览、操作、学习。 本教材概念清楚、语言简洁、知识结构合理、通俗易懂、适用性强，可作为高等职业教育电子与信息大类、装备制造大类相关专业的“C语言程序设计”课程教材，零基础或有一定基础的学生均可使用本教材。', 49.80, 39.84, 460, '本教材面向高等职业教育，教材编写充分考虑了高等职业院校学生的学习基础，按照职业岗位需求，结合高等职业院校学生的学习特点，以学生为主体、教师为主导，依据岗位能力设计教学模块，采用“教、学、做”一体化教学方法，教材内容秉承“理论够用、重在实践”的原则进行设计，秉持“项目引领、任务驱动”理念，将C 语言程序设计的基础知识、选择结构、循环结构、数组、函数、指针、结构体及文件等内容进行重构，设计了“简易个人信息系统”“简易体重管理系统”“简易密码验证系统”“学生成绩管理系统”“学生信息管理系统”五个典型教学项目。
本教材是高等职业教育融媒体、交互式、智能化数字教材。配有相关的微课视频、重难点动画、在线测试等丰富的数字化教学资源，读者可在教材中直接点击浏览、操作、学习。 本教材概念清楚、语言简洁、知识结构合理、通俗易懂、适用性强，可作为高等职业教育电子与信息大类、装备制造大类相关专业的“C语言程序设计”课程教材，零基础或有一定基础的学生均可使用本教材。', '前言
