  ('139', '本书对接2023年职业教育国家在线精品课程“SIMATIC S7-1500 PLC综合应用”，以西门子S7-1500 PLC为学习机型，以全自动灌装生产线的工作流程为主线，碎片化PLC指令和设计方法，舍弃跳转编程等旧内容，增添SCL、图形化编程、结构化编程新方法，融合触摸屏技术，融入“复兴号产线”等思政案例，序化重构教材内容，按学生认知规律，由浅到深，通过“基础模块”“应用模块”两大模块递进展开。
本书实现了互联网与传统教育的完美结合，采用数字化新形态的出版形式，基于高等教育出版社云创平台学习微课、动画等视频类数字资源，突破传统课堂教学的时空限制，激发学生自主学习的积极性，打造高效课堂。
本书可作为高等职业院校机电、电气相关专业的教材，也可以作为工程技术人员学习可编程控制器的参考书。', 49.80, 39.84, 630, '本书对接2023年职业教育国家在线精品课程“SIMATIC S7-1500 PLC综合应用”，以西门子S7-1500 PLC为学习机型，以全自动灌装生产线的工作流程为主线，碎片化PLC指令和设计方法，舍弃跳转编程等旧内容，增添SCL、图形化编程、结构化编程新方法，融合触摸屏技术，融入“复兴号产线”等思政案例，序化重构教材内容，按学生认知规律，由浅到深，通过“基础模块”“应用模块”两大模块递进展开。
本书实现了互联网与传统教育的完美结合，采用数字化新形态的出版形式，基于高等教育出版社云创平台学习微课、动画等视频类数字资源，突破传统课堂教学的时空限制，激发学生自主学习的积极性，打造高效课堂。
本书可作为高等职业院校机电、电气相关专业的教材，也可以作为工程技术人员学习可编程控制器的参考书。', '前言
模块1 电动机单向启停的S7-1500 PLC控制系统——基础篇
　项目1.1 电动机单向启停的S7-1500 PLC硬件系统
　　任务1.1.1 探寻工业控制中的PLC系统
　　任务1.1.2 安装电动机单向启停的PLC硬件模块
　　任务1.1.3 连接与调试电动机单向启停的PLC硬件线路
　　项目1.1 测试题
　项目1.2 电动机单向启停的S7-1500 PLC软件系统
　　任务1.2.1 探秘PLC的工作原理
　　任务1.2.2 设计与仿真电动机单向启停的PLC软件程序
　　项目1.2 测试题
　项目1.3 电动机单向启停的S7-1500 PLC软硬件综合系统
　　任务1.3 调试与实现电动机单向启停的PLC软硬件综合系统
