　　任务2.1.3 提升：探讨并行灌装线流程的PLC控制系统
　　项目2.1 测试题
　项目2.2 自动注液阀的S7-1500 PLC控制系统
　　任务2.2.1 设计电动机点动和连续混合运行的PLC控制系统
　　任务2.2.2 实现自动注液阀的PLC控制系统
　　任务2.2.3 提升：探讨自动灌装生产线的程序架构
　　项目2.2 测试题
　项目2.3 运料货物车的S7-1500 PLC控制系统
　　任务2.3.1 设计电动机正反转的PLC控制系统
　　任务2.3.2 实现运料车定位往复的PLC控制系统（起保停法）
　　任务2.3.3 实现运料车定位往复的PLC控制系统（置位复位法）
　　任务2.3.4 提升：“置位复位”设计自动化灌装生产线的“模式选择”FC和“单步调试”FC
　　项目2.3 测试题
　项目2.4 装料卸料门的S7-1500 PLC控制系统
　　任务2.4.1 设计电动机单键启停的PLC控制系统
　　任务2.4.2 实现装料卸料门单键顺启逆停的PLC控制系统
　　任务2.4.3 提升：应用SCL语言搭建运料卸料系统的仿真输入信号
　　项目2.4 测试题
　项目2.5 混料加热罐的S7-1500 PLC控制系统
　　任务2.5.1 设计电动机定时运行的PLC控制系统
　　任务2.5.2 设计数目超额自动报警的PLC控制系统
　　任务2.5.3 实现混料加热罐定时定次自动运行的PLC控制系统
　　任务2.5.4 提升：应用FB函数块和背景DB设计可复用的混料加热系统
　　项目2.5 测试题
　项目2.6 送瓶灌装站的S7-1500 PLC控制系统
　　任务2.6.1 设计与实现送瓶灌装站的PLC控制系统
　　任务2.6.2 提升：应用OB30组织块和触摸屏组态实现送瓶灌装站的动画展示
　　项目2.6 测试题
　项目2.7 机械手装箱的S7-1500 PLC控制系统
　　任务2.7.1 “起保停”顺序控制法实现机械手装箱的PLC控制系统
　　任务2.7.2 “置位复位”顺序控制法实现机械手装箱的PLC控制系统
　　任务2.7.3 “Graph”顺序功能图语言实现机械手装箱的PLC控制系统
