　　项目2.7 测试题
　项目2.8 自动化仓库的S7-1500 PLC控制系统
　　任务2.8.1 设计仓库货物数自动显示的PLC控制系统
　　任务2.8.2 设计仓库总容量自助设置的PLC控制系统
　　任务2.8.3 实现智能温控及自动化仓储的PLC控制系统
　　任务2.8.4 提升：应用OB100实现自动化灌装生产线的出厂复位
　　项目2.8 测试题
参考文献'),
  ('138', '本教材内容将理论知识与实践技能高度结合，共编写了六个项目，分别为：S7-1200 PLC和TIA博图软件认知、S7-1200 PLC 基本指令应用、S7-1200 PLC程序结构设计、S7-1200 PLC以太网通信技术应用、基于S7-1200 PLC、G120变频器的电动机控制、S7-1200 PLC与HMI的综合应用。每个项目包含：项目导入、学习目标、若干个任务、项目小结和项目作业。教材中选用的典型项目任务部分来源于比亚迪生产现场的PLC控制系统案例，适合进行理实一体化教学，有利于培养学生的工程意识和分析问题、解决问题的能力。
本教材是高等职业教育融媒体、交互式、智能化数字教材，配有操作视频、微课、在线测试等数字化教学资源，读者可在教材中直接点击浏览、操作、学习。
本教材可以作为高职专科自动化类机电一体化技术专业、电气自动化技术专业等相关专业的教材，也可以作为职业培训学校的可编程控制器技术与应用培训教材，或作为相关工程技术人员的自学参考书。', 40.00, 32.00, 207, '本教材内容将理论知识与实践技能高度结合，共编写了六个项目，分别为：S7-1200 PLC和TIA博图软件认知、S7-1200 PLC 基本指令应用、S7-1200 PLC程序结构设计、S7-1200 PLC以太网通信技术应用、基于S7-1200 PLC、G120变频器的电动机控制、S7-1200 PLC与HMI的综合应用。每个项目包含：项目导入、学习目标、若干个任务、项目小结和项目作业。教材中选用的典型项目任务部分来源于比亚迪生产现场的PLC控制系统案例，适合进行理实一体化教学，有利于培养学生的工程意识和分析问题、解决问题的能力。
本教材是高等职业教育融媒体、交互式、智能化数字教材，配有操作视频、微课、在线测试等数字化教学资源，读者可在教材中直接点击浏览、操作、学习。
本教材可以作为高职专科自动化类机电一体化技术专业、电气自动化技术专业等相关专业的教材，也可以作为职业培训学校的可编程控制器技术与应用培训教材，或作为相关工程技术人员的自学参考书。', '前言
