  ('137', '本书是按照高职院校人才培养目标及专业教学改革的需要，依据建筑工程最新的国家有关标准及相关专业施工规范编写的。以施工员、建造师等职业岗位能力培养为导向，融合装配式建筑施工员职业技能大赛及“1+X”证书的考核要求，结合工程实例，以建筑工程分部分项工程施工为主线进行编写，实现标准引领、“岗赛课证”融通。本书反映了国内外建筑施工技术的最新动态，结合工程实例，以常见分部分项工程施工为主线进行编写，重点内容包括：土方工程施工、地基与基础工程施工、砌体工程施工、钢筋混凝土工程施工、预应力钢筋混凝土施工、装配式混凝土工程施工、防水与保温工程施工和装饰工程施工等。 本书对建筑工程施工的工序、工艺、质量标准等采用案例导入、问题导向的全新体例编写，在编写工作中注重以培养德技并修的技术技能型人才为目标，以培养职业道德和专业技术能力为主线。结合高等职业教育的教学特点，通过建筑规范、知识链接、建筑大师、榜样引领等模块，在课程教学中育人，在课程实践中立德，加强学生职业道德的培养。教材内容紧跟建筑行业新技术、新工艺、新标准规范的发展步伐，保证了教材的灵活性、实效性和适应性。 本书在编写上力求体系完整、内容精练、文字表达流畅，所附插图力求准确直观，阐述上力求由浅入深，内容全面。利用信息化教学手段，凸显职业教育的特色，充分吸纳企业和同类院校的优质教学资源，做到校企双元，产教融合，编写了配套的电子课件、微视频、教学习题等教学资源包，以满足校内师生教学和社会企业人员学习的需要，形成高质量教学资源体系。 本书既可作为高职高专院校建筑工程类相关专业的教材和教学指导书，也可作为土建施工类及工程管理类各专业职业资格考试的参考教材。', 68.00, 54.40, 132, '本书是按照高职院校人才培养目标及专业教学改革的需要，依据建筑工程最新的国家有关标准及相关专业施工规范编写的。以施工员、建造师等职业岗位能力培养为导向，融合装配式建筑施工员职业技能大赛及“1+X”证书的考核要求，结合工程实例，以建筑工程分部分项工程施工为主线进行编写，实现标准引领、“岗赛课证”融通。本书反映了国内外建筑施工技术的最新动态，结合工程实例，以常见分部分项工程施工为主线进行编写，重点内容包括：土方工程施工、地基与基础工程施工、砌体工程施工、钢筋混凝土工程施工、预应力钢筋混凝土施工、装配式混凝土工程施工、防水与保温工程施工和装饰工程施工等。 本书对建筑工程施工的工序、工艺、质量标准等采用案例导入、问题导向的全新体例编写，在编写工作中注重以培养德技并修的技术技能型人才为目标，以培养职业道德和专业技术能力为主线。结合高等职业教育的教学特点，通过建筑规范、知识链接、建筑大师、榜样引领等模块，在课程教学中育人，在课程实践中立德，加强学生职业道德的培养。教材内容紧跟建筑行业新技术、新工艺、新标准规范的发展步伐，保证了教材的灵活性、实效性和适应性。 本书在编写上力求体系完整、内容精练、文字表达流畅，所附插图力求准确直观，阐述上力求由浅入深，内容全面。利用信息化教学手段，凸显职业教育的特色，充分吸纳企业和同类院校的优质教学资源，做到校企双元，产教融合，编写了配套的电子课件、微视频、教学习题等教学资源包，以满足校内师生教学和社会企业人员学习的需要，形成高质量教学资源体系。 本书既可作为高职高专院校建筑工程类相关专业的教材和教学指导书，也可作为土建施工类及工程管理类各专业职业资格考试的参考教材。', '前言
