  ('136', '本教材挖掘、整理湖北省最具特色的传统民间舞蹈，将之与当代舞蹈行业审美、发展需求相结合，具有极高的原创性。本教材由“跳丧”“摆手”两个徒手类民间舞蹈，“碟子舞”“莲湘”“耍耍”三个道具类民间舞蹈组成五个教学模块。本教材编写组深入剖析设计之“理”，示范之“法”，引导达成训练之“果”。本教材内容生动，可读性强，实践成果权威而丰富，是对中华传统文化的创新性继承和创造性发展。本教材可作为高等职业院校文化艺术大类舞蹈相关专业教材，也可作为教育培训机构和社会相关行业从业人士业务参考书。', 49.50, 39.60, 55, '本教材挖掘、整理湖北省最具特色的传统民间舞蹈，将之与当代舞蹈行业审美、发展需求相结合，具有极高的原创性。本教材由“跳丧”“摆手”两个徒手类民间舞蹈，“碟子舞”“莲湘”“耍耍”三个道具类民间舞蹈组成五个教学模块。本教材编写组深入剖析设计之“理”，示范之“法”，引导达成训练之“果”。本教材内容生动，可读性强，实践成果权威而丰富，是对中华传统文化的创新性继承和创造性发展。本教材可作为高等职业院校文化艺术大类舞蹈相关专业教材，也可作为教育培训机构和社会相关行业从业人士业务参考书。', '序言与前言
