　　五、《炫碟飞》碟技组合
　　六、综合组合（碟子舞表演）
　　七、传统组合
第二章 莲湘
　第一部分 基础知识
　　一、“莲湘”介绍
　　二、“莲湘”的设计与编创
　第二部分 训练组合（女班）
　　一、《围身打》打法组合
　　二、《龙缠身》动律组合
　　三、《灵逸步》步伐组合
　　四、《紫竹奏》竹花组合
　　五、综合组合（莲湘表演）
　第三部分 训练组合（男班）
　　一、《围身打》打法组合
　　二、《龙缠身》动律组合
　　三、《临风步》步伐组合
　　四、传统短句（滚龙连厢）
第三章 耍耍
