　　二、“耍耍”的设计与编创
　第二部分 训练组合
　　一、《耍耍扇》扇花组合
　　二、《农闲乐》文耍耍组合
　　三、《逗幺妹儿》武耍耍组合
　　四、综合组合（耍耍表演）
