  ('135', '本书为职业本科教育数字艺术类课程系列教材之一，同时为一本融媒体、交互式、智能化数字教材。本书以适应岗位技能及为进入更为专业领域的学习打好基础为出发点，将设计原理、设计流程与Illustrator、Photoshop具体操作深度融合，知识与技能并行，内容包含设计导论、标志设计、插画设计（包括设计色彩和图案与纹样设计）、文字创意设计、版式设计、图册设计、海报与主视觉设计等，按知识点的连贯性依次设立了7个项目，15个任务模块。项目设计以工作任务为导向，由任务入手引入相关知识和理论；通过技能训练引出相关概念、设计理念与软件操作技能；体现任务驱动、以学生为中心，突出实践性、趣味性、职业性，体现“教、学、做合一”的设计理念。在每个项目的知识构架中，除了知识讲授、技能教学，还包括企业案例、实训操作，使课程目标与专业需求、行业需求的对应关系更为明确。
本书可作为职业本科数字媒体艺术、视觉传达设计等相关专业教材，也可供设计工作者参考。', 39.50, 31.60, 202, '本书为职业本科教育数字艺术类课程系列教材之一，同时为一本融媒体、交互式、智能化数字教材。本书以适应岗位技能及为进入更为专业领域的学习打好基础为出发点，将设计原理、设计流程与Illustrator、Photoshop具体操作深度融合，知识与技能并行，内容包含设计导论、标志设计、插画设计（包括设计色彩和图案与纹样设计）、文字创意设计、版式设计、图册设计、海报与主视觉设计等，按知识点的连贯性依次设立了7个项目，15个任务模块。项目设计以工作任务为导向，由任务入手引入相关知识和理论；通过技能训练引出相关概念、设计理念与软件操作技能；体现任务驱动、以学生为中心，突出实践性、趣味性、职业性，体现“教、学、做合一”的设计理念。在每个项目的知识构架中，除了知识讲授、技能教学，还包括企业案例、实训操作，使课程目标与专业需求、行业需求的对应关系更为明确。
本书可作为职业本科数字媒体艺术、视觉传达设计等相关专业教材，也可供设计工作者参考。', '前言
