  ('134', '航海仪器（nautical instruments），是用于确定船舶位置和保证其安全航行的各种仪器的统称。
本书内容共包含九个项目，分别是导航卫星系统、回声测深仪、自动识别系统、船舶计程仪、船载航行数据记录仪、船舶远程识别与跟踪系统、船舶磁罗经、船舶陀螺罗经和船舶导航雷达。
本书在内容、结构和体例上均有创新，采用项目引导的教学方式，突出面向船舶驾驶员航海仪器操作的职业能力培养，辅以专业理论知识。本书内容满足《海船船员培训大纲（2021版）》《海船船员考试大纲（2022版）》和《1978年海员培训、发证和值班标准国际公约》的相关要求，力求知识点全面、针对性强、实用性强、图文并茂、易于学员学习、理解，旨在帮助学员顺利通过海船船员适任考试，同时传播行业发展的新知识、新标准、新规范，突出应用能力培养。
本书满足航海技术专业人才培养方案中对航海仪器的要求，可作为高职院校航海技术专业“航海仪器”课程二副、三副适任证书考试及定向培养军士生的培训教材，也可用作交通运输类轮机工程技术专业、港口管理专业及相关专业师生的选修教材或教学参考书，还可作为商船、舰艇驾驶员和引航人员、港口管理人员等其他有关人员的技术参考书。', 40.00, 32.00, 72, '航海仪器（nautical instruments），是用于确定船舶位置和保证其安全航行的各种仪器的统称。
本书内容共包含九个项目，分别是导航卫星系统、回声测深仪、自动识别系统、船舶计程仪、船载航行数据记录仪、船舶远程识别与跟踪系统、船舶磁罗经、船舶陀螺罗经和船舶导航雷达。
本书在内容、结构和体例上均有创新，采用项目引导的教学方式，突出面向船舶驾驶员航海仪器操作的职业能力培养，辅以专业理论知识。本书内容满足《海船船员培训大纲（2021版）》《海船船员考试大纲（2022版）》和《1978年海员培训、发证和值班标准国际公约》的相关要求，力求知识点全面、针对性强、实用性强、图文并茂、易于学员学习、理解，旨在帮助学员顺利通过海船船员适任考试，同时传播行业发展的新知识、新标准、新规范，突出应用能力培养。
本书满足航海技术专业人才培养方案中对航海仪器的要求，可作为高职院校航海技术专业“航海仪器”课程二副、三副适任证书考试及定向培养军士生的培训教材，也可用作交通运输类轮机工程技术专业、港口管理专业及相关专业师生的选修教材或教学参考书，还可作为商船、舰艇驾驶员和引航人员、港口管理人员等其他有关人员的技术参考书。', '前 言
