  ('133', '本教材围绕字体设计，从基础理论到实践操作，字体设计是设计类专业的基础课程。本教材围绕字体设计，从基础理论到实践操作全方位展开，以七个模块为架构，包含字体设计概论、字体的进化历程、民间字体设计、字体的基础知识、字体设计的方法、字体的形态与风格、字体设计案例分析与实训，讲述字体设计的定义与范畴、发展与创新、方法与实践等，助力提升学生的字体设计能力与审美能力。
本教材可作为视觉传达、广告设计、包装设计等专业学生的学习用书，也可供相关行业从业者参考学习。', 30.00, 24.00, 107, '本教材围绕字体设计，从基础理论到实践操作，字体设计是设计类专业的基础课程。本教材围绕字体设计，从基础理论到实践操作全方位展开，以七个模块为架构，包含字体设计概论、字体的进化历程、民间字体设计、字体的基础知识、字体设计的方法、字体的形态与风格、字体设计案例分析与实训，讲述字体设计的定义与范畴、发展与创新、方法与实践等，助力提升学生的字体设计能力与审美能力。
本教材可作为视觉传达、广告设计、包装设计等专业学生的学习用书，也可供相关行业从业者参考学习。', '前言
