  ('132', '《牧草及饲料作物育种学实验指导》一书全面覆盖了引种、种质资源评价、牧草繁殖方式、选择育种、杂交育种、杂种优势利用、远缘杂交、倍性育种、抗逆育种、基因工程育种等多个关键领域。书中详细阐述了牧草及饲料作物新品种选育过程中所需的实验技能和实践技巧，旨在帮助学生将理论知识与生产实践紧密结合，解决学习与应用之间的脱节问题。本教材所采用的实验方法均源自国内多位牧草育种专家超过20年的实践经验，经过归纳、筛选和修正，既新颖实用又有效可靠。这些方法不仅重点突出了本科教学的适用性，而且可以作为教学参考书使用，同时也适用于企事业单位的培训和研修。', 28.00, 22.40, 89, '《牧草及饲料作物育种学实验指导》一书全面覆盖了引种、种质资源评价、牧草繁殖方式、选择育种、杂交育种、杂种优势利用、远缘杂交、倍性育种、抗逆育种、基因工程育种等多个关键领域。书中详细阐述了牧草及饲料作物新品种选育过程中所需的实验技能和实践技巧，旨在帮助学生将理论知识与生产实践紧密结合，解决学习与应用之间的脱节问题。本教材所采用的实验方法均源自国内多位牧草育种专家超过20年的实践经验，经过归纳、筛选和修正，既新颖实用又有效可靠。这些方法不仅重点突出了本科教学的适用性，而且可以作为教学参考书使用，同时也适用于企事业单位的培训和研修。', '绪 论
