  ('131', '本教材立足于黑土地保护的国家重大战略，以服务东北黑土区农业生态、资源利用和环境保护等方面的教学与研究为目标，系统介绍了土壤、植物营养、肥料、农业环境保护等多方面的基础理论知识与专业实验分析方法。教材共包括十五章，涉及三大类实验项目：土壤性质分析实验、植物营养与肥料分析实验、环境污染分析实验。各章都设计了实验项目概述、分析方法、教学案例及分析等内容。本教材可作为东北地区乃至全国高等农业院校农业资源与环境（或资源环境科学）专业的核心实验课程教材，也适用于涉农高等院校植物生产类各专业及农业资源与环境保护相关专业的师生学习和参考，同时也可为从事相关领域研究及推广的广大农业科技工作者开展实验分析提供参考。', 28.00, 22.40, 214, '本教材立足于黑土地保护的国家重大战略，以服务东北黑土区农业生态、资源利用和环境保护等方面的教学与研究为目标，系统介绍了土壤、植物营养、肥料、农业环境保护等多方面的基础理论知识与专业实验分析方法。教材共包括十五章，涉及三大类实验项目：土壤性质分析实验、植物营养与肥料分析实验、环境污染分析实验。各章都设计了实验项目概述、分析方法、教学案例及分析等内容。本教材可作为东北地区乃至全国高等农业院校农业资源与环境（或资源环境科学）专业的核心实验课程教材，也适用于涉农高等院校植物生产类各专业及农业资源与环境保护相关专业的师生学习和参考，同时也可为从事相关领域研究及推广的广大农业科技工作者开展实验分析提供参考。', '前言
