  ('130', '该教材由三大内容组成：实验操作、虚拟仿真、作业与习题。其中，实验操作分为二大部分：第一部分是总论的实验，结合总论的作物生长研究法而开设，包括叶面积测定和作物生长分析；第二部分为各论实验内容，主要包括作物的形态观测和类型识别、穗分化、测土配方施肥、测产和考种分析、品质测定及改良。该教材将理论与实际相结合，通过对实验内容和教学方法的改进，使学生了解生产现状、提高学习兴趣、丰富专业知识。本教材可作为相关专业本科生教学使用，也适用于继续教育学生学习。', 28.00, 22.40, 257, '该教材由三大内容组成：实验操作、虚拟仿真、作业与习题。其中，实验操作分为二大部分：第一部分是总论的实验，结合总论的作物生长研究法而开设，包括叶面积测定和作物生长分析；第二部分为各论实验内容，主要包括作物的形态观测和类型识别、穗分化、测土配方施肥、测产和考种分析、品质测定及改良。该教材将理论与实际相结合，通过对实验内容和教学方法的改进，使学生了解生产现状、提高学习兴趣、丰富专业知识。本教材可作为相关专业本科生教学使用，也适用于继续教育学生学习。', '内容提要
