参考文献'),
  ('129', '《影视非线性编辑教程》是一本面向影视制作爱好者和专业人士的实用教程，全面覆盖了非线性编辑的各个环节。首先，本书从数字视频标准入手，介绍了视频时间、电视制式、分辨率与宽高比、视频压缩等基础知识，为读者打下坚实的理论基石。然后，本书详细讲解了软件工作流程，包括项目创建、素材导入、剪辑、字幕添加、特效应用、音量调整等，帮助读者熟悉非线性编辑软件的操作。其次，在剪辑基本操作章节，深入探讨了导入素材、离线编辑、代理文件使用、保存与输出等关键步骤。最后，从字幕制作、关键帧动画和调色、多机位剪辑和音频编辑等各个板块详细阐述了具体的操作流程。《影视非线性编辑教程》内容丰富、结构清晰，适合不同层次的读者学习，是影视后期制作的宝贵参考资料。通过学习本书，读者将能够熟练掌握非线性编辑技能，提升影视作品的整体质量。', 28.00, 22.40, 213, '《影视非线性编辑教程》是一本面向影视制作爱好者和专业人士的实用教程，全面覆盖了非线性编辑的各个环节。首先，本书从数字视频标准入手，介绍了视频时间、电视制式、分辨率与宽高比、视频压缩等基础知识，为读者打下坚实的理论基石。然后，本书详细讲解了软件工作流程，包括项目创建、素材导入、剪辑、字幕添加、特效应用、音量调整等，帮助读者熟悉非线性编辑软件的操作。其次，在剪辑基本操作章节，深入探讨了导入素材、离线编辑、代理文件使用、保存与输出等关键步骤。最后，从字幕制作、关键帧动画和调色、多机位剪辑和音频编辑等各个板块详细阐述了具体的操作流程。《影视非线性编辑教程》内容丰富、结构清晰，适合不同层次的读者学习，是影视后期制作的宝贵参考资料。通过学习本书，读者将能够熟练掌握非线性编辑技能，提升影视作品的整体质量。', '第一章 数字视频标准
