  ('128', '本书全面系统地介绍了C语言程序设计的基础知识与应用技巧，涵盖了从数据类型、控制结构、函数到指针、数组和文件操作等各个方面的内容。采用循序渐进的教学方法，引导读者逐步深入理解C语言的核心概念。通过清晰的讲解和丰富的实例，帮助读者从零开始，逐步掌握C语言的编程技能。书中精选了大量实际案例提升读者的综合应用能力。同时，本书特别注重知识点之间的连贯性和系统性，使读者能够系统地构建起完整的C语言知识体系。本书适用于广大初学者，包括高等院校计算机专业学生、计算机培训班学员以及对编程感兴趣的自学者。', 28.00, 22.40, 1741, '本书全面系统地介绍了C语言程序设计的基础知识与应用技巧，涵盖了从数据类型、控制结构、函数到指针、数组和文件操作等各个方面的内容。采用循序渐进的教学方法，引导读者逐步深入理解C语言的核心概念。通过清晰的讲解和丰富的实例，帮助读者从零开始，逐步掌握C语言的编程技能。书中精选了大量实际案例提升读者的综合应用能力。同时，本书特别注重知识点之间的连贯性和系统性，使读者能够系统地构建起完整的C语言知识体系。本书适用于广大初学者，包括高等院校计算机专业学生、计算机培训班学员以及对编程感兴趣的自学者。', '前言
