  ('127', '本数字教材系统全面介绍了植物细胞工程的基本原理与主要技术应用，内容包括植物细胞工程基础、植物组织快速繁殖技术、植物体细胞胚发生、植物胚胎培养、植物人工种子技术、植物脱毒培养、植物单倍体与多倍体育种、植物细胞培养反应器、植物原生质体培养、植物的离体受精、植物体细胞杂交与转基因植物等。教材配套视频讲解、教学课件、自测题等数字课程资源，便于师生参考使用。本教材可作为高等院校生物技术、农学、林学、园艺等相关专业本科生的教材，也可供相关专业研究生、教师与科研工作者开展植物细胞工程相关研究时参考。', 58.00, 46.40, 273, '本数字教材系统全面介绍了植物细胞工程的基本原理与主要技术应用，内容包括植物细胞工程基础、植物组织快速繁殖技术、植物体细胞胚发生、植物胚胎培养、植物人工种子技术、植物脱毒培养、植物单倍体与多倍体育种、植物细胞培养反应器、植物原生质体培养、植物的离体受精、植物体细胞杂交与转基因植物等。教材配套视频讲解、教学课件、自测题等数字课程资源，便于师生参考使用。本教材可作为高等院校生物技术、农学、林学、园艺等相关专业本科生的教材，也可供相关专业研究生、教师与科研工作者开展植物细胞工程相关研究时参考。', '前言
