  ('126', '《生物工程专业综合实验》主要介绍生物工程主要专业实验课程的基本操作技术与实验手段，全书共分三章：发酵工程实验、酶工程实验和生物工程分析实验。在本书编写的过程中，以学生的需求和专业培养目标为总的指导思想，力求理论联系实际，既保证本专业常规常用技术，又能将相关实验与其对应的理论课程有机结合，形成既具有一定理论体系又具有一定通用性和指导性的教学实验用书。本书可以作为高等院校生物科学、生物技术、生物工程等专业本专科生的教材，也可作为相关学科科技人员和研究生的参考用书。', 28.00, 22.40, 278, '《生物工程专业综合实验》主要介绍生物工程主要专业实验课程的基本操作技术与实验手段，全书共分三章：发酵工程实验、酶工程实验和生物工程分析实验。在本书编写的过程中，以学生的需求和专业培养目标为总的指导思想，力求理论联系实际，既保证本专业常规常用技术，又能将相关实验与其对应的理论课程有机结合，形成既具有一定理论体系又具有一定通用性和指导性的教学实验用书。本书可以作为高等院校生物科学、生物技术、生物工程等专业本专科生的教材，也可作为相关学科科技人员和研究生的参考用书。', '前言
