  ('124', '本教材主要以数字化形式呈现，分理论篇与实践篇，理论篇介绍了大学体育与健康、体适能与运动处方、体育卫生与运动损伤、体育竞赛与欣赏等方面的内容；实践篇包括球类运动、操舞类运动、民族传统体育运动、求生技能、户外休闲娱乐等五部分，球类运动重点介绍了篮球、足球、排球、乒乓球、羽毛球、网球、棒垒球、橄榄球等球类项目运动文化、基本技战术、练习方法、比赛规则裁判法及竞赛欣赏；操舞类运动重点介绍了健美操、啦啦操、瑜伽、体育舞蹈、形体舞蹈等项目运动文化、教学练习方法、运动展演与欣赏等；民族传统体育运动重点介绍了武术、健身气功、散打、拳击、跆拳道、空手道、太极扇等项目运动文化、基本技术、练习方法、竞赛规则和竞赛展演欣赏；求生技能重点介绍了田径、体操、游泳等项目运动文化、教学练习方法手段、竞赛规则与赛事欣赏；户外休闲娱乐重点介绍了极限飞盘、攀岩等项目运动文化、基本知识、基本技术和竞赛规则。所有项目配有技术动作、战术配合教学、经典赛事视频。', 56.00, 44.80, 383, '本教材主要以数字化形式呈现，分理论篇与实践篇，理论篇介绍了大学体育与健康、体适能与运动处方、体育卫生与运动损伤、体育竞赛与欣赏等方面的内容；实践篇包括球类运动、操舞类运动、民族传统体育运动、求生技能、户外休闲娱乐等五部分，球类运动重点介绍了篮球、足球、排球、乒乓球、羽毛球、网球、棒垒球、橄榄球等球类项目运动文化、基本技战术、练习方法、比赛规则裁判法及竞赛欣赏；操舞类运动重点介绍了健美操、啦啦操、瑜伽、体育舞蹈、形体舞蹈等项目运动文化、教学练习方法、运动展演与欣赏等；民族传统体育运动重点介绍了武术、健身气功、散打、拳击、跆拳道、空手道、太极扇等项目运动文化、基本技术、练习方法、竞赛规则和竞赛展演欣赏；求生技能重点介绍了田径、体操、游泳等项目运动文化、教学练习方法手段、竞赛规则与赛事欣赏；户外休闲娱乐重点介绍了极限飞盘、攀岩等项目运动文化、基本知识、基本技术和竞赛规则。所有项目配有技术动作、战术配合教学、经典赛事视频。', '前言
