  ('122', '本书内容分为四个模块，第一模块主要介绍3ds Max软件的界面设置和基础操作，第二模块从标准体建模、二维修改器建模、三维修改器建模三个项目内容分任务解析室内常见单体模型的建模方法与技巧，第三模块重点内容包含摄影机布设、灯光表现、材质表现以及渲染设置的知识技能，第四模块以新中式客厅和书房三维空间效果制作为例实践真实项目的建模、材质、灯光、摄像机以及渲染出图的全流程操作，融入传统文化+创新设计开展教学。
本书依托环境艺术设计专业国家教学资源库课程“三维空间表现”并结合装饰企业实践项目编写而成，附带自建模型库、材质库、教案、PPT课件等教学资源，强调软件的操作技能掌握，注重思政元素浸润与前沿探索，具有较强的实用性。
本书可作为高职专科环境艺术设计专业、建筑装饰专业的“3dsMax三维空间表现”课程教材，以及各类数字艺术教育培训机构或数字创意建模技能大赛用书，也可供室内效果图制作的爱好者自学使用。', 46.00, 36.80, 241, '本书内容分为四个模块，第一模块主要介绍3ds Max软件的界面设置和基础操作，第二模块从标准体建模、二维修改器建模、三维修改器建模三个项目内容分任务解析室内常见单体模型的建模方法与技巧，第三模块重点内容包含摄影机布设、灯光表现、材质表现以及渲染设置的知识技能，第四模块以新中式客厅和书房三维空间效果制作为例实践真实项目的建模、材质、灯光、摄像机以及渲染出图的全流程操作，融入传统文化+创新设计开展教学。
本书依托环境艺术设计专业国家教学资源库课程“三维空间表现”并结合装饰企业实践项目编写而成，附带自建模型库、材质库、教案、PPT课件等教学资源，强调软件的操作技能掌握，注重思政元素浸润与前沿探索，具有较强的实用性。
本书可作为高职专科环境艺术设计专业、建筑装饰专业的“3dsMax三维空间表现”课程教材，以及各类数字艺术教育培训机构或数字创意建模技能大赛用书，也可供室内效果图制作的爱好者自学使用。', '前言
模块一 3ds Max 初识
　项目一 3ds Max 2022操作界面
　　任务1 界面认识
　　任务2 单位设置
　　任务3 文件存档
