  ('120', '本教材是具有交互性、智能化的数字教材，是省级精品课程配套教材的修订版，是按照计算机类专业标准的要求，总结高水平专业群专业教学改革经验编写而成的。
本教材以培养Java开发能力为目标，注重Java项目开发技术的应用，通过精心选择工程中典型工作案例，对Java知识点进行精心编排，通过项目的学习，加深对所学知识的理解和提升。通过任务拓展，激发学生创新意识，提升发现问题和解决问题的能力。
本教材共分9个项目，内容包括：搭建Java开发环境、面向过程编程、面向对象编程、常见API应用、集合容器使用、数据输入输出、数据库编程、技术热点实施、图形界面开发。每个项目首先是“项目导学、技能导图”，然后进入任务，每个任务都分为“学习目标、任务描述、准备知识、任务实施、任务评价、任务拓展”，最后是“项目小结、项目练习”。
每个项目都配有项目导学和项目小结音频资源，每个任务都配备了若干个音视频资源，直接进行视听，其中任务评价实现在线交互，自测自评。
各个任务按工作过程设计学习过程，选取了典型的工作任务组织教学内容，通过任务分析、准备知识、任务实施、任务评价、任务拓展的递进方式让读者掌握Java程序设计，通过项目练习，应用相关知识，提升学习兴趣，训练Java开发能力。
本教材配有微课视频、课程标准、授课计划、授课用PPT、案例素材等丰富的数字化学习资源。教师也可发邮件至编辑邮箱305941300@qq.com获取相关资源。
