参考文献'),
  ('119', '作为电子信息类专业的重要基础课程，“模拟电子技术基础”是学生完成大类基础课程之后切入专业类课程的第一站，是沟通基础性课程和未来专业课程的桥梁，起到承上启下的作用。本书以学习者为中心，以全新的教学内容呈现形式，全方位的学习交互模式，全覆盖的教学资源汇聚，全流程支撑教、学、管、评的智慧化、数字化应用。
本书主编牵头建设的“模拟电子技术基础”课程为国家级精品在线开放课程、国家级一流线上课程、国家级一流线上线下混合式课程、湖南省课程思政示范课程。本书主编为教育部电子科学课程群虚拟教研室负责人，依托虚拟教研室组织本书建设团队，汇聚了多院校教研成果。
本书以“不失真的放大和信号处理”为主线，由简入繁，螺旋上升组织教材内容。首先以半导体器件作为引入，明确器件的基本特性和应用，初步构建电子技术概念体系；然后基于已有器件介绍基本放大电路，重点介绍电子电路的构造和分析方法；进而逐步构建更为复杂的集成运放内部电路模块，在加深对器件和基本电路的理解基础之上，掌握复杂电路的分析能力；结合反馈，介绍集成运放的应用，最终形成“器件-电路-系统-应用”的知识链。
为适应教育数字化趋势，本数字教材主要体现以下特色：
1、以BOPPPS模型组织内容架构，凸显以学生为中心
按照BOPPPS模型组织教材内容，每一小节都以应用案例或知识背景引入，“有的放矢”明确学习目标，通过“见微知著”和“小试牛刀”开展学前学后测试，以“踏石留印”中的思维导图总结归纳，形成以内容为主体，以学习成效为中心的知识闭环。
2、思政元素显隐结合，达成知识传递与思政育人同向同行
打造“钩深致远”栏目，挖掘教材内容中蕴含的丰富的辩证观和方法论，培养学生工匠精神和科学思维；引入名人大家创新研究拓展内容，培塑学生科研精神和素养；将基本电路落脚到具体应用，学以致用，培养工程意识。
3、教学资源多元化配置，形成立体教材资源体系
结合知识点的类型和教学实际需求，配置丰富多元的数字化资源，包括微课视频、音频、动画、图片等多媒体资源，帮助学习者突破重难点，强化对抽象分析过程的理解。部署了大量在线测试题、习题和思维导图等学习辅助资源，支持学习者检验学习成效，巩固所学。
4、注重启发互动，打造数字教材的“两性一度”
梳理教学内容中的启发性知识点，形成思考研讨点，从经典出发开展深层次探究，让学习者带着问题主动思考，进而通过打开答案的方式求证分析问题的正确性，培养问题意识和科学思维，提升教材的创新性和高阶性。
5、突出工程实践，强化探究意识和工程思维培养
在深度剖析原理电路的基础上，突出工程背景下的实际问题，强调理论联系实际，原理衔接工程。通过配套15个在线仿真实验，形成“知行统一”模块，在实践中加深对工程问题的认识。
本数字教材可作为普通高等院校电子信息类、自动化类、电气类、计算机类及相关专业的本科生教学用书，也可作为从事电子技术相关工作的工程技术人员的参考书。', 29.90, 23.92, 2055, '作为电子信息类专业的重要基础课程，“模拟电子技术基础”是学生完成大类基础课程之后切入专业类课程的第一站，是沟通基础性课程和未来专业课程的桥梁，起到承上启下的作用。本书以学习者为中心，以全新的教学内容呈现形式，全方位的学习交互模式，全覆盖的教学资源汇聚，全流程支撑教、学、管、评的智慧化、数字化应用。
本书主编牵头建设的“模拟电子技术基础”课程为国家级精品在线开放课程、国家级一流线上课程、国家级一流线上线下混合式课程、湖南省课程思政示范课程。本书主编为教育部电子科学课程群虚拟教研室负责人，依托虚拟教研室组织本书建设团队，汇聚了多院校教研成果。
本书以“不失真的放大和信号处理”为主线，由简入繁，螺旋上升组织教材内容。首先以半导体器件作为引入，明确器件的基本特性和应用，初步构建电子技术概念体系；然后基于已有器件介绍基本放大电路，重点介绍电子电路的构造和分析方法；进而逐步构建更为复杂的集成运放内部电路模块，在加深对器件和基本电路的理解基础之上，掌握复杂电路的分析能力；结合反馈，介绍集成运放的应用，最终形成“器件-电路-系统-应用”的知识链。
为适应教育数字化趋势，本数字教材主要体现以下特色：
1、以BOPPPS模型组织内容架构，凸显以学生为中心
按照BOPPPS模型组织教材内容，每一小节都以应用案例或知识背景引入，“有的放矢”明确学习目标，通过“见微知著”和“小试牛刀”开展学前学后测试，以“踏石留印”中的思维导图总结归纳，形成以内容为主体，以学习成效为中心的知识闭环。
