  ('118', '本书是智能网联和新能源汽车新兴领域“十四五”高等教育教材。本书立足智能电动汽车及其系统组成的原理分析、典型构造举例说明，内容涵盖电动汽车、智能汽车、网联汽车等各类整车及其关键零部件，如电机驱动系统、动力电池组系统、电动化辅助系统、车载网络系统、电子电气架构与计算平台，以及智能电动汽车的基础设施和应用等各个方面。本书以数字教材的形式出版，采用多元的数字化形式呈现。
本书可作为车辆工程、交通工程、能源与动力工程等专业本科生和研究生课程教材或重要参考读物，也可供智能网联电动汽车领域技术人员参考学习。', 40.00, 32.00, 132, '本书是智能网联和新能源汽车新兴领域“十四五”高等教育教材。本书立足智能电动汽车及其系统组成的原理分析、典型构造举例说明，内容涵盖电动汽车、智能汽车、网联汽车等各类整车及其关键零部件，如电机驱动系统、动力电池组系统、电动化辅助系统、车载网络系统、电子电气架构与计算平台，以及智能电动汽车的基础设施和应用等各个方面。本书以数字教材的形式出版，采用多元的数字化形式呈现。
