  ('117', '本书是职业教育汽车类专业“互联网+”创新教材。本书是理论与实践一体化教材，内容包括汽车营销策划认知、汽车营销活动市场调研、汽车营销活动目标设计、汽车营销活动策略选择与计划制订、汽车营销活动策划文案编制、汽车营销活动实施与评价。
结合理论知识内容进行实践操作，形成理论与实践一体化教学模式。
本书内容新颖全面，同时运用了“互联网+”形式，在理论知识部分配以视频、动画等多媒体资源，方便读者理解相关知识，以便更深入地学习。
本书可作为职业院校相关专业的教学用书，也可作为汽车销售企业内部培训资料，还可作为汽车经销商销售部、市场部工作人员和汽车厂家策划人员的参考书。', 32.80, 26.24, 50, '本书是职业教育汽车类专业“互联网+”创新教材。本书是理论与实践一体化教材，内容包括汽车营销策划认知、汽车营销活动市场调研、汽车营销活动目标设计、汽车营销活动策略选择与计划制订、汽车营销活动策划文案编制、汽车营销活动实施与评价。
结合理论知识内容进行实践操作，形成理论与实践一体化教学模式。
本书内容新颖全面，同时运用了“互联网+”形式，在理论知识部分配以视频、动画等多媒体资源，方便读者理解相关知识，以便更深入地学习。
本书可作为职业院校相关专业的教学用书，也可作为汽车销售企业内部培训资料，还可作为汽车经销商销售部、市场部工作人员和汽车厂家策划人员的参考书。', '前言
