  ('116', '本书依据工业产品绿色制造过程对知识和能力的需求来选择和组织内容，重点介绍绿色制造新技术和新工艺，强调工作任务和岗位能力与知识的联系。全书紧密围绕解决绿色制造问题的工作方法，将绿色制造的全过程分解为5个项目，每个项目设立关联的工作任务，充分体现了工作过程的完整性，重点帮助学习者在体验工作过程中掌握工作方法。全书主要内容由绿色设计、绿色材料的选择、绿色制造工艺、再制造技术和绿色产品5个项目组成，每个项目包含项目描述、项目分析、想一想练一练等部分。', 29.80, 23.84, 71, '本书依据工业产品绿色制造过程对知识和能力的需求来选择和组织内容，重点介绍绿色制造新技术和新工艺，强调工作任务和岗位能力与知识的联系。全书紧密围绕解决绿色制造问题的工作方法，将绿色制造的全过程分解为5个项目，每个项目设立关联的工作任务，充分体现了工作过程的完整性，重点帮助学习者在体验工作过程中掌握工作方法。全书主要内容由绿色设计、绿色材料的选择、绿色制造工艺、再制造技术和绿色产品5个项目组成，每个项目包含项目描述、项目分析、想一想练一练等部分。', '前言
