  ('115', '本书是为了高等学校电气与电子类、自动化类、计算机类和其他相近专业而编著的基础教材。聚焦打牢电路素质基础的同时，加强中大规模集成电路的逻辑设计，形成强基础重逻辑的理念。
教材打破传统的章节的单线结构，按照“数字逻辑基础、数字逻辑电路、数字电路设计新技术”三大模块进行划分，每个模块再细分到知识单元，根据具体教学情况，可以进行灵活组合。比如“数字逻辑基础”中的逻辑代数基础、逻辑门电路可以与“数字电路设计新技术”中的Verilog HDL组合，构成整门课的基础知识部分（数学基础、电路基础和语言基础）。“数字逻辑电路”中的组合逻辑电路、时序逻辑电路可以与“数字电路设计新技术”中的常用器件建模组合，构成电路分析和设计方法部分。每个知识点所对应的电路应用仿真以及综合设计实践可以组合作为课程实践专题。
为了提高教材的易学性。本教材融入了课程组的教学策略和教学环节设计，每一章通过思维导图体现知识点的逻辑性，每一节都采用“引入-目标-课前测-参与式学习-课后测-总结”的方式排布内容，知识点讲解中穿插大量随堂测和电路仿真，模拟课堂实境，突出交互性。', 29.90, 23.92, 1555, '本书是为了高等学校电气与电子类、自动化类、计算机类和其他相近专业而编著的基础教材。聚焦打牢电路素质基础的同时，加强中大规模集成电路的逻辑设计，形成强基础重逻辑的理念。
教材打破传统的章节的单线结构，按照“数字逻辑基础、数字逻辑电路、数字电路设计新技术”三大模块进行划分，每个模块再细分到知识单元，根据具体教学情况，可以进行灵活组合。比如“数字逻辑基础”中的逻辑代数基础、逻辑门电路可以与“数字电路设计新技术”中的Verilog HDL组合，构成整门课的基础知识部分（数学基础、电路基础和语言基础）。“数字逻辑电路”中的组合逻辑电路、时序逻辑电路可以与“数字电路设计新技术”中的常用器件建模组合，构成电路分析和设计方法部分。每个知识点所对应的电路应用仿真以及综合设计实践可以组合作为课程实践专题。
为了提高教材的易学性。本教材融入了课程组的教学策略和教学环节设计，每一章通过思维导图体现知识点的逻辑性，每一节都采用“引入-目标-课前测-参与式学习-课后测-总结”的方式排布内容，知识点讲解中穿插大量随堂测和电路仿真，模拟课堂实境，突出交互性。', '序
