  ('114', '本书共计14章，全面介绍了模拟集成电路设计的基础知识、关键技术及其在现代电子系统中的应用。本书内容基于众多优秀教材的知识基础，汲取了各方的精华，同时紧密结合现代模拟集成电路设计发展境况与作者多年来总结的电路分析方法经验编撰，为学习者提供更优质更前沿的知识体系与教学引导。
本书遵循知识吸收过程的循序渐进原则，从基本的MOS器件物理开始，将电路的高阶特性和复杂的电路处理技术逐步渗透于后续各章。读者在学习过程中将逐步认识到各种电路特性和效应之间的相互关系，从而深入掌握一些同时适用于简单和复杂电路的普适性理解与分析处理技术。
第1章从模拟集成电路设计的基本概念出发，探讨了学习模拟集成电路设计的重要性。
第2章深入讲解了模拟集成电路中常用的器件及基本单元(MOS器件、BJT器件、与CMOS技术兼容的无源器件等)，重点讨论了它们的小信号模型、跨导与高频特性以及参数比较，并给出合理的器件模型，以便读者进一步理解与应用。
第3、4、5章系统地介绍了单级放大器、电流源电路与差分放大器等基本电路结构，建立了对基本电路性能的量化方法，并分析各结构的频率响应特性。同时，这三章还讨论了噪声的重要性，涵盖了其类型、来源、影响及抑制方法。
第6、7、8章 阐述了运算放大器设计及相关反馈和系统稳定性，使读者能够通过反馈的有益特性来设计高性能、更稳定的运放，并理解设计中对不同参数指标（精度、速度、功耗等）的取舍。同时，章节中还介绍了一些相对复杂的模拟电路以及其中运用的补偿原理和性能优化技术。
第9、10章介绍了模拟集成电路设计中常见的挑战和解决方案，即失真、失配以及版图设计对电路性能的影响，并提供了一系列常用的方法来消除或降低其负面影响，从而完善设计全流程中对电路性能的优化。
第11、12、13章讨论一些其他常见模拟集成电路结构的实现，其中开关电容电路与带隙参考是现代大多数模拟或混合信号系统的基础内容，研究这些结构的设计方法能够完善读者对模拟集成电路系统的认识。
第14章对模拟集成电路设计中的信号与系统方面的知识进行了简单的回顾，包括傅里叶变换、拉普拉斯变换、系统函数与s域分析，以及反馈系统的原理，为读者更好地吸收和理解本书内容提供了理论基础。', 30.00, 24.00, 146, '本书共计14章，全面介绍了模拟集成电路设计的基础知识、关键技术及其在现代电子系统中的应用。本书内容基于众多优秀教材的知识基础，汲取了各方的精华，同时紧密结合现代模拟集成电路设计发展境况与作者多年来总结的电路分析方法经验编撰，为学习者提供更优质更前沿的知识体系与教学引导。
