  ('113', '本书是面向高端装备制造新兴领域“十四五”高等教育的系列教材之一，系统介绍了微纳机器人的发展历史，涉及交叉学科的基础知识、游动微纳机器人的驱动方式、设计与制造、微纳米操作机器人的分类和系统设计，以及微纳机器人的应用领域等。全书共七章。第一、二章是全书的理论基础：第一章为绪论，系统概述了微纳机器人技术的发展历史分类、应用领域；第二章介绍了微纳机器人技术涉及的流体力学、电磁学、声学、材料学、化学、纳米医学、机械学等交叉性基础知识。第三至七章是全书的精华，分别从游动微纳机器人的驱动方式、设计制造，微纳米操作机器人的类型、系统设计，以及微纳机器人应用方面进行了阐述：第三章系统地介绍了化学驱动、磁场驱动、超声场驱动、光场驱动、电场驱动等常见的游动微纳机器人驱动方式；第四章全面概述了螺旋状、管状、Janus球形、生物杂化、纳米线及其他形状游动微纳机器人的设计制造方法；第五章系统地介绍了非接触式、接触式以及介质辅助型、并联型、气泡型等常见的微纳米操作机器人；第六章主要从微视觉系统、非接触微操作策略、执行器、位移放大器、载物平台、传感器及微操作控制方法几个方面概述了微纳米操作机器人的系统设计；第七章在前六章内容的基础上进一步介绍了游动微纳机器人以及微纳米操作机器人的应用研究。本书适合机械、材料、生物、物理、化学、纳米科学等相关专业的高年级本科生或研究生阅读和参考。', 30.00, 24.00, 119, '本书是面向高端装备制造新兴领域“十四五”高等教育的系列教材之一，系统介绍了微纳机器人的发展历史，涉及交叉学科的基础知识、游动微纳机器人的驱动方式、设计与制造、微纳米操作机器人的分类和系统设计，以及微纳机器人的应用领域等。全书共七章。第一、二章是全书的理论基础：第一章为绪论，系统概述了微纳机器人技术的发展历史分类、应用领域；第二章介绍了微纳机器人技术涉及的流体力学、电磁学、声学、材料学、化学、纳米医学、机械学等交叉性基础知识。第三至七章是全书的精华，分别从游动微纳机器人的驱动方式、设计制造，微纳米操作机器人的类型、系统设计，以及微纳机器人应用方面进行了阐述：第三章系统地介绍了化学驱动、磁场驱动、超声场驱动、光场驱动、电场驱动等常见的游动微纳机器人驱动方式；第四章全面概述了螺旋状、管状、Janus球形、生物杂化、纳米线及其他形状游动微纳机器人的设计制造方法；第五章系统地介绍了非接触式、接触式以及介质辅助型、并联型、气泡型等常见的微纳米操作机器人；第六章主要从微视觉系统、非接触微操作策略、执行器、位移放大器、载物平台、传感器及微操作控制方法几个方面概述了微纳米操作机器人的系统设计；第七章在前六章内容的基础上进一步介绍了游动微纳机器人以及微纳米操作机器人的应用研究。本书适合机械、材料、生物、物理、化学、纳米科学等相关专业的高年级本科生或研究生阅读和参考。', '前 言
