  ('112', '本教材是国家职业教育跨境电子商务、国际经济与贸易专业教学资源库配套教材，是教育部课程思政示范课程配套教材、国家职业教育在线精品课程配套教材。全书分为基础认知篇、技能实践篇和素养提升篇，内容包括国际商务谈判初探、国际商务谈判影响因素分析、国际商务谈判方案制定、出口贸易洽谈、国际展会业务洽谈、国际采购贸易洽谈、谈判沟通技巧应用、国际商务礼仪训练8个项目，共28个典型工作任务。
本教材以“数字教材+在线课程”的方式，配有在线课程网站与教、学、做一体化设计的专业教学资源库，包含微课、AI数字人等资源类型，内容丰富，功能完善。书中的理论知识点与相应学习资源直接对应，在数字教材对应知识点处即可观看学习；核心技能点与数字化实训资源对应，可使用AI数字人对话功能开展实践学习。此外，本书提供习题答案、课外学习视频、教学案例库、PPT课件、教案等，授课教师可发电子邮件至编者邮箱57581336@qq.com获取。
本教材适合作为高等职业院校跨境电子商务、国际经济与贸易专业以及财经商贸大类相关专业的教材，也可作为国际商务从业人员的参考资料和培训用书。', 40.00, 32.00, 176, '本教材是国家职业教育跨境电子商务、国际经济与贸易专业教学资源库配套教材，是教育部课程思政示范课程配套教材、国家职业教育在线精品课程配套教材。全书分为基础认知篇、技能实践篇和素养提升篇，内容包括国际商务谈判初探、国际商务谈判影响因素分析、国际商务谈判方案制定、出口贸易洽谈、国际展会业务洽谈、国际采购贸易洽谈、谈判沟通技巧应用、国际商务礼仪训练8个项目，共28个典型工作任务。
本教材以“数字教材+在线课程”的方式，配有在线课程网站与教、学、做一体化设计的专业教学资源库，包含微课、AI数字人等资源类型，内容丰富，功能完善。书中的理论知识点与相应学习资源直接对应，在数字教材对应知识点处即可观看学习；核心技能点与数字化实训资源对应，可使用AI数字人对话功能开展实践学习。此外，本书提供习题答案、课外学习视频、教学案例库、PPT课件、教案等，授课教师可发电子邮件至编者邮箱57581336@qq.com获取。
