  ('111', '本书是风景园林设计专业的基础课程教材，包含认识园林美术、园林美术基础、园林景观常见元素线稿表现、园林景观小品线稿表现、色彩基础及水彩上色技法表现、园林景观小品综合表现六个项目。
本书顺应风景园林设计行业个性化、生态化、智能化的新发展，有机嵌入各类富媒体资源，以学生未来就业岗位的手绘表现技能培养为宗旨，针对风景园林设计师岗位需求设计教学项目，培养学生运用基础手绘表现技能进行风景园林的创意设计，并将设计构思转化成设计图纸的职业能力，达到适应风景园林设计师工作岗位的要求。
本书可作为职业本科院校、高职院校林业类专业的教学用书，也可供相关从业者参考使用。', 42.00, 33.60, 123, '本书是风景园林设计专业的基础课程教材，包含认识园林美术、园林美术基础、园林景观常见元素线稿表现、园林景观小品线稿表现、色彩基础及水彩上色技法表现、园林景观小品综合表现六个项目。
本书顺应风景园林设计行业个性化、生态化、智能化的新发展，有机嵌入各类富媒体资源，以学生未来就业岗位的手绘表现技能培养为宗旨，针对风景园林设计师岗位需求设计教学项目，培养学生运用基础手绘表现技能进行风景园林的创意设计，并将设计构思转化成设计图纸的职业能力，达到适应风景园林设计师工作岗位的要求。
