  ('110', '视听栏目策划是广播影视类专业的核心课程，本教材坚持理论和实践相结合，分为概论（专题）与实务（项目）两大模块，概论包含视听栏目概念解析、视听栏目文案编制、视听栏目品牌策划三个专题；实务包含新闻类栏目策划、文化类栏目策划、综艺类栏目策划、短剧视频策划、微短剧策划、网络主题直播策划六个项目，充分体现传统媒体与新兴媒体的融合，促进教学内容与行业资源的有机对接。同时，本教材在编排上坚持教、学、做相结合，通过由学到做、由做到思的层层递进，促进学生技能与素养的螺旋式上升。 本教材可作为职业本科院校、高职院校广播影视类专业的教学用书，也可供相关从业者参考使用。', 48.00, 38.40, 40, '视听栏目策划是广播影视类专业的核心课程，本教材坚持理论和实践相结合，分为概论（专题）与实务（项目）两大模块，概论包含视听栏目概念解析、视听栏目文案编制、视听栏目品牌策划三个专题；实务包含新闻类栏目策划、文化类栏目策划、综艺类栏目策划、短剧视频策划、微短剧策划、网络主题直播策划六个项目，充分体现传统媒体与新兴媒体的融合，促进教学内容与行业资源的有机对接。同时，本教材在编排上坚持教、学、做相结合，通过由学到做、由做到思的层层递进，促进学生技能与素养的螺旋式上升。 本教材可作为职业本科院校、高职院校广播影视类专业的教学用书，也可供相关从业者参考使用。', '前言
