参考文献'),
  ('109', '本书全面阐述了氢储能零碳智慧能源系统的基础理论、研究方法以及相关应用。氢储能零碳智慧能源系统协同氢、电、冷、热、可再生等多种能源形式，基于电解槽、储氢罐和氢能燃料电池实现可再生新能源的完全利用，利用储氢、储热、储冷等多种储能方式，有效提升可再生新能源使用效率，从而以近零污染、零碳排放实现多能负荷的高效供应。本书结合当前最新的科学前沿、关键技术和应用需求，系统讨论了氢储能零碳智慧能源系统的理论与应用基础、系统结构、建模优化、智能性设计、经济性分析、碳排放分析等内容。
本书可作为高等院校能源动力、自动化、电气类、计算机专业研究生和高年级本科生的教材，也可作为能源电力系统、综合能源系统、氢能系统等相关领域的研究人员和工程技术人员的参考书。', 30.00, 24.00, 79, '本书全面阐述了氢储能零碳智慧能源系统的基础理论、研究方法以及相关应用。氢储能零碳智慧能源系统协同氢、电、冷、热、可再生等多种能源形式，基于电解槽、储氢罐和氢能燃料电池实现可再生新能源的完全利用，利用储氢、储热、储冷等多种储能方式，有效提升可再生新能源使用效率，从而以近零污染、零碳排放实现多能负荷的高效供应。本书结合当前最新的科学前沿、关键技术和应用需求，系统讨论了氢储能零碳智慧能源系统的理论与应用基础、系统结构、建模优化、智能性设计、经济性分析、碳排放分析等内容。
本书可作为高等院校能源动力、自动化、电气类、计算机专业研究生和高年级本科生的教材，也可作为能源电力系统、综合能源系统、氢能系统等相关领域的研究人员和工程技术人员的参考书。', '总序/前言
