  ('108', '随着摩尔定律逐渐逼近极限，集成电路封装技术特别是先进封装技术，通过采用更先进的设计思路和集成工艺对芯片进行封装级重构，已经发展成为支撑全球集成电路产业持续发展的重要力量。本书主要围绕先进封装技术特别是三维集成技术，在系统介绍先进封装技术发展脉络的基础上，对硅通孔以及三维集成系统的仿真和建模进行了详细阐述。同时，本书使用大量篇幅详细介绍当前主流消费电子产品中先进封装技术的应用实例，充分展示先进封装技术的行业发展现状。
本书可作为高等学校集成电路设计与集成系统、微电子科学与工程等相关专业的教学用书，同时适合从事先进封装技术研发的科技人员阅读使用。', 30.00, 24.00, 54, '随着摩尔定律逐渐逼近极限，集成电路封装技术特别是先进封装技术，通过采用更先进的设计思路和集成工艺对芯片进行封装级重构，已经发展成为支撑全球集成电路产业持续发展的重要力量。本书主要围绕先进封装技术特别是三维集成技术，在系统介绍先进封装技术发展脉络的基础上，对硅通孔以及三维集成系统的仿真和建模进行了详细阐述。同时，本书使用大量篇幅详细介绍当前主流消费电子产品中先进封装技术的应用实例，充分展示先进封装技术的行业发展现状。
本书可作为高等学校集成电路设计与集成系统、微电子科学与工程等相关专业的教学用书，同时适合从事先进封装技术研发的科技人员阅读使用。', '丛书序言
