  ('107', '本教材是浙江省高职院校“十四五”重点教材。在当前高职“双高”专业群课程体系重构、基础医学整合的新课改背景下，本教材依据教育部职业学校医药卫生类专业教学标准，并参照相关行业标准，解构传统生理学、病理学等课程内容，将水、电解质紊乱及酸碱平衡失调、弥散性血管内凝血(DIC)、休克、心力衰竭、呼吸功能衰竭、肾衰竭等病理生理内容，以“人体基本功能→人体分系统功能→人体功能调节”为逻辑主线重构模块化教材体例，设置稳态维持与健康、细胞的基本功能与应用、血液的基本功能与应用、循环功能与失衡、呼吸功能与失衡、消化功能与失衡、泌尿功能与失衡、人体功能的神经调节、人体功能的内分泌调节等9个项目。另外，将人体机能常用的17个实训任务作为一个项目单独编排，以便于教学中选择开设。
本教材可供护理类、中医药类及相关医学类其他专业学生教学使用，也可供在职卫生技术人员和有关人员学习参考。', 48.00, 38.40, 153, '本教材是浙江省高职院校“十四五”重点教材。在当前高职“双高”专业群课程体系重构、基础医学整合的新课改背景下，本教材依据教育部职业学校医药卫生类专业教学标准，并参照相关行业标准，解构传统生理学、病理学等课程内容，将水、电解质紊乱及酸碱平衡失调、弥散性血管内凝血(DIC)、休克、心力衰竭、呼吸功能衰竭、肾衰竭等病理生理内容，以“人体基本功能→人体分系统功能→人体功能调节”为逻辑主线重构模块化教材体例，设置稳态维持与健康、细胞的基本功能与应用、血液的基本功能与应用、循环功能与失衡、呼吸功能与失衡、消化功能与失衡、泌尿功能与失衡、人体功能的神经调节、人体功能的内分泌调节等9个项目。另外，将人体机能常用的17个实训任务作为一个项目单独编排，以便于教学中选择开设。
本教材可供护理类、中医药类及相关医学类其他专业学生教学使用，也可供在职卫生技术人员和有关人员学习参考。', '前 言
第一章 稳态维持与健康
　第一节 人体机能导学
　第二节 内环境稳态与健康
　第三节 内环境紊乱与疾病
　第四节 体温调节与发热
第二章 细胞的基本功能与应用
　第一节 细胞的跨膜物质转运
　第二节 细胞信号转导与疾病
　第三节 细胞的电活动与应用
　第四节 神经元的基本功能
　第五节 肌细胞的收缩功能
第三章 血液的基本功能与应用
　第一节 输液：血浆渗透压
　第二节 贫血：血细胞的功能
　第三节 出血：生理性止血
　第四节 凝血：弥散性血管内凝血
　第五节 输血：血量与血型
第四章 循环功能与失衡
　第一节 心脏的电活动及生理特性
　第二节 心脏的泵血功能
　第三节 血管生理
　第四节 心血管活动的调节
　第五节 休克
　第六节 心力衰竭
第五章 呼吸功能与失衡
　第一节 肺通气与肺换气
　第二节 气体在血液中的运输
　第三节 呼吸运动的调节
　第四节 氧的供给利用与缺氧
　第五节 呼吸衰竭
第六章 消化功能与失衡
　第一节 消化及其功能活动调节
　第二节 营养物质的吸收
　第三节 肝性脑病
第七章 泌尿功能与失衡
　第一节 肾血流量及自身调节
　第二节 尿生成的过程
　第三节 尿生成的调节
　第四节 水、电解质平衡及其紊乱
　第五节 酸碱平衡及其紊乱
　第六节 肾功能衰竭
第八章 人体功能的神经调节
　第一节 感觉器官的功能
　第二节 感觉的分析功能
　第三节 躯体运动的调节
　第四节 内脏活动的调节
第九章 人体功能的内分泌调节
　第一节 下丘脑-垂体的中枢调控功能
　第二节 甲状腺激素的功能和调节
　第三节 肾上腺激素的功能和调节
　第四节 胰岛素的功能和调节
　第五节 生殖功能和调节
附录 人体机能实训
　任务1 反射弧的分析
　任务2 蟾蜍坐骨神经-腓肠肌标本的制备
　任务3 不同刺激强度和频率对骨骼肌收缩和影响
　任务4 红细胞的渗透脆性试验
　任务5 红细胞沉降率的测定
　任务6 ABO血型的测定
　任务7 人体心音听诊
　任务8 人体心电图描记
　任务9 人体动脉血压测量
　任务10 神经、体液因素对动脉血压的调节
　任务11 人体肺通气功能测定
　任务12 呼吸运动的调节
　任务13 影响尿生成的因素
　任务14 视野测定
