  ('106', '本书专注于高校实验设计和操作规程，侧重于实验探索和风险管理，旨在推进高校实验室管理的量化、细化和优化。本书内容具有实用性和权威性，包括清华大学在实验技术安全方面的最新研究成果和实践，不仅探讨了教师应如何有效地指导学生进行实验操作，还强调了学生在实验过程中，应如何确保自身及周围人员在健康安全的情况下高效达成研究目标。每个“实验室标准操作规程”包括实验导引、实验器材、操作步骤、目标达成分析、风险管理、参考资料、自测题、思考题、编后感等模块。本书将按照系列出版，第一辑选编的内容涉及安全、健康与环境等方面，涵盖化学安全、生物安全、辐射安全、机械安全、用电安全、人员健康及环境建设等。本书由长期在高校教学科研一线工作的教师、技术人员等精心编制，作者专业知识深厚、经验丰富。本书内容全面，指导性和可操作性强，既可作为实验室课题组负责人、进入实验室工作的教师与学生的实验指南，还可供高校及科研院所的安全管理及技术人员，以及相关行业的安全工作人员参考。', 198.00, 158.40, 73, '本书专注于高校实验设计和操作规程，侧重于实验探索和风险管理，旨在推进高校实验室管理的量化、细化和优化。本书内容具有实用性和权威性，包括清华大学在实验技术安全方面的最新研究成果和实践，不仅探讨了教师应如何有效地指导学生进行实验操作，还强调了学生在实验过程中，应如何确保自身及周围人员在健康安全的情况下高效达成研究目标。每个“实验室标准操作规程”包括实验导引、实验器材、操作步骤、目标达成分析、风险管理、参考资料、自测题、思考题、编后感等模块。本书将按照系列出版，第一辑选编的内容涉及安全、健康与环境等方面，涵盖化学安全、生物安全、辐射安全、机械安全、用电安全、人员健康及环境建设等。本书由长期在高校教学科研一线工作的教师、技术人员等精心编制，作者专业知识深厚、经验丰富。本书内容全面，指导性和可操作性强，既可作为实验室课题组负责人、进入实验室工作的教师与学生的实验指南，还可供高校及科研院所的安全管理及技术人员，以及相关行业的安全工作人员参考。', '序
