  ('104', '集成电路是现代信息社会的重要基石，以晶体管为基础的微电子器件是集成电路的基本组成单元，广泛应用于计算机、通信等诸多领域。本书从P-N结二极管开始，在系统介绍微电子器件的工作原理、性能参数等核心知识的基础上，结合具体的器件模型，回归本质，深入探讨了双极型晶体管、场效应管等微电子器件的直流、频率等基本特性。同时，本书提供了大量思考题和习题，便于读者检验所学知识的掌握程度。
本书可作为高等学校相关专业的教学用书，同时适合从事微电子器件研发的科技人员阅读使用。', 30.00, 24.00, 114, '集成电路是现代信息社会的重要基石，以晶体管为基础的微电子器件是集成电路的基本组成单元，广泛应用于计算机、通信等诸多领域。本书从P-N结二极管开始，在系统介绍微电子器件的工作原理、性能参数等核心知识的基础上，结合具体的器件模型，回归本质，深入探讨了双极型晶体管、场效应管等微电子器件的直流、频率等基本特性。同时，本书提供了大量思考题和习题，便于读者检验所学知识的掌握程度。
本书可作为高等学校相关专业的教学用书，同时适合从事微电子器件研发的科技人员阅读使用。', '丛书序言
