  ('103', '在产教融合的大背景下，本科高校的课程建设正经历着一场深刻的变革，以知识传授为主的教学方式逐渐转变为以能力培养为核心的教学理念。在产教融合模式下，课程建设更加注重实践性和创新性，以满足当今社会对人才的需求。常州大学高度重视产教融合模式的探索，以课程建设为抓手，人才培养模式的改革初见成效。本书精选了一系列课程改革的案例，分为产教融合理论篇、课程建设案例篇、教学案例设计篇三个篇章，展示了产教融合在本科课程建设中的成功实践与探索。', 59.00, 47.20, 65, '在产教融合的大背景下，本科高校的课程建设正经历着一场深刻的变革，以知识传授为主的教学方式逐渐转变为以能力培养为核心的教学理念。在产教融合模式下，课程建设更加注重实践性和创新性，以满足当今社会对人才的需求。常州大学高度重视产教融合模式的探索，以课程建设为抓手，人才培养模式的改革初见成效。本书精选了一系列课程改革的案例，分为产教融合理论篇、课程建设案例篇、教学案例设计篇三个篇章，展示了产教融合在本科课程建设中的成功实践与探索。', '本书编委会
前言
第一章 产教融合理论篇
　1-1 产教融合的理论基础与常州大学的教育实践
