  ('101', '《集成电路科学与工程导论》是一本为集成电路与微电子相关专业的学生和从业者编写的综合性数字教材。本书是一本全面介绍集成电路科学与工程领域知识的教材，内容涵盖了集成电路的历史、材料、器件、工艺、设计、测试、封装以及未来发展趋势等多个方面。本书旨在为读者提供一个全面了解集成电路的窗口，为后续的学习和深造奠定基础。
通过数字化的手段，本教材将以崭新的方式呈现给学生，采用图文并茂、通俗易懂的方式，降低学习难度，激发学生的学习兴趣。教学内容上，本书重点在于建立起集成电路领域的知识脉络和体系，培养读者思考问题、分析问题的能力。本书每一章节都配有详细的文字介绍与多媒体资源。本书不仅适合用作高等院校集成电路与微电子相关专业本科生和研究生的教材，而且对于希望深入了解集成电路领域的工程师和技术人员来说，也是一本不可多得的实用指南。', 40.00, 32.00, 142, '《集成电路科学与工程导论》是一本为集成电路与微电子相关专业的学生和从业者编写的综合性数字教材。本书是一本全面介绍集成电路科学与工程领域知识的教材，内容涵盖了集成电路的历史、材料、器件、工艺、设计、测试、封装以及未来发展趋势等多个方面。本书旨在为读者提供一个全面了解集成电路的窗口，为后续的学习和深造奠定基础。
通过数字化的手段，本教材将以崭新的方式呈现给学生，采用图文并茂、通俗易懂的方式，降低学习难度，激发学生的学习兴趣。教学内容上，本书重点在于建立起集成电路领域的知识脉络和体系，培养读者思考问题、分析问题的能力。本书每一章节都配有详细的文字介绍与多媒体资源。本书不仅适合用作高等院校集成电路与微电子相关专业本科生和研究生的教材，而且对于希望深入了解集成电路领域的工程师和技术人员来说，也是一本不可多得的实用指南。', '前言
