  ('100', '为适应新时期高等职业教育人才培养的需要，做到产教融合、科教融汇，贯彻“专业与技术相结合、理论与实践相结合、教学和科研相结合”的教学方针，本教材以项目驱动为引领，创新教材内容，与时俱进，吐故纳新，让学生在学习丰富的基础数控知识时，还能了解数控学科领域的最新研究进展。
