  ('99', '内容简介
本书是机器人新兴领域“十四五”高等教育教材，本书面向航空航天、智能制造、国防军事、医疗康复等国家重大战略与学科前沿发展的迫切应用需求，立足“两化融合”特色，详细介绍机器人技术的基本原理及其典型应用。
本书以读者为中心，注重教材新形态立体化建设，注重融入思政元素，注重产教融合，增强教材的可读性和实用性。本书分为6 章，主要内容涉及机器人的概念、发展历史、组成、分类、主要技术参数；机器人运动描述的数学基础、正运动学、逆运动学、雅可比矩阵、轨迹规划、动力学；并联机器人运动学、奇异性、工作空间、动力学；机器人感知系统、驱动系统；机器人控制方法、控制装置；机器人在航空航天、军事、工业、医疗康复、服务、教育等领域的应用。
本书采用现代信息技术，运用书中二维码关联视频资源，帮助读者理解和拓展相关知识内容。
本书可作为普通高等教育机器人工程、智能制造等相关专业的本科教材，也可供相关专业研究生参考学习，还可作为相关领域科研和技术人员的参考书。', 40.00, 32.00, 58, '内容简介
本书是机器人新兴领域“十四五”高等教育教材，本书面向航空航天、智能制造、国防军事、医疗康复等国家重大战略与学科前沿发展的迫切应用需求，立足“两化融合”特色，详细介绍机器人技术的基本原理及其典型应用。
本书以读者为中心，注重教材新形态立体化建设，注重融入思政元素，注重产教融合，增强教材的可读性和实用性。本书分为6 章，主要内容涉及机器人的概念、发展历史、组成、分类、主要技术参数；机器人运动描述的数学基础、正运动学、逆运动学、雅可比矩阵、轨迹规划、动力学；并联机器人运动学、奇异性、工作空间、动力学；机器人感知系统、驱动系统；机器人控制方法、控制装置；机器人在航空航天、军事、工业、医疗康复、服务、教育等领域的应用。
本书采用现代信息技术，运用书中二维码关联视频资源，帮助读者理解和拓展相关知识内容。
本书可作为普通高等教育机器人工程、智能制造等相关专业的本科教材，也可供相关专业研究生参考学习，还可作为相关领域科研和技术人员的参考书。', '前言
