  ('98', '内容简介
本书是作者多年从事工业机器人研发的一些技术总结。主要针对工业机器人的设计和应用过程，分别从工业机器人的分类、机械系统设计、控制系统设计、机器人测试、机器人编程及应用等方面给读者提供了完整的工业机器人开发和应用流程及应该注意的一些技术问题。本书可供机器人研发、设计、工程应用的技术人员参考，也可以作为高等院校机器人工程、机械制造工程专业的教材及相关专业教师、本科生和研究生的教学参考书。', 29.90, 23.92, 143, '内容简介
