  ('97', '本书是以高职高专人才培养定位为目标，按照"工学结合、项目引导、任务驱动"的高职高专教学改革和课程改革思路来编写的。
本书共有10个项目，每个项目根据实现过程分解为多个任务，并按照“任务引入、知识讲解、任务实现”的思路围绕项目任务进行分析和寻求解决方案。所涉及的数字电子技术基本知识、基本理论融入每一个任务中，循序渐进地展开。全书内容突出应用性、实用性、针对性，在内容的先后顺序安排上遵循由浅入深、循序渐进的原则。通过学习可使学生初步具备应用数字电子技术的能力。
本书可作为高职高专电气类、电子信息类、计算机类、自动化类等专业的自学参考书和培训教材使用。也可作为职工大学、业余大学等同类专业的数字电子技术课程教材，同时适合电子技术现场工程的技术人员及数字电子技术爱好者自学使用。', 38.00, 30.40, 196, '本书是以高职高专人才培养定位为目标，按照"工学结合、项目引导、任务驱动"的高职高专教学改革和课程改革思路来编写的。
