  ('96', '“线性代数”是高等学校理工科各专业的必修课程，该课程围绕线性方程组的求解，诞生了行列式、矩阵、向量三大工具。特别是矩阵，已经发展成长为一个枝繁叶茂的分枝。本数字教材注重概念讲授，以此带动对算法的理解，如利用高斯消元法应对解线性方程组、求逆矩阵、求矩阵的秩、解矩阵方程等众多计算问题。本书重视用几何视角理解线性代数的概念，内容联系实际，案例丰富。
本书的主要内容包括: 向量、行列式、矩阵、线性方程组解的结构、线性空间与线性变换、矩阵特征值、二次型等。
本书可作为高等学校理工类、经济管理类等专业的教材或教学参考书，同时可供科技工作者阅读或考研学生参考，也可供各类成人教育及参加自学考试的学习者使用。', 48.00, 38.40, 1579, '“线性代数”是高等学校理工科各专业的必修课程，该课程围绕线性方程组的求解，诞生了行列式、矩阵、向量三大工具。特别是矩阵，已经发展成长为一个枝繁叶茂的分枝。本数字教材注重概念讲授，以此带动对算法的理解，如利用高斯消元法应对解线性方程组、求逆矩阵、求矩阵的秩、解矩阵方程等众多计算问题。本书重视用几何视角理解线性代数的概念，内容联系实际，案例丰富。
本书的主要内容包括: 向量、行列式、矩阵、线性方程组解的结构、线性空间与线性变换、矩阵特征值、二次型等。
