  ('95', '本书是高等学校航空航天专业飞行器设计方向的核心专业课教材全面系统阐述人工智能在飞行设计中的应用。全书共八章，主要包括飞行器的智能设计技术体系、体系智能设计、总体智能设计、气动智能设计、结构智能设计、控制智能设计、机电智能设计等内容。
