  ('94', '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果。航天智能探测原理与设计是面向本科生的核心专业课程，以航空航天探测为背景，以现有探测的成就和发展为着眼点，主要讲授智能探测的相关原理和知识，使学生了解其中的科学目标与科学意义和具体实现的相关技术。内容包括四个部分：探测与识别技术的需求（目标探测与识别的基本概念、目标探测与识别技术智能化发展的需求、地面目标、空中目标、水面及水下目标），智能目标探测算法基础（机器学习基础、基于机器学习的目标探测算法、深度学习基础、基于深度学习的目标探测算法），智能探测传感器与应用（基于光学传感器的目标探测、基于SAR图像的目标探测、基于高光谱传感器的目标探测、红外探测基本原理、红外探测系统及应用、地磁探测基本原理、地磁探测系统及应用、毫米波探测原理、毫米波探测系统及应用），基于探测信息的无人系统设计（航迹规划基本概念、基于节点的航迹规划算法、基于随机采样的航迹规划算法、基于图形分解的航迹规划算法、智能优化与人工势场算法、融合算法、融合定位理论和应用、地图构建技术及实践、无人系统自主导航技术及应用、固定翼无人系统的设计和开发）。
本书可供高等学校从事航空航天类课程教学的教师参考，也可供相关学科教学管理部门进行课程体系建设与管理时参考使用。', 52.00, 41.60, 16, '本书是航空航天战略性新兴领域“十四五”高等教育教材体系建设规划项目的研究成果。航天智能探测原理与设计是面向本科生的核心专业课程，以航空航天探测为背景，以现有探测的成就和发展为着眼点，主要讲授智能探测的相关原理和知识，使学生了解其中的科学目标与科学意义和具体实现的相关技术。内容包括四个部分：探测与识别技术的需求（目标探测与识别的基本概念、目标探测与识别技术智能化发展的需求、地面目标、空中目标、水面及水下目标），智能目标探测算法基础（机器学习基础、基于机器学习的目标探测算法、深度学习基础、基于深度学习的目标探测算法），智能探测传感器与应用（基于光学传感器的目标探测、基于SAR图像的目标探测、基于高光谱传感器的目标探测、红外探测基本原理、红外探测系统及应用、地磁探测基本原理、地磁探测系统及应用、毫米波探测原理、毫米波探测系统及应用），基于探测信息的无人系统设计（航迹规划基本概念、基于节点的航迹规划算法、基于随机采样的航迹规划算法、基于图形分解的航迹规划算法、智能优化与人工势场算法、融合算法、融合定位理论和应用、地图构建技术及实践、无人系统自主导航技术及应用、固定翼无人系统的设计和开发）。
本书可供高等学校从事航空航天类课程教学的教师参考，也可供相关学科教学管理部门进行课程体系建设与管理时参考使用。', '前言
