  ('93', '本书以航空航天领域信息处理实际工程需求为牵引，针对行业所需科研、工作技能和素养、从信息检索、科技文献调研和阅读、研究问题发现、研究方法设计、科技论文写作方法与工具、航天信息工程科研实践案例等方面，科学合理设计教材内容，为创新实践能力的完整训练提供全面参考。本书可作为航天信息工程方向相关本科或研究生的课程教材，也可以为相关领域工程技术人员学习提供参考资料。', 22.00, 17.60, 40, '本书以航空航天领域信息处理实际工程需求为牵引，针对行业所需科研、工作技能和素养、从信息检索、科技文献调研和阅读、研究问题发现、研究方法设计、科技论文写作方法与工具、航天信息工程科研实践案例等方面，科学合理设计教材内容，为创新实践能力的完整训练提供全面参考。本书可作为航天信息工程方向相关本科或研究生的课程教材，也可以为相关领域工程技术人员学习提供参考资料。', '前言
