  ('92', '本书全面阐述了深亚微米尺度下的半导体器件基础理论，特别是MOS器件的结构、工作原理及其在现代集成电路中的核心应用，并拓展了FinFET、FDSOI、GAAFET等前沿半导体技术，为读者提供了宽广的技术视野。书中详细探讨了组合逻辑电路的设计原理与优化技术，通过逻辑努力等简化模型，提供了高效的优化设计方法。同时，时序逻辑电路的设计技巧也得到了深入分析，涵盖了从基本原理到实际应用的全过程。在低功耗设计技术方面，本书介绍了多种策略，包括设计时低功耗、运行时低功耗以及面向休眠的节能技术，旨在帮助读者掌握在不同应用场景下实现功耗最优化的方法。本书内容丰富，通过图表、公式及基于28纳米工艺的实例，增强了理论与实践的结合，适用于集成电路、电子工程等相关专业的本科生，要求读者具备电路分析与半导体物理的基础知识，以便更好地吸收和应用书中所述内容。', 30.00, 24.00, 39, '本书全面阐述了深亚微米尺度下的半导体器件基础理论，特别是MOS器件的结构、工作原理及其在现代集成电路中的核心应用，并拓展了FinFET、FDSOI、GAAFET等前沿半导体技术，为读者提供了宽广的技术视野。书中详细探讨了组合逻辑电路的设计原理与优化技术，通过逻辑努力等简化模型，提供了高效的优化设计方法。同时，时序逻辑电路的设计技巧也得到了深入分析，涵盖了从基本原理到实际应用的全过程。在低功耗设计技术方面，本书介绍了多种策略，包括设计时低功耗、运行时低功耗以及面向休眠的节能技术，旨在帮助读者掌握在不同应用场景下实现功耗最优化的方法。本书内容丰富，通过图表、公式及基于28纳米工艺的实例，增强了理论与实践的结合，适用于集成电路、电子工程等相关专业的本科生，要求读者具备电路分析与半导体物理的基础知识，以便更好地吸收和应用书中所述内容。', '丛书序言
