  ('91', '本书主要讨论数字电路的基本理论、逻辑变换的基本原理和方法、各种常用逻辑模块与器件的原理及应用，旨在使读者初步掌握数字电路的基本分析方法和设计方法。本书分为理论和实践两大部分。
理论部分共七章，包括绪论、逻辑函数相关知识、组合逻辑电路、触发器、时序逻辑电路、半导体存储器、脉冲波形的产生和整形。每章均指明了内容中的重难点，明确了知识目标、能力目标和课程思政目标，并通过知识导图的方式，帮助读者迅速理解知识点之间的关系。此外，课程团队还利用AI技术录制了难点知识点视频，并提供了配套的PPT、习题与解答等丰富的学习资源。
实践部分共三章，包括Multisim 仿真设计、基于Verilog HDL的FPGA设计基础以及课程实践优秀案例。每一章都结合实际案例，由教师和学生共同录制了学习视频。为方便读者，本书最后还附有中英文关键词对照表及试卷样例，为学有余力的读者提供了自我检验的机会。 本书内容全面，资源丰富，兼具深度与广度，适合作为高等学校电子电气、计算机类等专业本科生的教材。', 39.00, 31.20, 110, '本书主要讨论数字电路的基本理论、逻辑变换的基本原理和方法、各种常用逻辑模块与器件的原理及应用，旨在使读者初步掌握数字电路的基本分析方法和设计方法。本书分为理论和实践两大部分。
