赵汝法，澳门大学集成电路国家重点实验室博士、博士后，重庆邮电大学副教授。专注于芯片设计研发24年。先后参与多所高校和企业的项目合作，开展了模数转换器、电源管理、电池管理系统、NB-IoT、人工智能、生物信号检测等各类芯片的研究。在 IEEE JSSC、ISSCC 等国际权威期刊和会议上发表50多篇 SCI/EI 论文，主持及参与10多项集成电路领域的国家级、省部级科研项目，取得28个中国和5个美国授权发明专利，并著有教材和专著各1本。
刘挺，法国南锡大学微电子学博士，重庆市集成电路协同创新中心技术总监，硕导，集成电路EMC国家标准工作组成员。研究方向包括数字信号处理、可重构电路建模、混合信号处理、通讯加密算法。曾在 Wavsat、PMC-Sierra 等公司进行 VLSI 电路设计、验证的研发工作，在数字系统、混合信号系统和嵌入式系统研究、设计等领域有丰富的研发和教学经历。
其余参与人员还包括了来自中国电科集团芯片院、重庆吉芯科技等产业一线公司的技术专家，在相关领域具有丰富的工程实践经验，能够有力的保障本教材内容与工程需求和产业发展紧密结合。', '前言
