  ('89', '简介
《冶金备料技术》是冶金类专业的一门必修核心课程。本教材以冶金备料的方法、技术及过程为导向，采用项目、任务驱动的方式，共设置《冶金备料技术概述》、《物理处理方法》、《配料与配矿》、《焙烧》、《炼铁原料的制备》、《铜冶金备料》、《铅冶金备料》、《锌冶金备料》、《锡冶金备料》、《氧化铝原矿浆的制备》等十个教学模块。
本书适用于职业教育冶金技术相关专业的教学，也可作为行业职业技能培训的教材或工程技术人员的参考用书。', 36.80, 29.44, 36, '简介
《冶金备料技术》是冶金类专业的一门必修核心课程。本教材以冶金备料的方法、技术及过程为导向，采用项目、任务驱动的方式，共设置《冶金备料技术概述》、《物理处理方法》、《配料与配矿》、《焙烧》、《炼铁原料的制备》、《铜冶金备料》、《铅冶金备料》、《锌冶金备料》、《锡冶金备料》、《氧化铝原矿浆的制备》等十个教学模块。
本书适用于职业教育冶金技术相关专业的教学，也可作为行业职业技能培训的教材或工程技术人员的参考用书。', '前言
