  ('88', '本教材根据教育部《高等学校工科基础课程教学基本要求》（2024年版）编写的。基本内容共九章：信号与系统的基本概念、连续系统时域分析、连续信号频域分析、连续系统频域分析、连续系统的复频域分析、复频域系统函数、离散信号与系统时域分析、离散信号与系统时域分析、状态变量法。每章按照知识图谱、教学目标、教学内容、教学课件、仿真实现、思政案例、习题等七个部分。教学内容阐述简洁，表述严谨，数字资源丰富多维，有助于学习者在获取知识的同时，提高自主学习能力，锻炼高阶思维能力。
