  ('86', '《建筑材料检测》以现行的国家及行业最新检测、评定标准、规范为主要依据，采用融媒体教材形式系统介绍了建筑工程领域主要材料的性能、选用、检测以及应用。本教材共分为七个项目，包括通用硅酸盐水泥检测、水泥混凝土用砂石检测、水泥和混凝土中粉煤灰检测、混凝土检测、建筑砂浆检测、建筑钢材检测、沥青检测。每一检测项目配有教学目标、项目概述、知识准备、思维导图、项目拓展、总结、综合练习并附有与本项目相关规范标准，供读者学习使用。
本教材可作为高职院校水利水电工程类、建筑工程类、交通工程等工程类教材，也可作为水利、建筑、交通、城建等工程技术人员、管理人员学习、培训参考用书。', 39.90, 31.92, 53, '《建筑材料检测》以现行的国家及行业最新检测、评定标准、规范为主要依据，采用融媒体教材形式系统介绍了建筑工程领域主要材料的性能、选用、检测以及应用。本教材共分为七个项目，包括通用硅酸盐水泥检测、水泥混凝土用砂石检测、水泥和混凝土中粉煤灰检测、混凝土检测、建筑砂浆检测、建筑钢材检测、沥青检测。每一检测项目配有教学目标、项目概述、知识准备、思维导图、项目拓展、总结、综合练习并附有与本项目相关规范标准，供读者学习使用。
