  ('84', '本教程是专为《结晶学及矿物学》实验课程量身定制的创新型数字教材。全书共包含18次实验，其中结晶学部分7次，矿物学部分11次。教材详细阐述了每次实验的目的、核心知识要点、关键实验步骤以及实验矿物的鉴定特征，并为每一次实验的知识要点提供了清晰的思维导图，帮助学生系统梳理知识脉络。
在结晶学部分，教材内容按照晶体对称操作、晶体投影、晶体定向、对称型国际符号、单形与聚形、晶体内部结构等顺序层层递进，构建起完整的学习路径。教材中不仅对具体操作过程进行了详尽分析，更针对学生在学习中常见的错误提供了特别说明，旨在帮助学生全面、深入地理解结晶学理论，并能够综合运用所学知识分析晶体。
在矿物学部分，教材内容从矿物通论入手，逐步深入各大类矿物的各论，并对相似矿物进行细致的对比分析，总结其鉴别方法。通过这部分内容的学习，学生不仅能掌握矿物形态与物理性质的观察和描述方法，更能熟练掌握70种矿物的鉴定特点，从而培养独立鉴定未知矿物的能力。
本书的显著特点在于其数字化教学资源的整合。我们利用先进的三维建模技术，制作了大量宏观晶体和晶体内部结构模型，并通过动画或3D模型直观展现抽象概念。此外，教材还提供了“晶体定向和投影”虚拟仿真实验项目，支持在线晶体形态分析，并允许学生自主构建复杂晶体模型，满足差异化学习需求。教材中还融入了实习矿物的典型标本鉴定视频，并配套详细讲解，以及可交互的实验作业，学生可直接利用教材中的交互模型完成，系统实时反馈，极大提升了学习效率和互动性。
本实验教程不仅适用于地质学类、地质类、材料类等相关专业学生在结晶学、矿物学等课程实验中使用，更可作为相关专业人员的参考资料或理想的自学用书，尤其适合缺乏晶体模型和矿物标本的个人学习和科普研学场景。', 39.80, 31.84, 42, '本教程是专为《结晶学及矿物学》实验课程量身定制的创新型数字教材。全书共包含18次实验，其中结晶学部分7次，矿物学部分11次。教材详细阐述了每次实验的目的、核心知识要点、关键实验步骤以及实验矿物的鉴定特征，并为每一次实验的知识要点提供了清晰的思维导图，帮助学生系统梳理知识脉络。
在结晶学部分，教材内容按照晶体对称操作、晶体投影、晶体定向、对称型国际符号、单形与聚形、晶体内部结构等顺序层层递进，构建起完整的学习路径。教材中不仅对具体操作过程进行了详尽分析，更针对学生在学习中常见的错误提供了特别说明，旨在帮助学生全面、深入地理解结晶学理论，并能够综合运用所学知识分析晶体。
在矿物学部分，教材内容从矿物通论入手，逐步深入各大类矿物的各论，并对相似矿物进行细致的对比分析，总结其鉴别方法。通过这部分内容的学习，学生不仅能掌握矿物形态与物理性质的观察和描述方法，更能熟练掌握70种矿物的鉴定特点，从而培养独立鉴定未知矿物的能力。
本书的显著特点在于其数字化教学资源的整合。我们利用先进的三维建模技术，制作了大量宏观晶体和晶体内部结构模型，并通过动画或3D模型直观展现抽象概念。此外，教材还提供了“晶体定向和投影”虚拟仿真实验项目，支持在线晶体形态分析，并允许学生自主构建复杂晶体模型，满足差异化学习需求。教材中还融入了实习矿物的典型标本鉴定视频，并配套详细讲解，以及可交互的实验作业，学生可直接利用教材中的交互模型完成，系统实时反馈，极大提升了学习效率和互动性。
本实验教程不仅适用于地质学类、地质类、材料类等相关专业学生在结晶学、矿物学等课程实验中使用，更可作为相关专业人员的参考资料或理想的自学用书，尤其适合缺乏晶体模型和矿物标本的个人学习和科普研学场景。', '前言
实验一 晶体对称操作及分类
实验二 晶体对称及目估投影
实验三 晶体定向和对称型国际符号
