  ('81', '本书坚持以习近平新时代中国特色社会主义思想为指导，以党的十八届三中全会提出的“财政是国家治理的基础和重要支柱”为遵循，以全面深化改革为着力点，以建立现代财政制度为努力方向，按照“财政基础理论——财政支出理论——财政收入理论——财政管理理论”的框架设计相关内容，全书共十五章。
本书内容以中国的文化传统、经济背景和财政实践为基础，融合当代市场经济下国家财政理论的合理成分，积极传递有中国特色的经济学观、财政学观与伦理学观，从而既能反映中国财政学的特点，又能反映当代财政学共同关注的主要问题。本书在体例上遵循“是什么”“为什么”“怎么样”“效果如何”的逻辑路径，着力提升行文的可读性。
本书可作为高等院校经济管理类和公共管理类本科生财政学课程的教材，也可作为相关领域人员的参考用书。', 50.00, 40.00, 224, '本书坚持以习近平新时代中国特色社会主义思想为指导，以党的十八届三中全会提出的“财政是国家治理的基础和重要支柱”为遵循，以全面深化改革为着力点，以建立现代财政制度为努力方向，按照“财政基础理论——财政支出理论——财政收入理论——财政管理理论”的框架设计相关内容，全书共十五章。
本书内容以中国的文化传统、经济背景和财政实践为基础，融合当代市场经济下国家财政理论的合理成分，积极传递有中国特色的经济学观、财政学观与伦理学观，从而既能反映中国财政学的特点，又能反映当代财政学共同关注的主要问题。本书在体例上遵循“是什么”“为什么”“怎么样”“效果如何”的逻辑路径，着力提升行文的可读性。
本书可作为高等院校经济管理类和公共管理类本科生财政学课程的教材，也可作为相关领域人员的参考用书。', '前言
