  ('80', '管理学基础与实务是一门理论性和实践性、科学性和艺术性兼而有之的课程，也是管理类各专业的一门专业基础课，对后续专业核心课的学习具有重要指导性，起着引导学生管理入门及初步养成管理思维的作用。本书结构紧凑、体系完整，内容包括基础理论、管理职能、综合实训三个模块，共七个教学单元。基础理论模块包括管理总论和管理理论两个单元；管理职能模块按照管理者在管理工作中履行的工作职能设计了计划职能、组织职能、领导职能、控制职能四个单元；综合实训模块包含创业设计综合实训，使学生将所学知识运用于创业设计项目，以此提升学生的综合管理技能和数字素养，为学习后续专业核心课程提供指导，并为学生未来走向管理工作岗位奠定基础。本书主要特色包括：一是单元体例新颖，古今中西合璧，引导学生研习国学文化，学习中西方管理之道；二是传承国学智慧，培根立德树人，提升道德品质；三是模拟创业设计，强化管理实践，提升学生综合管理技能，为后续专业核心课程学习及未来的管理岗位工作奠定基础；四是依托MOOC平台和丰富的平台资源，为教师便捷备课、学生自主学习提供便利；五是融入AI技术，赋能课程教学，通过交互式提问和回答，促进学生对复杂问题和案例进行深入探讨。
本书可作为高等职业教育工商管理、行政管理、物流管理、人力资源管理、工程管理、市场营销、旅游管理、酒店管理等专业的教材，同时也可供中等职业学校参考使用。
编者
