  ('79', '“形势与政策”课作为高校思想政治理论课的重要组成部分，是对学生进行形势与政策教育的主渠道、主阵地，是每个大学生的必修课程，在大学生思想政治教育中担负着重要使命，具有不可替代的重要作用。本书是“形势与政策”课的配套教材，采用专题式编写方法，从奋力谱写中国式现代化新篇章，新时代新征程坚持好、完善好、运行好人民代表大会制度，弘扬遵义会议精神，宏观政策更加积极有为 推动经济持续回升向好，大力推动社会主义文化繁荣兴盛，加快推进教育强国建设，在发展中保障和改善民生，贯彻落实总体国家安全观，“全球南方”崛起与中国担当，纪念中国人民抗日战争暨世界反法西斯战争胜利 80周年等方面及时回应和引导青年学生普遍关注的热点难点焦点问题，对党的理论创新成果及时跟进，第一时间推动最新成果进教材进课堂进学生头脑。', 18.00, 14.40, 238, '“形势与政策”课作为高校思想政治理论课的重要组成部分，是对学生进行形势与政策教育的主渠道、主阵地，是每个大学生的必修课程，在大学生思想政治教育中担负着重要使命，具有不可替代的重要作用。本书是“形势与政策”课的配套教材，采用专题式编写方法，从奋力谱写中国式现代化新篇章，新时代新征程坚持好、完善好、运行好人民代表大会制度，弘扬遵义会议精神，宏观政策更加积极有为 推动经济持续回升向好，大力推动社会主义文化繁荣兴盛，加快推进教育强国建设，在发展中保障和改善民生，贯彻落实总体国家安全观，“全球南方”崛起与中国担当，纪念中国人民抗日战争暨世界反法西斯战争胜利 80周年等方面及时回应和引导青年学生普遍关注的热点难点焦点问题，对党的理论创新成果及时跟进，第一时间推动最新成果进教材进课堂进学生头脑。', '前言
