  ('77', '本书为国家精品在线开放课程“幼儿教师音乐技能—歌唱与声势”、教师教育国家级精品资源共享课“幼儿教师音乐技能”的配套教材。本书以学前教育专业学生音乐歌唱能力培养为目标，基于集体歌唱教学特点，从语音切入，按照“以说带唱、说唱结合”的教学方式，安排了无韵尾类、带韵尾类、前鼻韵类、后鼻韵类四类歌曲的歌唱以及幼儿歌曲创作基础知识、幼儿歌曲演唱与声势的理论和实践六个学习情境。
第3版教材相较于第2 版教材，把歌表演创编方法与歌表演技能学习有机融合，弥补了歌表演创编方法不系统这一遗憾，同时幼儿歌曲数量更多，风格更广，时代性更强，并且突显了文化传承的意蕴。在原有的丰富的音响资源、教学录像资源的基础上，利用数字教材优势，增补了更多的舞台歌唱、舞台歌表演录像等。教材中的歌表演都按舞台艺术要求来呈现，将歌唱、肢体语言、舞蹈、表情以及灯光、舞台设计、服装等多种视觉与听觉相融合，为学生提供一个全方位的感官体验，有助于学生更深入地理解、感受歌曲，当然，也更能促进学生热爱学习歌唱、热爱幼教音乐教学。
本书适合高等院校学前教育专业本科、专科学生和教师使用，同时也适合幼儿教育工作者、音乐爱好者等进行网络学习、培训使用。', 34.00, 27.20, 81, '本书为国家精品在线开放课程“幼儿教师音乐技能—歌唱与声势”、教师教育国家级精品资源共享课“幼儿教师音乐技能”的配套教材。本书以学前教育专业学生音乐歌唱能力培养为目标，基于集体歌唱教学特点，从语音切入，按照“以说带唱、说唱结合”的教学方式，安排了无韵尾类、带韵尾类、前鼻韵类、后鼻韵类四类歌曲的歌唱以及幼儿歌曲创作基础知识、幼儿歌曲演唱与声势的理论和实践六个学习情境。
第3版教材相较于第2 版教材，把歌表演创编方法与歌表演技能学习有机融合，弥补了歌表演创编方法不系统这一遗憾，同时幼儿歌曲数量更多，风格更广，时代性更强，并且突显了文化传承的意蕴。在原有的丰富的音响资源、教学录像资源的基础上，利用数字教材优势，增补了更多的舞台歌唱、舞台歌表演录像等。教材中的歌表演都按舞台艺术要求来呈现，将歌唱、肢体语言、舞蹈、表情以及灯光、舞台设计、服装等多种视觉与听觉相融合，为学生提供一个全方位的感官体验，有助于学生更深入地理解、感受歌曲，当然，也更能促进学生热爱学习歌唱、热爱幼教音乐教学。
本书适合高等院校学前教育专业本科、专科学生和教师使用，同时也适合幼儿教育工作者、音乐爱好者等进行网络学习、培训使用。', '前言
