  ('76', '本书是计算机领域本科教育教学改革试点工作计划（“101计划”）系列教材之一。本书按照“厚算法基础、养伦理意识、匠工具平台、促赋能应用”的培养目标，以表达与推理、搜索与优化、建模与学习和伦理与安全为核心，按照如下内容进行组织：第1章绪论、第2章知识表达与推理、第3章搜索探寻与问题求解、第4章机器学习、第5章神经网络与深度学习、第6章强化学习、第7章人工智能博弈、第8章人工智能伦理与安全、第9章人工智能架构与系统、第10章人工智能应用。
本书可作为高等学校人工智能专业及信息技术相关专业人工智能课程的教材，也可供对人工智能技术感兴趣的读者及相关从业人员参考。', 56.00, 44.80, 3677, '本书是计算机领域本科教育教学改革试点工作计划（“101计划”）系列教材之一。本书按照“厚算法基础、养伦理意识、匠工具平台、促赋能应用”的培养目标，以表达与推理、搜索与优化、建模与学习和伦理与安全为核心，按照如下内容进行组织：第1章绪论、第2章知识表达与推理、第3章搜索探寻与问题求解、第4章机器学习、第5章神经网络与深度学习、第6章强化学习、第7章人工智能博弈、第8章人工智能伦理与安全、第9章人工智能架构与系统、第10章人工智能应用。
本书可作为高等学校人工智能专业及信息技术相关专业人工智能课程的教材，也可供对人工智能技术感兴趣的读者及相关从业人员参考。', '前言
