  ('75', '本电子书内容成熟丰富，讲解生动通俗、深入浅出，高校各专业学生及社会读者均可轻松阅读。作者通过几十个专题，概览了当代宇宙探索与发现的研究和进展。从数千年前人类祖先对天地宇宙的猜想、感悟，到现代科学家研究太空的重大发现，书中内容包括诸多启迪心灵、启发思考、激发兴趣、引人入胜的天文专题故事，如银河系及宇宙膨胀的发现、科学家的黑洞预言、古今中外宇宙说、夜空灿烂的恒星世界、暗物质与暗能量、类星体、星系和星云及星系团、彗星撞地球与生物大灭绝、火箭与航天、望远镜与天文观测、探索地外生命等，对于广大天文爱好者都具有重要的启示和思考价值。作者在编著中力求简明扼要、取材翔实、富于趣味、通俗易懂，避免一切繁复的数学计算和推演，融科学思想和观点于知识中，寓生动和情趣于题材中，努力引领读者形成认识宇宙的清晰脉络和纲目。', 18.00, 14.40, 693, '本电子书内容成熟丰富，讲解生动通俗、深入浅出，高校各专业学生及社会读者均可轻松阅读。作者通过几十个专题，概览了当代宇宙探索与发现的研究和进展。从数千年前人类祖先对天地宇宙的猜想、感悟，到现代科学家研究太空的重大发现，书中内容包括诸多启迪心灵、启发思考、激发兴趣、引人入胜的天文专题故事，如银河系及宇宙膨胀的发现、科学家的黑洞预言、古今中外宇宙说、夜空灿烂的恒星世界、暗物质与暗能量、类星体、星系和星云及星系团、彗星撞地球与生物大灭绝、火箭与航天、望远镜与天文观测、探索地外生命等，对于广大天文爱好者都具有重要的启示和思考价值。作者在编著中力求简明扼要、取材翔实、富于趣味、通俗易懂，避免一切繁复的数学计算和推演，融科学思想和观点于知识中，寓生动和情趣于题材中，努力引领读者形成认识宇宙的清晰脉络和纲目。', '前言
