  ('74', '这是一部集传统教材、在线课程、重难点讲析、解题技巧讲解、在线自检自测于一体的立体化数字教材，适合于不同专业背景和层次的理论力学学习者和教学者。初学者能够快速地实现对知识点的理解和应用；深度学习者能够对课程有更高阶的理解和对解题方法有更深层次的掌握；教学者能够从中总结规律，开阔教学思路。
教材主要内容立足于哈尔滨工业大学理论力学教研室主编的《理论力学》第9版的第I册，整合了国家级一流本科课程哈尔滨工业大学“理论力学”MOOC课程的部分视频内容，针对一些关键的知识点和典型例题提供了视频讲解，结合《理论力学在线试题库与自测系统》在每章后都提供了在线自检自测试题，并给出了试题解析。同时，对于课程内容中重要的知识点、难以理解的内容或易混淆的部分提供了相应的解释和说明，帮助学习者理解和掌握；并提供了重难点解析和相应的讲解视频，帮助学有余力的同学进行高阶学习，从而实现对课程内容更深入的理解。此外教材中对某些内容进行了重新的推导和编写，这些全新的内容在此前教材中未出现过，例如速度和加速度合成定理的推导、重心公式的推导等。相信这部数字教材能够给读者带来一个全新的、立体化的学习体验，提升学习效率，加强对课程内容的掌握。', 38.00, 30.40, 1633, '这是一部集传统教材、在线课程、重难点讲析、解题技巧讲解、在线自检自测于一体的立体化数字教材，适合于不同专业背景和层次的理论力学学习者和教学者。初学者能够快速地实现对知识点的理解和应用；深度学习者能够对课程有更高阶的理解和对解题方法有更深层次的掌握；教学者能够从中总结规律，开阔教学思路。
