  ('73', '本书是依据2023年版的“理工科类大学物理实验课程教学基本要求”，结合东北大学物理实验课教学改革的经验编写的，是一本针对大学物理实验课程的综合性教材。它以实验为主线，结合理论分析，旨在帮助学生掌握物理实验的基本技能和方法，培养学生的实验能力和科学素养。
教材内容分为六章，涵盖了力学、热学、电磁学、光学和近代物理等领域的实验76项，每个实验详细介绍了实验的目的、原理、步骤和数据处理方法。同时，教材还强调了实验安全要求和测量不确定度评定等重要内容。
通过学习这本教材，学生可以掌握各种物理实验的基本原理和操作技巧，培养实验设计、数据分析和解决问题的能力。同时，教材还注重培养学生的安全意识和团队合作精神，为学生今后从事科学研究和工程实践打下坚实的基础。
本书可作为理工类本科大学生大学物理实验教材，也可作为从事物理实验教学的教师和工程技术人员的教学参考书。', 38.00, 30.40, 374, '本书是依据2023年版的“理工科类大学物理实验课程教学基本要求”，结合东北大学物理实验课教学改革的经验编写的，是一本针对大学物理实验课程的综合性教材。它以实验为主线，结合理论分析，旨在帮助学生掌握物理实验的基本技能和方法，培养学生的实验能力和科学素养。
教材内容分为六章，涵盖了力学、热学、电磁学、光学和近代物理等领域的实验76项，每个实验详细介绍了实验的目的、原理、步骤和数据处理方法。同时，教材还强调了实验安全要求和测量不确定度评定等重要内容。
通过学习这本教材，学生可以掌握各种物理实验的基本原理和操作技巧，培养实验设计、数据分析和解决问题的能力。同时，教材还注重培养学生的安全意识和团队合作精神，为学生今后从事科学研究和工程实践打下坚实的基础。
