  ('72', '图像处理为广告艺术设计、广播影视节目制作、电子商务等专业的专业基础课程。本教材包含图像操作基础、图像处理、建筑效果后期处理、视觉设计、包装设计5个学习情境，通过大量实训任务让学生在实践中积累经验，提升解决实际问题的能力。同时，每个项目均配有详细的理论讲解和操作步骤，旨在通过系统、科学的教学内容安排，帮助学生掌握Photoshop软件的核心功能与应用技巧，提升其在图像处理领域的专业素养，为学生未来的职业发展奠定坚实的基础。
本书可作为职业本科院校、高职专科院校艺术设计、视觉传达设计、广告艺术设计、广播影视节目制作等专业的教学用书，也可供相关从业者参考使用。', 42.00, 33.60, 47, '图像处理为广告艺术设计、广播影视节目制作、电子商务等专业的专业基础课程。本教材包含图像操作基础、图像处理、建筑效果后期处理、视觉设计、包装设计5个学习情境，通过大量实训任务让学生在实践中积累经验，提升解决实际问题的能力。同时，每个项目均配有详细的理论讲解和操作步骤，旨在通过系统、科学的教学内容安排，帮助学生掌握Photoshop软件的核心功能与应用技巧，提升其在图像处理领域的专业素养，为学生未来的职业发展奠定坚实的基础。
本书可作为职业本科院校、高职专科院校艺术设计、视觉传达设计、广告艺术设计、广播影视节目制作等专业的教学用书，也可供相关从业者参考使用。', '前言
