  ('71', '本书编写遵循通俗易懂的原则，秉承“以学生为主体，以理论为基础，以能力为中心，以实践为导向，实现理论实践融合与创新能力贯通”的编写理念。本书基于职业岗位能力需求，结合财务场景、大赛案例设计典型工作任务，围绕知识传授、能力培养、价值塑造、创新创业训练、学习成果评价设计教材内容和结构，形成大数据技术与Python认知、程序基本结构和输入输出、Python 基本语法、分支结构、循环结构、Pandas入门、财务数据统计分析、财务数据预处理、财务数据可视化等9个教学项目（含33个典型工作任务），通过项目引领、任务驱动，强化学生逻辑思维、数据思维及Python工具应用能力。
本书是融媒体、交互式、智能化数字教材，配套在线课程、视频、音频等丰富的数字化资源。本书可作为高等职业教育财务会计类专业及财经商贸类专业的教材，也可以作为财务工作从业人员和社会人士学习“大数据技术与财务应用”的参考用书。', 40.00, 32.00, 157, '本书编写遵循通俗易懂的原则，秉承“以学生为主体，以理论为基础，以能力为中心，以实践为导向，实现理论实践融合与创新能力贯通”的编写理念。本书基于职业岗位能力需求，结合财务场景、大赛案例设计典型工作任务，围绕知识传授、能力培养、价值塑造、创新创业训练、学习成果评价设计教材内容和结构，形成大数据技术与Python认知、程序基本结构和输入输出、Python 基本语法、分支结构、循环结构、Pandas入门、财务数据统计分析、财务数据预处理、财务数据可视化等9个教学项目（含33个典型工作任务），通过项目引领、任务驱动，强化学生逻辑思维、数据思维及Python工具应用能力。
