  ('69', '本书为先进轨道交通战略性新兴领域“十四五”高等教育教材之一。本书介绍了现代轨道车辆的转向架结构及其设计原理，全书共分为七章，第一章为轨道车辆发展概述，第二章为动车组转向架构造及原理，第三章为重载货车转向架构造及原理，第四章为城轨车辆转向架构造及原理，第五章为轮轨关系及走行原理，第六章为车辆系统动力学及评价方法，第七章为转向架结构强度及评价方法。本书主要面向机车车辆相关专业的本科生，可以作为专业基础课教材，而在轮轨关系、蛇行运动和动力学性能评价等方面可以作为研究生的参考资料。
本书在内容上的主要特色有：
(1) 介绍国内外时速300公里及以上高速列车的转向架技术及其解决方案和发展趋势，介绍新型转向架技术方案，例如，轴箱内置转向架、可变轨距转向架、轻量化转向架等。从车辆动力学与结构强度设计角度出发，说明不同速度等级和运用场景下高速转向架的迭代设计依据。
(2) 介绍25吨以上轴重和高性能货运转向架结构、技术原理和未来发展态势，从动力学性能和运维角度出发，说明其高性能、低磨耗和免维护等设计原理，以期达到启发性教学的目的。
(3) 针对80km/h、120km/h和160km/h速度级城轨车辆和新型城轨车辆，介绍转向架的结构组成、设计原理、技术方案与实际运用问题，归纳总结多种运用场景下机械结构设计原理。
(4)介绍典型类型车辆的动力学评价标准、评价方法与指标，以及转向架结构强度评价标准和方法等，指导转向架结构设计。', 30.00, 24.00, 13, '本书为先进轨道交通战略性新兴领域“十四五”高等教育教材之一。本书介绍了现代轨道车辆的转向架结构及其设计原理，全书共分为七章，第一章为轨道车辆发展概述，第二章为动车组转向架构造及原理，第三章为重载货车转向架构造及原理，第四章为城轨车辆转向架构造及原理，第五章为轮轨关系及走行原理，第六章为车辆系统动力学及评价方法，第七章为转向架结构强度及评价方法。本书主要面向机车车辆相关专业的本科生，可以作为专业基础课教材，而在轮轨关系、蛇行运动和动力学性能评价等方面可以作为研究生的参考资料。
本书在内容上的主要特色有：
(1) 介绍国内外时速300公里及以上高速列车的转向架技术及其解决方案和发展趋势，介绍新型转向架技术方案，例如，轴箱内置转向架、可变轨距转向架、轻量化转向架等。从车辆动力学与结构强度设计角度出发，说明不同速度等级和运用场景下高速转向架的迭代设计依据。
(2) 介绍25吨以上轴重和高性能货运转向架结构、技术原理和未来发展态势，从动力学性能和运维角度出发，说明其高性能、低磨耗和免维护等设计原理，以期达到启发性教学的目的。
(3) 针对80km/h、120km/h和160km/h速度级城轨车辆和新型城轨车辆，介绍转向架的结构组成、设计原理、技术方案与实际运用问题，归纳总结多种运用场景下机械结构设计原理。
(4)介绍典型类型车辆的动力学评价标准、评价方法与指标，以及转向架结构强度评价标准和方法等，指导转向架结构设计。', '前言
