  ('68', '本书为航空航天战略新兴领域“十四五”高等教育教材体系建设项目成果。为落实立德树人根本任务，充分发挥教材作为人才培养关键要素的重要作用，着力破解飞行器智能感知课程相关教材整体规划性不强、部分内容陈旧、更新迭代速度慢等问题，加快建设体现时代精神、融汇产学共识、凸显数字赋能、具有飞行器领域新兴技术驱动的智能感知教材体系，牵引带动该领域核心课程与高等教育水平。本书紧密围绕飞行器信息感知、传感器及其软硬件系统，从传感器本身的发展历程出发，涵盖现代传感技术及其智能化、智能传感器、无线传感器网络、机敏材料与灵巧结构、智能微机电系统、可见光成像与智能形貌感知、点云智能感知、目标检测方法状态感知与估计以及多源数据融合。内容范围不仅涵盖飞行器感知的硬件和算法，还一定程度上拓展了应用场景，对于发展行业前沿和增强该领域教学水平具有重要意义。
本书系统讲述飞行器智能感知技术的基本理论和方法。全书共分为10章，内容包括绪论、飞行器机敏材料与灵巧结构、典型飞行器传感器、飞行器智能传感器、飞行器无线传感器网络、飞行器可见光成像与智能形貌感知、飞行器点云智能感知与特征提取、飞行器智能目标检测方法、飞行器智能状态感知与估计、飞行器多源数据融合智能感知。每章配备了适当的习题，书后附有习题答案或提示。教材的编写紧密结合专业特色和行业产业发展最新成果以及人才培养特点，深度融合智能传感与智能算法，软硬件结合驱动教学理论与实践双轨并行，与建设重点校内实验和校外综合实践项目相配套。其中实验坚持“能实不虚、虚实结合”，校外实践融合工程需求和重大急需，最大化发挥教材的人才培养潜力。
本书可作为理工科高等院校“飞行器智能感知”相关课程的教材或教学参考书，也可供相关专业科技工作者和工程技术人员学习参考。', 39.80, 31.84, 356, '本书为航空航天战略新兴领域“十四五”高等教育教材体系建设项目成果。为落实立德树人根本任务，充分发挥教材作为人才培养关键要素的重要作用，着力破解飞行器智能感知课程相关教材整体规划性不强、部分内容陈旧、更新迭代速度慢等问题，加快建设体现时代精神、融汇产学共识、凸显数字赋能、具有飞行器领域新兴技术驱动的智能感知教材体系，牵引带动该领域核心课程与高等教育水平。本书紧密围绕飞行器信息感知、传感器及其软硬件系统，从传感器本身的发展历程出发，涵盖现代传感技术及其智能化、智能传感器、无线传感器网络、机敏材料与灵巧结构、智能微机电系统、可见光成像与智能形貌感知、点云智能感知、目标检测方法状态感知与估计以及多源数据融合。内容范围不仅涵盖飞行器感知的硬件和算法，还一定程度上拓展了应用场景，对于发展行业前沿和增强该领域教学水平具有重要意义。
本书系统讲述飞行器智能感知技术的基本理论和方法。全书共分为10章，内容包括绪论、飞行器机敏材料与灵巧结构、典型飞行器传感器、飞行器智能传感器、飞行器无线传感器网络、飞行器可见光成像与智能形貌感知、飞行器点云智能感知与特征提取、飞行器智能目标检测方法、飞行器智能状态感知与估计、飞行器多源数据融合智能感知。每章配备了适当的习题，书后附有习题答案或提示。教材的编写紧密结合专业特色和行业产业发展最新成果以及人才培养特点，深度融合智能传感与智能算法，软硬件结合驱动教学理论与实践双轨并行，与建设重点校内实验和校外综合实践项目相配套。其中实验坚持“能实不虚、虚实结合”，校外实践融合工程需求和重大急需，最大化发挥教材的人才培养潜力。
本书可作为理工科高等院校“飞行器智能感知”相关课程的教材或教学参考书，也可供相关专业科技工作者和工程技术人员学习参考。', '前言
