PPT'),
  ('67', '本书是“新工科产学合作数字教材建设项目”基础软件系列教材之一，以数据库能力闯关进阶训练项目贯穿始终，实现从需求分析到调试优化的全过程，系统培养数据库理论知识和实践能力。全书共11章，从数据库基础开始，以openGauss数据库为实施工具，讲解数据表、SQL语法、视图、索引、事务、存储过程、触发器、游标等知识点，并通过讲解概念、逻辑、物理结构设计等介绍数据库的具体设计过程，最后通过一个真实项目全面展现了openGauss的特征与性能。
本书可作为高等学校计算机等相关专业数据库原理与应用课程的教材，也可供对openGauss数据库感兴趣的读者学习参考。', 52.00, 41.60, 50, '本书是“新工科产学合作数字教材建设项目”基础软件系列教材之一，以数据库能力闯关进阶训练项目贯穿始终，实现从需求分析到调试优化的全过程，系统培养数据库理论知识和实践能力。全书共11章，从数据库基础开始，以openGauss数据库为实施工具，讲解数据表、SQL语法、视图、索引、事务、存储过程、触发器、游标等知识点，并通过讲解概念、逻辑、物理结构设计等介绍数据库的具体设计过程，最后通过一个真实项目全面展现了openGauss的特征与性能。
本书可作为高等学校计算机等相关专业数据库原理与应用课程的教材，也可供对openGauss数据库感兴趣的读者学习参考。', '前言
