参考文献'),
  ('66', '本教材是国家级一本科线上课程“货币金融学”课程的配套教材。教材以现代金融理论为基础，以改革开放以来我国金融业取得的伟大成就为素材，系统展现金融学原理、方法和理论，在确保知识系统完整的基础上，紧扣中国金融实际、讲述中国金融故事。
教材既考虑了货币金融学固有的理论架构，又切实站在学习者的角度，由浅入深、层层深入。
教材从金融本源“资金融通”开始，讲述“融通什么：货币与货币资金”对应第一篇货币与金融体系概览，“如何融通：直接融资和间接融资”对应第二篇金融市场和第三篇金融机构，以及“如何调控：中央银行货币政策操作”对应第四篇货币理论与货币政策。
教材充分紧扣我国金融实际，各章节基本都以我国金融体系为背景讲述金融理论。无论是金融市场还是金融机构，无论是中央银行、金融监管还是货币政策，本教材始终把我国的金融实践和成就贯穿其中。除正文始终贯穿中国素材之外，教材还穿插了大量基于我国金融实际的知识拓展和案例介绍，深入讲述中国金融故事和成就。
教材充分及时反映党和国家对金融领域的改革举措，及时把我国重大金融改革举措编入教材。此外，教材密切追踪金融理论和实践发展动向，及时把理论的新发展和实践的新探索编入教材。
总之，本教材在讲解金融理论的同时努力紧扣中国金融实际、讲述中国金融故事。本教材适合供财经类专业本科生，尤其是金融类专业本科生学习使用，也可以作为金融专业研究生以及金融机构从业人员的参考书，既适合国内教学或学生自学使用，也适合其他国家相关人员了解中国金融实际和金融成就。', 48.00, 38.40, 582, '本教材是国家级一本科线上课程“货币金融学”课程的配套教材。教材以现代金融理论为基础，以改革开放以来我国金融业取得的伟大成就为素材，系统展现金融学原理、方法和理论，在确保知识系统完整的基础上，紧扣中国金融实际、讲述中国金融故事。
教材既考虑了货币金融学固有的理论架构，又切实站在学习者的角度，由浅入深、层层深入。
教材从金融本源“资金融通”开始，讲述“融通什么：货币与货币资金”对应第一篇货币与金融体系概览，“如何融通：直接融资和间接融资”对应第二篇金融市场和第三篇金融机构，以及“如何调控：中央银行货币政策操作”对应第四篇货币理论与货币政策。
教材充分紧扣我国金融实际，各章节基本都以我国金融体系为背景讲述金融理论。无论是金融市场还是金融机构，无论是中央银行、金融监管还是货币政策，本教材始终把我国的金融实践和成就贯穿其中。除正文始终贯穿中国素材之外，教材还穿插了大量基于我国金融实际的知识拓展和案例介绍，深入讲述中国金融故事和成就。
教材充分及时反映党和国家对金融领域的改革举措，及时把我国重大金融改革举措编入教材。此外，教材密切追踪金融理论和实践发展动向，及时把理论的新发展和实践的新探索编入教材。
总之，本教材在讲解金融理论的同时努力紧扣中国金融实际、讲述中国金融故事。本教材适合供财经类专业本科生，尤其是金融类专业本科生学习使用，也可以作为金融专业研究生以及金融机构从业人员的参考书，既适合国内教学或学生自学使用，也适合其他国家相关人员了解中国金融实际和金融成就。', '前言
