  ('65', '本教材依据高等职业学校电子信息类专业教学标准，以项目案例为载体，介绍计算机网络的基础知识和技术应用。本教材内容包括认识网络世界、认识网络设备、网络数据通信基础、计算机网络体系结构、组建局域网、虚拟局域网、无线局域网、网络安全及管理、搭建应急网络、物联网、车联网、无人机自组网等12个项目，每个项目中设计了多个任务，分别介绍相应的知识和技术，再通过实训项目帮助读者进一步理解技术原理，并掌握技术应用。
本教材可作为高等职业学校电子信息类专业的基础课教材使用，也可作为职业培训机构的培训教材使用，还可作为计算机网络爱好者的自学参考书。', 39.00, 31.20, 225, '本教材依据高等职业学校电子信息类专业教学标准，以项目案例为载体，介绍计算机网络的基础知识和技术应用。本教材内容包括认识网络世界、认识网络设备、网络数据通信基础、计算机网络体系结构、组建局域网、虚拟局域网、无线局域网、网络安全及管理、搭建应急网络、物联网、车联网、无人机自组网等12个项目，每个项目中设计了多个任务，分别介绍相应的知识和技术，再通过实训项目帮助读者进一步理解技术原理，并掌握技术应用。
本教材可作为高等职业学校电子信息类专业的基础课教材使用，也可作为职业培训机构的培训教材使用，还可作为计算机网络爱好者的自学参考书。', '前言
