作为计算机科学与技术专业及相关专业的专业核心课教材，“计算机组成与结构”这门课程重点讲授计算机单处理器系统的组成架构和工作原理，聚焦关键技术和最新发展，旨在帮助读者加深理解从底层硬件到上层应用的完整框架。作者将计算机系统结构、指令系统、存储器系统、中央处理器、输入输出系统、总线技术等融为一体，内容的组合体现了完整的课程教学体系，突出了计算机技术及应用。每章均给出案例导读、小结和思考练习题，为读者的学习提供了帮助。通过本书的学习，读者能够掌握计算机系统的基本组成、数据表示与运算、存储器层次结构、指令系统设计、输入输出系统等关键知识，具备分析和解决复杂计算机系统问题的能力。
本书是作者多年教学和实践经验的总结，结合了普通高等院校计算机应用型人才培养的实际，具有内容由浅入深、循序渐进、重点和难点突出，应用性强等特点，以学生为中心，突出案例与实践相结合，理论与应用相结合的特点。本书合理地编排教学内容，全面阐述计算机原理与结构中必须掌握的基本知识和技能，为后续课程的学习和实际应用奠定基础。本书及时更新和反映最新的计算机硬件技术趋势和发展动态，使读者能够了解到当前最先进的硬件设计思路和实践应用。
本书重点突出，内容新颖，配有视频讲解，读者可以扫描书中章节对应的二维码查阅相关内容。教材中的案例结合实际，语言精炼、通俗易懂，便于自学，有广泛的应用范围，可作为普通高等院校计算机专业和各类相关专业的教材，也可作为研究生、业余爱好者、在职培训人员、高等教育自学人员和从事计算机相关工作的工程技术人员、科研人员的参考用书。
在本书编写的过程中和课程视频制作的过程中，尹莹莹、侯丽新老师参与了视频制作，习题库研发，实验设计与演示，课程设计等工作，以及高等教育出版社编辑们的辛苦工作，为本书的顺利完成提供了非常大的帮助，作者在此表示衷心感谢。
在本书完成的过程中，作者深知能力有限，虽然从事教学工作多年，但是书中难免存在疏漏之处，恳请读者谅解并指正。', '前言
