  ('63', '本书基于编者团队数十年植物学课程与数字化教学资源建设，以及线上线下混合式教学模式的教学改革成果，持续探索信息技术与教育教学融合，设计“可视、可练、可互动、可考核”的“全彩色内容+数字化资源”一体化设计的数字教材。
本书按照经典“植物学”课程教学知识体系，从植物细胞、组织、器官、个体发育、系统发育层次，阐述植物局部与整体、机能与结构、个体与群体、植物与环境之间协作的统一性和多样性。书中采用3000余幅原创彩图、近2000份数字化资源（高清视频、动画、虚拟仿真项目、数字切片、虚拟标本、课件等），将微观的、渐变的、不易理解的生命活动现象连贯、直观地呈现，还原形态各异、色彩丰富的植物界本来面目。
本书紧跟学科前沿进展，在植物个体发育部分增加了探究与应用章节，以期激发学生对植物的亲近感和探究植物界奥秘的兴趣；在被子植物主要分科概述章节中，加强了植物形态术语的配图，并以常见作物、花卉或园林植物的“全生育期”精细解剖标本来阐述代表科的形态特征，以期让学生用少量物种来熟悉描述植物器官形态特征“术语”的含义，掌握检索表的运用。
本书选材尽量兼顾综合、农林、师范院校的教学需求和科普实践的需要，既可作为各类高校的植物学课程教材，也可供中学生物学教师、相关科研工作者及植物爱好者参考使用。', 120.00, 96.00, 236, '本书基于编者团队数十年植物学课程与数字化教学资源建设，以及线上线下混合式教学模式的教学改革成果，持续探索信息技术与教育教学融合，设计“可视、可练、可互动、可考核”的“全彩色内容+数字化资源”一体化设计的数字教材。
本书按照经典“植物学”课程教学知识体系，从植物细胞、组织、器官、个体发育、系统发育层次，阐述植物局部与整体、机能与结构、个体与群体、植物与环境之间协作的统一性和多样性。书中采用3000余幅原创彩图、近2000份数字化资源（高清视频、动画、虚拟仿真项目、数字切片、虚拟标本、课件等），将微观的、渐变的、不易理解的生命活动现象连贯、直观地呈现，还原形态各异、色彩丰富的植物界本来面目。
本书紧跟学科前沿进展，在植物个体发育部分增加了探究与应用章节，以期激发学生对植物的亲近感和探究植物界奥秘的兴趣；在被子植物主要分科概述章节中，加强了植物形态术语的配图，并以常见作物、花卉或园林植物的“全生育期”精细解剖标本来阐述代表科的形态特征，以期让学生用少量物种来熟悉描述植物器官形态特征“术语”的含义，掌握检索表的运用。
本书选材尽量兼顾综合、农林、师范院校的教学需求和科普实践的需要，既可作为各类高校的植物学课程教材，也可供中学生物学教师、相关科研工作者及植物爱好者参考使用。', '编者
