  ('61', '本书是西南交通大学翟婉明院士牵头的教育部战略性新兴领域“十四五”高等教育教材体系建设项目成果之一。从复杂产品数字化研发共性技术入手，结合轨道交通装备的特点，重点介绍轨道交通装备数字化建模、模块化设计、数字化仿真分析等内容，覆盖轨道交通装备设计全过程，形成详细的轨道交通装备数字化设计理论、方法、技术和工具体系。主要内容有：第1章 工业革命与复杂机电产品研发技术；第2章 复杂产品数字化设计技术基础；第3章 先进轨道交通装备及其研发技术；第4章 先进轨道交通装备数字化建模技术；第5章 先进轨道交通装备模块化设计；第6章 先进轨道交通装备数字化仿真分析技术。
本书可作为轨道交通装备领域的专门教材，不仅适用于高等学校本科生、研究生，也适用于企业工程师，帮助读者建立全面的知识体系。', 49.00, 39.20, 38, '本书是西南交通大学翟婉明院士牵头的教育部战略性新兴领域“十四五”高等教育教材体系建设项目成果之一。从复杂产品数字化研发共性技术入手，结合轨道交通装备的特点，重点介绍轨道交通装备数字化建模、模块化设计、数字化仿真分析等内容，覆盖轨道交通装备设计全过程，形成详细的轨道交通装备数字化设计理论、方法、技术和工具体系。主要内容有：第1章 工业革命与复杂机电产品研发技术；第2章 复杂产品数字化设计技术基础；第3章 先进轨道交通装备及其研发技术；第4章 先进轨道交通装备数字化建模技术；第5章 先进轨道交通装备模块化设计；第6章 先进轨道交通装备数字化仿真分析技术。
本书可作为轨道交通装备领域的专门教材，不仅适用于高等学校本科生、研究生，也适用于企业工程师，帮助读者建立全面的知识体系。', '前言
