  ('60', '本书为教育部战略性新兴领域“十四五”高等教育教材体系系列。 本书系统讲解了经典控制、现代控制、模型预测控制、非线性控制等先进控制理论，以完善学生在电动汽车智能控制领域的知识体系。此外，进一步引入了神经网络、强化学习、模仿学习等多个前沿控制方法，聚焦对学生“AI for Science”交叉创新能力的培养。各个章节还精选了电动汽车智能控制领域的研究、工程实践案例，旨在培育学生对于电动汽车各类控制问题求解的工程实践能力，激发学生的创新思维。
本书可作为高等院校车辆工程专业或其他相关专业智能电动汽车试验理论与技术教学的专业教材，也可作为汽车相关行业从业人员的技术参考书。', 49.00, 39.20, 53, '本书为教育部战略性新兴领域“十四五”高等教育教材体系系列。 本书系统讲解了经典控制、现代控制、模型预测控制、非线性控制等先进控制理论，以完善学生在电动汽车智能控制领域的知识体系。此外，进一步引入了神经网络、强化学习、模仿学习等多个前沿控制方法，聚焦对学生“AI for Science”交叉创新能力的培养。各个章节还精选了电动汽车智能控制领域的研究、工程实践案例，旨在培育学生对于电动汽车各类控制问题求解的工程实践能力，激发学生的创新思维。
本书可作为高等院校车辆工程专业或其他相关专业智能电动汽车试验理论与技术教学的专业教材，也可作为汽车相关行业从业人员的技术参考书。', '前言
