  ('59', '本教材采用“项目教学法”的编写思路，以学习项目为目标，以典型任务驱动教学内容的组织和知识技能的学习。教材构建了包括项目介绍、教学目标、任务描述、知识准备、任务实操、任务练习等在内的结构体系，助力学习者理论知识的学习与职业技能的培养。
本教材在注重学科知识的系统性、规范性和准确性的同时，充分考虑高职学生的思维特点，采取由易到难、循序渐进的设计思路。内容采用模块化设计，包括机电概念设计认识、传送带的运动仿真、机器人的运动仿真、机器人搬运物料的工作仿真、自动供料单元的工作仿真、智能分拣单元的工作仿真六大项目。
本教材包含大量的微课、动画、虚拟仿真等教学资源，并对重点词加以提炼，方便读者学习。本教材可作为高等职业院校开设的智能控制技术、工业机器人技术、电气自动化技术、机电一体化技术等专业的教学用书，也可作为相关行业从业人员的参考资料。', 39.80, 31.84, 121, '本教材采用“项目教学法”的编写思路，以学习项目为目标，以典型任务驱动教学内容的组织和知识技能的学习。教材构建了包括项目介绍、教学目标、任务描述、知识准备、任务实操、任务练习等在内的结构体系，助力学习者理论知识的学习与职业技能的培养。
本教材在注重学科知识的系统性、规范性和准确性的同时，充分考虑高职学生的思维特点，采取由易到难、循序渐进的设计思路。内容采用模块化设计，包括机电概念设计认识、传送带的运动仿真、机器人的运动仿真、机器人搬运物料的工作仿真、自动供料单元的工作仿真、智能分拣单元的工作仿真六大项目。
