  ('58', '教育部战略性新兴领域“十四五”高等教育教材。全书内容涵盖绪论、控制基础、电子电气架构、动力电池管理系统、驱动控制技术、制动控制技术、转向控制技术、悬架控制技术、智能座舱系统、整车控制器及其集成控制技术、高级辅助驾驶技术、故障诊断系统，以及电子控制系统测试等章节，且每章节后均附有习题以供练习。
本书特色在于将系统性与前沿性相融合，全面覆盖智能电动汽车控制的核心技术领域；同时，注重理论联系实际，书中穿插大量行业实例，内容表述深入浅出，既突出重点，又便于教学与自学。
本书适合普通高等学校车辆工程及其相关专业本科生、研究生作为教材使用，对相关研究领域的研究人员及工程师同样具有极佳的参考价值。', 30.00, 24.00, 74, '教育部战略性新兴领域“十四五”高等教育教材。全书内容涵盖绪论、控制基础、电子电气架构、动力电池管理系统、驱动控制技术、制动控制技术、转向控制技术、悬架控制技术、智能座舱系统、整车控制器及其集成控制技术、高级辅助驾驶技术、故障诊断系统，以及电子控制系统测试等章节，且每章节后均附有习题以供练习。
本书特色在于将系统性与前沿性相融合，全面覆盖智能电动汽车控制的核心技术领域；同时，注重理论联系实际，书中穿插大量行业实例，内容表述深入浅出，既突出重点，又便于教学与自学。
本书适合普通高等学校车辆工程及其相关专业本科生、研究生作为教材使用，对相关研究领域的研究人员及工程师同样具有极佳的参考价值。', '前言
