　习题'),
  ('57', 'Photoshop图像处理是高等职业院校艺术设计类专业的核心课程，也是艺术设计工作者适应数字传媒时代必须具备的一项技能。本书以Photoshop在实际工作岗位中的工作任务为基础，分类别进行任务设计，通过任务开展，不仅介绍软件的运用技能，还传授实践操作经验；既有单个软件的运用，也有软件间的穿插互用；既有理论基础，又有数字输出等行业企业新技术的实践运用，具有很强的实践性和经验指导性。
本书按任务驱动体例编写，每个任务包括任务介绍、任务分析、知识与技能准备、任务实施、总结与评价、任务拓展6个环节，注重横向的知识贯通和纵向的应用与操作讲解，突出引导与实践。
全书分为四大模块：模块1是认识Photoshop，指导读者如何成为一个图像设计师；模块2是熟悉Photoshop，通过常用技能点运用，引导读者如何胜任图像处理师；模块3是掌握Photoshop，指引读者如何成为优秀的图像处理师；模块4是Photoshop图像输入与输出实践以及相关职业技能等级证书介绍。
本书通过图像合成、照片翻新、图像磨皮、平面广告绘制、动漫插画、效果图后期处理等实践任务，讲解图像处理软件在艺术设计领域的运用技巧，内容由浅入深，由简单到复杂，非常适合高等职业院校艺术设计类专业学生和艺术设计工作者学习。', 45.00, 36.00, 256, 'Photoshop图像处理是高等职业院校艺术设计类专业的核心课程，也是艺术设计工作者适应数字传媒时代必须具备的一项技能。本书以Photoshop在实际工作岗位中的工作任务为基础，分类别进行任务设计，通过任务开展，不仅介绍软件的运用技能，还传授实践操作经验；既有单个软件的运用，也有软件间的穿插互用；既有理论基础，又有数字输出等行业企业新技术的实践运用，具有很强的实践性和经验指导性。
本书按任务驱动体例编写，每个任务包括任务介绍、任务分析、知识与技能准备、任务实施、总结与评价、任务拓展6个环节，注重横向的知识贯通和纵向的应用与操作讲解，突出引导与实践。
全书分为四大模块：模块1是认识Photoshop，指导读者如何成为一个图像设计师；模块2是熟悉Photoshop，通过常用技能点运用，引导读者如何胜任图像处理师；模块3是掌握Photoshop，指引读者如何成为优秀的图像处理师；模块4是Photoshop图像输入与输出实践以及相关职业技能等级证书介绍。
本书通过图像合成、照片翻新、图像磨皮、平面广告绘制、动漫插画、效果图后期处理等实践任务，讲解图像处理软件在艺术设计领域的运用技巧，内容由浅入深，由简单到复杂，非常适合高等职业院校艺术设计类专业学生和艺术设计工作者学习。', '前言
