  ('56', '图书简介
本教材结合建筑室内设计专业、建筑装饰工程技术专业、环境艺术设计专业要求，对应工作岗位对手绘能力的需求、室内设计技能大赛及1+X室内设计职业技能等级证书中效果图考核部分对手绘能力的要求，校企合作共同编写。主要内容包括手绘工具、透视规律及画法、室内单体线稿表现、室内单体上色表现、空间线稿表现、空间色彩表现、手绘快题表现、优秀作品赏析等模块。
本教材可以作为高等职业院校建筑室内设计、建筑装饰工程技术、环境艺术设计等专业手绘课程教材和指导书，也可作为从事相关专业的艺术设计学生、设计师及工程技术人员的参考用书。', 36.80, 29.44, 154, '图书简介
