  ('55', '岩石力学试验方法是岩石工程相关专业的学生、技术人员和科研人员必须熟练掌握的一项必要技能。本教材力图为读者提供一份全面而深入的岩石力学试验操作指南，通过“视频讲解为主、文字叙述为辅”的方式，使读者能够准确、快速地掌握岩石力学物理试验的基本原理、操作过程及数值试验的一般操作流程。全书共分7章，包括由教学团队拍摄加工制作的37个讲解视频，以及团队设计制作的52个各类试验记录表，涵盖了几乎所有重要的岩石力学室内试验、原位试验和数值试验；同时，本教材为读者提供了岩石力学试验相关的国际规范与国内规范的主要差异，为我国岩石力学学科国际化及岩石工程国际服务提供支持。
本教材内容准确、多媒体资源丰富、实践特色鲜明，可作为高等学校岩石力学课程的辅助教材，亦可为相关科研院所及设计施工单位的研究与技术人员提供有益参考。', 38.00, 30.40, 128, '岩石力学试验方法是岩石工程相关专业的学生、技术人员和科研人员必须熟练掌握的一项必要技能。本教材力图为读者提供一份全面而深入的岩石力学试验操作指南，通过“视频讲解为主、文字叙述为辅”的方式，使读者能够准确、快速地掌握岩石力学物理试验的基本原理、操作过程及数值试验的一般操作流程。全书共分7章，包括由教学团队拍摄加工制作的37个讲解视频，以及团队设计制作的52个各类试验记录表，涵盖了几乎所有重要的岩石力学室内试验、原位试验和数值试验；同时，本教材为读者提供了岩石力学试验相关的国际规范与国内规范的主要差异，为我国岩石力学学科国际化及岩石工程国际服务提供支持。
本教材内容准确、多媒体资源丰富、实践特色鲜明，可作为高等学校岩石力学课程的辅助教材，亦可为相关科研院所及设计施工单位的研究与技术人员提供有益参考。', '前言
