  ('54', '本书是专门针对小学教育专业学生实际情况和学习特点精心编写的简笔画教学书籍。本书内容丰富，有简笔画的基础知识、简笔画的造型、静物简笔画、植物简笔画、动物简笔画等11章，书中包括孩子们常见的、熟悉的、喜爱的动物、植物、人物和风景及日常用品、交通工具等简笔画教学内容。
本书理论与实践相结合，图片丰富，并配有一定量的课后训练。内容由浅入深、由易到难、循序渐进，能使读者对简笔画产生学习的兴趣。
