  ('53', '本教材系统而全面地介绍了地理信息系统（GIS）的基本功能与典型应用。全书共分为两个篇章，共十五章内容。第一篇聚焦于GIS的分析对象——地理空间数据，系统讲解其类型、获取方式与处理方法；第二篇则围绕GIS的空间分析功能及实际应用，深入介绍各类核心工具和典型应用场景。本教材配有丰富的案例，直观演示GIS的关键功能与应用流程，增强学习的实践性和操作性。
本教材适合作为高职高专、本科、专业硕士及学术硕士阶段社会科学类专业地理信息系统相关课程的教学用书，也可作为对地理信息系统感兴趣及相关领域就业人员的参考资料。', 45.00, 36.00, 79, '本教材系统而全面地介绍了地理信息系统（GIS）的基本功能与典型应用。全书共分为两个篇章，共十五章内容。第一篇聚焦于GIS的分析对象——地理空间数据，系统讲解其类型、获取方式与处理方法；第二篇则围绕GIS的空间分析功能及实际应用，深入介绍各类核心工具和典型应用场景。本教材配有丰富的案例，直观演示GIS的关键功能与应用流程，增强学习的实践性和操作性。
本教材适合作为高职高专、本科、专业硕士及学术硕士阶段社会科学类专业地理信息系统相关课程的教学用书，也可作为对地理信息系统感兴趣及相关领域就业人员的参考资料。', '前言
