  ('52', '本书是为高端装备制造（机器人）新兴领域“十四五”高等教育教材，是机器人工程领域的专业教材。本书系统阐述了机器人工程的基础理论、技术方法及其应用。在介绍机器人基本概念和关键技术的基础上，结合实际案例，深入剖析了机器人在工业、服务、特殊应用等领域的工程设计与实践，呈现机器人系统的构建与运行过程。本书梳理了机器人技术的发展脉络并展望未来趋势，为机器人领域的专业人员、学生及爱好者提供参考，助力其掌握机器人技术的核心要点，进一步推动机器人技术的发展与应用。', 40.00, 32.00, 52, '本书是为高端装备制造（机器人）新兴领域“十四五”高等教育教材，是机器人工程领域的专业教材。本书系统阐述了机器人工程的基础理论、技术方法及其应用。在介绍机器人基本概念和关键技术的基础上，结合实际案例，深入剖析了机器人在工业、服务、特殊应用等领域的工程设计与实践，呈现机器人系统的构建与运行过程。本书梳理了机器人技术的发展脉络并展望未来趋势，为机器人领域的专业人员、学生及爱好者提供参考，助力其掌握机器人技术的核心要点，进一步推动机器人技术的发展与应用。', '序 言
