  ('51', '本书以项目为引导，以任务为主线，以UG NX12.0软件为蓝本，内容涵盖了从基础操作到高级应用的全面指南。本书采用任务驱动编写模式，内容丰富、条理清晰、易学易用。
本书介绍了UG NX 12.0的工作界面、草图设计、零件建模、曲面编辑、装配设计、工程图绘制以及运动仿真等核心功能，并通过实践案例，让读者掌握UG NX 12.0的操作技巧和设计方法，提升三维建模和设计能力。无论是初学者还是进阶学习者，都能从中获得实用的知识和技能。
本书可作为高等职业院校机械类专业CAD/CAM相关课程的教材，也可作为其他相近专业的教学用书，还可以作为职业技能培训和工程技术人员自学UG NX 12.0软件的参考教材。', 42.00, 33.60, 203, '本书以项目为引导，以任务为主线，以UG NX12.0软件为蓝本，内容涵盖了从基础操作到高级应用的全面指南。本书采用任务驱动编写模式，内容丰富、条理清晰、易学易用。
本书介绍了UG NX 12.0的工作界面、草图设计、零件建模、曲面编辑、装配设计、工程图绘制以及运动仿真等核心功能，并通过实践案例，让读者掌握UG NX 12.0的操作技巧和设计方法，提升三维建模和设计能力。无论是初学者还是进阶学习者，都能从中获得实用的知识和技能。
本书可作为高等职业院校机械类专业CAD/CAM相关课程的教材，也可作为其他相近专业的教学用书，还可以作为职业技能培训和工程技术人员自学UG NX 12.0软件的参考教材。', '前言
