  ('50', '本书结合高等职业教育相关专业办学特点，本着培养学生识图和绘图技能的目的，以实际工程项目为载体，着重介绍制图的基本知识、投影的基本知识、剖面图和断面图、轴测图以及形体的视图、建筑施工图的平立剖详识读与绘制，以及结构中基础、柱、梁、板和楼梯五大主要构件平法信息的识读与绘制。每部分内容讲解时，将基本知识和CAD绘图进行了有机融合，使学生具备识读图纸能力，同时强化绘图能力，做到“边学边绘，边绘边识，以绘促识”。
本书的特点是将CAD和制图识图进行有机融合，更符合网络学习和无纸化办公的时代特色，采用项目任务式教学，使学生的学习更具针对性。
