  ('49', '本书是航空航天新兴领域“十四五”高等教育教材之一，主要面向飞行器动力工程专业高年级本科生，以数学与算法为基础，以航空发动机设计技术为内核，主要内容包括：（1）人工智能在航空发动机涡轮叶片设计领域的发展趋势；（2）相关线性代数及概率论数学基础；（3）传统机器学习模型、深度学习网络模型、强化学习模型及物理信息神经网络模型等人工智能方法的基础理论；（4）人工智能方法在航空发动机涡轮叶片设计中的具体应用案例，以及相关的优化算法和数据的生成与获取方法等。旨在通过基础理论与航发设计中应用案例的深度结合，提升学生分析问题并采用创新手段解决问题的能力，培养人工智能时代的航空发动机设计领域复合型工程技术人才。
本书可作为高等院校飞行器动力工程及相关专业的本科生教材，也可供从事相关研究的科技人员参考。', 34.00, 27.20, 153, '本书是航空航天新兴领域“十四五”高等教育教材之一，主要面向飞行器动力工程专业高年级本科生，以数学与算法为基础，以航空发动机设计技术为内核，主要内容包括：（1）人工智能在航空发动机涡轮叶片设计领域的发展趋势；（2）相关线性代数及概率论数学基础；（3）传统机器学习模型、深度学习网络模型、强化学习模型及物理信息神经网络模型等人工智能方法的基础理论；（4）人工智能方法在航空发动机涡轮叶片设计中的具体应用案例，以及相关的优化算法和数据的生成与获取方法等。旨在通过基础理论与航发设计中应用案例的深度结合，提升学生分析问题并采用创新手段解决问题的能力，培养人工智能时代的航空发动机设计领域复合型工程技术人才。
本书可作为高等院校飞行器动力工程及相关专业的本科生教材，也可供从事相关研究的科技人员参考。', '前言
