  ('47', '内容简介
“基础创客工具的使用”章节主要培养学生或科技工作者使用常用创客工具的技能，并学会选择合适的工具加工各类材料，提升其工具的使用技能，并为后续实践课程的学习打下基础。
“科学教具的制作”章节主要以小学科学教材中具有代表性的课程案例为依托，以小学科学教材中相关科学教具设计与制作的痛点、难点问题的解决为目的，选择合适的工具与材料来设计与制作科学教具,解决科学教学中的痛点和难点问题为目标,培养小学科学教育专业学生教具设计与制作和动手实践能力，从而达到提升学生教具的设计与制作能力。
“科技模型的制作”章节主要以目前中小学流行的相关模型赛事案例为依托，以模型的设计与制作为载体，以模型设计与制作过程中的难点问题解决为目的，解决科学教育专业师范生岗位相关常见模型的设计与制作技能的提升为目标，培养学生各类模型设计与制作和动手实践能力，从而达到提升学生模型的设计与制作能力。
“青少年创意编程”章节主要以中小学流行的编程软件（Mixly）、Arduino 主板以及各类传感器为载体，依托具有代表性的、结构螺旋上升设计的项目式案例为章节内容;以各个案例作品的设计与制作为目标要求，学会软件编程、电路搭建、结构设计等知识，依托各类工具、材料的选择性使用、各类材料的科学、规范化加工，以达到综合设计与制作创意知识编程作品的目的，从而培养学生综合运用知识、技能创新解决实际问题的能力。模型、桥梁模型四个模块。并且，这四个模块内包含的内容均体现由简到难，螺旋上升的排布格局。这四个模块内容的学习，可为相关教师指导学生参加模型类比赛提供参考和技术指导。其中，均已各类模型的设计与制作实操案例为学习载体，来提升相关模型的设计与制作能力。', 39.80, 31.84, 27, '内容简介
