  ('46', '“钢结构基本原理”是土木工程专业核心课程。其作为钢结构系列课程中的重要前导课程，继材料力学、结构力学等专业基础课之后开设，与工程力学有着紧密的关联。主要以建立基本概念、阐述基本理论为重点，注重夯实钢结构材料、构件和连接三部分的专业基础知识，建立基本构件和连接的设计与计算知识体系。
本数字教材面向土木工程专业学生及从业人员，紧密围绕“钢结构基本原理”课程的核心内容编写，旨在帮助学习者系统掌握钢结构的基本理论和设计方法。
本教材共6模块，从钢结构的特点与结构组成入手，深入探讨钢材的性能、破坏形式及影响因素，并详细讲解轴心受力构件、受弯构件、拉弯与压弯构件的设计理论，最后重点介绍焊接和螺栓连接的传力机理及设计方法。
本教材结合文字、图片、视频和音频等多媒体资源，生动呈现复杂概念，帮助读者突破学习难点，既是纸质教材的优质辅助工具，也适用于土木工程专业钢结构相关课程的课堂教学及自学参考。', 32.00, 25.60, 39, '“钢结构基本原理”是土木工程专业核心课程。其作为钢结构系列课程中的重要前导课程，继材料力学、结构力学等专业基础课之后开设，与工程力学有着紧密的关联。主要以建立基本概念、阐述基本理论为重点，注重夯实钢结构材料、构件和连接三部分的专业基础知识，建立基本构件和连接的设计与计算知识体系。
本数字教材面向土木工程专业学生及从业人员，紧密围绕“钢结构基本原理”课程的核心内容编写，旨在帮助学习者系统掌握钢结构的基本理论和设计方法。
本教材共6模块，从钢结构的特点与结构组成入手，深入探讨钢材的性能、破坏形式及影响因素，并详细讲解轴心受力构件、受弯构件、拉弯与压弯构件的设计理论，最后重点介绍焊接和螺栓连接的传力机理及设计方法。
本教材结合文字、图片、视频和音频等多媒体资源，生动呈现复杂概念，帮助读者突破学习难点，既是纸质教材的优质辅助工具，也适用于土木工程专业钢结构相关课程的课堂教学及自学参考。', '前言
