  ('45', '本书为集成电路新兴领域“十四五”高等教育教材，本书编写团队已入选教育部“战略性新兴领域‘十四五’高等教育教材体系建设团队”。
本书共分为10章，第1章为集成电路封装的简介。第2章为集成电路封装中涉及的材料、力学、热学和电磁学基础知识。第3章为集成电路封装工艺基础，包括芯片减薄与切割、芯片贴片与互连、芯片成型技术等。第4章介绍集成电路封装的基本形式。第5章介绍晶圆级封装技术。第6章为多芯片封装技术。第7章为3D封装，主要介绍3D封装的特点和类型、TSV技术、TGV技术以及3D封装发展趋势。第8章主要介绍2.5D封装技术。第9章主要介绍集成电路封装缺陷和检测。第10章为封装可靠性与失效分析。
本书凝结上海大学“集成电路封装”课程十余年的教学成果，为适应教育数字化趋势，本书采用数字教材的形式，全面展示集成电路封装技术，更好地服务课堂教学。
本书可作为微电子科学与工程、电子科学与技术等专业的本科生“集成电路封装”相关课程的教材，建议授课学时为40学时。同时，本书也可供集成电路领域及相关专业技术人员参考使用。', 30.00, 24.00, 62, '本书为集成电路新兴领域“十四五”高等教育教材，本书编写团队已入选教育部“战略性新兴领域‘十四五’高等教育教材体系建设团队”。
本书共分为10章，第1章为集成电路封装的简介。第2章为集成电路封装中涉及的材料、力学、热学和电磁学基础知识。第3章为集成电路封装工艺基础，包括芯片减薄与切割、芯片贴片与互连、芯片成型技术等。第4章介绍集成电路封装的基本形式。第5章介绍晶圆级封装技术。第6章为多芯片封装技术。第7章为3D封装，主要介绍3D封装的特点和类型、TSV技术、TGV技术以及3D封装发展趋势。第8章主要介绍2.5D封装技术。第9章主要介绍集成电路封装缺陷和检测。第10章为封装可靠性与失效分析。
本书凝结上海大学“集成电路封装”课程十余年的教学成果，为适应教育数字化趋势，本书采用数字教材的形式，全面展示集成电路封装技术，更好地服务课堂教学。
本书可作为微电子科学与工程、电子科学与技术等专业的本科生“集成电路封装”相关课程的教材，建议授课学时为40学时。同时，本书也可供集成电路领域及相关专业技术人员参考使用。', '前言
