  ('43', '本教材以开发智能小车产品为导向，设计一个完整的项目贯穿全书，并拆分成直流稳压电源、车内空气监测报警器、智能循迹小车、车内双控灯、多路胎压监测系统、汽车尾灯控制电路、红外倒车雷达7个项目，主要包括二极管、三极管、集成运算放大器、逻辑门和逻辑函数、编码器和译码器、计数器、555定时器等内容。本教材以培养电子技术相关岗位需具备的职业能力为主线，不仅突出电子技术基础内容和知识体系，同时也侧重对学习者的电子技术基本技能的培养，将理论与实践、仿真与项目相结合，使学习者在做中学、学中做。
本教材为核心知识点配有视频等数字化学习资源。此外，还提供PPT课件等，授课教师可发送电子邮件至编辑邮箱gzdz@pub.hep.cn获取。
本教材适用于高等职业院校电子信息大类、装备制造大类各专业课程的教学，也可作为电子类工程技术人员学习参考、岗位培训和自学教材。', 40.00, 32.00, 76, '本教材以开发智能小车产品为导向，设计一个完整的项目贯穿全书，并拆分成直流稳压电源、车内空气监测报警器、智能循迹小车、车内双控灯、多路胎压监测系统、汽车尾灯控制电路、红外倒车雷达7个项目，主要包括二极管、三极管、集成运算放大器、逻辑门和逻辑函数、编码器和译码器、计数器、555定时器等内容。本教材以培养电子技术相关岗位需具备的职业能力为主线，不仅突出电子技术基础内容和知识体系，同时也侧重对学习者的电子技术基本技能的培养，将理论与实践、仿真与项目相结合，使学习者在做中学、学中做。
本教材为核心知识点配有视频等数字化学习资源。此外，还提供PPT课件等，授课教师可发送电子邮件至编辑邮箱gzdz@pub.hep.cn获取。
