  ('42', '本教材是高等职业教育教学教材。
本教材共分为五部分内容，包括认知老年生活照料、老年人清洁照料、老年人进食照料、老年人排泄照料和老年人睡眠照料。每部分设置项目内容聚焦、学习目标、工作任务描述、任务分析、知识解读、能力检测等模块。
本教材在编写过程中以养老护理员实际工作中的任务为导入，引导学生主动思考问题，通过工作流程图和具体的任务实施步骤，帮助学生理清工作思路和流程，并配以相应的图片和实际操作视频，加强直观感受；通过能力检测环节，检测学生理论知识的掌握情况及解决实际问题的能力。
本教材适用于全国职业教育老年保健与管理、智慧健康养老服务、老年人服务与管理及相关专业使用，也可作为养老护理员的参考用书。', 45.00, 36.00, 303, '本教材是高等职业教育教学教材。
本教材共分为五部分内容，包括认知老年生活照料、老年人清洁照料、老年人进食照料、老年人排泄照料和老年人睡眠照料。每部分设置项目内容聚焦、学习目标、工作任务描述、任务分析、知识解读、能力检测等模块。
本教材在编写过程中以养老护理员实际工作中的任务为导入，引导学生主动思考问题，通过工作流程图和具体的任务实施步骤，帮助学生理清工作思路和流程，并配以相应的图片和实际操作视频，加强直观感受；通过能力检测环节，检测学生理论知识的掌握情况及解决实际问题的能力。
本教材适用于全国职业教育老年保健与管理、智慧健康养老服务、老年人服务与管理及相关专业使用，也可作为养老护理员的参考用书。', '前言
导入：认知老年生活照料
　项目内容聚焦
　任务一：认知老年生活照料模式
　任务二：认知老年生活照料理念
　任务三：认知养老护理员职业
　能力检测练习题答案
项目一：老年人清洁照料
　项目内容聚焦
　任务一：为老年人进行环境及物品清洁与消毒
　任务二：为卧床老年人整理床单位、更换被服
　任务三：为老年人进行晨晚间梳洗
　任务四：为老年人进行口腔清洁
　任务五：为卧床老年人床上洗头
　任务六：为卧床老年人床上擦浴
　任务七：为卧床老年人更换衣服
　任务八：协助老年人穿脱弹力足踝矫形器
　能力检测练习题答案
项目二：老年人进食照料
　项目内容聚焦
　任务一：评估、观察与记录老年人进食情况
　任务二：指导老年人建立良好的饮食习惯
　任务三：协助老年人进食
　任务四：照护卧床老年人进食、进水
　任务五：照护戴鼻饲管的老年人进食、进水
　任务六：用海姆立克急救法对噎食老年人进行急救
　能力检测练习题答案
项目三：老年人排泄照料
　项目内容聚焦
　任务一：评估老年人的排泄能力
　任务二：协助老年人正常如厕
　任务三：协助卧床老年人使用便器排泄
　任务四：协助老年人更换护理垫、纸尿裤
　任务五：协助便秘老年人排便
　任务六：为老年人更换尿液引流袋
　任务七：为肠造瘘的老年人更换造瘘袋
　能力检测练习题答案
项目四：老年人睡眠照料
　项目内容聚焦
　任务一：为老年人布置睡眠环境
　任务二：协助睡眠障碍老年人入睡
　任务三：指导老年人改变不良睡眠习惯
　能力检测练习题答案
参考文献'),
  ('41', '本教材从护理临床工作实际出发，内容涵盖每个护生必须掌握的基本理论、基本知识和基本技能，旨在培养护生基本的临床思维能力、独立思考能力、人际沟通能力，以及发现问题、分析问题和解决问题的能力。
本教材基于项目化课程建设思路，按照学习者的职业认知习惯和护士角色逐渐渗透的理念设计学习内容，以项目驱动、任务引领、情境呈现的方式进行编排，主要内容包括认识护理工作、迎接病人入院、实施生活护理、执行基础治疗、处理特殊情况、指导病人出院，含6个项目、24个典型任务、135个知识点、82个技能点，接轨临床护理工作，强化知识技能的应用。
本教材包含丰富的视频资源，包括主要知识点和技能点的教学资源、示范性操作视频资源、思政教学资源、虚拟仿真资源等，融入老年照护职业技能等级证书的主要知识点和技能点，能够同时满足国家护士执业资格考试、护理技能大赛及1+X证书的备赛备考需求，满足“岗课赛证”融通需要。
本教材具备适应性、丰富性和先进性，可作为高等职业教育护理和助产专业教材，也可作为临床一线护士和助产士的重要参考学习工具。', 59.00, 47.20, 850, '本教材从护理临床工作实际出发，内容涵盖每个护生必须掌握的基本理论、基本知识和基本技能，旨在培养护生基本的临床思维能力、独立思考能力、人际沟通能力，以及发现问题、分析问题和解决问题的能力。
本教材基于项目化课程建设思路，按照学习者的职业认知习惯和护士角色逐渐渗透的理念设计学习内容，以项目驱动、任务引领、情境呈现的方式进行编排，主要内容包括认识护理工作、迎接病人入院、实施生活护理、执行基础治疗、处理特殊情况、指导病人出院，含6个项目、24个典型任务、135个知识点、82个技能点，接轨临床护理工作，强化知识技能的应用。
本教材包含丰富的视频资源，包括主要知识点和技能点的教学资源、示范性操作视频资源、思政教学资源、虚拟仿真资源等，融入老年照护职业技能等级证书的主要知识点和技能点，能够同时满足国家护士执业资格考试、护理技能大赛及1+X证书的备赛备考需求，满足“岗课赛证”融通需要。
本教材具备适应性、丰富性和先进性，可作为高等职业教育护理和助产专业教材，也可作为临床一线护士和助产士的重要参考学习工具。', '项目1 认识护理工作
　任务1.1 认识护理学科的发展史和工作内涵
　任务1.2 认识护士的职业防护
　任务1.3 认识医院的种类、布局和环境
　任务1.4 认识医院感染及其预防
