  ('40', '本书为国家职业教育药学专业教学资源库配套系列教材之一，体现“岗课赛证”融通的编写模式，凝练药物制剂最新理论、实践和技术发展精华，紧贴岗位、项目和任务要求编写而成。
本书共19章，附10个实验，分药物制剂基础知识，液体类、固体类、其他类药物制剂，药物制剂应用和药物制剂实验六部分。重要视频、动画、设备运行、技术规范、逼真场景、考证真题等教学资源以二维码形式融入书中；创设了“囊型制剂”“雾型制剂”“膏型制剂”等章节；实验体现微格教学理念，融入大量原创图片、操作要点等元素；以“案例导入”“知识拓展”“课堂互动”等形式凸显了实用性、技能性和趣味性。
本书可作为职业教育药学、药物制剂技术、药品生产技术、药品生物技术、生物制药技术、化学制药技术、药品经营与管理、药品质量与安全等相关专业或方向的教学用书，其他涉药专业的各类培训、进修、考证等学习者也可参考选用。', 70.00, 56.00, 338, '本书为国家职业教育药学专业教学资源库配套系列教材之一，体现“岗课赛证”融通的编写模式，凝练药物制剂最新理论、实践和技术发展精华，紧贴岗位、项目和任务要求编写而成。
本书共19章，附10个实验，分药物制剂基础知识，液体类、固体类、其他类药物制剂，药物制剂应用和药物制剂实验六部分。重要视频、动画、设备运行、技术规范、逼真场景、考证真题等教学资源以二维码形式融入书中；创设了“囊型制剂”“雾型制剂”“膏型制剂”等章节；实验体现微格教学理念，融入大量原创图片、操作要点等元素；以“案例导入”“知识拓展”“课堂互动”等形式凸显了实用性、技能性和趣味性。
本书可作为职业教育药学、药物制剂技术、药品生产技术、药品生物技术、生物制药技术、化学制药技术、药品经营与管理、药品质量与安全等相关专业或方向的教学用书，其他涉药专业的各类培训、进修、考证等学习者也可参考选用。', '前言
