  ('39', '《中药材加工学》分为总论和各论两部分。总论部分结合课程思政论述了中药材加工的基础理论和技术应用的实际意义。各论部分按药用部位分类，列举了174种代表性中药材的来源、产地、采收、产地加工、炮制、主要商品规格、包装与贮藏、质量要求和现代研究等内容，重点描述其中75种药材的各项内容。教材可供高等农业和中医药院校的中药学、中药资源与开发、中草药栽培与鉴定等相关专业教学使用。', 28.00, 22.40, 420, '《中药材加工学》分为总论和各论两部分。总论部分结合课程思政论述了中药材加工的基础理论和技术应用的实际意义。各论部分按药用部位分类，列举了174种代表性中药材的来源、产地、采收、产地加工、炮制、主要商品规格、包装与贮藏、质量要求和现代研究等内容，重点描述其中75种药材的各项内容。教材可供高等农业和中医药院校的中药学、中药资源与开发、中草药栽培与鉴定等相关专业教学使用。', '前言
