  ('38', '本书为高等职业教育国家在线精品课程——爱课程（中国大学MOOC）“人体解剖与组织学”和智慧职教数字课程“正常人体结构”的配套教材。主要内容包括绪论、基本组织、人体九大系统、人体胚胎学概论四大部分，将人体大体结构、微细结构和护理应用有机地结合在一起，以人体系统解剖学整体结构为框架，各系统器官从位置、形态、结构到护理应用逐步深入，使学生能在短时间内构建人体结构整体观并了解其护理临床应用。
本书可供高等职业教育护理类、康复治疗技术、健康管理与促进类等医药卫生类专业教学使用。', 69.00, 55.20, 2217, '本书为高等职业教育国家在线精品课程——爱课程（中国大学MOOC）“人体解剖与组织学”和智慧职教数字课程“正常人体结构”的配套教材。主要内容包括绪论、基本组织、人体九大系统、人体胚胎学概论四大部分，将人体大体结构、微细结构和护理应用有机地结合在一起，以人体系统解剖学整体结构为框架，各系统器官从位置、形态、结构到护理应用逐步深入，使学生能在短时间内构建人体结构整体观并了解其护理临床应用。
