  ('37', '本教材是浙江省高职院校“十四五”重点教材，也是职业教育护理专业中高本贯通的数字化新形态教材，为凸显职业教育的类型特征和中高本贯通的进阶性和连续性，教材内容分为三个模块，第一个模块是急危重症护理的初阶模块，培养学生的急危重症救护和监护能力，实现学生从生手到新手的进阶；第二个模块是急危重症护理的中阶模块，培养学生的临床思维能力和综合职业能力，实现学生从新手到熟手的进阶；第三个模块为高阶模块，强化学生综合职业能力的基础上培养科研思维和创新能力，实现学生从熟手到能手的进阶。
本教材可供高等职业教育4年制本科护理专业使用，也可供从中职升入高职的护理专业学生使用。', 38.00, 30.40, 210, '本教材是浙江省高职院校“十四五”重点教材，也是职业教育护理专业中高本贯通的数字化新形态教材，为凸显职业教育的类型特征和中高本贯通的进阶性和连续性，教材内容分为三个模块，第一个模块是急危重症护理的初阶模块，培养学生的急危重症救护和监护能力，实现学生从生手到新手的进阶；第二个模块是急危重症护理的中阶模块，培养学生的临床思维能力和综合职业能力，实现学生从新手到熟手的进阶；第三个模块为高阶模块，强化学生综合职业能力的基础上培养科研思维和创新能力，实现学生从熟手到能手的进阶。
