  ('36', '康复评定是康复治疗的基石，没有康复评定就没有康复。本书是一本面向运动康复、康复治疗技术、智慧康养等专业教学而编写的工作手册式教材，书中通过踝关节损伤康复评估、肥胖症康复评估、颈椎病康复评估、卒中康复评估4个典型真实病例项目的康复评估，将康复功能评估的理论、基础知识及评定方法融入4个项目的临床工作流程中，从而方便学生深入理解各种康复评定理论及操作流程，破解学生在面对真实病例无法正确选择恰当康复评定技术的难题。康复评定的主要内容包括康复评定学总论、人体形态评定、关节活动度评定、肌力评定、肌张力评定、反射评定、姿势评定、步态分析、平衡与协调功能评定、功能性动作评定、心肺功能评定、感觉功能评定、认知功能评定、中枢神经系统损伤运动功能评估、日常生活活动能力评定、生活质量与社会功能的评定、环境评估。
本书可作为运动康复、康复治疗技术、智慧康养等专业学生的教材，也可作为养老护理员、运动员、教练员、运动队队医以及体育运动参加者的学习参考书。', 48.00, 38.40, 204, '康复评定是康复治疗的基石，没有康复评定就没有康复。本书是一本面向运动康复、康复治疗技术、智慧康养等专业教学而编写的工作手册式教材，书中通过踝关节损伤康复评估、肥胖症康复评估、颈椎病康复评估、卒中康复评估4个典型真实病例项目的康复评估，将康复功能评估的理论、基础知识及评定方法融入4个项目的临床工作流程中，从而方便学生深入理解各种康复评定理论及操作流程，破解学生在面对真实病例无法正确选择恰当康复评定技术的难题。康复评定的主要内容包括康复评定学总论、人体形态评定、关节活动度评定、肌力评定、肌张力评定、反射评定、姿势评定、步态分析、平衡与协调功能评定、功能性动作评定、心肺功能评定、感觉功能评定、认知功能评定、中枢神经系统损伤运动功能评估、日常生活活动能力评定、生活质量与社会功能的评定、环境评估。
本书可作为运动康复、康复治疗技术、智慧康养等专业学生的教材，也可作为养老护理员、运动员、教练员、运动队队医以及体育运动参加者的学习参考书。', '前言
