参考文献'),
  ('35', '《儿童保健理论与实操手册》是一本全面、实用的儿童保健指南，旨在为护理、助产、婴幼儿托育服务与管理等专业人才的培养、儿童保健工作者和广大家长提供全面、实用的指导和帮助。本书将理论知识与实践操作相结合，深入浅出地介绍了儿童保健的基本理论，包括儿童生长发育的特点、营养需求、疾病预防等方面的知识。同时，本书结合实际操作，详细介绍了儿童体格生长指标的检查、常见疾病的处理、急救等方面的技能。
本书共分为7个项目，包括儿童体格生长发育与评价、儿童神经心理行为发育与评价、儿童营养与营养相关性疾病、儿童日常保健、儿童安全防护、儿童疾病预防等。每个项目下设计了若干实际任务，共包括37个主任务（含116个子任务），这些任务均基于实际情境，旨在帮助读者更好地理解并应用理论知识。通过任务情境的引领，使读者能够更好地理解任务的内涵、内容和意义。通过任务实施落实该情境任务的解决方案，再通过考核标准进行任务实施的有效评价。这种理论和实践相结合的编写特色，让本书更加系统化、生动化和实用化。', 59.90, 47.92, 71, '《儿童保健理论与实操手册》是一本全面、实用的儿童保健指南，旨在为护理、助产、婴幼儿托育服务与管理等专业人才的培养、儿童保健工作者和广大家长提供全面、实用的指导和帮助。本书将理论知识与实践操作相结合，深入浅出地介绍了儿童保健的基本理论，包括儿童生长发育的特点、营养需求、疾病预防等方面的知识。同时，本书结合实际操作，详细介绍了儿童体格生长指标的检查、常见疾病的处理、急救等方面的技能。
本书共分为7个项目，包括儿童体格生长发育与评价、儿童神经心理行为发育与评价、儿童营养与营养相关性疾病、儿童日常保健、儿童安全防护、儿童疾病预防等。每个项目下设计了若干实际任务，共包括37个主任务（含116个子任务），这些任务均基于实际情境，旨在帮助读者更好地理解并应用理论知识。通过任务情境的引领，使读者能够更好地理解任务的内涵、内容和意义。通过任务实施落实该情境任务的解决方案，再通过考核标准进行任务实施的有效评价。这种理论和实践相结合的编写特色，让本书更加系统化、生动化和实用化。', '前言
