  ('34', '人体解剖学是研究人体正常形态、结构及其相互关系的科学，揭示人体如何构成，是生物学和医学的基础学科，也是医学实践的基石。 本教材主要内容包括绪论及运动系统、消化系统、呼吸系统、泌尿系统、生殖系统、脉管系统、感觉器、神经系统、内分泌系统等人体九大系统。每个系统涵盖系统组成及器官位置、形态和结构等内容。 本教材以职业能力和学习能力培养为根本，在解剖学知识中紧密联系临床实践，注重培养学生临床思维能力和责任意识以及分析问题、解决问题的能力。本教材利用数字技术将四色彩图、3D交互式解剖结构（H5）、动画、微课等数字资源融于解剖学理论知识和技能学习中，让学生可以直观理解人体结构，从而更好地联系临床，为后续课程学习打好基础。
本教材可作为高等职业教育临床医学类、护理类、中医药类、康复治疗类专业教学用书，也可供相关从业人员参考。', 38.50, 30.80, 377, '人体解剖学是研究人体正常形态、结构及其相互关系的科学，揭示人体如何构成，是生物学和医学的基础学科，也是医学实践的基石。 本教材主要内容包括绪论及运动系统、消化系统、呼吸系统、泌尿系统、生殖系统、脉管系统、感觉器、神经系统、内分泌系统等人体九大系统。每个系统涵盖系统组成及器官位置、形态和结构等内容。 本教材以职业能力和学习能力培养为根本，在解剖学知识中紧密联系临床实践，注重培养学生临床思维能力和责任意识以及分析问题、解决问题的能力。本教材利用数字技术将四色彩图、3D交互式解剖结构（H5）、动画、微课等数字资源融于解剖学理论知识和技能学习中，让学生可以直观理解人体结构，从而更好地联系临床，为后续课程学习打好基础。
本教材可作为高等职业教育临床医学类、护理类、中医药类、康复治疗类专业教学用书，也可供相关从业人员参考。', '前言
