  ('33', '《高等数学》数字教材分上、下两册。下册主要内容包括微分方程、空间解析几何与向量代数、多元函数微分法及其应用、重积分、曲线积分与曲面积分、无穷级数等6章。每章除了高等数学的经典内容外，还增加了典型例题与考研题选讲，以满足学有余力学生的个性化需求。本教材充分利用数字媒体表现形式丰富的特点，在本册中，绘制了近400幅精美彩图，制作了48个形象动画，嵌入了40余个视频和拓展阅读，研发了14个H5自主学习模型。本教材可用作高等学校高等数学课程的主教材，也可作为教学参考书供读者参考。
高等数学数字教材是华中师范大学大学数学共建共享虚拟教研室的建设成果，参与编写的高校均来自该虚拟教研室，具体是:华中师范大学、新疆农业大学、重庆交通大学、鄂尔多斯应用技术学院、武汉纺织大学。', 68.00, 54.40, 79, '《高等数学》数字教材分上、下两册。下册主要内容包括微分方程、空间解析几何与向量代数、多元函数微分法及其应用、重积分、曲线积分与曲面积分、无穷级数等6章。每章除了高等数学的经典内容外，还增加了典型例题与考研题选讲，以满足学有余力学生的个性化需求。本教材充分利用数字媒体表现形式丰富的特点，在本册中，绘制了近400幅精美彩图，制作了48个形象动画，嵌入了40余个视频和拓展阅读，研发了14个H5自主学习模型。本教材可用作高等学校高等数学课程的主教材，也可作为教学参考书供读者参考。
