  ('32', '本教材以“岗课赛证+思政融通”的人才培养理念为导向，采用“模块—任务”的逻辑结构，依据学生“求职、成长、成熟、晋升”职业发展轨迹以及“由易到难”的认知规律，系统性地设计4大模块、27项任务。各模块间既相互独立、自成一体，又彼此关联、层层递进，既能够支撑全流程的体系化学习，也可根据岗位需求进行精准选学。每项任务均以“任务导读—学习目标—引导案例—实施准备—任务实施—考核与评价—拓展提升”为主线进行编排，充分彰显了“学中做、做中学”的职业教育特色。
本教材配套制作了微课视频、教学课件、PPT、习题测试、虚拟3D宴会设计案例库、“1+X”证书考试题库等数字资源，借助多模态学习资源为职业教育赋能。
本教材既可作为高等职业院校旅游类、餐饮类专业的教学和学习用书，又可以作为酒店行业人员培训和职业资格考试的辅导教材。', 35.00, 28.00, 74, '本教材以“岗课赛证+思政融通”的人才培养理念为导向，采用“模块—任务”的逻辑结构，依据学生“求职、成长、成熟、晋升”职业发展轨迹以及“由易到难”的认知规律，系统性地设计4大模块、27项任务。各模块间既相互独立、自成一体，又彼此关联、层层递进，既能够支撑全流程的体系化学习，也可根据岗位需求进行精准选学。每项任务均以“任务导读—学习目标—引导案例—实施准备—任务实施—考核与评价—拓展提升”为主线进行编排，充分彰显了“学中做、做中学”的职业教育特色。
