  ('30', '本书全面系统地介绍了参与式农村发展的理论体系，构建了 “理论→方法→实践” 的系统性知识架构。通过清晰的讲解和丰富的案例，本书助力读者深入理解参与式农村发展的核心理论、基本原则与实践方法等内容。本书既适用于对农村发展领域感兴趣的学者，也旨在为从事农村发展与推广、农业经济管理、农村社会治理等领域的研究者提供系统化的研究思路与实践策略，助力其在农村发展领域探索更具创新性的理论成果与实践路径。', 28.00, 22.40, 18, '本书全面系统地介绍了参与式农村发展的理论体系，构建了 “理论→方法→实践” 的系统性知识架构。通过清晰的讲解和丰富的案例，本书助力读者深入理解参与式农村发展的核心理论、基本原则与实践方法等内容。本书既适用于对农村发展领域感兴趣的学者，也旨在为从事农村发展与推广、农业经济管理、农村社会治理等领域的研究者提供系统化的研究思路与实践策略，助力其在农村发展领域探索更具创新性的理论成果与实践路径。', '序言
第一章 参与式农村发展的缘起和内涵
　第一节 参与式农村发展的缘起
　第二节 对参与发展及参与式发展的理解
　第三节 农村发展与参与式农村发展
第二章 从脱贫到振兴的案例分析参与式农村发展的要素
　第一节 吉林省洮南市那金镇好田村的脱贫到振兴实践
　第二节 云南省西双版纳州勐腊县勐伴镇河边村的脱贫振兴实践
　第三节 参与式农村发展的要素及相互关系分析
第三章 农村发展导向的行动研究
　第一节 对行动研究的理解
　第二节 问题、研究问题与行动 研究问题的界定
　第三节 行动研究在农村发展中的作用
第四章 参与式农村发展的研究方法
　第一节 参与式农村发展工作的基本程序
