  ('29', '本书是在高等教育出版社2004 年出版的，严子谦、尹景学、张然主编的《数学分析》教材基础上，结合吉林大学近十几年的教学经验编写而成的数字教材。从初等数学到微积分的过渡出发，全书包括数列极限、函数极限、函数的连续性、导数与微分、中值定理与Taylor 公式、不定积分、定积分、数项级数、函数项级数、Fourier 级数、多元函数的极限与连续性、偏导数与全微分、多元函数极值和高阶偏导数、重积分、第一型曲线曲面积分、第二型曲线曲面积分、广义积分、含参变量积分等内容。
本书可作为综合性大学和高等师范院校数学类专业教材，也可供其他对数学要求相对较高的专业学生或研究人员选用。', 96.00, 76.80, 107, '本书是在高等教育出版社2004 年出版的，严子谦、尹景学、张然主编的《数学分析》教材基础上，结合吉林大学近十几年的教学经验编写而成的数字教材。从初等数学到微积分的过渡出发，全书包括数列极限、函数极限、函数的连续性、导数与微分、中值定理与Taylor 公式、不定积分、定积分、数项级数、函数项级数、Fourier 级数、多元函数的极限与连续性、偏导数与全微分、多元函数极值和高阶偏导数、重积分、第一型曲线曲面积分、第二型曲线曲面积分、广义积分、含参变量积分等内容。
本书可作为综合性大学和高等师范院校数学类专业教材，也可供其他对数学要求相对较高的专业学生或研究人员选用。', '内容提要
