  ('28', '《人工智能内生安全》是一本聚焦人工智能模型内在安全问题的专业教材，系统探讨了AI技术在数据收集、模型训练及部署等全生命周期中面临的安全风险与防护策略。本书立足于大模型时代的新挑战，填补了国内在大模型安全领域的教材空白，兼具理论深度与实践指导价值。
教材主要内容涵盖传统小模型与大模型两大领域的安全攻防技术。基础部分梳理了对抗样本、后门攻击、数据泄露等经典问题的攻防算法；进阶部分则聚焦视觉大模型、大语言模型和多模态大模型三类主流模型，详细分析其特有安全隐患（如虚假信息生成、参数抽取等），并介绍前沿防御机制与技术解决方案。全书通过“基础—进阶”结构，为读者构建从理论到实践的知识体系。
本书适合人工智能、信息安全、计算机科学等相关专业的本科生、研究生及行业从业者阅读。教材中部分复杂技术细节可为研究人员提供专业参考，也可助力从业者提升AI系统的安全防护能力。', 40.00, 32.00, 37, '《人工智能内生安全》是一本聚焦人工智能模型内在安全问题的专业教材，系统探讨了AI技术在数据收集、模型训练及部署等全生命周期中面临的安全风险与防护策略。本书立足于大模型时代的新挑战，填补了国内在大模型安全领域的教材空白，兼具理论深度与实践指导价值。
教材主要内容涵盖传统小模型与大模型两大领域的安全攻防技术。基础部分梳理了对抗样本、后门攻击、数据泄露等经典问题的攻防算法；进阶部分则聚焦视觉大模型、大语言模型和多模态大模型三类主流模型，详细分析其特有安全隐患（如虚假信息生成、参数抽取等），并介绍前沿防御机制与技术解决方案。全书通过“基础—进阶”结构，为读者构建从理论到实践的知识体系。
本书适合人工智能、信息安全、计算机科学等相关专业的本科生、研究生及行业从业者阅读。教材中部分复杂技术细节可为研究人员提供专业参考，也可助力从业者提升AI系统的安全防护能力。', '前言
