  ('27', '本教材是高等职业教育融媒体、交互式、智能化公共英语数字教材，以“产出导向”教育理念为核心，以任务做引领，引导学生在解决实际问题的过程中，高效掌握英语听说读写译等各项技能。本教材数字资源丰富，特色鲜明，与旅游、外贸、汽车等涉外行业企业专家深度合作，依据职业通用能力需求，精心构建内容体系，确保学习内容紧贴时代前沿。
