  ('26', '本教材共有9个项目，全面介绍新能源汽车技术涉及的主要知识，包括新能源汽车概况、纯电动汽车、混合动力汽车、燃料电池汽车、新能源汽车动力电池、新能源汽车驱动电机、新能源汽车充电系统、新能源汽车的维修与保养、其他新能源汽车，并融入新能源汽车维修、保养和故障诊断等方面的基本技能，为后续专业课程的学习打基础。本教材在图文结合讲解的基础上融入大量数字化教学资源，如微课、技能实操视频、动画，支持线上线下混合式教学。
本教材可作为职业院校新能源汽车技术、汽车检测与维修技术等汽车类专业的教学用书，也可供汽车行业相关技术人员学习参考。授课教师如需本书配套的教学课件等资源，可发送邮件至gzjx@pub.hep.cn获取。', 40.00, 32.00, 91, '本教材共有9个项目，全面介绍新能源汽车技术涉及的主要知识，包括新能源汽车概况、纯电动汽车、混合动力汽车、燃料电池汽车、新能源汽车动力电池、新能源汽车驱动电机、新能源汽车充电系统、新能源汽车的维修与保养、其他新能源汽车，并融入新能源汽车维修、保养和故障诊断等方面的基本技能，为后续专业课程的学习打基础。本教材在图文结合讲解的基础上融入大量数字化教学资源，如微课、技能实操视频、动画，支持线上线下混合式教学。
