  ('25', '本书以Python语法、Python应用为载体，介绍计算机科学的基本原理、计算思维在人工智能时代的必要性及程序设计的方法论。
本书具体包括Python语法元素、数据类型、程序控制结构、函数、文件等内容。此外，围绕数据处理，讲解各种办公文档的自动化处理、网页数据爬取、图形用户界面设计等内容。
本书从日常工作、学习需求出发设计教学案例，使Python语法知识的学习自然地融入探寻解决问题的过程中。以更贴近生活的语言、合理的难度进阶设置、明晰的图片、丰富的视频、启发式的试题资源等多种方式，帮助读者更好地理解Python。
本书既适合作为高职院校各专业的信息技术通识课、程序设计入门课程的教材，也适合自学者学习。', 39.00, 31.20, 676, '本书以Python语法、Python应用为载体，介绍计算机科学的基本原理、计算思维在人工智能时代的必要性及程序设计的方法论。
本书具体包括Python语法元素、数据类型、程序控制结构、函数、文件等内容。此外，围绕数据处理，讲解各种办公文档的自动化处理、网页数据爬取、图形用户界面设计等内容。
本书从日常工作、学习需求出发设计教学案例，使Python语法知识的学习自然地融入探寻解决问题的过程中。以更贴近生活的语言、合理的难度进阶设置、明晰的图片、丰富的视频、启发式的试题资源等多种方式，帮助读者更好地理解Python。
