  ('23', '本书是职业教育国家在线精品课程、国家精品在线开放课程、江苏省职业教育课程思政示范课程“程序设计基础”的配套数字教材。
本书以程序设计方法为核心，以算法、数据结构为主线，坚守以“立德树人”为根本，以培养能力、提高兴趣为目标，改传统授课方式为信息化教学方式，把程序设计领域最新、最有价值的思想和方法渗透到C语言教学中，强化学生灵活运用这些思想与方法分析和解决实际问题的能力，培养具有科技报国情怀、创新协作能力和历史使命担当的新时代程序设计者。
本书以“身高体型判定系统”“考试系统”“学生信息管理系统”三个真实项目为引领，由易到难，由简到繁，逐层深入，步步递进，展开教学，讲解C语言基本知识与结构化程序设计方法。全书分为程序设计入门和项目化教学2个部分，共10个教学单元，内容主要包括C语言的数据类型、程序结构、各种语句、函数、预处理、文件等。每个单元由项目需求引领，按三层六环模式从“理论知识、实践教学、项目实施”三层面构建具有“全、精、细”特色教学资源，按企业项目开发流程划分“项目需求→相关知识→过关斩将→解决问题→能力测试→项目实施”六环节展开教学，可极大提高学生的知识、技能、素质水平。
本数字教材含微课视频、PPT动画、H5交互式动画、源代码、习题、讨论、拓展知识等丰富的数字化资源。
本教材的配套辅助用书为“十四五”职业教育国家规划教材《C语言程序设计（第2版）》（赵彦主编，高等教育出版社，2023年12月），本教材及配套辅助用书适用于高等职业院校电子与信息大类各专业C语言课程的教材，也可作为C语言学习者的参考用书和继续教育学习者用书。', 45.00, 36.00, 1471, '本书是职业教育国家在线精品课程、国家精品在线开放课程、江苏省职业教育课程思政示范课程“程序设计基础”的配套数字教材。
本书以程序设计方法为核心，以算法、数据结构为主线，坚守以“立德树人”为根本，以培养能力、提高兴趣为目标，改传统授课方式为信息化教学方式，把程序设计领域最新、最有价值的思想和方法渗透到C语言教学中，强化学生灵活运用这些思想与方法分析和解决实际问题的能力，培养具有科技报国情怀、创新协作能力和历史使命担当的新时代程序设计者。
本书以“身高体型判定系统”“考试系统”“学生信息管理系统”三个真实项目为引领，由易到难，由简到繁，逐层深入，步步递进，展开教学，讲解C语言基本知识与结构化程序设计方法。全书分为程序设计入门和项目化教学2个部分，共10个教学单元，内容主要包括C语言的数据类型、程序结构、各种语句、函数、预处理、文件等。每个单元由项目需求引领，按三层六环模式从“理论知识、实践教学、项目实施”三层面构建具有“全、精、细”特色教学资源，按企业项目开发流程划分“项目需求→相关知识→过关斩将→解决问题→能力测试→项目实施”六环节展开教学，可极大提高学生的知识、技能、素质水平。
本数字教材含微课视频、PPT动画、H5交互式动画、源代码、习题、讨论、拓展知识等丰富的数字化资源。
本教材的配套辅助用书为“十四五”职业教育国家规划教材《C语言程序设计（第2版）》（赵彦主编，高等教育出版社，2023年12月），本教材及配套辅助用书适用于高等职业院校电子与信息大类各专业C语言课程的教材，也可作为C语言学习者的参考用书和继续教育学习者用书。', '前言
