  ('22', '本书是贯彻落实职业教育提质培优行动计划中校企双元合作教材建设任务的项目成果之一，也是在线开放课程的配套教材。
本书根据企业税务工作人员的岗位任职要求与各项财经法规进行编写，全书依照税制分类，划分为3个模块。模块一主要介绍征纳管理方面的各项规定，是企业涉税业务的起点；模块二以单个税种的纳税工作作为一个项目进行编排，以项目案例驱动，围绕案例所需知识点与技能点展开，以项目案例的实施工作成果作为学习的成果；模块三介绍大数据技术在税费申报与管理中的运用，包括财务共享中的税务管理和机器人在税务领域中的运用。
本书以课程建设为依托，以职业能力培养为主线，内容全面，形式多样，资源丰富，既能满足教师运用多种教学方法教学，也能满足学生探究性学习的需求。', 42.00, 33.60, 273, '本书是贯彻落实职业教育提质培优行动计划中校企双元合作教材建设任务的项目成果之一，也是在线开放课程的配套教材。
本书根据企业税务工作人员的岗位任职要求与各项财经法规进行编写，全书依照税制分类，划分为3个模块。模块一主要介绍征纳管理方面的各项规定，是企业涉税业务的起点；模块二以单个税种的纳税工作作为一个项目进行编排，以项目案例驱动，围绕案例所需知识点与技能点展开，以项目案例的实施工作成果作为学习的成果；模块三介绍大数据技术在税费申报与管理中的运用，包括财务共享中的税务管理和机器人在税务领域中的运用。
