  ('21', '本教材致力于对数字创业现象进行回顾，对创业者如何识别和开发数字创业机会，促进企业成长进行较为系统的讲解。教材内容强调理论与实践的充分融合：在理论方面，以介绍数字创业相关议题的基础理论为主；在实践方面，提供大量与数字创业有关的真实数据、案例、资料，由此启发学生积极研究、分析、参与数字创业活动。
本教材共11章，内容包括如下4个模块：数字创业的概貌，主要对数字创业的基础概念进行分析，包括数字创业的概念、数字创业活动的发展历史、数字创业的过程分析以及数字创业的伦理问题；数字创业机会的识别，主要介绍数字创业的准备工作，包括数字创业者与创业团队、数字创业的商业模式、数字创业融资三个方面的内容；数字创业企业的成长，主要分析数字创业企业的成长问题，包括数字创业的战略、数字创业的营销；特定类型的数字创业活动，主要关注特定领域的数字创业，包括数字社会创业、数字公司创业。
本教材涉及大量数字创业领域的案例资料，可为高等学校学生学习和了解数字创业活动的基础知识提供素材，也可为数字领域创业实践者提供实际创业的借鉴。', 30.00, 24.00, 74, '本教材致力于对数字创业现象进行回顾，对创业者如何识别和开发数字创业机会，促进企业成长进行较为系统的讲解。教材内容强调理论与实践的充分融合：在理论方面，以介绍数字创业相关议题的基础理论为主；在实践方面，提供大量与数字创业有关的真实数据、案例、资料，由此启发学生积极研究、分析、参与数字创业活动。
本教材共11章，内容包括如下4个模块：数字创业的概貌，主要对数字创业的基础概念进行分析，包括数字创业的概念、数字创业活动的发展历史、数字创业的过程分析以及数字创业的伦理问题；数字创业机会的识别，主要介绍数字创业的准备工作，包括数字创业者与创业团队、数字创业的商业模式、数字创业融资三个方面的内容；数字创业企业的成长，主要分析数字创业企业的成长问题，包括数字创业的战略、数字创业的营销；特定类型的数字创业活动，主要关注特定领域的数字创业，包括数字社会创业、数字公司创业。
本教材涉及大量数字创业领域的案例资料，可为高等学校学生学习和了解数字创业活动的基础知识提供素材，也可为数字领域创业实践者提供实际创业的借鉴。', '前言
