  ('20', '本书主要内容包括矩阵及其初等变换、行列式、n维向量空间、特征值与特征向量、二次型、线性空间与线性变换等。前5章内容自成体系，满足教育部高等学校大学数学课程教学指导委员会制订的工科类线性代数相关方面教学要求；第6章线性空间与线性变换供教学要求较高的学校选用。
本书对线性代数的传统内容进行了全新处理。特别是，代数与几何的结合，将矩阵的初等变换作为贯穿全书的计算和重要的理论推导工具，注重不同知识点与重要理论的内在本质联系，将几何空间、n维向量空间到抽象线性空间概念的建立从特殊到一般进行铺垫，在理论体系的处理上科学简洁、深入浅出、可读性强、易教易学；除了传统的应用实例，精心设计了一批与课程内容紧密贴合，反映人工智能、大数据等新工科前沿科技的应用实例（如，图像处理、电影推荐、Google搜索引擎、北斗卫星导航系统等)，为大学一年级新生搭建起跨越数学基础课与前沿信息科技鸿沟的桥梁。
作为数字教材，进一步完善了数字教学资源，包括概念解析微视频、典型例题精讲微视频、知识点注释、自测题、应用实例（特别是反映新工科前沿科技的应用实例）、习题答案等。
本书配套有作者主讲的同名国家精品在线开放课（中国大学MOOC平台）和高等教育出版社出版的同名数字课程等，便于学生自主学习。
本书可作为工科和其他所有非数学类专业的教材或教学参考书。', 68.00, 54.40, 3649, '本书主要内容包括矩阵及其初等变换、行列式、n维向量空间、特征值与特征向量、二次型、线性空间与线性变换等。前5章内容自成体系，满足教育部高等学校大学数学课程教学指导委员会制订的工科类线性代数相关方面教学要求；第6章线性空间与线性变换供教学要求较高的学校选用。
