  ('19', '本书是是国家级精品课程、国家级精品资源共享课、国家级一流课程“设计概论”的配套教材。全书共12章，第1~2章解决了设计是什么、它是如何形成发展的等基本问题，有助于学生形成对设计专业的初步认识；第3~9章分别介绍了视觉传达设计、环境设计、产品设计、服装与服饰设计、公共艺术、工艺美术、数字媒体艺术等设计实践类型，学生在理解设计学科整体架构的基础上，可以选择所学专业及兴趣所在的部分重点学习；第10章概括了以上不同类型的设计活动所遵循的一般规律，介绍了基本的设计原理和方法；第11章介绍了设计师的工作形式、能力要求、岗位职位与责任等，可供有志以设计为职业的学生参考；第12章介绍了设计学学术研究的基础知识，既面向艺术设计理论专业的学生，也是对设计实践专业学生理论知识的扩充和提升。
本书根据时代和学科的最新发展形势，修订为数字教材后，突出了融媒体特点，丰富了图片、视频、动画、交互式三维模型等数字化资源，生动直观地展现了经典设计作品，提高了知识点的可视化程度，以增加学习的趣味性和互动性；部分拓展案例借助了AI辅助，并提供制作方法和步骤。
本书可作为高等院校艺术学、艺术设计、工业设计等相关专业领域的专业基础课教材，也可供相关行业领域学习者参考使用。', 38.00, 30.40, 127, '本书是是国家级精品课程、国家级精品资源共享课、国家级一流课程“设计概论”的配套教材。全书共12章，第1~2章解决了设计是什么、它是如何形成发展的等基本问题，有助于学生形成对设计专业的初步认识；第3~9章分别介绍了视觉传达设计、环境设计、产品设计、服装与服饰设计、公共艺术、工艺美术、数字媒体艺术等设计实践类型，学生在理解设计学科整体架构的基础上，可以选择所学专业及兴趣所在的部分重点学习；第10章概括了以上不同类型的设计活动所遵循的一般规律，介绍了基本的设计原理和方法；第11章介绍了设计师的工作形式、能力要求、岗位职位与责任等，可供有志以设计为职业的学生参考；第12章介绍了设计学学术研究的基础知识，既面向艺术设计理论专业的学生，也是对设计实践专业学生理论知识的扩充和提升。
本书根据时代和学科的最新发展形势，修订为数字教材后，突出了融媒体特点，丰富了图片、视频、动画、交互式三维模型等数字化资源，生动直观地展现了经典设计作品，提高了知识点的可视化程度，以增加学习的趣味性和互动性；部分拓展案例借助了AI辅助，并提供制作方法和步骤。
本书可作为高等院校艺术学、艺术设计、工业设计等相关专业领域的专业基础课教材，也可供相关行业领域学习者参考使用。', '新版前言
