  ('17', '本教材是国家职业教育电子信息工程技术专业教学资源库配套教材，也是职业教育国家在线精品课程配套教材。全书通过完成10个生活中常见的、有一定趣味的实践项目，介绍了电路的基本概念和基本定律、电路的基本分析方法、正弦交流电路等内容。每个项目都是制作与调试一个实际应用电路的完整过程，按照学习者的认知规律分为“做什么”“来仿真”“动手做”“去拓展”“学知识”等环节。
