  ('16', '本书是国家级精品课程、国家级精品资源共享课、首批国家级一流本科课程“会计信息化”的配套教材，也是教育部首批虚拟教研室建设试点（会计信息化课程虚拟教研室）推荐用书。
本书针对小型商品流通企业，设计了一个简化版的企业业财融合教学案例，从案例经济业务引入，分析其业务处理流程、数据处理流程、数据库设计；应用SQL实现业务数据查询统计分析；应用SQL实现从业务单据到对应会计凭证生成、账务处理、会计报表查询计算，从而实现从业务数据到会计报表的业财融合顺向计算处理；应用SQL实现从会计报表到业务数据的业财融合逆向溯源处理；应用SQL实现对业财融合系统中异常数据的稽核审计处理。最后，应用会计软件开发平台，实现业务管理系统、账务处理系统、业财融合系统的分析设计与开发。通过学习，可深入了解掌握SQL在会计数据处理中的应用，提升应用信息技术进行查（数据分析统计查询）、算（会计账表数据计算）、审（异常数据稽核审计）、溯（账表数据追踪溯源）四大核心会计数据处理的能力。
本书共五篇18章。第一篇会计数据分析，包括第一章业财融合案例引入、第二章业财融合系统分析、第三章业财融合系统数据库设计。本篇结合业财融合教学案例阐述系统业务处理流程与数据处理流程分析、功能分析、数据库设计等内容。
第二篇数据库与SQL语言基础，包括第四章数据库管理器与数据操作、第五章SQL语言基础。本篇以进销存管理系统与账务处理系统为案例原型，介绍了SQL语句的基本语法、常用函数。通过应用简单的SQL，实现对案例数据的增加、删除、修改、查询等基本数据处理功能。本篇是全书的重点。
第三篇SQL在查算审溯中的应用，包括第六章SQL统计分析、第七章SQL账表计算、第八章SQL稽核审计、第九章SQL数据溯源、第十章SQL编程、第十一章SQL综合应用案例。本篇第六章至第十章以进销存管理系统与账务处理系统为案例原型，介绍SQL在查、算、审、溯四大核心会计数据处理中的应用。第十一章综合应用SQL实现账务处理系统的基本功能、从业务单据查询分析会计报表、从业务单据计算处理会计报表、从业务单据稽核审计会计报表以及从会计报表追踪溯源业务单据。本篇是全书的精华与难点。
第四篇会计软件开发技术，包括第十二章数据窗口实现SQL可视化、第十三章会计软件开发基础、第十四章嵌入SQL应用、第十五章数据窗口应用。本篇介绍了PowerBuilder强大的数据处理利器数据窗口对象、SQL可视化、会计软件开发基础、通过嵌入SQL实现对数据的处理等会计软件开发技术。
第五篇会计信息系统开发，包括第十六章业务处理系统开发、第十七章账务处理系统开发、第十八章业财融合系统开发。本篇介绍了费用管理系统、融资管理系统、低值易耗品管理系统、工资管理系统、固定资产管理系统、进销存管理系统以及账务处理系统的开发，最后介绍了各个业务系统与账务处理系统打通数据接口的业财融合系统开发。
本书可作为普通高校会计、财务管理、审计、信息管理与信息系统、大数据管理与应用等专业的会计信息化、审计信息化、会计数据分析与处理、管理信息系统、数据库SQL应用、信息系统分析设计与开发等相关课程教材或教学参考书。也可作为会计审计SQL培训教材以及高职院校相关课程使用。', 50.00, 40.00, 139, '本书是国家级精品课程、国家级精品资源共享课、首批国家级一流本科课程“会计信息化”的配套教材，也是教育部首批虚拟教研室建设试点（会计信息化课程虚拟教研室）推荐用书。
