　附录2 案例列表'),
  ('15', '本教材系统介绍新能源领域设备与系统的专业知识，为新能源相关专业本专科学生提供全面的理论知识与实践技能指导。本书内容编排深度融合理论与实践，通过丰富的案例与实操步骤引导学生掌握核心知识与技能。同时，紧密追踪新能源领域前沿发展与趋势，确保教材兼具实用性和前瞻性。
全书共分为四章。第一章介绍新能源高效利用设备，从氢气压缩机、制冷压缩机的基础认知与拆装检修，到制冷设备的维护保养与故障分析排除，内容层层递进，帮助学习者掌握设备实操与故障处理的核心技能，为后续学习筑牢根基。第二章围绕新能源高效利用系统展开，深入剖析高效多功能制冷实验系统、气调冷藏库系统、太阳能冷库系统等多种系统的运行及维护管理，让学习者深入理解新能源在不同应用场景下的系统运作，全面提升解决复杂工程问题的能力。第三章借助虚拟手段开展新能源高效利用系统仿真，涵盖制冷系统及暖通空调系统的虚拟仿真操作，进一步深化学习者对新能源高效利用系统的理解与操作能力。第四章强调新能源冷热工程师职业道德规范，在技术飞速发展的当下，着重强调从业者的职业操守，确保新能源行业健康、可持续发展。
本书可作为高校新能源相关专业本专科学生的教材，包括能源与动力工程专业本科生及制冷与空调技术专业高职专科生等，也可供新能源行业从业者或对新能源领域感兴趣的研究人员阅读参考。', 48.00, 38.40, 139, '本教材系统介绍新能源领域设备与系统的专业知识，为新能源相关专业本专科学生提供全面的理论知识与实践技能指导。本书内容编排深度融合理论与实践，通过丰富的案例与实操步骤引导学生掌握核心知识与技能。同时，紧密追踪新能源领域前沿发展与趋势，确保教材兼具实用性和前瞻性。
全书共分为四章。第一章介绍新能源高效利用设备，从氢气压缩机、制冷压缩机的基础认知与拆装检修，到制冷设备的维护保养与故障分析排除，内容层层递进，帮助学习者掌握设备实操与故障处理的核心技能，为后续学习筑牢根基。第二章围绕新能源高效利用系统展开，深入剖析高效多功能制冷实验系统、气调冷藏库系统、太阳能冷库系统等多种系统的运行及维护管理，让学习者深入理解新能源在不同应用场景下的系统运作，全面提升解决复杂工程问题的能力。第三章借助虚拟手段开展新能源高效利用系统仿真，涵盖制冷系统及暖通空调系统的虚拟仿真操作，进一步深化学习者对新能源高效利用系统的理解与操作能力。第四章强调新能源冷热工程师职业道德规范，在技术飞速发展的当下，着重强调从业者的职业操守，确保新能源行业健康、可持续发展。
本书可作为高校新能源相关专业本专科学生的教材，包括能源与动力工程专业本科生及制冷与空调技术专业高职专科生等，也可供新能源行业从业者或对新能源领域感兴趣的研究人员阅读参考。', '前言
第一章 新能源高效利用设备
　第一节 氢气压缩机拆装检修
　　任务一 认识氢气压缩机
　　任务二 隔膜式氢气压缩机的结构认知
　　　子任务一 隔膜式氢气压缩机首次调试
　　　子任务二 隔膜式氢气压缩机操作与保养
　　　子任务三 隔膜式氢气压缩机拆装
　　　子任务四 隔膜式氢气压缩机故障
