  ('14', '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材以典型的继电器控制电路和三菱FX3U系列PLC的应用为主线，分别介绍了电气控制基本电路安装与调试、电气控制基本电路PLC的安装与调试、PLC的顺序控制、PLC的功能指令、变频器与PLC控制等相关内容。
本教材采用校企联合开发的方式，引入企业典型的项目案例，将PLC的基础知识、指令系统、编程技巧、安装调试融入实例中，配有丰富的视频和动画资源，突出技能的培养，提高读者对电气控制和PLC的综合应用能力，同时融入思政元素，培养工匠精神、创新思维等职业素养。
本教材可作为高职院校机电一体化技术、电气自动化技术、自动控制、工业自动化、应用电子、计算机应用及其他相关专业教材，也可作为工程技术人员、职业培训学校的PLC培训教材或自学参考书。', 45.00, 36.00, 348, '本教材是高等职业教育融媒体、交互式、智能化数字教材。
本教材以典型的继电器控制电路和三菱FX3U系列PLC的应用为主线，分别介绍了电气控制基本电路安装与调试、电气控制基本电路PLC的安装与调试、PLC的顺序控制、PLC的功能指令、变频器与PLC控制等相关内容。
本教材采用校企联合开发的方式，引入企业典型的项目案例，将PLC的基础知识、指令系统、编程技巧、安装调试融入实例中，配有丰富的视频和动画资源，突出技能的培养，提高读者对电气控制和PLC的综合应用能力，同时融入思政元素，培养工匠精神、创新思维等职业素养。
本教材可作为高职院校机电一体化技术、电气自动化技术、自动控制、工业自动化、应用电子、计算机应用及其他相关专业教材，也可作为工程技术人员、职业培训学校的PLC培训教材或自学参考书。', '前言
