  ('13', '本教材以商品、服务和生产要素的跨国流动等国际经济活动为研究对象，系统介绍各国或地区之间经济联系的内在机制、影响及其政策含义。本教材主要分为国际贸易和国际金融两大部分，其中国际贸易部分主要介绍国际贸易理论和政策，国际金融部分介绍国际收支、外汇理论与政策、内外部平衡等内容。
本教材立足中国实际、借鉴国外经验，尊重历史、把握当代、面向未来，试图在阐释西方经典国际经济学理论在中国的适用性和局限性的过程中，进一步发现、总结和提炼中国对外开放规律的特殊性，尝试探索构建有中国特色的国际经济学教材体系。本教材注重理论知识脉络的梳理，帮助读者搭建结构完整、逻辑清晰的知识架构；注重通过规范的经济学研究范式，夯实学生的理论基础；注重通过课程思政元素的挖掘，加强对学生价值观的引领。本教材嵌入视频、图片、习题等富媒体资源，全面彰显内容契合度、教学时效性与知识拓展性的有机统一。
本教材既可作为经济与贸易类相关专业及其他经济学类专业本科生的教学用书，又可供理论研究者和实际工作者参考。', 48.00, 38.40, 634, '本教材以商品、服务和生产要素的跨国流动等国际经济活动为研究对象，系统介绍各国或地区之间经济联系的内在机制、影响及其政策含义。本教材主要分为国际贸易和国际金融两大部分，其中国际贸易部分主要介绍国际贸易理论和政策，国际金融部分介绍国际收支、外汇理论与政策、内外部平衡等内容。
本教材立足中国实际、借鉴国外经验，尊重历史、把握当代、面向未来，试图在阐释西方经典国际经济学理论在中国的适用性和局限性的过程中，进一步发现、总结和提炼中国对外开放规律的特殊性，尝试探索构建有中国特色的国际经济学教材体系。本教材注重理论知识脉络的梳理，帮助读者搭建结构完整、逻辑清晰的知识架构；注重通过规范的经济学研究范式，夯实学生的理论基础；注重通过课程思政元素的挖掘，加强对学生价值观的引领。本教材嵌入视频、图片、习题等富媒体资源，全面彰显内容契合度、教学时效性与知识拓展性的有机统一。
本教材既可作为经济与贸易类相关专业及其他经济学类专业本科生的教学用书，又可供理论研究者和实际工作者参考。', '前言
