  ('12', '本教材是商业银行经营管理仿真实验的配套教材，由9个紧密关联的实验构成。主要特点：①实验育人。明确的能力培养与价值塑造目标，帮助学生形成对金融人才能力素养的认知。②理实结合。依据企业生命周期理论组织实验，使学生掌握商业银行在不同发展阶段的经营特征与管理重点，切实提升解决实际问题的能力。③知识重构。通过知识图谱重构知识体系，引导学生融会贯通战略管理、营销管理、人力资源管理、数据可视化及商业银行经营管理知识、工具与方法等理论知识。④紧贴现实。以中国银行作为典型案例贯穿实验，引导学生关注金融业发展。⑤数智赋能。开发虚拟仿真实验、交互习题、动画、数字人视频等丰富的数字资源，增强学习趣味性与互动性。
本教材可作为高等学校金融学类学生的专业教材，还可作为全国大学生“数字金融挑战赛”的指导用书，同时能为金融业从业人员提供有益参考。', 49.00, 39.20, 15, '本教材是商业银行经营管理仿真实验的配套教材，由9个紧密关联的实验构成。主要特点：①实验育人。明确的能力培养与价值塑造目标，帮助学生形成对金融人才能力素养的认知。②理实结合。依据企业生命周期理论组织实验，使学生掌握商业银行在不同发展阶段的经营特征与管理重点，切实提升解决实际问题的能力。③知识重构。通过知识图谱重构知识体系，引导学生融会贯通战略管理、营销管理、人力资源管理、数据可视化及商业银行经营管理知识、工具与方法等理论知识。④紧贴现实。以中国银行作为典型案例贯穿实验，引导学生关注金融业发展。⑤数智赋能。开发虚拟仿真实验、交互习题、动画、数字人视频等丰富的数字资源，增强学习趣味性与互动性。
本教材可作为高等学校金融学类学生的专业教材，还可作为全国大学生“数字金融挑战赛”的指导用书，同时能为金融业从业人员提供有益参考。', '序言
