  ('11', '本书***梳理了工业设计从手工业时代到智能时代的演进脉络，以全球视角解读工艺美术运动、包豪斯革命、现代主义浪潮等关键阶段，并创新融入中国设计的发展轨迹。从《考工记》中的造物思想对当代可持续设计的启示，再到当代中国设计的成就，不仅呈现设计风格流变，更深入阐释技术革新、社会文化和经济建设的互动关系。在“设计强国”建设的背景下，本书引导学生从传统造物智慧中汲取文化基因，以历史眼光审视技术伦理与社会责任。
本书既可作为工业设计、产品设计等专业核心课程教材，亦可为关注工业文明发展的研究者提供跨学科视角，助力培养兼具国际视野与文化根基的新时代设计人才。', 57.00, 45.60, 232, '本书***梳理了工业设计从手工业时代到智能时代的演进脉络，以全球视角解读工艺美术运动、包豪斯革命、现代主义浪潮等关键阶段，并创新融入中国设计的发展轨迹。从《考工记》中的造物思想对当代可持续设计的启示，再到当代中国设计的成就，不仅呈现设计风格流变，更深入阐释技术革新、社会文化和经济建设的互动关系。在“设计强国”建设的背景下，本书引导学生从传统造物智慧中汲取文化基因，以历史眼光审视技术伦理与社会责任。
本书既可作为工业设计、产品设计等专业核心课程教材，亦可为关注工业文明发展的研究者提供跨学科视角，助力培养兼具国际视野与文化根基的新时代设计人才。', '前言
第一章 绪论
　第一节 什么是设计
　第二节 工业设计
　第三节 工业设计史
第二章 青铜年代：手工业时代的设计
　第一节 古埃及、古希腊、古罗马时期
　第二节 从中世纪到文艺复兴
　第三节 从巴洛克、洛可可到新古典主义
　第四节 中国古代的设计
第三章 黑铁年代：现代设计的诞生
　第一节 工业伊始与工艺美术运动
　第二节 新艺术运动
　第三节 世纪之交的变革
　第四节 现代主义的诞生
第四章 白银年代：现代设计的繁荣
　第一节 发展中的现代主义设计
　第二节 美国设计：商业的引领
　第三节 北欧设计：现代与传统的融合
　第四节 战后新秩序
　第五节 意大利设计：文化的冲突
第五章 黄金年代：设计的多元化
　第一节 设计实现技术价值
　第二节 设计推动文化繁荣
　第三节 设计创建美好生活
　第四节 设计创造崭新未来
