  ('10', '本书采用项目-任务的形式编写，以信息通信网络运行管理员国家职业技能标准为依据，以综合职业能力培养为目标，以典型工作任务为载体，将理论知识和实践技能相结合，采用动画、视频、音频等富媒体手段，以及交互式操作和练习方法，生动形象地展示了数据通信的原理，以及交换和路由的定义、原理与主要协议，并基于企业真实场景，介绍了交换机、路由器的组网和应用。
本书由数据通信基础、办公局域网搭建、部门之间网络隔离、部门之间网络互联、外网访问、网络优化配置、企业网络搭建7个项目、24个任务构成。这些项目根据知识逻辑由浅入深地逐渐展开, 内容包括基础认知、地址计算、网络设备认知、VLAN 隔离、路由配置、访问列表应用、NAT和PAT应用及网络可靠性实施等。学习完这些项目的知识后, 读者可具备网络工程师的基本职业能力。
本书可作为高等职业院校电子信息工程技术、通信工程技术相关专业的核心课程数字教材，也可作为计算机网络技术等其他相关专业的拓展课程教材，还可作为相关企业岗前培训用书。', 46.00, 36.80, 61, '本书采用项目-任务的形式编写，以信息通信网络运行管理员国家职业技能标准为依据，以综合职业能力培养为目标，以典型工作任务为载体，将理论知识和实践技能相结合，采用动画、视频、音频等富媒体手段，以及交互式操作和练习方法，生动形象地展示了数据通信的原理，以及交换和路由的定义、原理与主要协议，并基于企业真实场景，介绍了交换机、路由器的组网和应用。
本书由数据通信基础、办公局域网搭建、部门之间网络隔离、部门之间网络互联、外网访问、网络优化配置、企业网络搭建7个项目、24个任务构成。这些项目根据知识逻辑由浅入深地逐渐展开, 内容包括基础认知、地址计算、网络设备认知、VLAN 隔离、路由配置、访问列表应用、NAT和PAT应用及网络可靠性实施等。学习完这些项目的知识后, 读者可具备网络工程师的基本职业能力。
本书可作为高等职业院校电子信息工程技术、通信工程技术相关专业的核心课程数字教材，也可作为计算机网络技术等其他相关专业的拓展课程教材，还可作为相关企业岗前培训用书。', '前言
