  ('9', '本教材遵循大学生生涯发展的规律、特点与实际需求，立足当下环境，以本土化、体验式全程生涯规划教育理论体系为指导，重构了大学生职业生涯规划的课程目标和内容，较为系统地介绍了职业规划相关的方法和工具，还特别设计了丰富多样的体验实践活动，旨在帮助读者主动构建适合自己的职业生涯发展路径，并为之付诸行动。
本教材共七章，包括“开启职业生涯——在体验实践中，成为更好的自己”“职业探索——了解职业要求，明确职业使命”“环境探索——拥抱国家政策，洞察市场需求”“学业探索——澄清目标，发展‘专业+’”“自我探索——重塑自我，拥抱可能性”“生涯决策与行动——知行合一，笃行致远”“从优秀到卓越——提高就业能力，实现胜任愉快”。
本教材可作为大学生职业生涯规划及就业指导类通识课程的教材，可供高中生及学生家长阅读借鉴，也可作为职场人士自我成长的参考书籍。', 36.00, 28.80, 65, '本教材遵循大学生生涯发展的规律、特点与实际需求，立足当下环境，以本土化、体验式全程生涯规划教育理论体系为指导，重构了大学生职业生涯规划的课程目标和内容，较为系统地介绍了职业规划相关的方法和工具，还特别设计了丰富多样的体验实践活动，旨在帮助读者主动构建适合自己的职业生涯发展路径，并为之付诸行动。
本教材共七章，包括“开启职业生涯——在体验实践中，成为更好的自己”“职业探索——了解职业要求，明确职业使命”“环境探索——拥抱国家政策，洞察市场需求”“学业探索——澄清目标，发展‘专业+’”“自我探索——重塑自我，拥抱可能性”“生涯决策与行动——知行合一，笃行致远”“从优秀到卓越——提高就业能力，实现胜任愉快”。
本教材可作为大学生职业生涯规划及就业指导类通识课程的教材，可供高中生及学生家长阅读借鉴，也可作为职场人士自我成长的参考书籍。', '本书编委会
序
前言
第一章 开启职业生涯 ——在体验实践中，成为更好的自己
　第一节 何为职业生涯规划
