  ('8', '本书紧扣虚拟现实，既阐述了虚拟现实的概念、硬件设备、核心技术及应用领域，又简单阐述了三维建模技术、全景技术，兼顾了理论与实践操作，可为后续的专业课程学习打下基础。与此同时，本书还紧扣时下热点，阐述了增强现实、混合现实的相关内容，使读者能在了解虚拟现实技术的同时，拓宽对行业相关知识的认知。
