  ('7', '“出境领队业务”是高等职业教育旅游大类各专业的核心课程。本教材包含认识领队工作、学习领队业务相关知识、出发前的准备工作、中国出境与他国（地区）入境、境外旅游服务工作、他国（地区）离境及中国入境、领队带队归来的后续工作七个项目，紧密围绕出境领队日常真实工作场景，从团队招募组建、行前培训，到境外食住行游购娱各环节协调，全流程还原业务操作细节。通过详实案例和模拟任务，让学习者深度掌握出境领队在复杂多变工作中的应对技巧，无缝对接职场需求。
本教材配套丰富的数字资源，教学视频与文字同步，学习者在教材中即可进行视频观摩、学习；教材内嵌自测练习、虚拟仿真等交互内容，更好提升学习者的阅读体验。
本教材可作为职业本科院校、高职专科院校旅游大类各专业的教学用书，也可供相关行业从业者参考学习。', 42.00, 33.60, 15, '“出境领队业务”是高等职业教育旅游大类各专业的核心课程。本教材包含认识领队工作、学习领队业务相关知识、出发前的准备工作、中国出境与他国（地区）入境、境外旅游服务工作、他国（地区）离境及中国入境、领队带队归来的后续工作七个项目，紧密围绕出境领队日常真实工作场景，从团队招募组建、行前培训，到境外食住行游购娱各环节协调，全流程还原业务操作细节。通过详实案例和模拟任务，让学习者深度掌握出境领队在复杂多变工作中的应对技巧，无缝对接职场需求。
本教材配套丰富的数字资源，教学视频与文字同步，学习者在教材中即可进行视频观摩、学习；教材内嵌自测练习、虚拟仿真等交互内容，更好提升学习者的阅读体验。
本教材可作为职业本科院校、高职专科院校旅游大类各专业的教学用书，也可供相关行业从业者参考学习。', '前言
