  ('6', '本教材是一本面向高校计算机类、电子信息类的理论实践一体化教材。教材以主流的ARM Cortex-M系列处理器（STM32）和FreeRTOS实时操作系统为核心，系统讲解嵌入式系统开发全流程。全书采用“基础理论+开发工具+项目实战” 的三维架构，涵盖从硬件平台搭建到操作系统移植，再到典型应用开发的完整知识链。
本教材分为基础篇与应用篇两大部分。基础篇系统解析嵌入式系统核心理论（涵盖ARM处理器体系、STM32硬件架构及实时操作系统原理），深度整合全栈开发工具链（包括MDK5/IAR环境配置、STM32CubeMX可视化工程构建与Proteus硬件仿真），并聚焦STM32外设驱动程序开发（从GPIO/定时器/串口通信到ADC/DAC的固件库函数源码级实现）。应用篇通过梯度化实战项目贯通知识应用——基础层以气体传感器（MP503）、红外传感器（AS312）及可燃气体监测仪开发夯实传感器驱动能力；进阶层结合VR动作捕捉（LIS3DH加速度传感器与姿态算法）、扫地机器人红外避障系统、步进电机工业机床控制实现复杂系统设计；操作系统层面深度整合FreeRTOS内核移植、任务管理、信号量及临界区保护等关键技术，形成“硬件抽象层→OS移植→智能设备开发”的闭环能力培养路径，每章辅以习题与实验指导，打造理论、实践深度融合的教学闭环。
本教材适用于高校计算机类、电子信息类、物联网工程专业本科生，也可作为全国电子设计竞赛、嵌入式系统认证考试的实训指南。为提升学习效率，本教材配套提供完整工程源代码与配置手册、关键外设的仿真模型、每章习题的参考答案解析。', 36.00, 28.80, 100, '本教材是一本面向高校计算机类、电子信息类的理论实践一体化教材。教材以主流的ARM Cortex-M系列处理器（STM32）和FreeRTOS实时操作系统为核心，系统讲解嵌入式系统开发全流程。全书采用“基础理论+开发工具+项目实战” 的三维架构，涵盖从硬件平台搭建到操作系统移植，再到典型应用开发的完整知识链。
本教材分为基础篇与应用篇两大部分。基础篇系统解析嵌入式系统核心理论（涵盖ARM处理器体系、STM32硬件架构及实时操作系统原理），深度整合全栈开发工具链（包括MDK5/IAR环境配置、STM32CubeMX可视化工程构建与Proteus硬件仿真），并聚焦STM32外设驱动程序开发（从GPIO/定时器/串口通信到ADC/DAC的固件库函数源码级实现）。应用篇通过梯度化实战项目贯通知识应用——基础层以气体传感器（MP503）、红外传感器（AS312）及可燃气体监测仪开发夯实传感器驱动能力；进阶层结合VR动作捕捉（LIS3DH加速度传感器与姿态算法）、扫地机器人红外避障系统、步进电机工业机床控制实现复杂系统设计；操作系统层面深度整合FreeRTOS内核移植、任务管理、信号量及临界区保护等关键技术，形成“硬件抽象层→OS移植→智能设备开发”的闭环能力培养路径，每章辅以习题与实验指导，打造理论、实践深度融合的教学闭环。
本教材适用于高校计算机类、电子信息类、物联网工程专业本科生，也可作为全国电子设计竞赛、嵌入式系统认证考试的实训指南。为提升学习效率，本教材配套提供完整工程源代码与配置手册、关键外设的仿真模型、每章习题的参考答案解析。', '前言
