  ('5', '《三维动画骨骼绑定》作为该套系列教材的重要组成部分，基础篇以Maya绑定制作为核心，讲解约束、驱动关键帧、关节、自定义属性等核心命令的使用技巧，并详细展示角色权重绘制的全过程。实战篇以产业真实项目为实例，结合项目的实际需求，介绍目中各种道具及角色的绑定制作思路、流程和方法。
本教材不仅注重理论知识的传授，更强调实践操作能力的培养，旨在提升学生对绑定基础命令的灵活运用能力，拓展其在绑定制作方面的思维方式。通过本教材的学习，学生将掌握Maya骨骼绑定的核心技能，能够独立完成道具与角色的绑定制作，为其未来投身动画行业打下坚实的基础。', 40.00, 32.00, 30, '《三维动画骨骼绑定》作为该套系列教材的重要组成部分，基础篇以Maya绑定制作为核心，讲解约束、驱动关键帧、关节、自定义属性等核心命令的使用技巧，并详细展示角色权重绘制的全过程。实战篇以产业真实项目为实例，结合项目的实际需求，介绍目中各种道具及角色的绑定制作思路、流程和方法。
本教材不仅注重理论知识的传授，更强调实践操作能力的培养，旨在提升学生对绑定基础命令的灵活运用能力，拓展其在绑定制作方面的思维方式。通过本教材的学习，学生将掌握Maya骨骼绑定的核心技能，能够独立完成道具与角色的绑定制作，为其未来投身动画行业打下坚实的基础。', '前言
