  ('3', '2016年，教育部等11部门发布了《关于推进中小学生研学旅行的意见》，提倡在中小学生中开展研学旅行。让学生走出学校、走向自然、走向社会、走向世界，做点活、开点窍、流点汗、创点新，是拓宽学生视野、增加学识、锻炼意识的好举措，也是对学生进行中华优秀传统文化教育的好方式。
国内研学旅行市场的发展，无论是在数量上还是在质量上，都对未来研学旅行服务人才提出了更高的要求。在1+X职业技能等级证书试点的大背景下，如何进行岗课赛证融通，是在进行研学旅行人才培养时需要重点关注的问题。
本教材是由武汉城市职业学院旅游与酒店管理学院研学旅行专业教师团队与1+X研学旅行评价组织——亲子猫（北京）国际教育科技有限公司共同合作完成。本教材注重理论内容与实践操作的有机结合，重视学生实际工作能力的培养，本教材可作为研学旅行管理与服务专业教材，也可作为1+X研学旅行策划与管理（EEPM）职业技能等级证书的配套教材。', 33.00, 26.40, 229, '2016年，教育部等11部门发布了《关于推进中小学生研学旅行的意见》，提倡在中小学生中开展研学旅行。让学生走出学校、走向自然、走向社会、走向世界，做点活、开点窍、流点汗、创点新，是拓宽学生视野、增加学识、锻炼意识的好举措，也是对学生进行中华优秀传统文化教育的好方式。
国内研学旅行市场的发展，无论是在数量上还是在质量上，都对未来研学旅行服务人才提出了更高的要求。在1+X职业技能等级证书试点的大背景下，如何进行岗课赛证融通，是在进行研学旅行人才培养时需要重点关注的问题。
