  ('2', '无人机是依托无线电控制、聚焦低空飞行领域的无人飞行器。人工智能技术的不断成熟与信息网络化的应用为无人机的发展增添了技术支持。目前在我国，无人机不仅仅是一个新兴的技术领域，更是经济发展、军事探测、环境保护、航空摄影等多领域与智慧城市、数字中国等多主题相配合的物质载体。本教材以项目任务式架构，展开对无人机装配技术的介绍。教材包括无人机结构与选型、无人机动力系统调试、无人机通信与导航控制系统装调、无人机飞行控制系统装调、无人机载荷系统认知、无人机发射回收系统认知6个项目。
本教材可作为高等职业院校无人机应用技术和中等职业学校无人机操控与维护等相关专业的教学用书，也可作为无人机爱好者和培训机构的参考用书。', 38.80, 31.04, 687, '无人机是依托无线电控制、聚焦低空飞行领域的无人飞行器。人工智能技术的不断成熟与信息网络化的应用为无人机的发展增添了技术支持。目前在我国，无人机不仅仅是一个新兴的技术领域，更是经济发展、军事探测、环境保护、航空摄影等多领域与智慧城市、数字中国等多主题相配合的物质载体。本教材以项目任务式架构，展开对无人机装配技术的介绍。教材包括无人机结构与选型、无人机动力系统调试、无人机通信与导航控制系统装调、无人机飞行控制系统装调、无人机载荷系统认知、无人机发射回收系统认知6个项目。
